-- Source: migrations/2026-08-03-reschedule-offers.sql
-- Asking a customer to move day, and paying them to say yes.
--
-- The mirror image of estimate_offers. That one FILLS a gap in the route with a
-- nearby lead; this one REMOVES a stop that is costing the day more driving than
-- it is worth, by offering the customer a discount to take a day the truck is
-- already going to be near them.
--
-- Four things the schema enforces itself, because they are the ones that hurt:
--
--   1. ONE LIVE OFFER PER JOB. A partial unique index on the open statuses. A
--      customer who gets asked twice reads it as chaos, and worse, two accepted
--      offers on one job would stack two discounts on the same invoice.
--   2. THE DISCOUNT HAS A CEILING. A check constraint, not a UI cap. This number
--      comes off real money and the form that sets it is one typo away from 90.
--   3. THE SENT TEXT IS KEPT VERBATIM. Not a template id — when the customer
--      says "you offered me fifteen percent", a template that has since been
--      edited is not an answer.
--   4. THE DISCOUNT LANDS ON THE JOB, NOT THE OFFER. jobs.reschedule_discount_*
--      is what the invoice reads, so an offer row that is later deleted cannot
--      quietly un-promise money somebody already agreed to.
--
-- Additive only: one new table and three nullable columns on jobs. Safe to run
-- twice.
--
-- Do NOT apply this with scripts/deploy-schema.mjs — that replays all of
-- schema.sql, including drop policy / create policy pairs, against a live
-- database. This file is the whole change.

begin;

create table if not exists reschedule_offers (
  id              uuid primary key default gen_random_uuid(),
  account_id      uuid not null references accounts(id) on delete cascade,
  job_id          uuid not null references jobs(id) on delete cascade,
  crew_id         uuid references crew(id) on delete set null,

  status          text not null default 'sent',

  -- Where it is now, and where we are asking them to go.
  from_date       date not null,
  to_date         date not null,
  -- The arrival window promised on the new day. A window, never a single time,
  -- for the same reason estimate offers use one.
  window_start    time not null,
  window_end      time not null,
  arrival_time    time not null,

  -- What they are being paid to move. Percent, because that is what
  -- invoices.discount_percent already is — one representation, no conversion,
  -- no rounding argument at the bottom of a bill.
  discount_percent numeric not null,

  -- Why this day was suggested: how close the truck already comes on to_date,
  -- and what dropping this stop gives back to from_date. Kept for the audit
  -- trail — "we said we'd be nearby" needs to have been true.
  near_miles      numeric,
  saved_miles     numeric,
  saved_minutes   integer,

  -- Exactly what was sent, to exactly this number.
  phone           text not null,
  body            text not null,

  sent_at         timestamptz not null default now(),
  replied_at      timestamptz,
  reply_body      text,
  -- One acknowledgement per offer for a free-text reply, not one per message.
  forwarded_at    timestamptz,

  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now()
);

do $$ begin
  alter table reschedule_offers add constraint reschedule_offers_status_check
    check (status in ('sent', 'accepted', 'declined', 'canceled'));
exception when duplicate_object then null; end $$;

do $$ begin
  alter table reschedule_offers add constraint reschedule_offers_window_check
    check (window_end > window_start and arrival_time >= window_start and arrival_time <= window_end);
exception when duplicate_object then null; end $$;

-- The ceiling. 40% is already generous for moving a day; anything past it is a
-- fat finger, and this is the last place that can catch one before it reaches
-- an invoice.
do $$ begin
  alter table reschedule_offers add constraint reschedule_offers_discount_check
    check (discount_percent > 0 and discount_percent <= 40);
exception when duplicate_object then null; end $$;

-- Moving a job to the day it already sits on is not an offer.
do $$ begin
  alter table reschedule_offers add constraint reschedule_offers_dates_check
    check (to_date <> from_date);
exception when duplicate_object then null; end $$;

-- One live ask per job. Partial, so a declined or canceled offer doesn't lock
-- the job out of ever being asked again — the customer said no to THAT day, not
-- to the idea.
create unique index if not exists reschedule_offers_one_live_per_job
  on reschedule_offers (job_id) where status = 'sent';

-- The plan page reads one account's one day.
create index if not exists reschedule_offers_day_idx on reschedule_offers (account_id, from_date);

-- The inbound webhook has a phone number and nothing else, and only ever cares
-- about offers still waiting on an answer.
create index if not exists reschedule_offers_pending_idx
  on reschedule_offers (phone, sent_at desc) where status = 'sent';

-- What the invoice actually reads. On the JOB, not the offer: the promise has to
-- outlive the row that made it.
alter table jobs add column if not exists reschedule_discount_percent numeric;
alter table jobs add column if not exists reschedule_discount_note text;
alter table jobs add column if not exists reschedule_discount_agreed_at timestamptz;

do $$ begin
  alter table jobs add constraint jobs_reschedule_discount_check
    check (reschedule_discount_percent is null or (reschedule_discount_percent > 0 and reschedule_discount_percent <= 40));
exception when duplicate_object then null; end $$;

alter table reschedule_offers enable row level security;

-- Owners see and manage their own offers. Writes from the inbound webhook come
-- through the service-role client, which bypasses RLS.
drop policy if exists reschedule_offer_owner on reschedule_offers;
create policy reschedule_offer_owner on reschedule_offers for all using ( is_owner(account_id) );

commit;

-- Source: migrations/2026-08-17-subcontractor-dispatch.sql
-- Subcontractor dispatch: saved subs, one job request, many offers, one winner.
--
-- THE SHAPE, and why it is this shape.
--
--   1. A SUBCONTRACTOR IS A CREW ROW. Not a second directory. Everything that
--      already works on a person — assigning them to a job (crew_assignments),
--      texting them (sms_events context='crew'), costing their labor (costs.crew_id),
--      archiving them — keeps working the moment a sub is one of these. A parallel
--      `subcontractors` table would have meant a second assignment table, a second
--      consent ledger and a second answer to "who is on this job".
--      worker_type is what tells the two apart, and it defaults to 'employee' so
--      every row that already exists stays exactly what it was.
--
--   2. THE REQUEST IS THE THING THAT GETS CLAIMED. Not the job. One row per ask,
--      carrying its own copy of what was offered — the pay, the window, the scope
--      as it was written at the time. A sub who accepted $650 on Tuesday must
--      still be able to see $650 on Friday after the job page was edited.
--
--   3. THE OFFER IS PER PERSON, and holds the only copy of the link. One row per
--      recipient, its own hashed token, its own delivery state. "First qualified
--      acceptance wins" is only meaningful if losing is a state somebody's own
--      offer can be in, which is what 'covered' is.
--
--   4. THE CLAIM IS A PARTIAL UNIQUE INDEX, not a promise the app makes.
--      subcontractor_requests_one_winner refuses a second accepted offer on one
--      request at the storage layer, so even if two acceptances somehow got past
--      the conditional UPDATE in lib/subcontractor-dispatch-data, the database
--      would still only ever hold one winner. Belt and braces, deliberately:
--      two subs turning up to one water heater is the failure this whole feature
--      exists to prevent.
--
-- Additive only. New columns are nullable or defaulted; new tables are created
-- if absent. Safe to run twice.
--
-- Do NOT apply this with scripts/deploy-schema.mjs — that replays all of
-- schema.sql, including drop policy / create policy pairs, against a live
-- database. Use: node scripts/run-migration.mjs 2026-08-17-subcontractor-dispatch.sql

begin;

-- ---------------------------------------------------------------------------
-- 1. CREW, extended into a directory of people AND firms.
-- ---------------------------------------------------------------------------

alter table crew add column if not exists worker_type text not null default 'employee';

do $$ begin
  alter table crew add constraint crew_worker_type_check
    check (worker_type in ('employee', 'subcontractor'));
exception when duplicate_object then null; end $$;

-- The firm behind the contact. Null for an employee, and null for a one-man
-- sub who trades under their own name — which is common enough that the UI must
-- never require it.
alter table crew add column if not exists company_name text;

-- What they do and what they will travel for. Arrays rather than a join table:
-- these are tags on a person, only ever read whole, and a `trades` table would
-- add two joins to every match query to store the same six strings.
alter table crew add column if not exists trades text[] not null default '{}';
alter table crew add column if not exists skills text[] not null default '{}';
alter table crew add column if not exists tags text[] not null default '{}';
alter table crew add column if not exists service_area text;
alter table crew add column if not exists travel_radius_miles numeric(6,1);

-- Availability as the sub described it ("weekdays, evenings by arrangement"),
-- plus the one fact worth its own column because it is the one people search on
-- at 11pm.
alter table crew add column if not exists availability_note text;
alter table crew add column if not exists emergency_available boolean not null default false;

-- How they price. hourly_rate and day_rate already exist and keep their meaning;
-- these two say which one they PREFER and the floor below which the trip is not
-- worth making. Fixed-price is the first-class case for dispatch — see the
-- composer, which only offers a fixed number.
alter table crew add column if not exists rate_preference text not null default 'fixed';
alter table crew add column if not exists minimum_charge numeric(10,2);

do $$ begin
  alter table crew add constraint crew_rate_preference_check
    check (rate_preference in ('hourly', 'day_rate', 'fixed'));
exception when duplicate_object then null; end $$;

-- Paperwork. Dates rather than booleans, because "insured" is a claim with an
-- end date on it and a boolean cannot expire. A null date beside a present
-- number means "on file, no expiry recorded" and is shown differently from
-- nothing at all.
alter table crew add column if not exists license_number text;
alter table crew add column if not exists license_expires_on date;
alter table crew add column if not exists insurance_carrier text;
alter table crew add column if not exists insurance_expires_on date;
alter table crew add column if not exists w9_status text not null default 'missing';
alter table crew add column if not exists agreement_status text not null default 'missing';
alter table crew add column if not exists payment_terms text;
alter table crew add column if not exists internal_notes text;

do $$ begin
  alter table crew add constraint crew_w9_status_check
    check (w9_status in ('missing', 'requested', 'on_file'));
exception when duplicate_object then null; end $$;

do $$ begin
  alter table crew add constraint crew_agreement_status_check
    check (agreement_status in ('missing', 'sent', 'signed'));
exception when duplicate_object then null; end $$;

-- Where this firm stands with this contractor. Separate from `active`, which
-- stays the roster's on/off switch: a backup sub is active and is not somebody
-- you call first. 'archived' here is a label; archiving for real still means
-- active = false, so nothing downstream has to learn a second rule.
alter table crew add column if not exists sub_status text not null default 'active';

do $$ begin
  alter table crew add constraint crew_sub_status_check
    check (sub_status in ('active', 'preferred', 'backup', 'archived'));
exception when duplicate_object then null; end $$;

-- The match query is always "subs on this account", never "everybody".
create index if not exists crew_worker_type_idx
  on crew (account_id, worker_type) where deleted_at is null;

-- ---------------------------------------------------------------------------
-- 2. THE REQUEST — one ask, put to several firms at once.
-- ---------------------------------------------------------------------------

create table if not exists subcontractor_requests (
  id                uuid primary key default gen_random_uuid(),
  account_id        uuid not null references accounts(id) on delete cascade,
  job_id            uuid not null references jobs(id) on delete cascade,

  status            text not null default 'draft',

  -- What was offered, frozen at the moment of sending. Deliberately copied off
  -- the job rather than joined to it: editing the job next week must not
  -- retroactively change what somebody agreed to, and the sub's own page reads
  -- these columns.
  work_description  text not null,
  service_date      date,
  window_start      time,
  window_end        time,
  -- "Royal Oak, MI" — a place, never the street address. This column is shown
  -- on a public page to people who have not accepted anything yet.
  general_location  text not null default '',

  pay_amount        numeric(10,2) not null,
  pay_kind          text not null default 'fixed',

  required_trade    text not null default '',
  required_skills   text[] not null default '{}',
  requires_license  boolean not null default false,
  requires_insurance boolean not null default false,

  expires_at        timestamptz not null,
  selection_mode    text not null default 'first_accept',

  -- Photos and documents already uploaded against the job, chosen for this ask.
  -- Paths into the same storage buckets the job page uses — not copies.
  document_paths    text[] not null default '{}',

  -- The text as the owner approved it, with [secure link] still in it. Each
  -- offer stores its own rendered copy; this is the template that produced them,
  -- kept so "what did we send" survives an edit to the next request.
  message_body      text not null default '',

  claimed_offer_id  uuid,
  claimed_crew_id   uuid references crew(id) on delete set null,
  claimed_at        timestamptz,
  sent_at           timestamptz,
  cancelled_at      timestamptz,
  reopened_at       timestamptz,

  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now()
);

do $$ begin
  alter table subcontractor_requests add constraint subcontractor_requests_status_check
    check (status in ('draft', 'sent', 'viewed', 'partially_responded', 'claimed', 'expired', 'cancelled', 'reopened'));
exception when duplicate_object then null; end $$;

do $$ begin
  alter table subcontractor_requests add constraint subcontractor_requests_mode_check
    check (selection_mode in ('first_accept', 'collect_interest'));
exception when duplicate_object then null; end $$;

do $$ begin
  alter table subcontractor_requests add constraint subcontractor_requests_pay_kind_check
    check (pay_kind in ('fixed', 'hourly', 'day_rate'));
exception when duplicate_object then null; end $$;

-- Paying a sub nothing is a typo, not an offer.
do $$ begin
  alter table subcontractor_requests add constraint subcontractor_requests_pay_check
    check (pay_amount > 0);
exception when duplicate_object then null; end $$;

do $$ begin
  alter table subcontractor_requests add constraint subcontractor_requests_window_check
    check (window_start is null or window_end is null or window_end > window_start);
exception when duplicate_object then null; end $$;

-- A claimed request has a winner, and an unclaimed one does not. Without this
-- a bug could leave `claimed` sitting over three null columns, which reads on
-- every screen as "somebody took it" and names nobody.
do $$ begin
  alter table subcontractor_requests add constraint subcontractor_requests_claim_check
    check (
      (status = 'claimed') = (claimed_offer_id is not null)
      and (claimed_offer_id is null) = (claimed_at is null)
    );
exception when duplicate_object then null; end $$;

-- ONE LIVE REQUEST PER JOB. A second open ask on the same job is how two subs
-- end up claiming one water heater from two different links.
create unique index if not exists subcontractor_requests_one_live_per_job
  on subcontractor_requests (job_id)
  where status in ('draft', 'sent', 'viewed', 'partially_responded', 'reopened');

create index if not exists subcontractor_requests_account_idx
  on subcontractor_requests (account_id, created_at desc);

create index if not exists subcontractor_requests_open_idx
  on subcontractor_requests (account_id, expires_at)
  where status in ('sent', 'viewed', 'partially_responded', 'reopened');

alter table subcontractor_requests enable row level security;
drop policy if exists subcontractor_requests_owner on subcontractor_requests;
create policy subcontractor_requests_owner on subcontractor_requests
  for all using (is_owner(account_id)) with check (is_owner(account_id));

-- ---------------------------------------------------------------------------
-- 3. THE OFFER — one row per recipient, one link per row.
-- ---------------------------------------------------------------------------

create table if not exists subcontractor_offers (
  id            uuid primary key default gen_random_uuid(),
  account_id    uuid not null references accounts(id) on delete cascade,
  request_id    uuid not null references subcontractor_requests(id) on delete cascade,
  crew_id       uuid not null references crew(id) on delete cascade,

  -- ONLY THE HASH. The link is shown once, in the text that goes out; a
  -- database read must not be able to reconstruct a working one. Unique so a
  -- token collision is a failed insert rather than two offers answering to one
  -- URL.
  token_hash    text not null unique,

  status        text not null default 'queued',

  phone         text not null,
  -- Exactly what this person was sent, link and all. Not a template id: when a
  -- sub says "you told me eleven o'clock", a template that has since been
  -- edited is not an answer.
  body          text not null default '',
  provider_id   text,
  error_reason  text,

  -- What we believed when we picked them, kept for the audit trail — a match
  -- explained after the fact from today's data is not an explanation.
  distance_miles numeric(6,1),
  match_reason   text,

  queued_at     timestamptz not null default now(),
  sent_at       timestamptz,
  delivered_at  timestamptz,
  viewed_at     timestamptz,
  responded_at  timestamptz,

  decline_reason text,
  question       text,
  -- "Keep me as backup", offered to everybody who arrives too late.
  backup         boolean not null default false,

  -- THE WINNER FLAG, and why it is not just status='accepted'.
  --
  -- Under "collect interest and let the owner choose", several firms accept —
  -- each one is saying "I can do it", and none of them has the job yet. So
  -- 'accepted' cannot be the thing the one-winner index is built on, or the
  -- second firm to put their hand up would be refused by the database. `won` is
  -- set on exactly one offer per request: immediately on acceptance in
  -- first-qualified mode, and when the owner picks in the other.
  won            boolean not null default false,

  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now(),

  unique (request_id, crew_id)
);

do $$ begin
  alter table subcontractor_offers add constraint subcontractor_offers_status_check
    check (status in ('queued', 'sent', 'delivered', 'failed', 'viewed', 'accepted', 'declined', 'expired', 'covered'));
exception when duplicate_object then null; end $$;

-- THE WINNER, ENFORCED BY STORAGE. See note 4 at the top of this file, and the
-- note on `won` above for why this is not keyed on status = 'accepted'.
create unique index if not exists subcontractor_offers_one_winner
  on subcontractor_offers (request_id) where won;

-- A winner has accepted. Nothing else may carry the flag.
do $$ begin
  alter table subcontractor_offers add constraint subcontractor_offers_won_check
    check (not won or status = 'accepted');
exception when duplicate_object then null; end $$;

create index if not exists subcontractor_offers_request_idx
  on subcontractor_offers (request_id, created_at);

create index if not exists subcontractor_offers_crew_idx
  on subcontractor_offers (account_id, crew_id, created_at desc);

alter table subcontractor_offers enable row level security;
-- Owners see and manage their own offers. The public proposal page reads and
-- writes through the service-role client, which bypasses RLS — it has no
-- session and is authorised by the token instead.
drop policy if exists subcontractor_offers_owner on subcontractor_offers;
create policy subcontractor_offers_owner on subcontractor_offers
  for all using (is_owner(account_id)) with check (is_owner(account_id));

-- The claim points at a real offer. Added after the offers table exists.
do $$ begin
  alter table subcontractor_requests add constraint subcontractor_requests_claimed_offer_fkey
    foreign key (claimed_offer_id) references subcontractor_offers(id) on delete set null;
exception when duplicate_object then null; end $$;

-- ---------------------------------------------------------------------------
-- 4. THE PRIVATE REVIEW — the contractor's own note on how it went.
--
-- Deliberately NOT the `reviews` table. That one holds what customers say in
-- public and feeds the review-request flow and the public site; a sub's score
-- for cleanliness has no business anywhere near it. Same reason this is keyed on
-- (job, crew) rather than on a client.
-- ---------------------------------------------------------------------------

create table if not exists subcontractor_reviews (
  id            uuid primary key default gen_random_uuid(),
  account_id    uuid not null references accounts(id) on delete cascade,
  job_id        uuid not null references jobs(id) on delete cascade,
  crew_id       uuid not null references crew(id) on delete cascade,
  request_id    uuid references subcontractor_requests(id) on delete set null,

  work_quality  smallint not null,
  communication smallint not null,
  on_time       smallint not null,
  cleanliness   smallint not null,
  within_price  boolean not null default true,
  hire_again    boolean not null default true,
  notes         text,

  author_email  text,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now(),

  unique (job_id, crew_id)
);

do $$ begin
  alter table subcontractor_reviews add constraint subcontractor_reviews_scores_check
    check (
      work_quality between 1 and 5
      and communication between 1 and 5
      and on_time between 1 and 5
      and cleanliness between 1 and 5
    );
exception when duplicate_object then null; end $$;

create index if not exists subcontractor_reviews_crew_idx
  on subcontractor_reviews (account_id, crew_id, created_at desc);

alter table subcontractor_reviews enable row level security;
drop policy if exists subcontractor_reviews_owner on subcontractor_reviews;
create policy subcontractor_reviews_owner on subcontractor_reviews
  for all using (is_owner(account_id)) with check (is_owner(account_id));

-- ---------------------------------------------------------------------------
-- 5. THE TEXT LEDGER, extended rather than duplicated.
--
-- sms_events already records every crew-directed text with its consent verdict,
-- its provider id and its failure reason. A subcontractor offer is a crew-
-- directed text; it gets a context and three event types, not a second table.
-- ---------------------------------------------------------------------------

alter table sms_events drop constraint if exists sms_events_context_check;
do $$ begin
  alter table sms_events add constraint sms_events_context_check
    check (context in ('payment', 'crew', 'subcontractor'));
exception when duplicate_object then null; end $$;

alter table sms_events drop constraint if exists sms_events_event_type_allowed;
do $$ begin
  alter table sms_events add constraint sms_events_event_type_allowed
    check (event_type in (
      'payment_requested','payment_paid','payment_failed','payment_refunded',
      'crew_assigned','crew_scheduled',
      'sub_offer','sub_offer_covered','sub_offer_won','sub_offer_cancelled'
    ));
exception when duplicate_object then null; end $$;

-- A subcontractor row targets a crew member, exactly like a crew row does.
alter table sms_events drop constraint if exists sms_events_target_check;
do $$ begin
  alter table sms_events add constraint sms_events_target_check
    check (
      (context = 'payment' and payment_id is not null)
      or (context in ('crew', 'subcontractor') and crew_id is not null)
    );
exception when duplicate_object then null; end $$;

commit;

-- Source: migrations/20260815213142_pricing_entitlements.sql
-- Pricing, subscriptions, usage credits, and direct-charge migration foundation.
--
-- This migration is deliberately additive. `accounts` remains the workspace
-- boundary, the legacy plan_tier enum remains untouched, and the existing
-- accounts.stripe_connect_id remains the legacy recipient/destination account.
-- New Stripe merchant accounts are recorded separately so a payment can always
-- be reconciled against the charge architecture that created it.

begin;

-- ---------------------------------------------------------------------------
-- Stripe Connect merchant readiness (new direct-charge architecture)
-- ---------------------------------------------------------------------------

alter table public.accounts
  add column if not exists stripe_merchant_account_id text,
  add column if not exists merchant_onboarding_state text not null default 'not_started',
  add column if not exists merchant_onboarding_started_at timestamptz,
  add column if not exists merchant_requirements_checked_at timestamptz,
  add column if not exists merchant_ready_at timestamptz,
  add column if not exists merchant_disabled_at timestamptz;

do $$
begin
  if not exists (
    select 1 from pg_catalog.pg_constraint
     where conrelid = 'public.accounts'::pg_catalog.regclass
       and conname = 'accounts_merchant_onboarding_state_check'
  ) then
    alter table public.accounts add constraint accounts_merchant_onboarding_state_check
      check (merchant_onboarding_state in ('not_started', 'pending', 'restricted', 'ready', 'disabled'));
  end if;

  if not exists (
    select 1 from pg_catalog.pg_constraint
     where conrelid = 'public.accounts'::pg_catalog.regclass
       and conname = 'accounts_merchant_ready_state_check'
  ) then
    alter table public.accounts add constraint accounts_merchant_ready_state_check
      check (
        merchant_onboarding_state <> 'ready'
        or (
          stripe_merchant_account_id is not null
          and merchant_ready_at is not null
          and merchant_disabled_at is null
        )
      );
  end if;

  if not exists (
    select 1 from pg_catalog.pg_constraint
     where conrelid = 'public.accounts'::pg_catalog.regclass
       and conname = 'accounts_merchant_timestamps_require_account_check'
  ) then
    alter table public.accounts add constraint accounts_merchant_timestamps_require_account_check
      check (
        stripe_merchant_account_id is not null
        or (
          merchant_onboarding_started_at is null
          and merchant_requirements_checked_at is null
          and merchant_ready_at is null
          and merchant_disabled_at is null
        )
      );
  end if;

  if not exists (
    select 1 from pg_catalog.pg_constraint
     where conrelid = 'public.accounts'::pg_catalog.regclass
       and conname = 'accounts_stripe_merchant_account_format_check'
  ) then
    alter table public.accounts add constraint accounts_stripe_merchant_account_format_check
      check (
        stripe_merchant_account_id is null
        or stripe_merchant_account_id ~ '^acct_[A-Za-z0-9]{8,}$'
      );
  end if;
end
$$;

create unique index if not exists accounts_stripe_merchant_account_unique
  on public.accounts (stripe_merchant_account_id)
  where stripe_merchant_account_id is not null;

create index if not exists accounts_merchant_onboarding_state_idx
  on public.accounts (merchant_onboarding_state, merchant_requirements_checked_at);

comment on column public.accounts.stripe_connect_id is
  'Legacy recipient/destination Connect account. Do not overwrite during the direct-charge migration.';
comment on column public.accounts.stripe_merchant_account_id is
  'Stripe Merchant connected account used for direct charges. Separate from the legacy recipient account.';

-- accounts already has an owner UPDATE policy. Without a column guard, that
-- broad legacy policy would let a browser session declare its own Merchant
-- account ready. Merchant readiness is provider state and is backend-managed.
create or replace function public.protect_account_merchant_state()
returns trigger
language plpgsql
set search_path = pg_catalog, pg_temp
as $$
begin
  if current_user in ('anon', 'authenticated') then
    if tg_op = 'INSERT' then
      if new.stripe_merchant_account_id is not null
         or new.merchant_onboarding_state <> 'not_started'
         or new.merchant_onboarding_started_at is not null
         or new.merchant_requirements_checked_at is not null
         or new.merchant_ready_at is not null
         or new.merchant_disabled_at is not null then
        raise exception 'Stripe Merchant state is backend-managed' using errcode = '42501';
      end if;
    elsif old.stripe_merchant_account_id is distinct from new.stripe_merchant_account_id
       or old.merchant_onboarding_state is distinct from new.merchant_onboarding_state
       or old.merchant_onboarding_started_at is distinct from new.merchant_onboarding_started_at
       or old.merchant_requirements_checked_at is distinct from new.merchant_requirements_checked_at
       or old.merchant_ready_at is distinct from new.merchant_ready_at
       or old.merchant_disabled_at is distinct from new.merchant_disabled_at then
      raise exception 'Stripe Merchant state is backend-managed' using errcode = '42501';
    end if;
  end if;
  return new;
end;
$$;

drop trigger if exists protect_account_merchant_state_insert_trigger on public.accounts;
create trigger protect_account_merchant_state_insert_trigger
before insert on public.accounts
for each row execute function public.protect_account_merchant_state();

drop trigger if exists protect_account_merchant_state_update_trigger on public.accounts;
create trigger protect_account_merchant_state_update_trigger
before update of stripe_merchant_account_id, merchant_onboarding_state,
  merchant_onboarding_started_at, merchant_requirements_checked_at,
  merchant_ready_at, merchant_disabled_at
on public.accounts
for each row execute function public.protect_account_merchant_state();

revoke all on function public.protect_account_merchant_state() from public, anon, authenticated;

-- ---------------------------------------------------------------------------
-- Immutable payment fee and charge-architecture snapshots
-- ---------------------------------------------------------------------------

alter table public.payments
  add column if not exists refunded_at timestamptz,
  add column if not exists platform_fee_refunded numeric(12,2) not null default 0,
  add column if not exists fee_basis_amount numeric(12,2),
  add column if not exists fee_plan_code text,
  add column if not exists fee_catalog_version text,
  add column if not exists fee_rate_bps integer,
  add column if not exists stripe_account_id text,
  add column if not exists charge_model text not null default 'destination',
  add column if not exists stripe_charge_id text,
  add column if not exists stripe_application_fee_id text,
  add column if not exists stripe_latest_refund_id text,
  add column if not exists stripe_latest_application_fee_refund_id text,
  add column if not exists stripe_balance_transaction_id text,
  add column if not exists reconciliation_status text,
  add column if not exists reconciled_at timestamptz;

do $$
begin
  if not exists (
    select 1 from pg_catalog.pg_constraint
     where conrelid = 'public.payments'::pg_catalog.regclass
       and conname = 'payments_refunded_amount_check'
  ) then
    alter table public.payments add constraint payments_refunded_amount_check
      check (refunded_amount >= 0 and refunded_amount <= amount);
  end if;

  if not exists (
    select 1 from pg_catalog.pg_constraint
     where conrelid = 'public.payments'::pg_catalog.regclass
       and conname = 'payments_platform_fee_refunded_check'
  ) then
    alter table public.payments add constraint payments_platform_fee_refunded_check
      check (
        platform_fee_refunded >= 0
        and (platform_fee is null or platform_fee_refunded <= platform_fee)
      );
  end if;

  if not exists (
    select 1 from pg_catalog.pg_constraint
     where conrelid = 'public.payments'::pg_catalog.regclass
       and conname = 'payments_fee_basis_amount_check'
  ) then
    alter table public.payments add constraint payments_fee_basis_amount_check
      check (fee_basis_amount is null or (fee_basis_amount >= 0 and fee_basis_amount <= amount));
  end if;

  if not exists (
    select 1 from pg_catalog.pg_constraint
     where conrelid = 'public.payments'::pg_catalog.regclass
       and conname = 'payments_fee_plan_code_check'
  ) then
    alter table public.payments add constraint payments_fee_plan_code_check
      check (fee_plan_code is null or fee_plan_code in ('flex', 'solo', 'growth', 'scale', 'enterprise'));
  end if;

  if not exists (
    select 1 from pg_catalog.pg_constraint
     where conrelid = 'public.payments'::pg_catalog.regclass
       and conname = 'payments_fee_catalog_version_check'
  ) then
    alter table public.payments add constraint payments_fee_catalog_version_check
      check (fee_catalog_version is null or pg_catalog.length(pg_catalog.btrim(fee_catalog_version)) > 0);
  end if;

  if not exists (
    select 1 from pg_catalog.pg_constraint
     where conrelid = 'public.payments'::pg_catalog.regclass
       and conname = 'payments_platform_fee_check'
  ) then
    alter table public.payments add constraint payments_platform_fee_check
      check (
        platform_fee is null
        or (
          platform_fee >= 0
          and platform_fee <= amount
          and (fee_basis_amount is null or platform_fee <= fee_basis_amount)
        )
      );
  end if;

  if not exists (
    select 1 from pg_catalog.pg_constraint
     where conrelid = 'public.payments'::pg_catalog.regclass
       and conname = 'payments_fee_rate_check'
  ) then
    alter table public.payments add constraint payments_fee_rate_check
      check (fee_rate is null or (fee_rate >= 0 and fee_rate <= 1));
  end if;

  if not exists (
    select 1 from pg_catalog.pg_constraint
     where conrelid = 'public.payments'::pg_catalog.regclass
       and conname = 'payments_fee_rate_bps_check'
  ) then
    alter table public.payments add constraint payments_fee_rate_bps_check
      check (fee_rate_bps is null or fee_rate_bps between 0 and 10000);
  end if;

  if not exists (
    select 1 from pg_catalog.pg_constraint
     where conrelid = 'public.payments'::pg_catalog.regclass
       and conname = 'payments_charge_model_check'
  ) then
    alter table public.payments add constraint payments_charge_model_check
      check (charge_model in ('destination', 'direct'));
  end if;

  if not exists (
    select 1 from pg_catalog.pg_constraint
     where conrelid = 'public.payments'::pg_catalog.regclass
       and conname = 'payments_direct_charge_account_check'
  ) then
    alter table public.payments add constraint payments_direct_charge_account_check
      check (
        charge_model <> 'direct'
        or (
          stripe_account_id is not null
          and fee_basis_amount is not null
          and fee_plan_code is not null
          and fee_catalog_version is not null
          and fee_rate_bps is not null
          and fee_rate is not null
          and platform_fee is not null
          and reconciliation_status is not null
          and stripe_account_id ~ '^acct_[A-Za-z0-9]{8,}$'
          and fee_rate = fee_rate_bps::numeric / 10000
          and platform_fee = pg_catalog.round(fee_basis_amount * fee_rate_bps::numeric / 10000, 2)
        )
      );
  end if;

  if not exists (
    select 1 from pg_catalog.pg_constraint
     where conrelid = 'public.payments'::pg_catalog.regclass
       and conname = 'payments_reconciliation_status_check'
  ) then
    alter table public.payments add constraint payments_reconciliation_status_check
      check (reconciliation_status is null or reconciliation_status in ('pending', 'reconciled', 'mismatch', 'waived'));
  end if;

  if not exists (
    select 1 from pg_catalog.pg_constraint
     where conrelid = 'public.payments'::pg_catalog.regclass
       and conname = 'payments_reconciled_at_check'
  ) then
    alter table public.payments add constraint payments_reconciled_at_check
      check (
        (
          reconciled_at is null
          and (reconciliation_status is null or reconciliation_status in ('pending', 'mismatch'))
        )
        or (
          reconciled_at is not null
          and reconciliation_status in ('reconciled', 'waived')
        )
      );
  end if;
end
$$;

create index if not exists payments_stripe_account_charge_idx
  on public.payments (stripe_account_id, stripe_charge_id)
  where stripe_account_id is not null;
create unique index if not exists payments_id_account_unique
  on public.payments (id, account_id);
create unique index if not exists payments_stripe_application_fee_unique
  on public.payments (stripe_application_fee_id)
  where stripe_application_fee_id is not null;
create index if not exists payments_reconciliation_queue_idx
  on public.payments (reconciliation_status, paid_at)
  where reconciliation_status in ('pending', 'mismatch');

create or replace function public.protect_payment_pricing_snapshot()
returns trigger
language plpgsql
set search_path = pg_catalog, pg_temp
as $$
begin
  if tg_op = 'INSERT' then
    if current_user in ('anon', 'authenticated')
       and (
         new.fee_basis_amount is not null
          or new.platform_fee is not null
          or new.fee_rate is not null
          or new.fee_rate_bps is not null
          or new.fee_plan_code is not null
         or new.fee_catalog_version is not null
         or new.stripe_account_id is not null
         or new.charge_model <> 'destination'
         or new.stripe_charge_id is not null
         or new.stripe_application_fee_id is not null
         or new.stripe_latest_refund_id is not null
         or new.stripe_latest_application_fee_refund_id is not null
         or new.stripe_balance_transaction_id is not null
         or new.reconciliation_status is not null
         or new.reconciled_at is not null
       ) then
      raise exception 'payment pricing and Stripe reconciliation fields are backend-managed' using errcode = '42501';
    end if;
    return new;
  end if;

  if current_user in ('anon', 'authenticated')
     and (
       old.fee_basis_amount is distinct from new.fee_basis_amount
        or old.platform_fee is distinct from new.platform_fee
        or old.fee_rate is distinct from new.fee_rate
        or old.fee_rate_bps is distinct from new.fee_rate_bps
        or old.fee_plan_code is distinct from new.fee_plan_code
       or old.fee_catalog_version is distinct from new.fee_catalog_version
       or old.stripe_account_id is distinct from new.stripe_account_id
       or old.charge_model is distinct from new.charge_model
       or old.stripe_charge_id is distinct from new.stripe_charge_id
       or old.stripe_application_fee_id is distinct from new.stripe_application_fee_id
       or old.stripe_latest_refund_id is distinct from new.stripe_latest_refund_id
       or old.stripe_latest_application_fee_refund_id is distinct from new.stripe_latest_application_fee_refund_id
       or old.stripe_balance_transaction_id is distinct from new.stripe_balance_transaction_id
       or old.reconciliation_status is distinct from new.reconciliation_status
       or old.reconciled_at is distinct from new.reconciled_at
     ) then
    raise exception 'payment pricing and Stripe reconciliation fields are backend-managed' using errcode = '42501';
  end if;

  if old.charge_model is distinct from new.charge_model then
    raise exception 'payments.charge_model is immutable' using errcode = '22000';
  end if;
  if old.stripe_account_id is not null and old.stripe_account_id is distinct from new.stripe_account_id then
    raise exception 'payments.stripe_account_id is immutable once assigned' using errcode = '22000';
  end if;
  if old.fee_basis_amount is not null and old.fee_basis_amount is distinct from new.fee_basis_amount then
    raise exception 'payments.fee_basis_amount is immutable once assigned' using errcode = '22000';
  end if;
  if old.charge_model = 'direct'
     and old.platform_fee is not null
     and old.platform_fee is distinct from new.platform_fee then
    raise exception 'payments.platform_fee is immutable once assigned' using errcode = '22000';
  end if;
  if old.charge_model = 'direct'
     and old.fee_rate is not null
     and old.fee_rate is distinct from new.fee_rate then
    raise exception 'payments.fee_rate is immutable once assigned' using errcode = '22000';
  end if;
  if old.fee_rate_bps is not null and old.fee_rate_bps is distinct from new.fee_rate_bps then
    raise exception 'payments.fee_rate_bps is immutable once assigned' using errcode = '22000';
  end if;
  if old.fee_plan_code is not null and old.fee_plan_code is distinct from new.fee_plan_code then
    raise exception 'payments.fee_plan_code is immutable once assigned' using errcode = '22000';
  end if;
  if old.fee_catalog_version is not null and old.fee_catalog_version is distinct from new.fee_catalog_version then
    raise exception 'payments.fee_catalog_version is immutable once assigned' using errcode = '22000';
  end if;
  if old.stripe_application_fee_id is not null
     and old.stripe_application_fee_id is distinct from new.stripe_application_fee_id then
    raise exception 'payments.stripe_application_fee_id is immutable once assigned' using errcode = '22000';
  end if;
  if old.stripe_charge_id is not null and old.stripe_charge_id is distinct from new.stripe_charge_id then
    raise exception 'payments.stripe_charge_id is immutable once assigned' using errcode = '22000';
  end if;
  if old.stripe_balance_transaction_id is not null
     and old.stripe_balance_transaction_id is distinct from new.stripe_balance_transaction_id then
    raise exception 'payments.stripe_balance_transaction_id is immutable once assigned' using errcode = '22000';
  end if;
  return new;
end;
$$;

drop trigger if exists protect_payment_pricing_snapshot_trigger on public.payments;
create trigger protect_payment_pricing_snapshot_trigger
before update of charge_model, stripe_account_id, fee_basis_amount, platform_fee, fee_rate, fee_rate_bps, fee_plan_code,
  fee_catalog_version, stripe_charge_id, stripe_application_fee_id,
  stripe_latest_refund_id, stripe_latest_application_fee_refund_id,
  stripe_balance_transaction_id, reconciliation_status, reconciled_at
on public.payments
for each row execute function public.protect_payment_pricing_snapshot();

drop trigger if exists protect_payment_pricing_snapshot_insert_trigger on public.payments;
create trigger protect_payment_pricing_snapshot_insert_trigger
before insert on public.payments
for each row execute function public.protect_payment_pricing_snapshot();

revoke all on function public.protect_payment_pricing_snapshot() from public, anon, authenticated;

-- A direct-charge payment row is a server-owned settlement record. Keep the
-- legacy destination/manual workflow unchanged, but prevent browser sessions
-- from forging Stripe outcomes and freeze the identity/amount of direct rows.
create or replace function public.protect_direct_payment_truth()
returns trigger
language plpgsql
set search_path = pg_catalog, pg_temp
as $$
begin
  if tg_op = 'DELETE' then
    if old.charge_model = 'direct' then
      raise exception 'direct payment audit rows cannot be deleted' using errcode = '42501';
    end if;
    return old;
  end if;

  if old.charge_model <> 'direct' then
    return new;
  end if;

  if old.account_id is distinct from new.account_id
     or old.job_id is distinct from new.job_id
     or old.invoice_id is distinct from new.invoice_id
     or old.payment_plan_id is distinct from new.payment_plan_id
     or old.recurring_plan_id is distinct from new.recurring_plan_id
     or old.kind is distinct from new.kind
     or old.amount is distinct from new.amount
     or old.due_date is distinct from new.due_date
     or old.installment_seq is distinct from new.installment_seq then
    raise exception 'direct payment identity and amount are immutable' using errcode = '22000';
  end if;

  if old.stripe_payment_intent is not null
     and old.stripe_payment_intent is distinct from new.stripe_payment_intent then
    raise exception 'direct payment intent is immutable once assigned' using errcode = '22000';
  end if;

  if current_user in ('anon', 'authenticated')
     and (
       old.status is distinct from new.status
       or old.paid_at is distinct from new.paid_at
       or old.stripe_checkout_session is distinct from new.stripe_checkout_session
       or old.stripe_payment_intent is distinct from new.stripe_payment_intent
       or old.refunded_amount is distinct from new.refunded_amount
       or old.refunded_at is distinct from new.refunded_at
       or old.platform_fee_refunded is distinct from new.platform_fee_refunded
       or old.disputed_at is distinct from new.disputed_at
       or old.dispute_reason is distinct from new.dispute_reason
       or old.dispute_status is distinct from new.dispute_status
       or old.stripe_dispute_id is distinct from new.stripe_dispute_id
       or old.dispute_due_by is distinct from new.dispute_due_by
       or old.failure_code is distinct from new.failure_code
       or old.failure_message is distinct from new.failure_message
       or old.failed_at is distinct from new.failed_at
       or old.dunning_attempts is distinct from new.dunning_attempts
       or old.charge_attempts is distinct from new.charge_attempts
       or old.next_retry_at is distinct from new.next_retry_at
       or old.dunning_state is distinct from new.dunning_state
     ) then
    raise exception 'direct payment provider state is backend-managed' using errcode = '42501';
  end if;

  return new;
end;
$$;

drop trigger if exists protect_direct_payment_truth_trigger on public.payments;
create trigger protect_direct_payment_truth_trigger
before update of account_id, job_id, invoice_id, payment_plan_id, recurring_plan_id,
  kind, amount, due_date, installment_seq, status, paid_at, stripe_checkout_session,
  stripe_payment_intent, refunded_amount, refunded_at, platform_fee_refunded,
  disputed_at, dispute_reason, dispute_status, stripe_dispute_id, dispute_due_by,
  failure_code, failure_message, failed_at, dunning_attempts, charge_attempts,
  next_retry_at, dunning_state
on public.payments
for each row execute function public.protect_direct_payment_truth();

drop trigger if exists protect_direct_payment_truth_delete_trigger on public.payments;
create trigger protect_direct_payment_truth_delete_trigger
before delete on public.payments
for each row execute function public.protect_direct_payment_truth();

revoke all on function public.protect_direct_payment_truth() from public, anon, authenticated;

-- ---------------------------------------------------------------------------
-- Current Stripe Billing subscription and safe workspace entitlement snapshot
-- ---------------------------------------------------------------------------

create table if not exists public.billing_subscriptions (
  id uuid primary key default gen_random_uuid(),
  account_id uuid not null references public.accounts(id) on delete cascade,
  provider text not null default 'stripe' check (provider = 'stripe'),
  provider_customer_id text not null check (pg_catalog.length(pg_catalog.btrim(provider_customer_id)) > 0),
  provider_subscription_id text not null check (pg_catalog.length(pg_catalog.btrim(provider_subscription_id)) > 0),
  provider_subscription_item_id text,
  provider_price_id text not null check (pg_catalog.length(pg_catalog.btrim(provider_price_id)) > 0),
  plan_code text not null check (plan_code in ('solo', 'growth', 'scale', 'enterprise')),
  billing_interval text not null check (billing_interval in ('monthly', 'annual')),
  status text not null check (
    status in ('incomplete', 'incomplete_expired', 'trialing', 'active', 'past_due', 'canceled', 'unpaid', 'paused')
  ),
  catalog_version text not null check (pg_catalog.length(pg_catalog.btrim(catalog_version)) > 0),
  currency text not null default 'usd' check (currency ~ '^[a-z]{3}$'),
  base_amount_cents bigint not null check (base_amount_cents >= 0),
  platform_fee_bps integer not null check (platform_fee_bps between 0 and 10000),
  current_period_start timestamptz,
  current_period_end timestamptz,
  cancel_at_period_end boolean not null default false,
  cancel_at timestamptz,
  canceled_at timestamptz,
  ended_at timestamptz,
  pending_plan_code text check (pending_plan_code is null or pending_plan_code in ('solo', 'growth', 'scale', 'enterprise')),
  pending_billing_interval text check (pending_billing_interval is null or pending_billing_interval in ('monthly', 'annual')),
  pending_effective_at timestamptz,
  metadata jsonb not null default '{}'::jsonb check (pg_catalog.jsonb_typeof(metadata) = 'object'),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint billing_subscriptions_provider_subscription_unique unique (provider, provider_subscription_id),
  constraint billing_subscriptions_period_check check (
    current_period_start is null or current_period_end is null or current_period_end > current_period_start
  ),
  constraint billing_subscriptions_pending_change_check check (
    (pending_plan_code is null and pending_billing_interval is null and pending_effective_at is null)
    or
    (pending_plan_code is not null and pending_billing_interval is not null and pending_effective_at is not null)
  )
);

create unique index if not exists billing_subscriptions_one_live_per_account
  on public.billing_subscriptions (account_id)
  where status in ('incomplete', 'trialing', 'active', 'past_due', 'unpaid', 'paused');
create index if not exists billing_subscriptions_customer_idx
  on public.billing_subscriptions (provider, provider_customer_id);
create index if not exists billing_subscriptions_period_end_idx
  on public.billing_subscriptions (current_period_end)
  where status in ('trialing', 'active', 'past_due', 'unpaid', 'paused');

create table if not exists public.workspace_entitlements (
  account_id uuid primary key references public.accounts(id) on delete cascade,
  plan_code text not null check (plan_code in ('flex', 'solo', 'growth', 'scale', 'enterprise')),
  billing_interval text not null check (billing_interval in ('none', 'monthly', 'annual')),
  billing_status text not null check (billing_status in ('free', 'trialing', 'active', 'past_due', 'paused', 'canceled')),
  entitlement_state text not null check (entitlement_state in ('active', 'grace', 'restricted', 'archived')),
  catalog_version text not null check (pg_catalog.length(pg_catalog.btrim(catalog_version)) > 0),
  platform_fee_bps integer not null check (platform_fee_bps between 0 and 10000),
  period_start timestamptz,
  period_end timestamptz,
  next_allowance_reset_at timestamptz,
  starter_credits_issued_at timestamptz,
  archived_at timestamptz,
  feature_limits jsonb not null default '{}'::jsonb check (pg_catalog.jsonb_typeof(feature_limits) = 'object'),
  feature_flags jsonb not null default '{}'::jsonb check (pg_catalog.jsonb_typeof(feature_flags) = 'object'),
  version bigint not null default 1 check (version > 0),
  effective_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint workspace_entitlements_period_check check (
    period_start is null or period_end is null or period_end > period_start
  ),
  constraint workspace_entitlements_archive_check check (
    entitlement_state <> 'archived' or archived_at is not null
  )
);

create index if not exists workspace_entitlements_plan_state_idx
  on public.workspace_entitlements (plan_code, entitlement_state);
create index if not exists workspace_entitlements_allowance_reset_idx
  on public.workspace_entitlements (next_allowance_reset_at)
  where next_allowance_reset_at is not null and entitlement_state = 'active';

create or replace function public.touch_billing_updated_at()
returns trigger
language plpgsql
set search_path = pg_catalog, pg_temp
as $$
begin
  new.updated_at := pg_catalog.now();
  return new;
end;
$$;

drop trigger if exists billing_subscriptions_touch_updated_at on public.billing_subscriptions;
create trigger billing_subscriptions_touch_updated_at
before update on public.billing_subscriptions
for each row execute function public.touch_billing_updated_at();

drop trigger if exists workspace_entitlements_touch_updated_at on public.workspace_entitlements;
create trigger workspace_entitlements_touch_updated_at
before update on public.workspace_entitlements
for each row execute function public.touch_billing_updated_at();

revoke all on function public.touch_billing_updated_at() from public, anon, authenticated;

-- ---------------------------------------------------------------------------
-- Durable, idempotent Stripe event inbox (payloads are backend-only)
-- ---------------------------------------------------------------------------

create table if not exists public.billing_events (
  id uuid primary key default gen_random_uuid(),
  provider text not null default 'stripe' check (provider = 'stripe'),
  provider_event_id text not null check (pg_catalog.length(pg_catalog.btrim(provider_event_id)) > 0),
  event_type text not null check (pg_catalog.length(pg_catalog.btrim(event_type)) > 0),
  account_id uuid references public.accounts(id) on delete set null,
  billing_subscription_id uuid references public.billing_subscriptions(id) on delete set null,
  provider_account_id text,
  livemode boolean not null,
  api_version text,
  provider_created_at timestamptz,
  payload jsonb not null check (pg_catalog.jsonb_typeof(payload) = 'object'),
  payload_sha256 text check (payload_sha256 is null or payload_sha256 ~ '^[0-9a-f]{64}$'),
  processing_status text not null default 'received'
    check (processing_status in ('received', 'processing', 'processed', 'failed', 'ignored')),
  attempt_count integer not null default 0 check (attempt_count >= 0),
  processing_started_at timestamptz,
  processed_at timestamptz,
  next_attempt_at timestamptz,
  last_error text,
  received_at timestamptz not null default now(),
  constraint billing_events_provider_event_unique unique (provider, provider_event_id),
  constraint billing_events_processed_state_check check (
    processed_at is null or processing_status in ('processed', 'ignored')
  )
);

create index if not exists billing_events_processing_queue_idx
  on public.billing_events (processing_status, next_attempt_at, received_at)
  where processing_status in ('received', 'failed');
create index if not exists billing_events_account_received_idx
  on public.billing_events (account_id, received_at desc)
  where account_id is not null;
create index if not exists billing_events_provider_account_idx
  on public.billing_events (provider_account_id, received_at desc)
  where provider_account_id is not null;

-- Stripe's idempotency window is not a durable business-operation ledger. This
-- table claims each create/refund operation exactly once and records its result,
-- while Stripe idempotency remains a second line of defense.
create table if not exists public.billing_payment_operations (
  id uuid primary key default gen_random_uuid(),
  account_id uuid not null references public.accounts(id) on delete restrict,
  payment_id uuid,
  operation_type text not null check (operation_type ~ '^[a-z][a-z0-9_.]{1,63}$'),
  operation_id text not null check (pg_catalog.length(pg_catalog.btrim(operation_id)) > 0),
  charge_model text not null default 'direct' check (charge_model = 'direct'),
  stripe_account_id text not null check (stripe_account_id ~ '^acct_[A-Za-z0-9]{8,}$'),
  stripe_idempotency_key text not null check (
    pg_catalog.length(pg_catalog.btrim(stripe_idempotency_key)) between 1 and 255
  ),
  request_fingerprint text not null check (request_fingerprint ~ '^[0-9a-f]{64}$'),
  state text not null default 'claimed'
    check (state in ('claimed', 'submitted', 'succeeded', 'failed', 'indeterminate')),
  provider_object_id text,
  attempt_count integer not null default 0 check (attempt_count >= 0),
  lease_expires_at timestamptz,
  completed_at timestamptz,
  last_error text,
  metadata jsonb not null default '{}'::jsonb check (pg_catalog.jsonb_typeof(metadata) = 'object'),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint billing_payment_operations_business_key_unique
    unique (account_id, operation_type, operation_id),
  constraint billing_payment_operations_stripe_key_unique
    unique (stripe_account_id, stripe_idempotency_key),
  constraint billing_payment_operations_payment_fk
    foreign key (payment_id, account_id)
    references public.payments(id, account_id) on delete restrict,
  constraint billing_payment_operations_completion_check check (
    completed_at is null or state in ('succeeded', 'failed')
  )
);

create index if not exists billing_payment_operations_recovery_idx
  on public.billing_payment_operations (state, lease_expires_at, created_at)
  where state in ('claimed', 'submitted', 'indeterminate');
create unique index if not exists billing_payment_operations_provider_object_unique
  on public.billing_payment_operations (stripe_account_id, provider_object_id)
  where provider_object_id is not null;

drop trigger if exists billing_payment_operations_touch_updated_at on public.billing_payment_operations;
create trigger billing_payment_operations_touch_updated_at
before update on public.billing_payment_operations
for each row execute function public.touch_billing_updated_at();

-- ---------------------------------------------------------------------------
-- Credit lots and reservation ledger
-- ---------------------------------------------------------------------------

create table if not exists public.usage_credit_lots (
  id uuid primary key default gen_random_uuid(),
  account_id uuid not null references public.accounts(id) on delete cascade,
  resource_code text not null check (resource_code ~ '^[a-z][a-z0-9_]{1,63}$'),
  source_type text not null check (
    source_type in ('flex_starter', 'plan_period', 'purchase', 'promotion', 'adjustment', 'voice_addon')
  ),
  idempotency_key text not null check (pg_catalog.length(pg_catalog.btrim(idempotency_key)) > 0),
  catalog_version text check (catalog_version is null or pg_catalog.length(pg_catalog.btrim(catalog_version)) > 0),
  billing_event_id uuid references public.billing_events(id) on delete set null,
  granted_units bigint not null check (granted_units > 0),
  consumed_units bigint not null default 0 check (consumed_units >= 0),
  reserved_units bigint not null default 0 check (reserved_units >= 0),
  revoked_units bigint not null default 0 check (revoked_units >= 0),
  available_from timestamptz not null default now(),
  expires_at timestamptz,
  metadata jsonb not null default '{}'::jsonb check (pg_catalog.jsonb_typeof(metadata) = 'object'),
  created_at timestamptz not null default now(),
  constraint usage_credit_lots_id_account_unique unique (id, account_id),
  constraint usage_credit_lots_idempotency_unique unique (account_id, resource_code, idempotency_key),
  constraint usage_credit_lots_units_check check (
    consumed_units + reserved_units + revoked_units <= granted_units
  ),
  constraint usage_credit_lots_expiration_check check (
    expires_at is null or expires_at > available_from
  ),
  constraint usage_credit_lots_purchases_do_not_expire check (
    source_type <> 'purchase' or expires_at is null
  )
);

create index if not exists usage_credit_lots_fifo_idx
  on public.usage_credit_lots (account_id, resource_code, expires_at, available_from, created_at, id)
  where consumed_units + reserved_units + revoked_units < granted_units;
create index if not exists usage_credit_lots_billing_event_idx
  on public.usage_credit_lots (billing_event_id)
  where billing_event_id is not null;

create table if not exists public.usage_reservations (
  id uuid primary key default gen_random_uuid(),
  account_id uuid not null references public.accounts(id) on delete cascade,
  resource_code text not null check (resource_code ~ '^[a-z][a-z0-9_]{1,63}$'),
  units bigint not null check (units > 0),
  operation_type text not null check (operation_type ~ '^[a-z][a-z0-9_]{1,63}$'),
  idempotency_key text not null check (pg_catalog.length(pg_catalog.btrim(idempotency_key)) > 0),
  state text not null default 'reserved' check (state in ('reserved', 'committed', 'released', 'expired')),
  expires_at timestamptz not null,
  committed_at timestamptz,
  released_at timestamptz,
  finalization_key text,
  release_reason text,
  metadata jsonb not null default '{}'::jsonb check (pg_catalog.jsonb_typeof(metadata) = 'object'),
  created_at timestamptz not null default now(),
  constraint usage_reservations_id_account_unique unique (id, account_id),
  constraint usage_reservations_idempotency_unique unique (account_id, resource_code, idempotency_key),
  constraint usage_reservations_expiration_check check (expires_at > created_at),
  constraint usage_reservations_final_state_check check (
    (state = 'reserved' and committed_at is null and released_at is null)
    or (state = 'committed' and committed_at is not null and released_at is null)
    or (state in ('released', 'expired') and committed_at is null and released_at is not null)
  )
);

create index if not exists usage_reservations_expiry_queue_idx
  on public.usage_reservations (expires_at, id)
  where state = 'reserved';
create index if not exists usage_reservations_account_created_idx
  on public.usage_reservations (account_id, created_at desc);

create table if not exists public.usage_reservation_allocations (
  account_id uuid not null,
  reservation_id uuid not null,
  credit_lot_id uuid not null,
  units bigint not null check (units > 0),
  created_at timestamptz not null default now(),
  primary key (reservation_id, credit_lot_id),
  constraint usage_reservation_allocations_reservation_fk
    foreign key (reservation_id, account_id)
    references public.usage_reservations(id, account_id) on delete cascade,
  constraint usage_reservation_allocations_lot_fk
    foreign key (credit_lot_id, account_id)
    references public.usage_credit_lots(id, account_id)
    on delete no action deferrable initially deferred
);

create index if not exists usage_reservation_allocations_lot_idx
  on public.usage_reservation_allocations (credit_lot_id, reservation_id);
create index if not exists usage_reservation_allocations_account_idx
  on public.usage_reservation_allocations (account_id, reservation_id);

-- A caller-safe balance projection. security_invoker is intentional: the view
-- obeys usage_credit_lots RLS and the caller's column grants rather than running
-- with its creator's rights.
create or replace view public.workspace_usage_credit_balances
with (security_invoker = true)
as
select
  l.account_id,
  l.resource_code,
  pg_catalog.sum(l.granted_units)::bigint as granted_units,
  pg_catalog.sum(l.consumed_units)::bigint as consumed_units,
  pg_catalog.sum(l.reserved_units)::bigint as reserved_units,
  pg_catalog.sum(l.revoked_units)::bigint as revoked_units,
  pg_catalog.sum(
    case
      when l.available_from <= pg_catalog.now()
       and (l.expires_at is null or l.expires_at > pg_catalog.now())
      then l.granted_units - l.consumed_units - l.reserved_units - l.revoked_units
      else 0
    end
  )::bigint as available_units,
  pg_catalog.sum(
    case
      when l.expires_at is not null and l.expires_at <= pg_catalog.now()
      then l.granted_units - l.consumed_units - l.reserved_units - l.revoked_units
      else 0
    end
  )::bigint as expired_unused_units,
  pg_catalog.min(l.expires_at) filter (
    where l.expires_at > pg_catalog.now()
      and l.granted_units - l.consumed_units - l.reserved_units - l.revoked_units > 0
  ) as next_expiration_at
from public.usage_credit_lots l
group by l.account_id, l.resource_code;

-- ---------------------------------------------------------------------------
-- Service-only credit grant and atomic reservation lifecycle
-- ---------------------------------------------------------------------------

create or replace function public.grant_usage_credits(
  p_account_id uuid,
  p_resource_code text,
  p_units bigint,
  p_source_type text,
  p_idempotency_key text,
  p_catalog_version text default null,
  p_billing_event_id uuid default null,
  p_available_from timestamptz default null,
  p_expires_at timestamptz default null,
  p_metadata jsonb default '{}'::jsonb
)
returns uuid
language plpgsql
security definer
set search_path = pg_catalog, pg_temp
as $$
declare
  v_id uuid;
  v_existing public.usage_credit_lots%rowtype;
  v_available_from timestamptz := coalesce(p_available_from, pg_catalog.now());
begin
  if p_units <= 0 then
    raise exception 'usage credit grant must be positive' using errcode = '22023';
  end if;
  if p_resource_code is null or p_resource_code !~ '^[a-z][a-z0-9_]{1,63}$' then
    raise exception 'invalid usage resource code' using errcode = '22023';
  end if;
  if p_idempotency_key is null or pg_catalog.length(pg_catalog.btrim(p_idempotency_key)) = 0 then
    raise exception 'usage credit idempotency key is required' using errcode = '22023';
  end if;
  if p_metadata is null or pg_catalog.jsonb_typeof(p_metadata) <> 'object' then
    raise exception 'usage credit metadata must be a JSON object' using errcode = '22023';
  end if;
  if p_expires_at is not null and p_expires_at <= v_available_from then
    raise exception 'usage credit expiration must follow availability' using errcode = '22023';
  end if;
  if not exists (select 1 from public.accounts a where a.id = p_account_id) then
    raise exception 'workspace not found' using errcode = '23503';
  end if;
  if p_billing_event_id is not null and not exists (
    select 1 from public.billing_events e
     where e.id = p_billing_event_id
       and e.account_id = p_account_id
  ) then
    raise exception 'billing event does not belong to workspace' using errcode = '23503';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(p_account_id::text || ':' || p_resource_code, 0)
  );

  select l.* into v_existing
    from public.usage_credit_lots l
   where l.account_id = p_account_id
     and l.resource_code = p_resource_code
     and l.idempotency_key = p_idempotency_key;

  if found then
    if v_existing.granted_units <> p_units
       or v_existing.source_type <> p_source_type
       or v_existing.catalog_version is distinct from p_catalog_version
       or v_existing.billing_event_id is distinct from p_billing_event_id
       or (p_available_from is not null and v_existing.available_from is distinct from p_available_from)
       or v_existing.expires_at is distinct from p_expires_at then
      raise exception 'usage credit idempotency key was reused with different grant data' using errcode = '22000';
    end if;
    return v_existing.id;
  end if;

  insert into public.usage_credit_lots (
    account_id, resource_code, source_type, idempotency_key, catalog_version,
    billing_event_id, granted_units, available_from, expires_at, metadata
  ) values (
    p_account_id, p_resource_code, p_source_type, p_idempotency_key, p_catalog_version,
    p_billing_event_id, p_units, v_available_from, p_expires_at, p_metadata
  )
  returning id into v_id;

  return v_id;
end;
$$;

create or replace function public.reserve_usage_credits(
  p_account_id uuid,
  p_resource_code text,
  p_units bigint,
  p_idempotency_key text,
  p_operation_type text default 'usage',
  p_expires_at timestamptz default (now() + interval '15 minutes'),
  p_metadata jsonb default '{}'::jsonb
)
returns uuid
language plpgsql
security definer
set search_path = pg_catalog, pg_temp
as $$
declare
  v_id uuid;
  v_remaining bigint := p_units;
  v_take bigint;
  v_lot record;
  v_existing public.usage_reservations%rowtype;
begin
  if p_units <= 0 then
    raise exception 'usage reservation must be positive' using errcode = '22023';
  end if;
  if p_resource_code is null or p_resource_code !~ '^[a-z][a-z0-9_]{1,63}$' then
    raise exception 'invalid usage resource code' using errcode = '22023';
  end if;
  if p_operation_type is null or p_operation_type !~ '^[a-z][a-z0-9_]{1,63}$' then
    raise exception 'invalid usage operation type' using errcode = '22023';
  end if;
  if p_idempotency_key is null or pg_catalog.length(pg_catalog.btrim(p_idempotency_key)) = 0 then
    raise exception 'usage reservation idempotency key is required' using errcode = '22023';
  end if;
  if p_metadata is null or pg_catalog.jsonb_typeof(p_metadata) <> 'object' then
    raise exception 'usage reservation metadata must be a JSON object' using errcode = '22023';
  end if;
  if p_expires_at <= pg_catalog.now() or p_expires_at > pg_catalog.now() + interval '24 hours' then
    raise exception 'usage reservation expiration must be within the next 24 hours' using errcode = '22023';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(p_account_id::text || ':' || p_resource_code, 0)
  );

  select r.* into v_existing
    from public.usage_reservations r
   where r.account_id = p_account_id
     and r.resource_code = p_resource_code
     and r.idempotency_key = p_idempotency_key;

  if found then
    if v_existing.units <> p_units or v_existing.operation_type <> p_operation_type then
      raise exception 'usage reservation idempotency key was reused with different request data' using errcode = '22000';
    end if;
    return v_existing.id;
  end if;

  insert into public.usage_reservations (
    account_id, resource_code, units, operation_type, idempotency_key, expires_at, metadata
  ) values (
    p_account_id, p_resource_code, p_units, p_operation_type, p_idempotency_key, p_expires_at, p_metadata
  )
  returning id into v_id;

  for v_lot in
    select
      l.id,
      l.granted_units - l.consumed_units - l.reserved_units - l.revoked_units as available_units
    from public.usage_credit_lots l
    where l.account_id = p_account_id
      and l.resource_code = p_resource_code
      and l.available_from <= pg_catalog.now()
      and (l.expires_at is null or l.expires_at > p_expires_at)
      and l.granted_units - l.consumed_units - l.reserved_units - l.revoked_units > 0
    order by l.expires_at asc nulls last, l.available_from asc, l.created_at asc, l.id asc
    for update
  loop
    exit when v_remaining = 0;
    v_take := least(v_remaining, v_lot.available_units);

    update public.usage_credit_lots l
       set reserved_units = l.reserved_units + v_take
     where l.id = v_lot.id;

    insert into public.usage_reservation_allocations (
      account_id, reservation_id, credit_lot_id, units
    ) values (
      p_account_id, v_id, v_lot.id, v_take
    );

    v_remaining := v_remaining - v_take;
  end loop;

  if v_remaining > 0 then
    raise exception 'insufficient usage credits for resource % (missing % units)', p_resource_code, v_remaining
      using errcode = 'P0001';
  end if;

  return v_id;
end;
$$;

create or replace function public.commit_usage_reservation(
  p_reservation_id uuid,
  p_finalization_key text
)
returns boolean
language plpgsql
security definer
set search_path = pg_catalog, pg_temp
as $$
declare
  v_reservation public.usage_reservations%rowtype;
  v_allocation record;
  v_updated integer;
begin
  if p_finalization_key is null or pg_catalog.length(pg_catalog.btrim(p_finalization_key)) = 0 then
    raise exception 'reservation finalization key is required' using errcode = '22023';
  end if;

  select r.* into v_reservation
    from public.usage_reservations r
   where r.id = p_reservation_id
   for update;

  if not found then
    raise exception 'usage reservation not found' using errcode = 'P0002';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_reservation.account_id::text || ':' || v_reservation.resource_code, 0)
  );

  if v_reservation.state = 'committed' then
    if v_reservation.finalization_key is distinct from p_finalization_key then
      raise exception 'reservation was committed with a different finalization key' using errcode = '22000';
    end if;
    return true;
  end if;
  if v_reservation.state in ('released', 'expired') then
    return false;
  end if;

  if v_reservation.expires_at <= pg_catalog.now() then
    for v_allocation in
      select a.credit_lot_id, a.units
        from public.usage_reservation_allocations a
       where a.reservation_id = p_reservation_id
       order by a.credit_lot_id
    loop
      update public.usage_credit_lots l
         set reserved_units = l.reserved_units - v_allocation.units
       where l.id = v_allocation.credit_lot_id
         and l.account_id = v_reservation.account_id
         and l.reserved_units >= v_allocation.units;
      get diagnostics v_updated = row_count;
      if v_updated <> 1 then
        raise exception 'usage credit reservation invariant failed while expiring' using errcode = 'P0001';
      end if;
    end loop;

    update public.usage_reservations
       set state = 'expired', released_at = pg_catalog.now(), finalization_key = p_finalization_key,
           release_reason = 'expired_before_commit'
     where id = p_reservation_id;
    return false;
  end if;

  for v_allocation in
    select a.credit_lot_id, a.units
      from public.usage_reservation_allocations a
     where a.reservation_id = p_reservation_id
     order by a.credit_lot_id
  loop
    update public.usage_credit_lots l
       set reserved_units = l.reserved_units - v_allocation.units,
           consumed_units = l.consumed_units + v_allocation.units
     where l.id = v_allocation.credit_lot_id
       and l.account_id = v_reservation.account_id
       and l.reserved_units >= v_allocation.units;
    get diagnostics v_updated = row_count;
    if v_updated <> 1 then
      raise exception 'usage credit reservation invariant failed while committing' using errcode = 'P0001';
    end if;
  end loop;

  update public.usage_reservations
     set state = 'committed', committed_at = pg_catalog.now(), finalization_key = p_finalization_key
   where id = p_reservation_id;
  return true;
end;
$$;

create or replace function public.release_usage_reservation(
  p_reservation_id uuid,
  p_finalization_key text,
  p_reason text default 'released'
)
returns boolean
language plpgsql
security definer
set search_path = pg_catalog, pg_temp
as $$
declare
  v_reservation public.usage_reservations%rowtype;
  v_allocation record;
  v_updated integer;
begin
  if p_finalization_key is null or pg_catalog.length(pg_catalog.btrim(p_finalization_key)) = 0 then
    raise exception 'reservation finalization key is required' using errcode = '22023';
  end if;

  select r.* into v_reservation
    from public.usage_reservations r
   where r.id = p_reservation_id
   for update;

  if not found then
    raise exception 'usage reservation not found' using errcode = 'P0002';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_reservation.account_id::text || ':' || v_reservation.resource_code, 0)
  );

  if v_reservation.state = 'committed' then
    return false;
  end if;
  if v_reservation.state in ('released', 'expired') then
    if v_reservation.finalization_key is distinct from p_finalization_key then
      raise exception 'reservation was finalized with a different key' using errcode = '22000';
    end if;
    return true;
  end if;

  for v_allocation in
    select a.credit_lot_id, a.units
      from public.usage_reservation_allocations a
     where a.reservation_id = p_reservation_id
     order by a.credit_lot_id
  loop
    update public.usage_credit_lots l
       set reserved_units = l.reserved_units - v_allocation.units
     where l.id = v_allocation.credit_lot_id
       and l.account_id = v_reservation.account_id
       and l.reserved_units >= v_allocation.units;
    get diagnostics v_updated = row_count;
    if v_updated <> 1 then
      raise exception 'usage credit reservation invariant failed while releasing' using errcode = 'P0001';
    end if;
  end loop;

  update public.usage_reservations
     set state = 'released', released_at = pg_catalog.now(), finalization_key = p_finalization_key,
         release_reason = pg_catalog.left(coalesce(p_reason, 'released'), 500)
   where id = p_reservation_id;
  return true;
end;
$$;

create or replace function public.expire_usage_reservations(p_limit integer default 250)
returns integer
language plpgsql
security definer
set search_path = pg_catalog, pg_temp
as $$
declare
  v_reservation record;
  v_allocation record;
  v_updated integer;
  v_expired integer := 0;
begin
  if p_limit < 1 or p_limit > 1000 then
    raise exception 'expiration batch limit must be between 1 and 1000' using errcode = '22023';
  end if;

  for v_reservation in
    select r.id, r.account_id, r.resource_code
      from public.usage_reservations r
     where r.state = 'reserved' and r.expires_at <= pg_catalog.now()
     order by
       pg_catalog.hashtextextended(r.account_id::text || ':' || r.resource_code, 0),
       r.account_id,
       r.resource_code,
       r.expires_at,
       r.id
     limit p_limit
     for update skip locked
  loop
    perform pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended(v_reservation.account_id::text || ':' || v_reservation.resource_code, 0)
    );

    for v_allocation in
      select a.credit_lot_id, a.units
        from public.usage_reservation_allocations a
       where a.reservation_id = v_reservation.id
       order by a.credit_lot_id
    loop
      update public.usage_credit_lots l
         set reserved_units = l.reserved_units - v_allocation.units
       where l.id = v_allocation.credit_lot_id
         and l.account_id = v_reservation.account_id
         and l.reserved_units >= v_allocation.units;
      get diagnostics v_updated = row_count;
      if v_updated <> 1 then
        raise exception 'usage credit reservation invariant failed in expiration sweep' using errcode = 'P0001';
      end if;
    end loop;

    update public.usage_reservations
       set state = 'expired', released_at = pg_catalog.now(),
           finalization_key = 'system-expiry:' || v_reservation.id::text,
           release_reason = 'reservation_expired'
     where id = v_reservation.id and state = 'reserved';
    get diagnostics v_updated = row_count;
    v_expired := v_expired + v_updated;
  end loop;

  return v_expired;
end;
$$;

-- ---------------------------------------------------------------------------
-- New workspaces and existing development workspaces begin on Flex exactly once
-- ---------------------------------------------------------------------------

-- There are no paying legacy customers at launch. Fail the whole migration if
-- that assumption changes instead of silently turning a paid/suspended legacy
-- workspace into Flex or issuing the wrong starter balance.
do $$
begin
  if exists (select 1 from public.accounts a where a.plan::text <> 'free') then
    raise exception 'pricing backfill requires an explicit review of non-free legacy workspaces'
      using errcode = 'P0001';
  end if;
end
$$;

create or replace function public.initialize_workspace_pricing()
returns trigger
language plpgsql
security definer
set search_path = pg_catalog, pg_temp
as $$
declare
  v_issued_at timestamptz := pg_catalog.now();
begin
  insert into public.workspace_entitlements (
    account_id, plan_code, billing_interval, billing_status, entitlement_state,
    catalog_version, platform_fee_bps, starter_credits_issued_at,
    feature_limits, feature_flags
  ) values (
    new.id, 'flex', 'none', 'free', 'active', '2026-08-15-preview', 125, v_issued_at,
    '{"office_users":1,"crew_users":2,"custom_domain_connections":1,"dedicated_business_numbers":0,"storage_gb":5,"quickbooks_connections":1,"voice_concurrent_calls":1,"voice_history_days":30}'::jsonb,
    '{"quickbooks":true,"shared_lgq_texting_number":true,"voice_included":false,"voice_advanced_routing":false}'::jsonb
  ) on conflict (account_id) do nothing;

  insert into public.usage_credit_lots (
    account_id, resource_code, source_type, idempotency_key, catalog_version,
    granted_units, available_from
  )
  select new.id, seed.resource_code, 'flex_starter',
         'flex-starter:2026-08-15-preview:' || seed.resource_code,
         '2026-08-15-preview', seed.units, v_issued_at
    from (values
      ('text_segments'::text, 50::bigint),
      ('marketing_email_sends'::text, 100::bigint),
      ('ai_intake_threads'::text, 30::bigint),
      ('ai_writing_drafts'::text, 25::bigint)
    ) as seed(resource_code, units)
  on conflict (account_id, resource_code, idempotency_key) do nothing;

  return new;
end;
$$;

drop trigger if exists initialize_workspace_pricing_trigger on public.accounts;
create trigger initialize_workspace_pricing_trigger
after insert on public.accounts
for each row execute function public.initialize_workspace_pricing();

insert into public.workspace_entitlements (
  account_id, plan_code, billing_interval, billing_status, entitlement_state,
  catalog_version, platform_fee_bps, starter_credits_issued_at,
  feature_limits, feature_flags
)
select
  a.id, 'flex', 'none', 'free', 'active', '2026-08-15-preview', 125, pg_catalog.now(),
  '{"office_users":1,"crew_users":2,"custom_domain_connections":1,"dedicated_business_numbers":0,"storage_gb":5,"quickbooks_connections":1,"voice_concurrent_calls":1,"voice_history_days":30}'::jsonb,
  '{"quickbooks":true,"shared_lgq_texting_number":true,"voice_included":false,"voice_advanced_routing":false}'::jsonb
from public.accounts a
on conflict (account_id) do nothing;

insert into public.usage_credit_lots (
  account_id, resource_code, source_type, idempotency_key, catalog_version,
  granted_units, available_from
)
select
  a.id,
  seed.resource_code,
  'flex_starter',
  'flex-starter:2026-08-15-preview:' || seed.resource_code,
  '2026-08-15-preview',
  seed.units,
  e.starter_credits_issued_at
from public.accounts a
join public.workspace_entitlements e on e.account_id = a.id
cross join (values
  ('text_segments'::text, 50::bigint),
  ('marketing_email_sends'::text, 100::bigint),
  ('ai_intake_threads'::text, 30::bigint),
  ('ai_writing_drafts'::text, 25::bigint)
) as seed(resource_code, units)
where e.plan_code = 'flex'
on conflict (account_id, resource_code, idempotency_key) do nothing;

-- ---------------------------------------------------------------------------
-- RLS and explicit Data API grants (Supabase's 2026 opt-in exposure model)
-- ---------------------------------------------------------------------------

alter table public.billing_subscriptions enable row level security;
alter table public.workspace_entitlements enable row level security;
alter table public.billing_events enable row level security;
alter table public.billing_payment_operations enable row level security;
alter table public.usage_credit_lots enable row level security;
alter table public.usage_reservations enable row level security;
alter table public.usage_reservation_allocations enable row level security;

drop policy if exists workspace_entitlements_owner_read on public.workspace_entitlements;
create policy workspace_entitlements_owner_read
on public.workspace_entitlements
for select
to authenticated
using ((select public.is_owner(account_id)));

drop policy if exists usage_credit_lots_owner_read on public.usage_credit_lots;
create policy usage_credit_lots_owner_read
on public.usage_credit_lots
for select
to authenticated
using ((select public.is_owner(account_id)));

-- Default privileges vary across Supabase projects. Revoke first, then grant
-- the exact API surface this migration intends.
revoke all on table public.billing_subscriptions from public, anon, authenticated;
revoke all on table public.workspace_entitlements from public, anon, authenticated;
revoke all on table public.billing_events from public, anon, authenticated;
revoke all on table public.billing_payment_operations from public, anon, authenticated;
revoke all on table public.usage_credit_lots from public, anon, authenticated;
revoke all on table public.usage_reservations from public, anon, authenticated;
revoke all on table public.usage_reservation_allocations from public, anon, authenticated;
revoke all on table public.workspace_usage_credit_balances from public, anon, authenticated;

grant select on table public.workspace_entitlements to authenticated;
grant select (
  account_id, resource_code, granted_units, consumed_units, reserved_units,
  revoked_units, available_from, expires_at
) on table public.usage_credit_lots to authenticated;
grant select on table public.workspace_usage_credit_balances to authenticated;

grant select, insert, update on table public.billing_subscriptions to service_role;
grant select, insert, update on table public.workspace_entitlements to service_role;
grant select, insert, update on table public.billing_events to service_role;
grant select, insert, update on table public.billing_payment_operations to service_role;
grant select on table public.usage_credit_lots to service_role;
grant select on table public.usage_reservations to service_role;
grant select on table public.usage_reservation_allocations to service_role;
grant select on table public.workspace_usage_credit_balances to service_role;

-- Every SECURITY DEFINER function is a backend capability, never a public RPC.
revoke all on function public.grant_usage_credits(uuid, text, bigint, text, text, text, uuid, timestamptz, timestamptz, jsonb)
  from public, anon, authenticated;
grant execute on function public.grant_usage_credits(uuid, text, bigint, text, text, text, uuid, timestamptz, timestamptz, jsonb)
  to service_role;

revoke all on function public.reserve_usage_credits(uuid, text, bigint, text, text, timestamptz, jsonb)
  from public, anon, authenticated;
grant execute on function public.reserve_usage_credits(uuid, text, bigint, text, text, timestamptz, jsonb)
  to service_role;

revoke all on function public.commit_usage_reservation(uuid, text)
  from public, anon, authenticated;
grant execute on function public.commit_usage_reservation(uuid, text)
  to service_role;

revoke all on function public.release_usage_reservation(uuid, text, text)
  from public, anon, authenticated;
grant execute on function public.release_usage_reservation(uuid, text, text)
  to service_role;

revoke all on function public.expire_usage_reservations(integer)
  from public, anon, authenticated;
grant execute on function public.expire_usage_reservations(integer)
  to service_role;

revoke all on function public.initialize_workspace_pricing()
  from public, anon, authenticated;
grant execute on function public.initialize_workspace_pricing()
  to service_role;

commit;

-- Source: migrations/20260815220739_pricing_entitlements_hardening.sql
-- Harden the pricing-entitlement foundation after validating it against a
-- legacy Supabase project whose default privileges predate opt-in Data API
-- exposure.

begin;

-- GRANT is additive. Remove any legacy default service_role privileges before
-- rebuilding the exact backend surface intended by the foundation migration.
revoke all on table public.billing_subscriptions from service_role;
revoke all on table public.workspace_entitlements from service_role;
revoke all on table public.billing_events from service_role;
revoke all on table public.billing_payment_operations from service_role;
revoke all on table public.usage_credit_lots from service_role;
revoke all on table public.usage_reservations from service_role;
revoke all on table public.usage_reservation_allocations from service_role;
revoke all on table public.workspace_usage_credit_balances from service_role;

grant select, insert, update on table public.billing_subscriptions to service_role;
grant select, insert, update on table public.workspace_entitlements to service_role;
grant select, insert, update on table public.billing_events to service_role;
grant select, insert, update on table public.billing_payment_operations to service_role;
grant select on table public.usage_credit_lots to service_role;
grant select on table public.usage_reservations to service_role;
grant select on table public.usage_reservation_allocations to service_role;
grant select on table public.workspace_usage_credit_balances to service_role;

-- A provider object may reconcile to only one LGQ payment in its connected
-- account. These indexes also make accidental double refunds/counting fail
-- closed at the database boundary.
create unique index if not exists payments_stripe_account_charge_unique
  on public.payments (stripe_account_id, stripe_charge_id)
  where stripe_account_id is not null and stripe_charge_id is not null;
create unique index if not exists payments_stripe_account_intent_unique
  on public.payments (stripe_account_id, stripe_payment_intent)
  where stripe_account_id is not null and stripe_payment_intent is not null;
create unique index if not exists payments_stripe_account_session_unique
  on public.payments (stripe_account_id, stripe_checkout_session)
  where stripe_account_id is not null and stripe_checkout_session is not null;

-- A durable operation must use the same connected account as its payment.
-- The original two-column FK proved the workspace but not the Stripe scope.
do $$
begin
  if not exists (
    select 1
      from pg_catalog.pg_constraint
     where conrelid = 'public.payments'::pg_catalog.regclass
       and conname = 'payments_id_account_stripe_account_unique'
  ) then
    alter table public.payments
      add constraint payments_id_account_stripe_account_unique
      unique (id, account_id, stripe_account_id);
  end if;
end
$$;

alter table public.billing_payment_operations
  drop constraint if exists billing_payment_operations_payment_fk;
alter table public.billing_payment_operations
  add constraint billing_payment_operations_payment_fk
  foreign key (payment_id, account_id, stripe_account_id)
  references public.payments(id, account_id, stripe_account_id)
  on delete restrict;

-- NULL is not a valid batch size. PostgreSQL treats LIMIT NULL as unlimited,
-- which would defeat the bounded expiration-worker contract.
create or replace function public.expire_usage_reservations(p_limit integer default 250)
returns integer
language plpgsql
security definer
set search_path = pg_catalog, pg_temp
as $$
declare
  v_reservation record;
  v_allocation record;
  v_updated integer;
  v_expired integer := 0;
begin
  if p_limit is null or p_limit < 1 or p_limit > 1000 then
    raise exception 'expiration batch limit must be between 1 and 1000' using errcode = '22023';
  end if;

  for v_reservation in
    select r.id, r.account_id, r.resource_code
      from public.usage_reservations r
     where r.state = 'reserved' and r.expires_at <= pg_catalog.now()
     order by
       pg_catalog.hashtextextended(r.account_id::text || ':' || r.resource_code, 0),
       r.account_id,
       r.resource_code,
       r.expires_at,
       r.id
     limit p_limit
     for update skip locked
  loop
    perform pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended(v_reservation.account_id::text || ':' || v_reservation.resource_code, 0)
    );

    for v_allocation in
      select a.credit_lot_id, a.units
        from public.usage_reservation_allocations a
       where a.reservation_id = v_reservation.id
       order by a.credit_lot_id
    loop
      update public.usage_credit_lots l
         set reserved_units = l.reserved_units - v_allocation.units
       where l.id = v_allocation.credit_lot_id
         and l.account_id = v_reservation.account_id
         and l.reserved_units >= v_allocation.units;
      get diagnostics v_updated = row_count;
      if v_updated <> 1 then
        raise exception 'usage credit reservation invariant failed in expiration sweep' using errcode = 'P0001';
      end if;
    end loop;

    update public.usage_reservations
       set state = 'expired', released_at = pg_catalog.now(),
           finalization_key = 'system-expiry:' || v_reservation.id::text,
           release_reason = 'reservation_expired'
     where id = v_reservation.id and state = 'reserved';
    get diagnostics v_updated = row_count;
    v_expired := v_expired + v_updated;
  end loop;

  return v_expired;
end;
$$;

revoke all on function public.expire_usage_reservations(integer) from service_role;
grant execute on function public.expire_usage_reservations(integer) to service_role;

commit;

-- Source: migrations/20260816061500_paid_plan_monthly_allowance_reset.sql
-- DARK paid-plan monthly allowance reset foundation.
--
-- This migration creates no route, cron, queue consumer, or environment
-- switch. A future server-only scheduler may call one RPC for one workspace.
-- The RPC derives plan and units exclusively from locked subscription and
-- entitlement rows, advances one exact calendar-month window at most, and is
-- atomic with all four credit lots. Annual payment cadence never pre-issues a
-- year of usage.

begin;

-- Composite ownership is useful to the immutable reset ledger and prevents an
-- audit row from ever pairing a subscription with another workspace.
alter table public.billing_subscriptions
  add constraint billing_subscriptions_id_account_unique
  unique (id, account_id);

create table public.billing_allowance_reset_operations (
  id uuid primary key default pg_catalog.gen_random_uuid(),
  account_id uuid not null,
  billing_subscription_id uuid not null,
  operation_key text not null check (
    operation_key ~ '^paid-plan-monthly-reset:v1:[0-9a-f-]{36}:[0-9]+$'
    and pg_catalog.length(operation_key) <= 200
  ),
  plan_code text not null check (plan_code in ('solo', 'growth', 'scale')),
  billing_interval text not null check (billing_interval in ('monthly', 'annual')),
  catalog_version text not null check (catalog_version = '2026-08-15-preview'),
  provider_period_start timestamptz not null,
  provider_period_end timestamptz not null,
  allowance_window_start timestamptz not null,
  allowance_window_end timestamptz not null,
  status text not null check (status in ('completed', 'blocked_catchup')),
  inserted_lot_count integer not null check (inserted_lot_count between 0 and 4),
  verified_lot_count integer not null check (verified_lot_count between 0 and 4),
  block_reason text check (block_reason in ('more_than_one_boundary_overdue')),
  metadata jsonb not null default '{}'::jsonb
    check (pg_catalog.jsonb_typeof(metadata) = 'object'),
  completed_at timestamptz not null default pg_catalog.now(),
  created_at timestamptz not null default pg_catalog.now(),
  constraint billing_allowance_reset_operations_subscription_fk
    foreign key (billing_subscription_id, account_id)
    references public.billing_subscriptions(id, account_id)
    on delete restrict,
  constraint billing_allowance_reset_operations_window_check check (
    provider_period_end > provider_period_start
    and allowance_window_end > allowance_window_start
    and allowance_window_start >= provider_period_start
    and allowance_window_end <= provider_period_end
  ),
  constraint billing_allowance_reset_operations_status_shape_check check (
    (
      status = 'completed'
      and inserted_lot_count between 0 and 4
      and verified_lot_count = 4
      and block_reason is null
    )
    or (
      status = 'blocked_catchup'
      and inserted_lot_count = 0
      and verified_lot_count = 0
      and block_reason = 'more_than_one_boundary_overdue'
    )
  ),
  constraint billing_allowance_reset_operations_window_unique
    unique (billing_subscription_id, allowance_window_start),
  constraint billing_allowance_reset_operations_business_key_unique
    unique (account_id, operation_key)
);

create index billing_allowance_reset_operations_account_created_idx
  on public.billing_allowance_reset_operations (account_id, created_at desc);
create index billing_allowance_reset_operations_subscription_account_idx
  on public.billing_allowance_reset_operations (billing_subscription_id, account_id);

alter table public.billing_allowance_reset_operations enable row level security;
alter table public.billing_allowance_reset_operations force row level security;

-- Terminal audit rows are append-only. The reset RPC inserts the terminal row
-- in the same transaction as its credits (or its explicit catch-up block).
create function public.protect_billing_allowance_reset_operation()
returns trigger
language plpgsql
set search_path = pg_catalog, pg_temp
as $$
begin
  raise exception 'paid-plan allowance reset audit rows are immutable'
    using errcode = '42501';
end;
$$;

create trigger protect_billing_allowance_reset_operation_trigger
before update or delete on public.billing_allowance_reset_operations
for each row execute function public.protect_billing_allowance_reset_operation();

revoke all on function public.protect_billing_allowance_reset_operation()
  from public, anon, authenticated, service_role;

-- Apply at most one exact next monthly window for one workspace.
--
-- There is deliberately no p_plan_code, p_units, p_window_start, p_window_end,
-- or p_now. Provider state and the entitlement cursor are the only authority.
-- Locks follow the projector's subscription-then-entitlement order.
create function public.apply_paid_plan_monthly_allowance_reset(
  p_account_id uuid
)
returns table (
  reset_status text,
  operation_id uuid,
  workspace_id uuid,
  billing_subscription_id uuid,
  allowance_window_start timestamptz,
  allowance_window_end timestamptz,
  inserted_lot_count integer,
  verified_lot_count integer,
  next_allowance_reset_at timestamptz,
  reason_code text
)
language plpgsql
security definer
set search_path = pg_catalog, pg_temp
set timezone to 'UTC'
as $$
declare
  v_now timestamptz := pg_catalog.clock_timestamp();
  v_subscription public.billing_subscriptions%rowtype;
  v_entitlement public.workspace_entitlements%rowtype;
  v_existing_operation public.billing_allowance_reset_operations%rowtype;
  v_existing_lot public.usage_credit_lots%rowtype;
  v_operation_id uuid := pg_catalog.gen_random_uuid();
  v_operation_key text;
  v_window_start timestamptz;
  v_window_end timestamptz;
  v_anchor_boundary timestamptz;
  v_next_anchor_boundary timestamptz;
  v_anchor_index integer;
  v_inserted integer;
  v_inserted_total integer := 0;
  v_verified_total integer := 0;
  v_resource record;
begin
  if p_account_id is null then
    raise exception 'workspace ID is required' using errcode = '22023';
  end if;

  -- The partial unique index permits at most one live subscription. Canceled
  -- rows are intentionally not candidates: cancellation always fails closed.
  select s.*
    into v_subscription
    from public.billing_subscriptions s
   where s.account_id = p_account_id
     and s.status in (
       'incomplete', 'trialing', 'active', 'past_due', 'unpaid', 'paused'
     )
   for update;

  if not found then
    return query select
      'not_eligible'::text, null::uuid, p_account_id, null::uuid,
      null::timestamptz, null::timestamptz, 0, 0, null::timestamptz,
      'subscription_not_live'::text;
    return;
  end if;

  select e.*
    into v_entitlement
    from public.workspace_entitlements e
   where e.account_id = p_account_id
   for update;
  if not found then
    raise exception 'workspace entitlement snapshot was not found'
      using errcode = 'P0002';
  end if;

  -- Both provider projection and entitlement access must independently say
  -- active. Open failed invoices also fail closed if a corrupted entitlement
  -- snapshot were ever to remain active.
  if v_subscription.status <> 'active'
     or (
       v_subscription.latest_invoice_status = 'open'
       and v_subscription.latest_invoice_event_type in (
         'invoice.payment_failed', 'invoice.payment_action_required'
       )
     )
     -- Uncollectible is terminal provider truth even when a later generic
     -- invoice.updated event becomes the latest event type for that invoice.
     or v_subscription.latest_invoice_status = 'uncollectible' then
    return query select
      'not_eligible'::text, null::uuid, p_account_id, v_subscription.id,
      null::timestamptz, null::timestamptz, 0, 0,
      v_entitlement.next_allowance_reset_at, 'subscription_not_active'::text;
    return;
  end if;

  if v_entitlement.billing_status <> 'active'
     or v_entitlement.entitlement_state <> 'active' then
    return query select
      'not_eligible'::text, null::uuid, p_account_id, v_subscription.id,
      null::timestamptz, null::timestamptz, 0, 0,
      v_entitlement.next_allowance_reset_at, 'entitlement_not_active'::text;
    return;
  end if;

  if v_subscription.plan_code not in ('solo', 'growth', 'scale')
     or v_subscription.billing_interval not in ('monthly', 'annual')
     or v_subscription.catalog_version <> '2026-08-15-preview'
     or v_entitlement.plan_code is distinct from v_subscription.plan_code
     or v_entitlement.billing_interval is distinct from v_subscription.billing_interval
     or v_entitlement.catalog_version is distinct from v_subscription.catalog_version
     or v_entitlement.period_start is distinct from v_subscription.current_period_start
     or v_entitlement.period_end is distinct from v_subscription.current_period_end then
    raise exception 'paid-plan allowance authority is inconsistent'
      using errcode = '22000';
  end if;

  if v_subscription.current_period_start is null
     or v_subscription.current_period_end is null
     or v_subscription.current_period_end <= v_subscription.current_period_start
     or v_entitlement.next_allowance_reset_at is null then
    return query select
      'not_eligible'::text, null::uuid, p_account_id, v_subscription.id,
      null::timestamptz, null::timestamptz, 0, 0,
      v_entitlement.next_allowance_reset_at, 'allowance_schedule_missing'::text;
    return;
  end if;

  v_window_start := v_entitlement.next_allowance_reset_at;

  if v_subscription.billing_interval = 'monthly' then
    -- A paid monthly renewal first advances Stripe's provider period. The
    -- exact next cursor must then equal that new period start. If it still
    -- equals the current period end, there is no due window yet.
    if v_window_start = v_subscription.current_period_end then
      return query select
        'not_due'::text, null::uuid, p_account_id, v_subscription.id,
        null::timestamptz, null::timestamptz, 0, 0, v_window_start,
        'waiting_for_provider_period'::text;
      return;
    end if;

    -- An active Subscription object can advance before its renewal invoice is
    -- paid. Do not let that provider-period update become payment evidence.
    if v_subscription.latest_invoice_status is distinct from 'paid'
       or v_subscription.latest_invoice_event_type not in (
         'invoice.paid', 'invoice.payment_succeeded'
       )
       or v_subscription.last_paid_at is null
       or v_subscription.last_paid_at < v_subscription.current_period_start then
      return query select
        'not_eligible'::text, null::uuid, p_account_id, v_subscription.id,
        null::timestamptz, null::timestamptz, 0, 0, v_window_start,
        'current_provider_period_not_paid'::text;
      return;
    end if;

    if v_window_start is distinct from v_subscription.current_period_start then
      raise exception 'monthly allowance cursor is not the provider period start'
        using errcode = '22000';
    end if;
    v_window_end := least(
      v_subscription.current_period_end,
      (
        v_subscription.current_period_start at time zone 'UTC'
        + pg_catalog.make_interval(months => 1)
      ) at time zone 'UTC'
    );
  else
    -- Annual billing changes only payment cadence. Derive every boundary from
    -- the original provider-period start, never by repeatedly adding a month
    -- to the prior cursor (which would drift after dates such as January 31).
    if v_window_start = v_subscription.current_period_end then
      return query select
        'not_due'::text, null::uuid, p_account_id, v_subscription.id,
        null::timestamptz, null::timestamptz, 0, 0, v_window_start,
        'waiting_for_provider_period'::text;
      return;
    end if;
    if v_window_start < v_subscription.current_period_start
       or v_window_start > v_subscription.current_period_end then
      raise exception 'annual allowance cursor is outside the provider period'
        using errcode = '22000';
    end if;

    -- A Stripe annual period has at most twelve monthly starts. The fixed
    -- bound is also a fail-closed guard against malformed provider periods.
    for v_anchor_index in 1..11 loop
      v_anchor_boundary := (
        v_subscription.current_period_start at time zone 'UTC'
        + pg_catalog.make_interval(months => v_anchor_index)
      ) at time zone 'UTC';
      if v_anchor_boundary = v_window_start then
        v_next_anchor_boundary := (
          v_subscription.current_period_start at time zone 'UTC'
          + pg_catalog.make_interval(months => v_anchor_index + 1)
        ) at time zone 'UTC';
        exit;
      end if;
    end loop;

    if v_anchor_boundary is distinct from v_window_start
       or v_next_anchor_boundary is null then
      raise exception 'annual allowance cursor is not an anchored monthly boundary'
        using errcode = '22000';
    end if;
    v_window_end := least(v_subscription.current_period_end, v_next_anchor_boundary);
  end if;

  if v_window_end <= v_window_start then
    raise exception 'paid-plan allowance window is empty'
      using errcode = '22000';
  end if;

  if v_now < v_window_start then
    return query select
      'not_due'::text, null::uuid, p_account_id, v_subscription.id,
      v_window_start, v_window_end, 0, 0, v_window_start,
      'allowance_window_not_started'::text;
    return;
  end if;

  v_operation_key := 'paid-plan-monthly-reset:v1:' || v_subscription.id::text || ':'
    || pg_catalog.date_part('epoch', v_window_start)::bigint::text;

  select o.*
    into v_existing_operation
    from public.billing_allowance_reset_operations o
   where o.billing_subscription_id = v_subscription.id
     and o.allowance_window_start = v_window_start;

  if found then
    if v_existing_operation.account_id is distinct from p_account_id
       or v_existing_operation.operation_key is distinct from v_operation_key
       or v_existing_operation.plan_code is distinct from v_subscription.plan_code
       or v_existing_operation.billing_interval is distinct from v_subscription.billing_interval
       or v_existing_operation.catalog_version is distinct from v_subscription.catalog_version
       or v_existing_operation.provider_period_start is distinct from v_subscription.current_period_start
       or v_existing_operation.provider_period_end is distinct from v_subscription.current_period_end
       or v_existing_operation.allowance_window_end is distinct from v_window_end then
      raise exception 'paid-plan allowance operation identity is inconsistent'
        using errcode = '22000';
    end if;
    if v_existing_operation.status = 'blocked_catchup' then
      return query select
        'blocked_catchup'::text, v_existing_operation.id, p_account_id,
        v_subscription.id, v_window_start, v_window_end, 0, 0, v_window_start,
        'catchup_requires_reconciliation'::text;
      return;
    end if;
    -- A completed operation and an unadvanced cursor cannot be produced by
    -- this atomic RPC. Refuse to conceal out-of-band state corruption.
    raise exception 'completed allowance operation has an unadvanced cursor'
      using errcode = '22000';
  end if;

  -- Policy decision: once the exact next window has fully elapsed, do not
  -- skip it, backfill it, or bulk-issue later months. Record the block and wait
  -- for explicit operator/provider reconciliation.
  if v_now >= v_window_end then
    insert into public.billing_allowance_reset_operations (
      id, account_id, billing_subscription_id, operation_key,
      plan_code, billing_interval, catalog_version,
      provider_period_start, provider_period_end,
      allowance_window_start, allowance_window_end,
      status, inserted_lot_count, verified_lot_count, block_reason, metadata
    ) values (
      v_operation_id, p_account_id, v_subscription.id, v_operation_key,
      v_subscription.plan_code, v_subscription.billing_interval,
      v_subscription.catalog_version,
      v_subscription.current_period_start, v_subscription.current_period_end,
      v_window_start, v_window_end,
      'blocked_catchup', 0, 0, 'more_than_one_boundary_overdue',
      pg_catalog.jsonb_build_object(
        'schema', 'paid_plan_monthly_allowance_reset_v1',
        'policy', 'fail_closed_no_retroactive_catchup'
      )
    );

    return query select
      'blocked_catchup'::text, v_operation_id, p_account_id,
      v_subscription.id, v_window_start, v_window_end, 0, 0, v_window_start,
      'catchup_requires_reconciliation'::text;
    return;
  end if;

  -- Exactly four canonical grants. Values are database-owned and match the
  -- initial subscription projector for this immutable catalog version.
  for v_resource in
    select * from (values
      ('text_segments'::text, case v_subscription.plan_code
        when 'solo' then 500 when 'growth' then 1500 when 'scale' then 1500 end),
      ('marketing_email_sends'::text, case v_subscription.plan_code
        when 'solo' then 500 when 'growth' then 2500 when 'scale' then 2500 end),
      ('ai_intake_threads'::text, case v_subscription.plan_code
        when 'solo' then 250 when 'growth' then 500 when 'scale' then 500 end),
      ('ai_writing_drafts'::text, case v_subscription.plan_code
        when 'solo' then 50 when 'growth' then 250 when 'scale' then 250 end)
    ) as resources(resource_code, units)
  loop
    -- A second key overlapping this exact subscription/window is never a
    -- legitimate catch-up or plan grant. Purchased credits are not selected,
    -- updated, expired, or otherwise touched by this RPC.
    if exists (
      select 1
        from public.usage_credit_lots l
       where l.account_id = p_account_id
         and l.resource_code = v_resource.resource_code
         and l.source_type = 'plan_period'
         and l.metadata ->> 'provider_subscription_id' =
           v_subscription.provider_subscription_id
         and l.idempotency_key <> (
           'plan-period:' || v_subscription.catalog_version || ':'
           || v_subscription.provider_subscription_id || ':'
           || pg_catalog.date_part('epoch', v_window_start)::bigint::text || ':'
           || v_resource.resource_code
         )
         and tstzrange(l.available_from, l.expires_at, '[)')
           && tstzrange(v_window_start, v_window_end, '[)')
    ) then
      raise exception 'paid-plan allowance window overlaps another grant'
        using errcode = '22000';
    end if;

    insert into public.usage_credit_lots (
      account_id, resource_code, source_type, idempotency_key,
      catalog_version, billing_event_id, granted_units,
      available_from, expires_at, metadata
    ) values (
      p_account_id,
      v_resource.resource_code,
      'plan_period',
      'plan-period:' || v_subscription.catalog_version || ':'
        || v_subscription.provider_subscription_id || ':'
        || pg_catalog.date_part('epoch', v_window_start)::bigint::text || ':'
        || v_resource.resource_code,
      v_subscription.catalog_version,
      null,
      v_resource.units,
      v_window_start,
      v_window_end,
      pg_catalog.jsonb_build_object(
        'schema', 'paid_plan_monthly_allowance_v1',
        'plan_code', v_subscription.plan_code,
        'billing_interval', v_subscription.billing_interval,
        'provider_subscription_id', v_subscription.provider_subscription_id,
        'allowance_start', v_window_start,
        'allowance_end', v_window_end,
        'reset_operation_id', v_operation_id
      )
    ) on conflict (account_id, resource_code, idempotency_key) do nothing;
    get diagnostics v_inserted = row_count;
    v_inserted_total := v_inserted_total + v_inserted;

    select l.*
      into v_existing_lot
      from public.usage_credit_lots l
     where l.account_id = p_account_id
       and l.resource_code = v_resource.resource_code
       and l.idempotency_key =
         'plan-period:' || v_subscription.catalog_version || ':'
         || v_subscription.provider_subscription_id || ':'
         || pg_catalog.date_part('epoch', v_window_start)::bigint::text || ':'
         || v_resource.resource_code
     for update;

    if not found
       or v_existing_lot.source_type <> 'plan_period'
       or v_existing_lot.catalog_version is distinct from v_subscription.catalog_version
       or v_existing_lot.granted_units is distinct from v_resource.units
       or v_existing_lot.available_from is distinct from v_window_start
       or v_existing_lot.expires_at is distinct from v_window_end
       or v_existing_lot.metadata ->> 'schema' <> 'paid_plan_monthly_allowance_v1'
       or v_existing_lot.metadata ->> 'plan_code' <> v_subscription.plan_code
       or v_existing_lot.metadata ->> 'billing_interval' <> v_subscription.billing_interval
       or v_existing_lot.metadata ->> 'provider_subscription_id' <>
         v_subscription.provider_subscription_id
       or (v_existing_lot.metadata ->> 'allowance_start')::timestamptz
         is distinct from v_window_start
       or (v_existing_lot.metadata ->> 'allowance_end')::timestamptz
         is distinct from v_window_end then
      raise exception 'monthly allowance idempotency binding is inconsistent'
        using errcode = '22000';
    end if;
    v_verified_total := v_verified_total + 1;
  end loop;

  if v_verified_total <> 4 then
    raise exception 'monthly allowance did not verify all canonical resources'
      using errcode = '22000';
  end if;

  insert into public.billing_allowance_reset_operations (
    id, account_id, billing_subscription_id, operation_key,
    plan_code, billing_interval, catalog_version,
    provider_period_start, provider_period_end,
    allowance_window_start, allowance_window_end,
    status, inserted_lot_count, verified_lot_count, metadata
  ) values (
    v_operation_id, p_account_id, v_subscription.id, v_operation_key,
    v_subscription.plan_code, v_subscription.billing_interval,
    v_subscription.catalog_version,
    v_subscription.current_period_start, v_subscription.current_period_end,
    v_window_start, v_window_end,
    'completed', v_inserted_total, v_verified_total,
    pg_catalog.jsonb_build_object(
      'schema', 'paid_plan_monthly_allowance_reset_v1',
      'grant_schema', 'paid_plan_monthly_allowance_v1'
    )
  );

  update public.workspace_entitlements e
     set next_allowance_reset_at = v_window_end,
         version = e.version + 1,
         effective_at = greatest(e.effective_at, v_window_start),
         updated_at = pg_catalog.now()
   where e.account_id = p_account_id
     and e.next_allowance_reset_at = v_window_start;
  get diagnostics v_inserted = row_count;
  if v_inserted <> 1 then
    raise exception 'monthly allowance cursor changed during its locked reset'
      using errcode = '40001';
  end if;

  return query select
    'completed'::text, v_operation_id, p_account_id, v_subscription.id,
    v_window_start, v_window_end, v_inserted_total, v_verified_total,
    v_window_end, null::text;
end;
$$;

-- Explicit 2026 Data API hardening: the audit table is backend-readable only,
-- while all mutation is constrained by the sole security-definer RPC.
revoke all on table public.billing_allowance_reset_operations
  from public, anon, authenticated, service_role;
grant select on table public.billing_allowance_reset_operations to service_role;

revoke all on function public.apply_paid_plan_monthly_allowance_reset(uuid)
  from public, anon, authenticated, service_role;
grant execute on function public.apply_paid_plan_monthly_allowance_reset(uuid)
  to service_role;

comment on table public.billing_allowance_reset_operations is
  'PII-free terminal audit for one-window paid-plan usage resets; no active scheduler exists.';
comment on function public.apply_paid_plan_monthly_allowance_reset(uuid) is
  'Dark atomic reset for exactly one anchored paid-plan monthly usage window; service role only.';

commit;

-- Activation blockers (intentionally unresolved here):
--   1. Apply and validate the subscription-event projector first.
--   2. Add a server-only due-workspace selector and scheduler with overlap lock.
--   3. Build an operator reconciliation path for blocked_catchup rows.
--   4. Run Stripe test-clock coverage across month-end/leap-day anchors.
--   5. Add monitoring for not_eligible, failures, and blocked_catchup outcomes.

-- Source: migrations/20260816083000_direct_payment_settlement_foundation.sql
-- DARK one-off direct-payment settlement and notification foundation.
--
-- This migration adds no route, cron, caller, environment flag, or provider
-- egress. The existing connected-payment projector remains the only intended
-- payment-success writer. Its processing -> paid UPDATE fires the trigger below
-- in the same transaction. The trigger re-proves the exact full-outstanding
-- invoice scope, preserves a real signature timestamp, and queues one PII-free
-- task. Any invariant or queue write failure aborts the payment projection.

begin;

-- A provider request can succeed even when the worker loses the response. Such
-- a pending row is not retryable evidence: on lease recovery it is explicitly
-- indeterminate, so no future worker can blindly send the same text again.
alter table public.sms_events
  drop constraint if exists sms_events_status_check;
alter table public.sms_events
  add constraint sms_events_status_check check (
    status in ('pending', 'sent', 'failed', 'opted_out', 'indeterminate')
  );

create table public.billing_direct_payment_settlement_tasks (
  id uuid primary key default pg_catalog.gen_random_uuid(),
  payment_id uuid not null unique,
  billing_event_id uuid not null unique
    references public.billing_events(id) on delete restrict,
  account_id uuid not null references public.accounts(id) on delete restrict,
  job_id uuid not null references public.jobs(id) on delete restrict,
  invoice_id uuid not null references public.invoices(id) on delete restrict,
  settled_at timestamptz not null,
  task_state text not null default 'ready'
    check (task_state in ('ready', 'leased', 'retry_wait', 'completed', 'dead_letter')),
  claim_token uuid,
  lease_expires_at timestamptz,
  attempt_count integer not null default 0 check (attempt_count between 0 and 8),
  next_attempt_at timestamptz,
  feed_status text not null default 'pending'
    check (feed_status in ('pending', 'recorded')),
  sms_status text not null default 'pending'
    check (
      sms_status in (
        'pending', 'dispatching', 'sent',
        'skipped_no_consent', 'skipped_opted_out', 'indeterminate'
      )
    ),
  sms_event_id uuid references public.sms_events(id) on delete restrict,
  last_error_code text check (
    last_error_code is null or last_error_code ~ '^[a-z][a-z0-9_]{2,99}$'
  ),
  completed_at timestamptz,
  dead_lettered_at timestamptz,
  created_at timestamptz not null default pg_catalog.now(),
  updated_at timestamptz not null default pg_catalog.now(),
  constraint billing_direct_payment_settlement_payment_scope_fk
    foreign key (payment_id, account_id)
    references public.payments(id, account_id) on delete restrict,
  constraint billing_direct_payment_settlement_task_shape_check check (
    (
      task_state = 'ready'
      and claim_token is null
      and lease_expires_at is null
      and attempt_count = 0
      and next_attempt_at is null
      and last_error_code is null
      and completed_at is null
      and dead_lettered_at is null
    )
    or (
      task_state = 'leased'
      and claim_token is not null
      and lease_expires_at is not null
      and attempt_count between 1 and 8
      and next_attempt_at is null
      and completed_at is null
      and dead_lettered_at is null
    )
    or (
      task_state = 'retry_wait'
      and claim_token is null
      and lease_expires_at is null
      and attempt_count between 1 and 7
      and next_attempt_at is not null
      and last_error_code is not null
      and completed_at is null
      and dead_lettered_at is null
    )
    or (
      task_state = 'completed'
      and claim_token is null
      and lease_expires_at is null
      and attempt_count between 1 and 8
      and next_attempt_at is null
      and feed_status = 'recorded'
      and sms_status in ('sent', 'skipped_no_consent', 'skipped_opted_out')
      and last_error_code is null
      and completed_at is not null
      and dead_lettered_at is null
    )
    or (
      task_state = 'dead_letter'
      and claim_token is null
      and lease_expires_at is null
      and attempt_count between 1 and 8
      and next_attempt_at is null
      and last_error_code is not null
      and completed_at is null
      and dead_lettered_at is not null
    )
  ),
  constraint billing_direct_payment_settlement_sms_shape_check check (
    (
      sms_status = 'pending'
      and sms_event_id is null
    )
    or (
      sms_status in ('skipped_no_consent', 'skipped_opted_out')
      and sms_event_id is null
      and task_state = 'completed'
    )
    or (
      sms_status = 'dispatching'
      and sms_event_id is not null
      and task_state = 'leased'
    )
    or (
      sms_status = 'sent'
      and sms_event_id is not null
      and task_state = 'completed'
    )
    or (
      sms_status = 'indeterminate'
      and sms_event_id is not null
      and task_state = 'dead_letter'
    )
  )
);

create unique index billing_direct_payment_settlement_claim_unique
  on public.billing_direct_payment_settlement_tasks (claim_token)
  where claim_token is not null;
create index billing_direct_payment_settlement_queue_idx
  on public.billing_direct_payment_settlement_tasks (
    task_state, next_attempt_at, created_at, id
  )
  where task_state in ('ready', 'leased', 'retry_wait');
create index billing_direct_payment_settlement_dead_letter_idx
  on public.billing_direct_payment_settlement_tasks (dead_lettered_at desc, id)
  where task_state = 'dead_letter';

create table public.billing_direct_payment_settlement_attempts (
  id uuid primary key default pg_catalog.gen_random_uuid(),
  task_id uuid not null
    references public.billing_direct_payment_settlement_tasks(id) on delete restrict,
  claim_token uuid not null unique,
  attempt_number integer not null check (attempt_number between 1 and 8),
  lease_expires_at timestamptz not null,
  outcome_status text check (
    outcome_status is null
    or outcome_status in (
      'completed', 'failed_retryable', 'failed_terminal', 'sms_indeterminate'
    )
  ),
  error_code text check (
    error_code is null or error_code ~ '^[a-z][a-z0-9_]{2,99}$'
  ),
  feed_status text check (feed_status is null or feed_status in ('pending', 'recorded')),
  sms_status text check (
    sms_status is null
    or sms_status in (
      'pending', 'dispatching', 'sent',
      'skipped_no_consent', 'skipped_opted_out', 'indeterminate'
    )
  ),
  claimed_at timestamptz not null default pg_catalog.now(),
  finished_at timestamptz,
  constraint billing_direct_payment_settlement_attempt_shape_check check (
    (
      outcome_status is null
      and error_code is null
      and feed_status is null
      and sms_status is null
      and finished_at is null
    )
    or (
      outcome_status = 'completed'
      and error_code is null
      and feed_status = 'recorded'
      and sms_status in ('sent', 'skipped_no_consent', 'skipped_opted_out')
      and finished_at is not null
    )
    or (
      outcome_status in ('failed_retryable', 'failed_terminal', 'sms_indeterminate')
      and error_code is not null
      and feed_status is not null
      and sms_status is not null
      and finished_at is not null
    )
  )
);

create unique index billing_direct_payment_settlement_one_open_attempt
  on public.billing_direct_payment_settlement_attempts (task_id)
  where outcome_status is null;
create index billing_direct_payment_settlement_attempt_history_idx
  on public.billing_direct_payment_settlement_attempts (task_id, claimed_at desc);

alter table public.billing_direct_payment_settlement_tasks enable row level security;
alter table public.billing_direct_payment_settlement_tasks force row level security;
alter table public.billing_direct_payment_settlement_attempts enable row level security;
alter table public.billing_direct_payment_settlement_attempts force row level security;

create function public.protect_direct_payment_settlement_attempt()
returns trigger
language plpgsql
set search_path = pg_catalog, pg_temp
set timezone to 'UTC'
as $$
begin
  if tg_op = 'DELETE' then
    raise exception 'direct payment settlement attempts are append-only'
      using errcode = '42501';
  end if;
  if old.id is distinct from new.id
     or old.task_id is distinct from new.task_id
     or old.claim_token is distinct from new.claim_token
     or old.attempt_number is distinct from new.attempt_number
     or old.lease_expires_at is distinct from new.lease_expires_at
     or old.claimed_at is distinct from new.claimed_at
     or old.outcome_status is not null
     or old.finished_at is not null
     or new.outcome_status is null
     or new.finished_at is null then
    raise exception 'direct payment settlement attempt transition is invalid'
      using errcode = '42501';
  end if;
  return new;
end;
$$;

create trigger protect_direct_payment_settlement_attempt_trigger
before update or delete on public.billing_direct_payment_settlement_attempts
for each row execute function public.protect_direct_payment_settlement_attempt();

revoke all on function public.protect_direct_payment_settlement_attempt()
  from public, anon, authenticated, service_role;

-- This AFTER trigger extends the connected projector transaction without
-- copying that large RPC. Lock order is payment -> invoice, matching the
-- existing payment mutation trigger. It intentionally does not lock line-item
-- rows after the invoice: the open direct snapshot's existing item trigger
-- serializes every mutation on this same invoice lock, avoiding an
-- item -> invoice / invoice -> item deadlock.
create function public.enqueue_one_off_direct_payment_settlement()
returns trigger
language plpgsql
security definer
set search_path = pg_catalog, pg_temp
set timezone to 'UTC'
as $$
declare
  v_invoice public.invoices%rowtype;
  v_operation public.billing_payment_operations%rowtype;
  v_billing_event_ids uuid[];
  v_billing_event_id uuid;
  v_item_count bigint;
  v_subtotal numeric(12,2);
  v_discount_amount numeric(12,2);
  v_eligible_subtotal numeric(12,2);
  v_tax_amount numeric(12,2);
  v_reconciled_total numeric(12,2);
  v_prior_paid numeric(12,2);
  v_prior_paid_cents bigint;
  v_invoice_total_cents bigint;
  v_eligible_total_cents bigint;
  v_expected_fee_basis_cents bigint;
  v_expected_fee_cents bigint;
  v_expected_bps integer;
begin
  if old.charge_model is distinct from 'direct'
     or new.charge_model is distinct from 'direct'
     or old.status::text is distinct from 'processing'
     or new.status::text is distinct from 'paid'
     or old.paid_at is not null
     or new.paid_at is null
     or old.stripe_account_id is distinct from new.stripe_account_id
     or old.stripe_livemode is distinct from new.stripe_livemode
     or old.stripe_checkout_session is distinct from new.stripe_checkout_session
     or old.fee_plan_code is distinct from new.fee_plan_code
     or old.fee_catalog_version is distinct from new.fee_catalog_version
     or old.fee_rate_bps is distinct from new.fee_rate_bps
     or old.fee_rate is distinct from new.fee_rate
     or old.fee_basis_amount is distinct from new.fee_basis_amount
     or old.platform_fee is distinct from new.platform_fee
     or (old.stripe_payment_intent is not null
       and old.stripe_payment_intent is distinct from new.stripe_payment_intent)
     or (old.stripe_charge_id is not null
       and old.stripe_charge_id is distinct from new.stripe_charge_id)
     or (old.stripe_application_fee_id is not null
       and old.stripe_application_fee_id is distinct from new.stripe_application_fee_id)
     or (old.stripe_balance_transaction_id is not null
       and old.stripe_balance_transaction_id is distinct from new.stripe_balance_transaction_id) then
    raise exception 'direct settlement requires the exact processing-to-paid transition'
      using errcode = '55000';
  end if;

  if new.invoice_id is null
     or new.kind::text not in ('deposit', 'stage', 'final')
     or new.payment_plan_id is not null
     or new.recurring_plan_id is not null
     or new.installment_seq is not null
     or new.due_date is not null
     or new.imported is distinct from false
     or new.amount <= 0
     or new.refunded_amount is distinct from 0
     or new.eligible_service_refunded_amount is distinct from 0
     or new.platform_fee_refunded is distinct from 0
     or new.refunded_at is not null
     or new.stripe_latest_refund_id is not null
     or new.stripe_latest_application_fee_refund_id is not null then
    raise exception 'direct settlement supports only an unrefunded one-off invoice payment'
      using errcode = '0A000';
  end if;

  if new.stripe_account_id is null
     or new.stripe_account_id !~ '^acct_[A-Za-z0-9]{8,}$'
     or new.stripe_livemode is null
     or new.stripe_checkout_session is null
     or new.stripe_checkout_session !~ '^cs_[A-Za-z0-9_]+$'
     or new.stripe_payment_intent is null
     or new.stripe_payment_intent !~ '^pi_[A-Za-z0-9_]+$'
     or new.stripe_charge_id is null
     or new.stripe_charge_id !~ '^ch_[A-Za-z0-9_]+$'
     or new.reconciliation_status is null
     or new.reconciliation_status not in ('pending', 'reconciled')
     or (
       new.stripe_application_fee_id is not null
       and new.stripe_application_fee_id !~ '^fee_[A-Za-z0-9_]+$'
     )
     or (new.platform_fee = 0 and new.stripe_application_fee_id is not null)
     or (
       new.stripe_balance_transaction_id is not null
       and new.stripe_balance_transaction_id !~ '^txn_[A-Za-z0-9_]+$'
     )
     or (
       new.reconciliation_status = 'reconciled'
       and (
         new.stripe_balance_transaction_id is null
         or (new.platform_fee > 0 and new.stripe_application_fee_id is null)
       )
     ) then
    raise exception 'direct settlement provider evidence is incomplete or contradictory'
      using errcode = '22000';
  end if;

  perform 1
    from public.accounts a
   where a.id = new.account_id
     and a.stripe_merchant_account_id = new.stripe_account_id
     and a.merchant_livemode = new.stripe_livemode
   for key share;
  if not found then
    raise exception 'direct settlement Merchant mapping changed'
      using errcode = '55000';
  end if;

  perform 1
    from public.jobs j
   where j.id = new.job_id
     and j.account_id = new.account_id
   for key share;
  if not found then
    raise exception 'direct settlement job scope changed'
      using errcode = '55000';
  end if;

  -- The existing BEFORE payment trigger has already acquired this invoice lock
  -- after the payment row. Re-selecting FOR UPDATE asserts ownership and makes
  -- the dependency explicit without reversing lock order.
  select i.*
    into v_invoice
    from public.invoices i
   where i.id = new.invoice_id
   for update;
  if not found
     or v_invoice.account_id is distinct from new.account_id
     or v_invoice.job_id is distinct from new.job_id
     or v_invoice.status::text not in ('sent', 'signed')
     or v_invoice.total <= 0
     or v_invoice.discount_percent not between 0 and 100
     or v_invoice.tax_rate not between 0 and 100 then
    raise exception 'direct settlement invoice is outside the exact payable scope'
      using errcode = '55000';
  end if;

  select pg_catalog.count(*),
         pg_catalog.round(coalesce(pg_catalog.sum(ii.amount), 0), 2)
    into v_item_count, v_subtotal
    from public.invoice_items ii
   where ii.invoice_id = new.invoice_id;
  if v_item_count = 0 or exists (
    select 1 from public.invoice_items ii
     where ii.invoice_id = new.invoice_id and ii.amount <= 0
  ) then
    raise exception 'direct settlement invoice requires positive canonical line items'
      using errcode = '55000';
  end if;

  v_discount_amount := pg_catalog.round(
    v_subtotal * v_invoice.discount_percent / 100,
    2
  );
  v_eligible_subtotal := pg_catalog.round(v_subtotal - v_discount_amount, 2);
  v_tax_amount := pg_catalog.round(
    v_eligible_subtotal * v_invoice.tax_rate / 100,
    2
  );
  v_reconciled_total := pg_catalog.round(v_eligible_subtotal + v_tax_amount, 2);
  if v_invoice.total is distinct from v_reconciled_total
     or v_eligible_subtotal < 0
     or v_eligible_subtotal > v_invoice.total then
    raise exception 'direct settlement invoice arithmetic no longer reconciles'
      using errcode = '22000';
  end if;

  if exists (
    select 1
      from public.payments p
     where p.invoice_id = new.invoice_id
       and p.id <> new.id
       and (
         p.status::text in ('requested', 'processing', 'failed', 'disputed')
         or p.charge_model = 'direct'
         or p.payment_plan_id is not null
         or p.recurring_plan_id is not null
         or p.kind::text = 'plan_installment'
         or (p.stripe_checkout_session is not null and p.status::text not in ('paid', 'refunded'))
         or (p.stripe_payment_intent is not null and p.status::text not in ('paid', 'refunded'))
       )
  ) then
    raise exception 'direct settlement invoice has a competing payment scope'
      using errcode = '55000';
  end if;

  select pg_catalog.round(coalesce(pg_catalog.sum(
           case when p.status::text = 'paid'
             then p.amount - p.refunded_amount
             else 0 end
         ), 0), 2)
    into v_prior_paid
    from public.payments p
   where p.invoice_id = new.invoice_id
     and p.id <> new.id;
  if v_prior_paid < 0
     or v_prior_paid >= v_invoice.total
     or new.amount is distinct from pg_catalog.round(v_invoice.total - v_prior_paid, 2)
     or pg_catalog.round(v_prior_paid + new.amount, 2) is distinct from v_invoice.total then
    raise exception 'direct settlement payment is not the exact full outstanding invoice balance'
      using errcode = '55000';
  end if;

  v_expected_bps := case new.fee_plan_code
    when 'flex' then 125
    when 'solo' then 50
    when 'growth' then 25
    when 'scale' then 10
    else null
  end;
  if v_expected_bps is null
     or new.fee_catalog_version is null
     or new.fee_rate_bps is null
     or new.fee_rate is null
     or new.fee_basis_amount is null
     or new.platform_fee is null
     or new.fee_catalog_version is distinct from '2026-08-15-preview'
     or new.fee_rate_bps is distinct from v_expected_bps
     or new.fee_rate is distinct from v_expected_bps::numeric / 10000 then
    raise exception 'direct settlement frozen fee snapshot is non-canonical'
      using errcode = '22000';
  end if;

  v_invoice_total_cents := (v_invoice.total * 100)::bigint;
  v_prior_paid_cents := (v_prior_paid * 100)::bigint;
  v_eligible_total_cents := (v_eligible_subtotal * 100)::bigint;
  v_expected_fee_basis_cents := v_eligible_total_cents - case
    when v_prior_paid_cents = 0 or v_eligible_total_cents = 0 then 0
    else pg_catalog.round(
      v_prior_paid_cents::numeric * v_eligible_total_cents::numeric
        / v_invoice_total_cents::numeric,
      0
    )::bigint
  end;
  v_expected_fee_cents := pg_catalog.round(
    v_expected_fee_basis_cents::numeric * v_expected_bps::numeric / 10000,
    0
  )::bigint;
  if (new.fee_basis_amount * 100)::bigint is distinct from v_expected_fee_basis_cents
     or (new.platform_fee * 100)::bigint is distinct from v_expected_fee_cents
     or v_expected_fee_basis_cents < 0
     or v_expected_fee_basis_cents > (new.amount * 100)::bigint
     or v_expected_fee_cents < 0
     or v_expected_fee_cents > v_expected_fee_basis_cents then
    raise exception 'direct settlement fee allocation no longer matches invoice scope'
      using errcode = '22000';
  end if;

  select o.*
    into v_operation
    from public.billing_payment_operations o
   where o.payment_id = new.id
     and o.account_id = new.account_id
     and o.operation_type = 'checkout_session.create'
   for share;
  if not found
     or v_operation.state is distinct from 'succeeded'
     or v_operation.provider_object_id is distinct from new.stripe_checkout_session
     or v_operation.stripe_account_id is distinct from new.stripe_account_id
     or v_operation.livemode is distinct from new.stripe_livemode
     or v_operation.charge_model is distinct from 'direct'
     or v_operation.completed_at is null then
    raise exception 'direct settlement has no exact succeeded Checkout operation'
      using errcode = '22000';
  end if;

  -- The projector still owns one unexpired inbox claim when it updates the
  -- payment. Binding the task to that exact minimized event prevents an
  -- unrelated service-role UPDATE from manufacturing settlement work.
  select pg_catalog.array_agg(e.id order by e.id)
    into v_billing_event_ids
    from public.billing_events e
   where e.provider = 'stripe'
     and e.event_scope = 'connected_payment'
     and e.event_type = 'checkout.session.completed'
     and e.processing_status = 'processing'
     and e.account_id = new.account_id
     and e.provider_account_id = new.stripe_account_id
     and e.livemode = new.stripe_livemode
     and e.provider_created_at >= new.paid_at
     and e.projection_claim_token is not null
     and e.projection_lease_expires_at > pg_catalog.now()
     and e.payload #>> '{schema}' = 'lgq.stripe-event-inbox.v1'
     and e.payload #>> '{scope}' = 'connected_payment'
     and e.payload #>> '{event,id}' = e.provider_event_id
     and e.payload #>> '{event,type}' = e.event_type
     and e.payload #>> '{event,account}' = e.provider_account_id
     and e.payload #> '{event,livemode}' = pg_catalog.to_jsonb(e.livemode)
     and e.payload #>> '{data_object,id}' = new.stripe_checkout_session
     and e.payload #>> '{data_object,object}' = 'checkout.session';
  if pg_catalog.cardinality(v_billing_event_ids) is distinct from 1 then
    raise exception 'direct settlement requires exactly one owned connected payment event'
      using errcode = '55000';
  end if;
  v_billing_event_id := v_billing_event_ids[1];

  update public.invoices i
     set status = 'paid',
         signed_at = coalesce(i.signed_at, new.paid_at)
   where i.id = v_invoice.id
     and i.account_id = new.account_id
     and i.job_id = new.job_id
     and i.status::text in ('sent', 'signed');
  if not found then
    raise exception 'direct settlement invoice transition was lost'
      using errcode = '55000';
  end if;

  insert into public.billing_direct_payment_settlement_tasks (
    payment_id, billing_event_id, account_id, job_id, invoice_id, settled_at
  ) values (
    new.id, v_billing_event_id, new.account_id, new.job_id, new.invoice_id, new.paid_at
  );

  return new;
end;
$$;

create trigger enqueue_one_off_direct_payment_settlement_trigger
after update of status, paid_at, stripe_payment_intent, stripe_charge_id,
  stripe_application_fee_id, stripe_balance_transaction_id,
  reconciliation_status, reconciled_at
on public.payments
for each row
when (
  old.charge_model = 'direct'
  and new.charge_model = 'direct'
  and old.status::text = 'processing'
  and new.status::text = 'paid'
)
execute function public.enqueue_one_off_direct_payment_settlement();

revoke all on function public.enqueue_one_off_direct_payment_settlement()
  from public, anon, authenticated, service_role;

create function public.claim_direct_payment_settlement_tasks(
  p_batch_size integer
)
returns table (
  work_claim_token uuid,
  task_id uuid,
  payment_id uuid,
  workspace_id uuid,
  job_id uuid,
  invoice_id uuid,
  billing_event_id uuid,
  settled_at timestamptz,
  feed_status text,
  sms_status text,
  attempt_number integer,
  lease_expires_at timestamptz
)
language plpgsql
security definer
set search_path = pg_catalog, pg_temp
set timezone to 'UTC'
as $$
declare
  v_now timestamptz := pg_catalog.clock_timestamp();
  v_task public.billing_direct_payment_settlement_tasks%rowtype;
  v_claim_token uuid;
  v_lease_expires_at timestamptz;
  v_updated integer;
begin
  if p_batch_size is null or p_batch_size not between 1 and 25 then
    raise exception 'direct settlement batch size must be between 1 and 25'
      using errcode = '22023';
  end if;

  for v_task in
    select t.*
      from public.billing_direct_payment_settlement_tasks t
     where t.task_state = 'ready'
        or (t.task_state = 'retry_wait' and t.next_attempt_at <= v_now)
        or (t.task_state = 'leased' and t.lease_expires_at <= v_now)
     order by t.created_at, t.id
     limit p_batch_size
     for update skip locked
  loop
    if v_task.task_state = 'leased' then
      if v_task.sms_status = 'dispatching' then
        update public.sms_events s
           set status = 'indeterminate',
               error_reason = 'settlement_sms_delivery_unknown_after_lease_expiry'
         where s.id = v_task.sms_event_id
           and s.payment_id = v_task.payment_id
           and s.event_type = 'payment_paid'
           and s.status = 'pending';
        get diagnostics v_updated = row_count;
        if v_updated <> 1 then
          raise exception 'stale settlement SMS has no exact pending event'
            using errcode = '55000';
        end if;

        update public.billing_direct_payment_settlement_attempts a
           set outcome_status = 'sms_indeterminate',
               error_code = 'sms_delivery_unknown_after_lease_expiry',
               feed_status = v_task.feed_status,
               sms_status = 'indeterminate',
               finished_at = v_now
         where a.claim_token = v_task.claim_token
           and a.outcome_status is null;
        get diagnostics v_updated = row_count;
        if v_updated <> 1 then
          raise exception 'stale settlement SMS lease has no open attempt'
            using errcode = '55000';
        end if;

        update public.billing_direct_payment_settlement_tasks t
           set task_state = 'dead_letter',
               claim_token = null,
               lease_expires_at = null,
               next_attempt_at = null,
               sms_status = 'indeterminate',
               last_error_code = 'sms_delivery_unknown_after_lease_expiry',
               dead_lettered_at = v_now,
               updated_at = v_now
         where t.id = v_task.id;
        continue;
      end if;

      update public.billing_direct_payment_settlement_attempts a
         set outcome_status = case
               when v_task.attempt_count >= 8 then 'failed_terminal'
               else 'failed_retryable'
             end,
             error_code = case
               when v_task.attempt_count >= 8 then 'worker_lease_expired_attempt_limit'
               else 'worker_lease_expired'
             end,
             feed_status = v_task.feed_status,
             sms_status = v_task.sms_status,
             finished_at = v_now
       where a.claim_token = v_task.claim_token
         and a.outcome_status is null;
      get diagnostics v_updated = row_count;
      if v_updated <> 1 then
        raise exception 'expired settlement lease has no open attempt'
          using errcode = '55000';
      end if;

      if v_task.attempt_count >= 8 then
        update public.billing_direct_payment_settlement_tasks t
           set task_state = 'dead_letter',
               claim_token = null,
               lease_expires_at = null,
               next_attempt_at = null,
               last_error_code = 'worker_lease_expired_attempt_limit',
               dead_lettered_at = v_now,
               updated_at = v_now
         where t.id = v_task.id;
        continue;
      end if;
    end if;

    if v_task.attempt_count >= 8 then
      update public.billing_direct_payment_settlement_tasks t
         set task_state = 'dead_letter',
             claim_token = null,
             lease_expires_at = null,
             next_attempt_at = null,
             last_error_code = 'worker_attempt_limit_reached',
             dead_lettered_at = v_now,
             updated_at = v_now
       where t.id = v_task.id;
      continue;
    end if;

    v_claim_token := pg_catalog.gen_random_uuid();
    v_lease_expires_at := v_now + interval '5 minutes';

    update public.billing_direct_payment_settlement_tasks t
       set task_state = 'leased',
           claim_token = v_claim_token,
           lease_expires_at = v_lease_expires_at,
           attempt_count = t.attempt_count + 1,
           next_attempt_at = null,
           last_error_code = null,
           dead_lettered_at = null,
           updated_at = v_now
     where t.id = v_task.id
     returning t.* into v_task;

    insert into public.billing_direct_payment_settlement_attempts (
      task_id, claim_token, attempt_number, lease_expires_at, claimed_at
    ) values (
      v_task.id, v_claim_token, v_task.attempt_count, v_lease_expires_at, v_now
    );

    return query select
      v_claim_token,
      v_task.id,
      v_task.payment_id,
      v_task.account_id,
      v_task.job_id,
      v_task.invoice_id,
      v_task.billing_event_id,
      v_task.settled_at,
      v_task.feed_status,
      v_task.sms_status,
      v_task.attempt_count,
      v_lease_expires_at;
  end loop;
end;
$$;

-- Feed recording is an independent, idempotent database outcome. It never
-- changes jobs; the source-key uniqueness is the same invariant used by the
-- existing timeline writer.
create function public.record_direct_payment_settlement_feed(
  p_task_id uuid,
  p_claim_token uuid
)
returns text
language plpgsql
security definer
set search_path = pg_catalog, pg_temp
set timezone to 'UTC'
as $$
declare
  v_now timestamptz := pg_catalog.clock_timestamp();
  v_task public.billing_direct_payment_settlement_tasks%rowtype;
  v_payment public.payments%rowtype;
  v_feed public.job_feed%rowtype;
begin
  select t.* into v_task
    from public.billing_direct_payment_settlement_tasks t
   where t.id = p_task_id
   for update;
  if not found
     or v_task.task_state <> 'leased'
     or v_task.claim_token is distinct from p_claim_token
     or v_task.lease_expires_at <= v_now then
    raise exception 'direct settlement feed claim is not owned or expired'
      using errcode = '55000';
  end if;
  if v_task.feed_status = 'recorded' then
    return 'recorded';
  end if;

  select p.* into v_payment
    from public.payments p
   where p.id = v_task.payment_id
     and p.account_id = v_task.account_id
   for share;
  if not found
     or v_payment.job_id is distinct from v_task.job_id
     or v_payment.invoice_id is distinct from v_task.invoice_id
     or v_payment.charge_model <> 'direct'
     or v_payment.status::text <> 'paid'
     or v_payment.paid_at is distinct from v_task.settled_at then
    raise exception 'direct settlement feed payment scope changed'
      using errcode = '55000';
  end if;

  insert into public.job_feed (
    account_id, job_id, kind, title, body, author, visibility, amount,
    source_table, source_id, action_url, published_at, created_at
  ) values (
    v_task.account_id,
    v_task.job_id,
    'payment_paid',
    'Payment received',
    v_payment.label,
    'Owner',
    'client_financial',
    v_payment.amount,
    'payments',
    v_payment.id,
    '/pay/' || v_payment.id::text,
    v_task.settled_at,
    v_task.settled_at
  )
  on conflict (source_table, source_id, kind)
    where source_table is not null and source_id is not null
  do nothing;

  select f.* into v_feed
    from public.job_feed f
   where f.source_table = 'payments'
     and f.source_id = v_payment.id
     and f.kind = 'payment_paid';
  if not found
     or v_feed.account_id is distinct from v_task.account_id
     or v_feed.job_id is distinct from v_task.job_id
     or v_feed.title is distinct from 'Payment received'
     or v_feed.body is distinct from v_payment.label
     or v_feed.visibility is distinct from 'client_financial'
     or v_feed.amount is distinct from v_payment.amount
     or v_feed.action_url is distinct from '/pay/' || v_payment.id::text then
    raise exception 'direct settlement feed outcome conflicts with payment truth'
      using errcode = '22000';
  end if;

  update public.billing_direct_payment_settlement_tasks t
     set feed_status = 'recorded',
         updated_at = v_now
   where t.id = v_task.id;
  return 'recorded';
end;
$$;

create function public.stage_direct_payment_settlement_sms(
  p_task_id uuid,
  p_claim_token uuid,
  p_normalized_phone text,
  p_body text
)
returns table (
  dispatch_status text,
  sms_event_id uuid,
  phone_number text
)
language plpgsql
security definer
set search_path = pg_catalog, pg_temp
set timezone to 'UTC'
as $$
declare
  v_now timestamptz := pg_catalog.clock_timestamp();
  v_task public.billing_direct_payment_settlement_tasks%rowtype;
  v_payment public.payments%rowtype;
  v_consent public.sms_consent%rowtype;
  v_sms public.sms_events%rowtype;
  v_digits text;
  v_expected_phone text;
  v_outcome text;
  v_updated integer;
  v_sms_exists boolean := false;
begin
  select t.* into v_task
    from public.billing_direct_payment_settlement_tasks t
   where t.id = p_task_id
   for update;
  if not found
     or v_task.task_state <> 'leased'
     or v_task.claim_token is distinct from p_claim_token
     or v_task.lease_expires_at <= v_now
     or v_task.feed_status <> 'recorded'
     or v_task.sms_status <> 'pending' then
    raise exception 'direct settlement SMS claim is not ready, owned, or current'
      using errcode = '55000';
  end if;

  select p.* into v_payment
    from public.payments p
   where p.id = v_task.payment_id
     and p.account_id = v_task.account_id
   for share;
  if not found
     or v_payment.job_id is distinct from v_task.job_id
     or v_payment.invoice_id is distinct from v_task.invoice_id
     or v_payment.charge_model <> 'direct'
     or v_payment.status::text <> 'paid'
     or v_payment.paid_at is distinct from v_task.settled_at then
    raise exception 'direct settlement SMS payment scope changed'
      using errcode = '55000';
  end if;

  -- Inspect the one-per-payment SMS ledger before any no-consent fast path.
  -- A stale pending/failed row remains ambiguous even if consent has since
  -- changed; quarantine it rather than leaving retry-looking evidence behind.
  select s.* into v_sms
    from public.sms_events s
   where s.payment_id = v_task.payment_id
     and s.event_type = 'payment_paid'
   for update;
  v_sms_exists := found;
  if v_sms_exists then
    if v_sms.account_id is distinct from v_task.account_id then
      raise exception 'existing settlement SMS conflicts with current payment scope'
        using errcode = '22000';
    end if;

    if v_sms.status not in ('sent', 'opted_out') then
      update public.sms_events s
         set status = 'indeterminate',
             error_reason = 'settlement_sms_existing_nonterminal_outcome'
       where s.id = v_sms.id;
      update public.billing_direct_payment_settlement_tasks t
         set task_state = 'dead_letter', claim_token = null,
             lease_expires_at = null, next_attempt_at = null,
             sms_status = 'indeterminate', sms_event_id = v_sms.id,
             last_error_code = 'sms_existing_nonterminal_outcome',
             dead_lettered_at = v_now, updated_at = v_now
       where t.id = v_task.id;
      update public.billing_direct_payment_settlement_attempts a
         set outcome_status = 'sms_indeterminate',
             error_code = 'sms_existing_nonterminal_outcome',
             feed_status = 'recorded', sms_status = 'indeterminate', finished_at = v_now
       where a.claim_token = p_claim_token and a.outcome_status is null;
      get diagnostics v_updated = row_count;
      if v_updated <> 1 then
        raise exception 'indeterminate settlement SMS has no open attempt'
          using errcode = '55000';
      end if;
      return query select 'indeterminate'::text, v_sms.id, null::text;
      return;
    end if;
  end if;

  if v_payment.sms_consent is distinct from true
     or v_payment.homeowner_phone is null
     or pg_catalog.length(pg_catalog.btrim(v_payment.homeowner_phone)) = 0 then
    v_outcome := 'skipped_no_consent';
  else
    v_digits := pg_catalog.regexp_replace(v_payment.homeowner_phone, '[^0-9]', '', 'g');
    v_expected_phone := case
      when pg_catalog.length(v_digits) = 10 then '+1' || v_digits
      when pg_catalog.length(v_digits) = 11 and v_digits like '1%' then '+' || v_digits
      when v_payment.homeowner_phone like '+%'
        and pg_catalog.length(v_digits) between 10 and 15 then '+' || v_digits
      else null
    end;
    if v_expected_phone is null
       or p_normalized_phone is distinct from v_expected_phone
       or p_normalized_phone !~ '^\+[0-9]{10,15}$'
       or p_body is null
       or pg_catalog.length(p_body) not between 1 and 1600
       or p_body ~ '[[:cntrl:]]' then
      raise exception 'direct settlement SMS envelope is invalid'
        using errcode = '22023';
    end if;

    select c.* into v_consent
      from public.sms_consent c
     where c.account_id = v_task.account_id
       and c.phone_number = p_normalized_phone
     for share;
    if not found
       or v_consent.status <> 'opted_in'
       or v_consent.consented_at is null
       or v_consent.opted_out_at is not null then
      v_outcome := case
        when found and v_consent.status = 'opted_out' then 'skipped_opted_out'
        else 'skipped_no_consent'
      end;
    end if;
  end if;

  if v_outcome is not null then
    update public.billing_direct_payment_settlement_tasks t
       set task_state = 'completed',
           claim_token = null,
           lease_expires_at = null,
           next_attempt_at = null,
           sms_status = v_outcome,
           last_error_code = null,
           completed_at = v_now,
           updated_at = v_now
     where t.id = v_task.id;

    update public.billing_direct_payment_settlement_attempts a
       set outcome_status = 'completed',
           feed_status = 'recorded',
           sms_status = v_outcome,
           finished_at = v_now
     where a.claim_token = p_claim_token
       and a.outcome_status is null;
    get diagnostics v_updated = row_count;
    if v_updated <> 1 then
      raise exception 'direct settlement SMS skip has no open attempt'
        using errcode = '55000';
    end if;

    return query select v_outcome, null::uuid, null::text;
    return;
  end if;

  if v_sms_exists then
    if v_sms.phone_number is distinct from p_normalized_phone
       or v_sms.body is distinct from p_body then
      raise exception 'existing settlement SMS conflicts with current envelope'
        using errcode = '22000';
    end if;

    if v_sms.status = 'sent' then
      update public.billing_direct_payment_settlement_tasks t
         set task_state = 'completed', claim_token = null,
             lease_expires_at = null, next_attempt_at = null,
             sms_status = 'sent', sms_event_id = v_sms.id,
             last_error_code = null, completed_at = v_now, updated_at = v_now
       where t.id = v_task.id;
      update public.billing_direct_payment_settlement_attempts a
         set outcome_status = 'completed', feed_status = 'recorded',
             sms_status = 'sent', finished_at = v_now
       where a.claim_token = p_claim_token and a.outcome_status is null;
      get diagnostics v_updated = row_count;
      if v_updated <> 1 then
        raise exception 'already-sent settlement SMS has no open attempt'
          using errcode = '55000';
      end if;
      return query select 'already_sent'::text, v_sms.id, null::text;
      return;
    end if;

    if v_sms.status = 'opted_out' then
      update public.billing_direct_payment_settlement_tasks t
         set task_state = 'completed', claim_token = null,
             lease_expires_at = null, next_attempt_at = null,
             sms_status = 'skipped_opted_out', sms_event_id = null,
             last_error_code = null, completed_at = v_now, updated_at = v_now
       where t.id = v_task.id;
      update public.billing_direct_payment_settlement_attempts a
         set outcome_status = 'completed', feed_status = 'recorded',
             sms_status = 'skipped_opted_out', finished_at = v_now
       where a.claim_token = p_claim_token and a.outcome_status is null;
      get diagnostics v_updated = row_count;
      if v_updated <> 1 then
        raise exception 'opted-out settlement SMS has no open attempt'
          using errcode = '55000';
      end if;
      return query select 'skipped_opted_out'::text, null::uuid, null::text;
      return;
    end if;

    raise exception 'existing settlement SMS has an unsupported terminal status'
      using errcode = '22000';
  end if;

  insert into public.sms_events (
    account_id, payment_id, event_type, phone_number, status, body, context
  ) values (
    v_task.account_id, v_task.payment_id, 'payment_paid',
    p_normalized_phone, 'pending', p_body, 'payment'
  ) returning * into v_sms;

  update public.billing_direct_payment_settlement_tasks t
     set sms_status = 'dispatching',
         sms_event_id = v_sms.id,
         updated_at = v_now
   where t.id = v_task.id;

  return query select 'dispatch'::text, v_sms.id, p_normalized_phone;
end;
$$;

create function public.complete_direct_payment_settlement_sms(
  p_task_id uuid,
  p_claim_token uuid,
  p_sms_event_id uuid,
  p_provider_id text
)
returns boolean
language plpgsql
security definer
set search_path = pg_catalog, pg_temp
set timezone to 'UTC'
as $$
declare
  v_now timestamptz := pg_catalog.clock_timestamp();
  v_task public.billing_direct_payment_settlement_tasks%rowtype;
  v_updated integer;
begin
  if p_provider_id is null
     or pg_catalog.length(pg_catalog.btrim(p_provider_id)) not between 1 and 255
     or p_provider_id ~ '[[:cntrl:]]' then
    raise exception 'direct settlement SMS provider ID is invalid'
      using errcode = '22023';
  end if;

  select t.* into v_task
    from public.billing_direct_payment_settlement_tasks t
   where t.id = p_task_id
   for update;
  if not found
     or v_task.task_state <> 'leased'
     or v_task.claim_token is distinct from p_claim_token
     or v_task.lease_expires_at <= v_now
     or v_task.feed_status <> 'recorded'
     or v_task.sms_status <> 'dispatching'
     or v_task.sms_event_id is distinct from p_sms_event_id then
    raise exception 'direct settlement SMS completion claim is not owned or current'
      using errcode = '55000';
  end if;

  update public.sms_events s
     set status = 'sent',
         provider_id = p_provider_id,
         sent_at = v_now,
         error_reason = null
   where s.id = p_sms_event_id
     and s.account_id = v_task.account_id
     and s.payment_id = v_task.payment_id
     and s.event_type = 'payment_paid'
     and s.status = 'pending';
  get diagnostics v_updated = row_count;
  if v_updated <> 1 then
    raise exception 'direct settlement SMS completion has no exact pending event'
      using errcode = '55000';
  end if;

  update public.billing_direct_payment_settlement_tasks t
     set task_state = 'completed',
         claim_token = null,
         lease_expires_at = null,
         next_attempt_at = null,
         sms_status = 'sent',
         last_error_code = null,
         completed_at = v_now,
         updated_at = v_now
   where t.id = v_task.id;

  update public.billing_direct_payment_settlement_attempts a
     set outcome_status = 'completed',
         feed_status = 'recorded',
         sms_status = 'sent',
         finished_at = v_now
   where a.claim_token = p_claim_token
     and a.outcome_status is null;
  get diagnostics v_updated = row_count;
  if v_updated <> 1 then
    raise exception 'direct settlement SMS completion has no open attempt'
      using errcode = '55000';
  end if;
  return true;
end;
$$;

create function public.fail_direct_payment_settlement_task(
  p_task_id uuid,
  p_claim_token uuid,
  p_error_code text,
  p_retryable boolean
)
returns table (
  failure_status text,
  task_state text,
  next_attempt_at timestamptz
)
language plpgsql
security definer
set search_path = pg_catalog, pg_temp
set timezone to 'UTC'
as $$
declare
  v_now timestamptz := pg_catalog.clock_timestamp();
  v_task public.billing_direct_payment_settlement_tasks%rowtype;
  v_next_attempt_at timestamptz;
  v_outcome text;
  v_updated integer;
begin
  if p_error_code is null
     or p_error_code !~ '^[a-z][a-z0-9_]{2,99}$'
     or p_retryable is null then
    raise exception 'direct settlement failure contract is invalid'
      using errcode = '22023';
  end if;

  select t.* into v_task
    from public.billing_direct_payment_settlement_tasks t
   where t.id = p_task_id
   for update;
  if not found then
    raise exception 'direct settlement task was not found' using errcode = 'P0002';
  end if;
  if v_task.task_state in ('completed', 'dead_letter') then
    return query select 'already_finished'::text, v_task.task_state, null::timestamptz;
    return;
  end if;
  if v_task.task_state <> 'leased'
     or v_task.claim_token is distinct from p_claim_token
     or v_task.lease_expires_at <= v_now then
    raise exception 'direct settlement failure claim is not owned or expired'
      using errcode = '55000';
  end if;

  if v_task.sms_status = 'dispatching' then
    update public.sms_events s
       set status = 'indeterminate',
           error_reason = 'settlement_sms_provider_result_unknown'
     where s.id = v_task.sms_event_id
       and s.payment_id = v_task.payment_id
       and s.event_type = 'payment_paid'
       and s.status = 'pending';
    get diagnostics v_updated = row_count;
    if v_updated <> 1 then
      raise exception 'ambiguous settlement SMS has no exact pending event'
        using errcode = '55000';
    end if;
    v_outcome := 'sms_indeterminate';
    p_error_code := 'sms_provider_result_unknown';

    update public.billing_direct_payment_settlement_tasks t
       set task_state = 'dead_letter', claim_token = null,
           lease_expires_at = null, next_attempt_at = null,
           sms_status = 'indeterminate', last_error_code = p_error_code,
           dead_lettered_at = v_now, updated_at = v_now
     where t.id = v_task.id;
  elsif p_retryable and v_task.attempt_count < 8 then
    v_outcome := 'failed_retryable';
    v_next_attempt_at := v_now + pg_catalog.make_interval(
      mins => least(60, (5 * pg_catalog.power(2, v_task.attempt_count - 1))::integer)
    );
    update public.billing_direct_payment_settlement_tasks t
       set task_state = 'retry_wait', claim_token = null,
           lease_expires_at = null, next_attempt_at = v_next_attempt_at,
           last_error_code = p_error_code, updated_at = v_now
     where t.id = v_task.id;
  else
    v_outcome := 'failed_terminal';
    update public.billing_direct_payment_settlement_tasks t
       set task_state = 'dead_letter', claim_token = null,
           lease_expires_at = null, next_attempt_at = null,
           last_error_code = case
             when p_retryable then 'worker_attempt_limit_reached'
             else p_error_code
           end,
           dead_lettered_at = v_now, updated_at = v_now
     where t.id = v_task.id;
    if p_retryable then p_error_code := 'worker_attempt_limit_reached'; end if;
  end if;

  update public.billing_direct_payment_settlement_attempts a
     set outcome_status = v_outcome,
         error_code = p_error_code,
         feed_status = v_task.feed_status,
         sms_status = case
           when v_outcome = 'sms_indeterminate' then 'indeterminate'
           else v_task.sms_status
         end,
         finished_at = v_now
   where a.claim_token = p_claim_token
     and a.outcome_status is null;
  get diagnostics v_updated = row_count;
  if v_updated <> 1 then
    raise exception 'direct settlement failure has no open attempt'
      using errcode = '55000';
  end if;

  return query select v_outcome, case
    when v_outcome = 'failed_retryable' then 'retry_wait'
    else 'dead_letter'
  end, v_next_attempt_at;
end;
$$;

revoke all on table public.billing_direct_payment_settlement_tasks
  from public, anon, authenticated, service_role;
revoke all on table public.billing_direct_payment_settlement_attempts
  from public, anon, authenticated, service_role;

revoke all on function public.claim_direct_payment_settlement_tasks(integer)
  from public, anon, authenticated, service_role;
revoke all on function public.record_direct_payment_settlement_feed(uuid, uuid)
  from public, anon, authenticated, service_role;
revoke all on function public.stage_direct_payment_settlement_sms(uuid, uuid, text, text)
  from public, anon, authenticated, service_role;
revoke all on function public.complete_direct_payment_settlement_sms(uuid, uuid, uuid, text)
  from public, anon, authenticated, service_role;
revoke all on function public.fail_direct_payment_settlement_task(uuid, uuid, text, boolean)
  from public, anon, authenticated, service_role;

grant execute on function public.claim_direct_payment_settlement_tasks(integer)
  to service_role;
grant execute on function public.record_direct_payment_settlement_feed(uuid, uuid)
  to service_role;
grant execute on function public.stage_direct_payment_settlement_sms(uuid, uuid, text, text)
  to service_role;
grant execute on function public.complete_direct_payment_settlement_sms(uuid, uuid, uuid, text)
  to service_role;
grant execute on function public.fail_direct_payment_settlement_task(uuid, uuid, text, boolean)
  to service_role;

commit;

-- Source: migrations/20260818190000_top_up_purchase_operations.sql
-- Claim one top-up purchase intent exactly once, before Stripe is asked.
--
-- WHY THIS TABLE EXISTS. Without a durable claim, a double-submitted form
-- creates two Checkout Sessions for one intent. The projector is idempotent per
-- SESSION, not per intent, so paying both would grant twice and charge twice --
-- correctly, by its own rules, which is the worst kind of wrong.
--
-- WHY NOT billing_payment_operations. That ledger requires payment_id NOT NULL
-- against public.payments, charge_model = 'direct', and a connected
-- stripe_account_id matching '^acct_'. A top-up is bought on the PLATFORM
-- account with no connected account and no payments row, so it satisfies none of
-- the three. Relaxing them would weaken the guarantees the contractor rail
-- depends on. billing_subscription_checkout_operations exists for exactly this
-- reason -- a platform checkout needs its own ledger -- and this mirrors it.
--
-- WHAT IT DELIBERATELY DOES NOT DO. It stops at checkout_created. What happens
-- to the money afterwards belongs to the projector, which keys on the Checkout
-- Session and owns the grant. Two ledgers competing to decide whether credit was
-- granted is how they disagree.
--
-- THE AMOUNT IS BOUND TO THE CATALOG. A row cannot record a price the published
-- catalog does not carry, the same way the subscription ledger pins its six plan
-- amounts. All eight SKUs are listed, not the five sellable ones: the price book
-- is published and settled, and which of them may be SOLD is the application's
-- decision (TOP_UPS_WITHHELD), not a shape the database should have to be
-- migrated to change.

begin;

create table public.billing_top_up_purchase_operations (
  id uuid primary key default pg_catalog.gen_random_uuid(),
  account_id uuid not null references public.accounts(id) on delete restrict,
  operation_id text not null check (
    pg_catalog.length(pg_catalog.btrim(operation_id)) between 1 and 200
    and operation_id !~ '[[:cntrl:]]'
    and operation_id = pg_catalog.btrim(operation_id)
  ),
  purpose text not null default 'top_up_purchase'
    check (purpose = 'top_up_purchase'),
  top_up_id text not null check (
    top_up_id in (
      'flex_text_250', 'text_1000', 'marketing_email_5000', 'ai_intake_100',
      'ai_writing_250', 'storage_100gb', 'office_user', 'crew_user'
    )
  ),
  resource_code text not null check (resource_code ~ '^[a-z][a-z0-9_]{1,63}$'),
  units bigint not null check (units > 0),
  catalog_version text not null check (catalog_version = '2026-08-18-preview'),
  livemode boolean not null,
  stripe_price_id text not null check (
    stripe_price_id ~ '^price_[A-Za-z0-9]{8,}$'
    and pg_catalog.length(stripe_price_id) <= 255
  ),
  stripe_product_id text not null check (
    stripe_product_id ~ '^prod_[A-Za-z0-9]{8,}$'
    and pg_catalog.length(stripe_product_id) <= 255
  ),
  currency text not null default 'usd' check (currency = 'usd'),
  unit_amount_cents bigint not null check (unit_amount_cents > 0),
  stripe_idempotency_key text not null check (
    stripe_idempotency_key ~ '^lgq:billing:v1:top_up_purchase[.]create:[0-9a-f]{64}$'
    and pg_catalog.length(stripe_idempotency_key) <= 255
  ),
  request_fingerprint text check (
    request_fingerprint is null or request_fingerprint ~ '^[0-9a-f]{64}$'
  ),
  state text not null default 'claimed'
    check (state in ('claimed', 'submitted', 'checkout_created', 'indeterminate', 'failed')),
  claim_token uuid,
  lease_expires_at timestamptz,
  submission_started_at timestamptz,
  provider_object_id text,
  checkout_created_at timestamptz,
  resolved_at timestamptz,
  attempt_count integer not null default 0 check (attempt_count >= 0),
  last_error text check (last_error is null or last_error ~ '^[a-z][a-z0-9_]{2,63}$'),
  metadata jsonb not null default '{}'::jsonb
    check (pg_catalog.jsonb_typeof(metadata) = 'object'),
  created_at timestamptz not null default pg_catalog.now(),
  updated_at timestamptz not null default pg_catalog.now(),

  -- One Session per client intent. This is the constraint that makes a
  -- double-submitted form idempotent rather than expensive.
  constraint billing_top_up_purchase_business_key_unique
    unique (account_id, operation_id),
  constraint billing_top_up_purchase_idempotency_key_unique
    unique (livemode, stripe_idempotency_key),
  constraint billing_top_up_purchase_provider_object_unique
    unique (livemode, provider_object_id),

  -- The published price book, so a row cannot record an amount the catalog does
  -- not carry. Changing a customer-visible price is a migration on purpose.
  constraint billing_top_up_purchase_catalog_binding_check check (
    (top_up_id = 'flex_text_250' and resource_code = 'text_segments'
      and units = 250 and unit_amount_cents = 1200)
    or (top_up_id = 'text_1000' and resource_code = 'text_segments'
      and units = 1000 and unit_amount_cents = 4200)
    or (top_up_id = 'marketing_email_5000' and resource_code = 'marketing_email_sends'
      and units = 5000 and unit_amount_cents = 1700)
    or (top_up_id = 'ai_intake_100' and resource_code = 'ai_intake_threads'
      and units = 100 and unit_amount_cents = 1500)
    or (top_up_id = 'ai_writing_250' and resource_code = 'ai_writing_drafts'
      and units = 250 and unit_amount_cents = 1900)
    or (top_up_id = 'storage_100gb' and resource_code = 'storage_gb'
      and units = 100 and unit_amount_cents = 1500)
    or (top_up_id = 'office_user' and resource_code = 'office_users'
      and units = 1 and unit_amount_cents = 1500)
    or (top_up_id = 'crew_user' and resource_code = 'crew_users'
      and units = 1 and unit_amount_cents = 500)
  ),

  constraint billing_top_up_purchase_provider_mode_check check (
    provider_object_id is null
    or (
      pg_catalog.length(provider_object_id) <= 255
      and (
        (livemode and provider_object_id ~ '^cs_live_[A-Za-z0-9_]+$')
        or (not livemode and provider_object_id ~ '^cs_test_[A-Za-z0-9_]+$')
      )
    )
  ),

  -- Each state carries exactly the evidence it has earned, and no more. This is
  -- what makes "we asked Stripe and never heard back" a distinguishable state
  -- rather than something inferred later from a missing row.
  constraint billing_top_up_purchase_state_shape_check check (
    (
      state = 'claimed'
      and claim_token is not null
      and lease_expires_at is not null
      and submission_started_at is null
      and request_fingerprint is null
      and provider_object_id is null
      and checkout_created_at is null
      and resolved_at is null
      and last_error is null
    )
    or (
      state = 'submitted'
      and claim_token is not null
      and lease_expires_at is not null
      and submission_started_at is not null
      and request_fingerprint is not null
      and provider_object_id is null
      and checkout_created_at is null
      and resolved_at is null
      and last_error is null
    )
    or (
      state = 'checkout_created'
      and claim_token is null
      and lease_expires_at is null
      and submission_started_at is not null
      and request_fingerprint is not null
      and provider_object_id is not null
      and checkout_created_at is not null
      and resolved_at is not null
      and last_error is null
    )
    or (
      state = 'indeterminate'
      and claim_token is not null
      and submission_started_at is not null
      and request_fingerprint is not null
      and provider_object_id is null
      and checkout_created_at is null
      and resolved_at is null
      and last_error is not null
    )
    or (
      state = 'failed'
      and claim_token is null
      and lease_expires_at is null
      and provider_object_id is null
      and checkout_created_at is null
      and resolved_at is not null
      and last_error is not null
    )
  )
);

create index billing_top_up_purchase_account_created_idx
  on public.billing_top_up_purchase_operations (account_id, created_at desc);
create index billing_top_up_purchase_recovery_idx
  on public.billing_top_up_purchase_operations (state, lease_expires_at, created_at)
  where state in ('claimed', 'submitted', 'indeterminate');

alter table public.billing_top_up_purchase_operations enable row level security;
-- No policy: this ledger is service-role only. `authenticated` reads nothing.

-- Append-only in the ways that matter, and one legal path through the states.
create or replace function public.protect_billing_top_up_purchase_operation()
returns trigger
language plpgsql
set search_path = pg_catalog, pg_temp
as $$
begin
  if tg_op = 'DELETE' then
    raise exception 'top-up purchase operations cannot be deleted' using errcode = '42501';
  end if;

  if old.account_id is distinct from new.account_id
     or old.operation_id is distinct from new.operation_id
     or old.purpose is distinct from new.purpose
     or old.top_up_id is distinct from new.top_up_id
     or old.resource_code is distinct from new.resource_code
     or old.units is distinct from new.units
     or old.catalog_version is distinct from new.catalog_version
     or old.livemode is distinct from new.livemode
     or old.stripe_price_id is distinct from new.stripe_price_id
     or old.stripe_product_id is distinct from new.stripe_product_id
     or old.currency is distinct from new.currency
     or old.unit_amount_cents is distinct from new.unit_amount_cents
     or old.stripe_idempotency_key is distinct from new.stripe_idempotency_key
     or old.created_at is distinct from new.created_at then
    raise exception 'top-up purchase operation identity is immutable' using errcode = '22000';
  end if;

  if old.provider_object_id is not null
     and old.provider_object_id is distinct from new.provider_object_id then
    raise exception 'top-up purchase Checkout Session is immutable once recorded'
      using errcode = '22000';
  end if;

  if new.attempt_count < old.attempt_count then
    raise exception 'top-up purchase attempt count cannot decrease' using errcode = '22000';
  end if;

  if new.state is distinct from old.state and not (
    (old.state = 'claimed' and new.state in ('submitted', 'failed'))
    or (old.state = 'submitted' and new.state in ('checkout_created', 'failed', 'indeterminate'))
    or (old.state = 'indeterminate' and new.state in ('checkout_created', 'failed'))
  ) then
    raise exception 'invalid top-up purchase operation state transition: % -> %',
      old.state, new.state using errcode = '22000';
  end if;

  new.updated_at := pg_catalog.now();
  return new;
end;
$$;

drop trigger if exists protect_billing_top_up_purchase_operation_update_trigger
  on public.billing_top_up_purchase_operations;
create trigger protect_billing_top_up_purchase_operation_update_trigger
before update on public.billing_top_up_purchase_operations
for each row execute function public.protect_billing_top_up_purchase_operation();

drop trigger if exists protect_billing_top_up_purchase_operation_delete_trigger
  on public.billing_top_up_purchase_operations;
create trigger protect_billing_top_up_purchase_operation_delete_trigger
before delete on public.billing_top_up_purchase_operations
for each row execute function public.protect_billing_top_up_purchase_operation();

-- A trigger fires regardless of who may EXECUTE it, so revoking costs nothing
-- and stops the guard being callable as an ordinary function by a client role.
revoke all on function public.protect_billing_top_up_purchase_operation()
  from public, anon, authenticated;

-- Claim one intent. A repeat of the same business key does not insert again; it
-- reports what the first claim became, so a double submit can be answered with
-- the Session that already exists instead of a second one.
create or replace function public.claim_stripe_top_up_purchase(
  p_account_id uuid,
  p_operation_id text,
  p_top_up_id text,
  p_resource_code text,
  p_units bigint,
  p_catalog_version text,
  p_livemode boolean,
  p_stripe_price_id text,
  p_stripe_product_id text,
  p_unit_amount_cents bigint,
  p_stripe_idempotency_key text
)
returns table (
  claim_status text,
  operation_pk uuid,
  claim_token uuid,
  state text,
  provider_object_id text
)
language plpgsql
security definer
set search_path = ''
set timezone to 'UTC'
as $$
declare
  v_existing public.billing_top_up_purchase_operations%rowtype;
  v_token uuid := pg_catalog.gen_random_uuid();
  v_row public.billing_top_up_purchase_operations%rowtype;
begin
  if p_account_id is null or p_operation_id is null or p_stripe_idempotency_key is null then
    raise exception 'top-up purchase claim input is invalid' using errcode = '22023';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(p_account_id::text || ':top_up_purchase:' || p_operation_id, 0)
  );

  select o.* into v_existing
    from public.billing_top_up_purchase_operations o
   where o.account_id = p_account_id
     and o.operation_id = p_operation_id
   for update;

  if found then
    -- The same intent must mean the same purchase. Anything else is a different
    -- request wearing a reused id, and it must not silently adopt this row.
    if v_existing.top_up_id is distinct from p_top_up_id
       or v_existing.livemode is distinct from p_livemode
       or v_existing.unit_amount_cents is distinct from p_unit_amount_cents
       or v_existing.stripe_price_id is distinct from p_stripe_price_id then
      raise exception 'top-up purchase intent was reused with different purchase data'
        using errcode = '22000';
    end if;
    return query select
      'replayed'::text, v_existing.id, v_existing.claim_token,
      v_existing.state, v_existing.provider_object_id;
    return;
  end if;

  insert into public.billing_top_up_purchase_operations (
    account_id, operation_id, top_up_id, resource_code, units, catalog_version,
    livemode, stripe_price_id, stripe_product_id, unit_amount_cents,
    stripe_idempotency_key, state, claim_token, lease_expires_at
  ) values (
    p_account_id, p_operation_id, p_top_up_id, p_resource_code, p_units, p_catalog_version,
    p_livemode, p_stripe_price_id, p_stripe_product_id, p_unit_amount_cents,
    p_stripe_idempotency_key, 'claimed', v_token, pg_catalog.now() + interval '5 minutes'
  )
  returning * into v_row;

  return query select
    'claimed'::text, v_row.id, v_row.claim_token, v_row.state, v_row.provider_object_id;
end;
$$;

-- Record that Stripe is about to be asked, BEFORE asking. This is the only
-- reason a crash mid-call is distinguishable from never having tried.
create or replace function public.begin_stripe_top_up_purchase_submission(
  p_operation_pk uuid,
  p_claim_token uuid,
  p_request_fingerprint text
)
returns boolean
language plpgsql
security definer
set search_path = ''
set timezone to 'UTC'
as $$
declare
  v_row public.billing_top_up_purchase_operations%rowtype;
begin
  if p_operation_pk is null or p_claim_token is null
     or p_request_fingerprint is null or p_request_fingerprint !~ '^[0-9a-f]{64}$' then
    raise exception 'top-up purchase submission input is invalid' using errcode = '22023';
  end if;

  select o.* into v_row
    from public.billing_top_up_purchase_operations o
   where o.id = p_operation_pk
   for update;
  if not found
     or v_row.state <> 'claimed'
     or v_row.claim_token is distinct from p_claim_token
     or v_row.lease_expires_at <= pg_catalog.now() then
    raise exception 'top-up purchase claim is not owned or expired' using errcode = '55000';
  end if;

  update public.billing_top_up_purchase_operations o
     set state = 'submitted',
         submission_started_at = pg_catalog.now(),
         request_fingerprint = p_request_fingerprint,
         attempt_count = o.attempt_count + 1,
         lease_expires_at = pg_catalog.now() + interval '5 minutes'
   where o.id = v_row.id;
  return true;
end;
$$;

-- The Session exists. This is terminal for the ledger: what happens to the money
-- afterwards belongs to the projector.
create or replace function public.complete_stripe_top_up_purchase(
  p_operation_pk uuid,
  p_claim_token uuid,
  p_checkout_session_id text
)
returns boolean
language plpgsql
security definer
set search_path = ''
set timezone to 'UTC'
as $$
declare
  v_row public.billing_top_up_purchase_operations%rowtype;
begin
  if p_operation_pk is null or p_claim_token is null
     or p_checkout_session_id is null or p_checkout_session_id !~ '^cs_(test|live)_[A-Za-z0-9_]+$' then
    raise exception 'top-up purchase completion input is invalid' using errcode = '22023';
  end if;

  select o.* into v_row
    from public.billing_top_up_purchase_operations o
   where o.id = p_operation_pk
   for update;
  if not found
     or v_row.state not in ('submitted', 'indeterminate')
     or v_row.claim_token is distinct from p_claim_token then
    raise exception 'top-up purchase claim is not owned or expired' using errcode = '55000';
  end if;

  update public.billing_top_up_purchase_operations o
     set state = 'checkout_created',
         provider_object_id = p_checkout_session_id,
         checkout_created_at = pg_catalog.now(),
         resolved_at = pg_catalog.now(),
         claim_token = null,
         lease_expires_at = null,
         last_error = null
   where o.id = v_row.id;
  return true;
end;
$$;

-- Stripe was asked and the answer never arrived. The claim is kept, deliberately:
-- a Session may exist, and inventing a second one is the failure this avoids.
create or replace function public.mark_stripe_top_up_purchase_indeterminate(
  p_operation_pk uuid,
  p_claim_token uuid,
  p_error_code text
)
returns boolean
language plpgsql
security definer
set search_path = ''
set timezone to 'UTC'
as $$
declare
  v_row public.billing_top_up_purchase_operations%rowtype;
begin
  if p_operation_pk is null or p_claim_token is null
     or p_error_code is null or p_error_code !~ '^[a-z][a-z0-9_]{2,63}$' then
    raise exception 'top-up purchase indeterminate input is invalid' using errcode = '22023';
  end if;

  select o.* into v_row
    from public.billing_top_up_purchase_operations o
   where o.id = p_operation_pk
   for update;
  if not found or v_row.state <> 'submitted' or v_row.claim_token is distinct from p_claim_token then
    raise exception 'top-up purchase claim is not owned or expired' using errcode = '55000';
  end if;

  update public.billing_top_up_purchase_operations o
     set state = 'indeterminate',
         last_error = p_error_code
   where o.id = v_row.id;
  return true;
end;
$$;

-- Stripe refused before creating anything. Nothing exists to reconcile.
create or replace function public.fail_stripe_top_up_purchase(
  p_operation_pk uuid,
  p_claim_token uuid,
  p_error_code text
)
returns boolean
language plpgsql
security definer
set search_path = ''
set timezone to 'UTC'
as $$
declare
  v_row public.billing_top_up_purchase_operations%rowtype;
begin
  if p_operation_pk is null or p_claim_token is null
     or p_error_code is null or p_error_code !~ '^[a-z][a-z0-9_]{2,63}$' then
    raise exception 'top-up purchase failure input is invalid' using errcode = '22023';
  end if;

  select o.* into v_row
    from public.billing_top_up_purchase_operations o
   where o.id = p_operation_pk
   for update;
  if not found
     or v_row.state not in ('claimed', 'submitted')
     or v_row.claim_token is distinct from p_claim_token then
    raise exception 'top-up purchase claim is not owned or expired' using errcode = '55000';
  end if;

  update public.billing_top_up_purchase_operations o
     set state = 'failed',
         resolved_at = pg_catalog.now(),
         claim_token = null,
         lease_expires_at = null,
         last_error = p_error_code
   where o.id = v_row.id;
  return true;
end;
$$;

comment on table public.billing_top_up_purchase_operations is
  'Durable claim for one top-up purchase intent. Terminal at checkout_created: the projector owns what happens to the money afterwards.';

