-- Source: migrations/20260821190000_voice_runtime_hardening.sql
-- Make the voice settings table tell the truth about the runtime that exists.
--
-- `recording_enabled` and `emergency_transfer_number` shipped ahead of their
-- provider behavior. The SWML answer starts no recording instruction, has no
-- recording storage/retention/deletion rail, and exposes one transfer target
-- only. A writable setting that changes neither behavior is worse than a
-- missing setting because the owner reasonably believes it took effect.
--
-- Keep both columns for the eventual feature migrations, but make the
-- unsupported state unrepresentable until those migrations deliberately remove
-- these constraints. Existing rows are made safe first.

begin;

update public.voice_settings
   set recording_enabled = false,
       emergency_transfer_number = null
 where recording_enabled is distinct from false
    or emergency_transfer_number is not null;

alter table public.voice_settings
  drop constraint if exists voice_settings_recording_runtime_disabled;
alter table public.voice_settings
  add constraint voice_settings_recording_runtime_disabled
  check (recording_enabled = false);

alter table public.voice_settings
  drop constraint if exists voice_settings_emergency_routing_runtime_disabled;
alter table public.voice_settings
  add constraint voice_settings_emergency_routing_runtime_disabled
  check (emergency_transfer_number is null);

comment on constraint voice_settings_recording_runtime_disabled on public.voice_settings is
  'Temporary product truth guard: remove only with working provider recording plus disclosure, storage, retention, and deletion.';
comment on constraint voice_settings_emergency_routing_runtime_disabled on public.voice_settings is
  'Temporary product truth guard: remove only when the provider answer implements a separately audited emergency route.';

-- The receipt inbox already carried queue state, an attempt counter, and a due
-- timestamp, but the route did not claim that work. A duplicate returned early
-- solely because ingest said `inserted = false`; if the first settlement threw,
-- every retry therefore became a successful no-op and the admitted call was
-- never settled. A rotating token and finite lease turn that latent queue shape
-- into an actual one-processor compare-and-set boundary.
alter table public.voice_events
  add column if not exists processing_token uuid;
alter table public.voice_events
  add column if not exists processing_lease_expires_at timestamptz;

-- A settlement retry is deliberately replayable: ledger finalization and call
-- history already use stable provider-call keys. Give the lead the same property
-- so a response lost after its INSERT cannot make the next attempt create a
-- second customer inquiry. PostgreSQL UNIQUE permits many NULLs, while still
-- giving PostgREST a non-partial conflict target for voice insert-or-ignore.
alter table public.leads
  add column if not exists source_voice_event_id uuid
    references public.voice_events(id) on delete set null;
create unique index if not exists leads_source_voice_event_uidx
  on public.leads (source_voice_event_id);

-- Recover any pre-CAS row that was left mid-processing. Existing definite
-- settlement failures are also made immediately eligible; unbillable/manual-
-- review failures keep next_attempt_at NULL and remain exhausted by design.
update public.voice_events
   set processing_status = 'failed',
       processing_token = null,
       processing_lease_expires_at = null,
       next_attempt_at = pg_catalog.now(),
       last_error = coalesce(last_error, 'voice_processing_interrupted')
 where processing_status = 'processing';

update public.voice_events
   set next_attempt_at = pg_catalog.now()
 where processing_status = 'failed'
   and last_error = 'settlement_failed'
   and attempt_count < 5
   and next_attempt_at is null;

update public.voice_events
   set processing_token = null,
       processing_lease_expires_at = null,
       processed_at = coalesce(processed_at, received_at),
       next_attempt_at = null
 where processing_status in ('processed', 'ignored');

alter table public.voice_events
  drop constraint if exists voice_events_processed_state_check;
alter table public.voice_events
  drop constraint if exists voice_events_processing_state_check;
alter table public.voice_events
  add constraint voice_events_processing_state_check check (
    (processing_status = 'processing'
      and processing_token is not null
      and processing_started_at is not null
      and processing_lease_expires_at is not null
      and processed_at is null)
    or (processing_status in ('received', 'failed')
      and processing_token is null
      and processing_lease_expires_at is null
      and processed_at is null)
    or (processing_status in ('processed', 'ignored')
      and processing_token is null
      and processing_lease_expires_at is null
      and processed_at is not null)
  );

create or replace function public.claim_voice_event_processing(
  p_voice_event_id uuid
)
returns table (
  claim_status text,
  claim_token uuid,
  attempt_number integer,
  retry_after_seconds integer
)
language plpgsql
security definer
set search_path = pg_catalog, pg_temp
set timezone to 'UTC'
as $$
declare
  v_now timestamptz := pg_catalog.clock_timestamp();
  v_event public.voice_events%rowtype;
  v_token uuid;
  v_retry integer;
begin
  if p_voice_event_id is null then
    raise exception 'voice event id is required' using errcode = '22023';
  end if;

  select e.* into v_event
    from public.voice_events e
   where e.id = p_voice_event_id
   for update;
  if not found then
    raise exception 'voice event does not exist' using errcode = '22023';
  end if;

  if v_event.processing_status = 'processed' then
    return query select 'processed'::text, null::uuid,
                        v_event.attempt_count, null::integer;
    return;
  end if;
  if v_event.processing_status = 'ignored' then
    return query select 'ignored'::text, null::uuid,
                        v_event.attempt_count, null::integer;
    return;
  end if;

  if v_event.processing_status = 'processing'
     and v_event.processing_lease_expires_at > v_now then
    v_retry := greatest(1, ceil(extract(epoch from
      (v_event.processing_lease_expires_at - v_now)))::integer);
    return query select 'busy'::text, null::uuid,
                        v_event.attempt_count, v_retry;
    return;
  end if;

  if v_event.attempt_count >= 5 then
    update public.voice_events e
       set processing_status = 'failed',
           processing_token = null,
           processing_lease_expires_at = null,
           next_attempt_at = null,
           last_error = coalesce(e.last_error, 'voice_processing_attempts_exhausted')
     where e.id = p_voice_event_id;
    return query select 'exhausted'::text, null::uuid,
                        v_event.attempt_count, null::integer;
    return;
  end if;

  if v_event.processing_status = 'failed'
     and v_event.next_attempt_at is null then
    return query select 'exhausted'::text, null::uuid,
                        v_event.attempt_count, null::integer;
    return;
  end if;

  if v_event.processing_status = 'failed'
     and v_event.next_attempt_at > v_now then
    v_retry := greatest(1, ceil(extract(epoch from
      (v_event.next_attempt_at - v_now)))::integer);
    return query select 'deferred'::text, null::uuid,
                        v_event.attempt_count, v_retry;
    return;
  end if;

  if v_event.processing_status not in ('received', 'failed', 'processing')
     or v_event.account_id is null then
    raise exception 'voice event is not eligible for processing' using errcode = '55000';
  end if;

  v_token := pg_catalog.gen_random_uuid();
  update public.voice_events e
     set processing_status = 'processing',
         processing_token = v_token,
         processing_started_at = v_now,
         processing_lease_expires_at = v_now + interval '5 minutes',
         attempt_count = e.attempt_count + 1,
         next_attempt_at = null,
         last_error = null
   where e.id = p_voice_event_id;

  return query select 'claimed'::text, v_token,
                      v_event.attempt_count + 1, null::integer;
end;
$$;

create or replace function public.complete_voice_event_processing(
  p_voice_event_id uuid,
  p_claim_token uuid
)
returns boolean
language plpgsql
security definer
set search_path = pg_catalog, pg_temp
set timezone to 'UTC'
as $$
begin
  update public.voice_events e
     set processing_status = 'processed',
         processing_token = null,
         processing_lease_expires_at = null,
         processed_at = pg_catalog.clock_timestamp(),
         next_attempt_at = null,
         last_error = null
   where e.id = p_voice_event_id
     and e.processing_status = 'processing'
     and e.processing_token = p_claim_token;
  if not found then
    raise exception 'voice event completion claim is stale or invalid'
      using errcode = '55000';
  end if;
  return true;
end;
$$;

create or replace function public.fail_voice_event_processing(
  p_voice_event_id uuid,
  p_claim_token uuid,
  p_error_code text,
  p_retryable boolean
)
returns table (
  failure_status text,
  retry_after_seconds integer
)
language plpgsql
security definer
set search_path = pg_catalog, pg_temp
set timezone to 'UTC'
as $$
declare
  v_now timestamptz := pg_catalog.clock_timestamp();
  v_event public.voice_events%rowtype;
  v_retry integer;
begin
  if p_error_code is null or p_error_code !~ '^[a-z][a-z0-9_]{2,99}$'
     or p_retryable is null then
    raise exception 'voice event failure arguments are invalid' using errcode = '22023';
  end if;

  select e.* into v_event
    from public.voice_events e
   where e.id = p_voice_event_id
   for update;
  if not found
     or v_event.processing_status <> 'processing'
     or v_event.processing_token is distinct from p_claim_token then
    raise exception 'voice event failure claim is stale or invalid'
      using errcode = '55000';
  end if;

  if p_retryable and v_event.attempt_count < 5 then
    v_retry := least(300, 5 * (2 ^ least(v_event.attempt_count - 1, 6)))::integer;
    update public.voice_events e
       set processing_status = 'failed',
           processing_token = null,
           processing_lease_expires_at = null,
           next_attempt_at = v_now + pg_catalog.make_interval(secs => v_retry),
           last_error = p_error_code
     where e.id = p_voice_event_id;
    return query select 'retryable'::text, v_retry;
    return;
  end if;

  update public.voice_events e
     set processing_status = 'failed',
         processing_token = null,
         processing_lease_expires_at = null,
         next_attempt_at = null,
         last_error = p_error_code
   where e.id = p_voice_event_id;
  return query select 'exhausted'::text, null::integer;
end;
$$;

revoke all on function public.claim_voice_event_processing(uuid)
  from public, anon, authenticated, service_role;
revoke all on function public.complete_voice_event_processing(uuid, uuid)
  from public, anon, authenticated, service_role;
revoke all on function public.fail_voice_event_processing(uuid, uuid, text, boolean)
  from public, anon, authenticated, service_role;
grant execute on function public.claim_voice_event_processing(uuid) to service_role;
grant execute on function public.complete_voice_event_processing(uuid, uuid) to service_role;
grant execute on function public.fail_voice_event_processing(uuid, uuid, text, boolean) to service_role;

do $$
declare
  v_definition text;
begin
  select pg_catalog.pg_get_constraintdef(c.oid)
    into v_definition
    from pg_catalog.pg_constraint c
   where c.conrelid = 'public.voice_settings'::pg_catalog.regclass
     and c.conname = 'voice_settings_recording_runtime_disabled';
  if v_definition is null or pg_catalog.strpos(v_definition, 'recording_enabled = false') = 0 then
    raise exception 'voice recording runtime guard is missing or drifted';
  end if;

  select pg_catalog.pg_get_constraintdef(c.oid)
    into v_definition
    from pg_catalog.pg_constraint c
   where c.conrelid = 'public.voice_settings'::pg_catalog.regclass
     and c.conname = 'voice_settings_emergency_routing_runtime_disabled';
  if v_definition is null or pg_catalog.strpos(v_definition, 'emergency_transfer_number IS NULL') = 0 then
    raise exception 'voice emergency routing runtime guard is missing or drifted';
  end if;

  if exists (
    select 1 from public.voice_settings
     where recording_enabled is distinct from false
        or emergency_transfer_number is not null
  ) then
    raise exception 'unsupported voice settings remain enabled';
  end if;
end $$;

commit;

-- Source: migrations/20260821191000_voice_admission_concurrency.sql
-- Make AI-voice concurrency an admission-time invariant rather than a read
-- followed by a later insert. Two webhook requests can otherwise both observe
-- one free seat and both answer, exceeding the plan limit.

begin;

alter table public.voice_call_admissions
  add column if not exists admission_state text not null default 'admitted';

alter table public.voice_call_admissions
  drop constraint if exists voice_call_admissions_state_check;
alter table public.voice_call_admissions
  add constraint voice_call_admissions_state_check
  check (admission_state in ('claimed', 'admitted'));

create or replace function public.claim_voice_call_admission(
  p_account_id uuid,
  p_provider_call_id text,
  p_concurrency_limit integer
)
returns table (
  claim_status text,
  admission_id uuid
)
language plpgsql
security definer
set search_path = pg_catalog, pg_temp
set timezone to 'UTC'
as $fn$
declare
  v_existing public.voice_call_admissions%rowtype;
  v_open bigint;
  v_id uuid;
begin
  if p_account_id is null
     or p_provider_call_id is null
     or pg_catalog.length(pg_catalog.btrim(p_provider_call_id)) = 0
     or pg_catalog.length(p_provider_call_id) > 255
     or p_concurrency_limit is null
     or p_concurrency_limit < 1
     or p_concurrency_limit > 100 then
    raise exception 'voice admission claim arguments are invalid'
      using errcode = '22023';
  end if;

  -- One transaction at a time may count and claim for a workspace. The lock is
  -- transaction-scoped, has no row lifecycle to clean up, and is independent
  -- across workspaces.
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(p_account_id::text, 84601211)
  );

  select a.* into v_existing
    from public.voice_call_admissions a
   where a.provider = 'signalwire'
     and a.provider_call_id = p_provider_call_id;

  if found then
    if v_existing.account_id <> p_account_id then
      raise exception 'voice call id is already bound to another workspace'
        using errcode = '22000';
    end if;
    if v_existing.admission_state = 'admitted' then
      return query select 'existing'::text, v_existing.id;
    else
      return query select 'busy'::text, v_existing.id;
    end if;
    return;
  end if;

  select pg_catalog.count(*) into v_open
    from public.voice_call_admissions a
   where a.account_id = p_account_id
     and a.provider = 'signalwire'
     and a.admitted_at >= pg_catalog.clock_timestamp() - interval '60 minutes'
     and not exists (
       select 1
         from public.voice_events e
        where e.provider = a.provider
          and e.provider_call_id = a.provider_call_id
     );

  if v_open >= p_concurrency_limit then
    return query select 'at_capacity'::text, null::uuid;
    return;
  end if;

  insert into public.voice_call_admissions (
    account_id, provider, provider_call_id, reservation_id,
    reserved_minutes, admission_state
  ) values (
    p_account_id, 'signalwire', p_provider_call_id, null, 0, 'claimed'
  )
  returning id into v_id;

  return query select 'claimed'::text, v_id;
end
$fn$;

create or replace function public.finalize_voice_call_admission(
  p_admission_id uuid,
  p_account_id uuid,
  p_provider_call_id text,
  p_reservation_id uuid,
  p_reserved_minutes integer,
  p_overage_key text
)
returns boolean
language plpgsql
security definer
set search_path = pg_catalog, pg_temp
set timezone to 'UTC'
as $fn$
begin
  if p_admission_id is null
     or p_account_id is null
     or p_provider_call_id is null
     or pg_catalog.length(pg_catalog.btrim(p_provider_call_id)) = 0
     or p_reserved_minutes is null
     or p_reserved_minutes < 0
     or (p_reservation_id is not null and p_overage_key is not null)
     or (p_reservation_id is null and p_overage_key is null and p_reserved_minutes <> 0)
     or ((p_reservation_id is not null or p_overage_key is not null)
         and p_reserved_minutes = 0) then
    raise exception 'voice admission finalization arguments are invalid'
      using errcode = '22023';
  end if;

  update public.voice_call_admissions a
     set reservation_id = p_reservation_id,
         reserved_minutes = p_reserved_minutes,
         overage_key = p_overage_key,
         admission_state = 'admitted'
   where a.id = p_admission_id
     and a.account_id = p_account_id
     and a.provider = 'signalwire'
     and a.provider_call_id = p_provider_call_id
     and a.admission_state = 'claimed';

  if found then
    return true;
  end if;

  -- A response can be lost after the transaction commits. Repeating the same
  -- finalization is success; a different value is never silently accepted.
  return exists (
    select 1 from public.voice_call_admissions a
     where a.id = p_admission_id
       and a.account_id = p_account_id
       and a.provider = 'signalwire'
       and a.provider_call_id = p_provider_call_id
       and a.admission_state = 'admitted'
       and a.reservation_id is not distinct from p_reservation_id
       and a.reserved_minutes = p_reserved_minutes
       and a.overage_key is not distinct from p_overage_key
  );
end
$fn$;

create or replace function public.release_voice_call_admission_claim(
  p_admission_id uuid,
  p_account_id uuid,
  p_provider_call_id text
)
returns boolean
language plpgsql
security definer
set search_path = pg_catalog, pg_temp
set timezone to 'UTC'
as $fn$
begin
  delete from public.voice_call_admissions a
   where a.id = p_admission_id
     and a.account_id = p_account_id
     and a.provider = 'signalwire'
     and a.provider_call_id = p_provider_call_id
     and a.admission_state = 'claimed'
     and a.reservation_id is null
     and a.reserved_minutes = 0
     and a.overage_key is null;
  return found;
end
$fn$;

revoke all on function public.claim_voice_call_admission(uuid, text, integer)
  from public, anon, authenticated, service_role;
revoke all on function public.finalize_voice_call_admission(uuid, uuid, text, uuid, integer, text)
  from public, anon, authenticated, service_role;
revoke all on function public.release_voice_call_admission_claim(uuid, uuid, text)
  from public, anon, authenticated, service_role;
grant execute on function public.claim_voice_call_admission(uuid, text, integer) to service_role;
grant execute on function public.finalize_voice_call_admission(uuid, uuid, text, uuid, integer, text) to service_role;
grant execute on function public.release_voice_call_admission_claim(uuid, uuid, text) to service_role;

commit;

-- Source: migrations/20260821191500_sms_usage_finalization.sql
-- Preserve text-credit/overage evidence before provider egress and reconcile
-- it after the durable delivery task reaches a known local outcome. A socket
-- can succeed while its response is lost; releasing the hold in that case can
-- make a carrier-delivered message free.

begin;

alter table public.sms_events
  add column if not exists text_usage_kind text,
  add column if not exists text_usage_reservation_id uuid
    references public.usage_reservations(id) on delete restrict,
  add column if not exists text_usage_finalization_key text,
  add column if not exists text_usage_overage_key text,
  add column if not exists text_usage_state text,
  add column if not exists text_usage_last_error text,
  add column if not exists text_usage_updated_at timestamptz;

alter table public.sms_events
  drop constraint if exists sms_events_text_usage_shape_check;
alter table public.sms_events
  add constraint sms_events_text_usage_shape_check check (
    (text_usage_kind is null
      and text_usage_reservation_id is null
      and text_usage_finalization_key is null
      and text_usage_overage_key is null
      and text_usage_state is null)
    or (text_usage_kind = 'reservation'
      and text_usage_reservation_id is not null
      and text_usage_finalization_key is not null
      and text_usage_overage_key is null
      and text_usage_state in ('held', 'committed', 'released', 'reconciliation_failed'))
    or (text_usage_kind = 'overage'
      and text_usage_reservation_id is null
      and text_usage_finalization_key is null
      and text_usage_overage_key is not null
      and text_usage_state in ('accrued', 'committed', 'released', 'reconciliation_failed'))
    or (text_usage_kind = 'unmetered'
      and text_usage_reservation_id is null
      and text_usage_finalization_key is null
      and text_usage_overage_key is null
      and text_usage_state = 'unmetered')
  );

create index if not exists sms_events_text_usage_reconcile_idx
  on public.sms_events (text_usage_updated_at, id)
  where text_usage_state in ('held', 'accrued', 'reconciliation_failed');

create or replace function public.mark_sms_delivery_request_started_with_usage(
  p_sms_event_id uuid,
  p_claim_token uuid,
  p_usage_kind text,
  p_reservation_id uuid,
  p_finalization_key text,
  p_overage_key text
)
returns boolean
language plpgsql
security definer
set search_path = pg_catalog, pg_temp
set timezone to 'UTC'
as $fn$
declare
  v_event public.sms_events%rowtype;
  v_task public.sms_delivery_tasks%rowtype;
  v_sender public.sms_sender_numbers%rowtype;
  v_consent public.sms_consent%rowtype;
  v_preference public.sms_sender_keyword_preferences%rowtype;
  v_reservation public.usage_reservations%rowtype;
  v_overage public.workspace_overage_accrual_events%rowtype;
  v_now timestamptz := pg_catalog.clock_timestamp();
begin
  if p_usage_kind not in ('reservation', 'overage', 'unmetered')
     or (p_usage_kind = 'reservation' and (
       p_reservation_id is null or p_finalization_key is null or p_overage_key is not null))
     or (p_usage_kind = 'overage' and (
       p_reservation_id is not null or p_finalization_key is not null or p_overage_key is null))
     or (p_usage_kind = 'unmetered' and (
       p_reservation_id is not null or p_finalization_key is not null or p_overage_key is not null)) then
    raise exception 'SMS text-usage evidence is malformed' using errcode = '22023';
  end if;

  select e.* into v_event
    from public.sms_events e
   where e.id = p_sms_event_id
   for update;
  select t.* into v_task
    from public.sms_delivery_tasks t
   where t.sms_event_id = p_sms_event_id
   for update;
  if v_event.id is null or v_task.sms_event_id is null
     or v_event.status <> 'queued'
     or v_task.task_state <> 'leased'
     or v_task.claim_token is distinct from p_claim_token
     or v_task.lease_expires_at <= v_now
     or v_task.request_started_at is not null then
    raise exception 'SMS delivery usage boundary is stale or invalid'
      using errcode = '55000';
  end if;

  -- `stage_sms_delivery` is an early filter, not the no-return boundary. Lock
  -- and prove the exact sender and consent again in the same transaction that
  -- records request_started_at. A STOP or suspension that commits before this
  -- boundary therefore wins; one trying concurrently waits behind these locks
  -- and observes request_started_at as the already-crossed boundary.
  select s.* into v_sender
    from public.sms_sender_numbers s
   where s.id = v_event.sender_number_id
     and s.provider = v_event.provider
     and s.purpose = v_event.sender_purpose
     and (s.account_id is null or s.account_id = v_event.account_id)
     and s.provisioning_status = 'active'
     and s.assignment_state = 'assigned'
     and s.inbound_ready
     and s.suspended_at is null
   for share;
  if not found then
    raise exception 'SMS sender became unavailable before provider request'
      using errcode = 'P5102';
  end if;

  -- This lock also covers the no-row sender-preference case. The inbound
  -- keyword transaction takes the same key before its upsert, so an INSERT of a
  -- first STOP preference cannot race this check as a phantom.
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'sms-sender-consent:' || v_sender.id::text || ':' || v_event.phone_number,
      20260821
    )
  );

  select c.* into v_consent
    from public.sms_consent c
   where c.account_id = v_event.account_id
     and c.phone_number = v_event.phone_number
   for share;
  if not found
     or v_consent.status <> 'opted_in'
     or v_consent.consented_at is null
     or v_consent.opted_out_at is not null then
    raise exception 'SMS consent became unavailable before provider request'
      using errcode = 'P5101';
  end if;

  select p.* into v_preference
    from public.sms_sender_keyword_preferences p
   where p.sender_number_id = v_sender.id
     and p.phone_number = v_event.phone_number
   for share;
  if found and v_preference.status = 'opted_out'
     and v_preference.opted_out_at is not null then
    raise exception 'SMS sender preference became opted out before provider request'
      using errcode = 'P5103';
  end if;

  if p_usage_kind = 'reservation' then
    select r.* into v_reservation
      from public.usage_reservations r
     where r.id = p_reservation_id;
    if not found
       or v_reservation.account_id <> v_event.account_id
       or v_reservation.resource_code <> 'text_segments'
       or v_reservation.operation_type <> 'text_send'
       or v_reservation.state <> 'reserved'
       or p_finalization_key <> v_reservation.idempotency_key || ':commit' then
      raise exception 'SMS text reservation does not match this delivery'
        using errcode = '22000';
    end if;
  elsif p_usage_kind = 'overage' then
    select o.* into v_overage
      from public.workspace_overage_accrual_events o
     where o.account_id = v_event.account_id
       and o.idempotency_key = p_overage_key;
    if not found
       or v_overage.resource_code <> 'text_segments'
       or v_overage.released_at is not null then
      raise exception 'SMS text overage does not match this delivery'
        using errcode = '22000';
    end if;
  end if;

  update public.sms_events e
     set text_usage_kind = p_usage_kind,
         text_usage_reservation_id = p_reservation_id,
         text_usage_finalization_key = p_finalization_key,
         text_usage_overage_key = p_overage_key,
         text_usage_state = case p_usage_kind
           when 'reservation' then 'held'
           when 'overage' then 'accrued'
           else 'unmetered'
         end,
         text_usage_last_error = null,
         text_usage_updated_at = v_now
   where e.id = p_sms_event_id;

  -- The legacy two-argument function owns the already-proven task/event/attempt
  -- transition. Calling it here keeps evidence plus no-return boundary in one
  -- transaction without maintaining a second copy of that state machine.
  perform public.mark_sms_delivery_request_started(p_sms_event_id, p_claim_token);
  return true;
end
$fn$;

-- A request-start RPC can commit and then lose its response. The worker still
-- knows one useful fact: its provider fetch was never opened. This token-bound
-- compensator releases the exact persisted usage evidence and returns the
-- attempt to its pre-request state; fail_sms_delivery can then apply the normal
-- retry policy. If this compensator is itself uncertain, the started boundary
-- remains and fail_sms_delivery quarantines the task as indeterminate.
create or replace function public.rollback_sms_delivery_pre_request_boundary(
  p_sms_event_id uuid,
  p_claim_token uuid
)
returns boolean
language plpgsql
security definer
set search_path = pg_catalog, pg_temp
set timezone to 'UTC'
as $fn$
declare
  v_event public.sms_events%rowtype;
  v_task public.sms_delivery_tasks%rowtype;
  v_reservation public.usage_reservations%rowtype;
  v_overage public.workspace_overage_accrual_events%rowtype;
  v_released bigint;
  v_ok boolean;
  v_now timestamptz := pg_catalog.clock_timestamp();
begin
  select e.* into v_event
    from public.sms_events e
   where e.id = p_sms_event_id
   for update;
  select t.* into v_task
    from public.sms_delivery_tasks t
   where t.sms_event_id = p_sms_event_id
   for update;
  if v_event.id is null or v_task.sms_event_id is null
     or v_task.task_state <> 'leased'
     or v_task.claim_token is distinct from p_claim_token
     or v_task.lease_expires_at <= v_now then
    raise exception 'SMS pre-request rollback lease is stale or invalid'
      using errcode = '55000';
  end if;

  -- The marker never committed. There is no durable boundary to undo and the
  -- send helper owns release of its local-only hold.
  if v_task.request_started_at is null then
    if v_event.text_usage_kind is not null then
      raise exception 'SMS pre-request usage exists without a request boundary'
        using errcode = '55000';
    end if;
    return true;
  end if;

  if v_event.status <> 'sending' or v_event.provider_id is not null
     or v_event.text_usage_kind is null then
    raise exception 'SMS pre-request boundary cannot be rolled back'
      using errcode = '55000';
  end if;

  if v_event.text_usage_kind = 'reservation' then
    select r.* into v_reservation
      from public.usage_reservations r
     where r.id = v_event.text_usage_reservation_id
       and r.account_id = v_event.account_id
     for update;
    if not found
       or v_reservation.resource_code <> 'text_segments'
       or v_reservation.operation_type <> 'text_send'
       or v_reservation.idempotency_key || ':commit'
            <> v_event.text_usage_finalization_key then
      raise exception 'SMS pre-request reservation is invalid'
        using errcode = '22000';
    end if;
    if v_reservation.state = 'reserved' then
      v_ok := public.release_usage_reservation(
        v_event.text_usage_reservation_id,
        v_event.text_usage_finalization_key,
        'provider_request_not_opened');
      if not v_ok then
        raise exception 'SMS pre-request reservation was not released'
          using errcode = '55000';
      end if;
    elsif v_reservation.state not in ('released', 'expired') then
      raise exception 'SMS pre-request reservation is already final'
        using errcode = '55000';
    end if;
  elsif v_event.text_usage_kind = 'overage' then
    select o.* into v_overage
      from public.workspace_overage_accrual_events o
     where o.account_id = v_event.account_id
       and o.idempotency_key = v_event.text_usage_overage_key
     for update;
    if not found or v_overage.resource_code <> 'text_segments' then
      raise exception 'SMS pre-request overage is invalid'
        using errcode = '22000';
    end if;
    if v_overage.released_at is null then
      v_released := public.release_usage_overage(
        v_event.account_id, v_event.text_usage_overage_key);
      if v_released <= 0 then
        raise exception 'SMS pre-request overage was not released'
          using errcode = '55000';
      end if;
    end if;
  elsif v_event.text_usage_kind <> 'unmetered' then
    raise exception 'SMS pre-request usage kind is invalid'
      using errcode = '22000';
  end if;

  update public.sms_events
     set status = 'queued', send_started_at = null,
         text_usage_kind = null,
         text_usage_reservation_id = null,
         text_usage_finalization_key = null,
         text_usage_overage_key = null,
         text_usage_state = null,
         text_usage_last_error = null,
         text_usage_updated_at = null,
         updated_at = v_now
   where id = p_sms_event_id;
  update public.sms_delivery_tasks
     set request_started_at = null, updated_at = v_now
   where sms_event_id = p_sms_event_id;
  update public.sms_delivery_attempts
     set request_started_at = null
   where claim_token = p_claim_token and outcome is null;
  if not found then
    raise exception 'SMS pre-request rollback has no open attempt'
      using errcode = '55000';
  end if;
  return true;
end
$fn$;

-- A definitive carrier rejection may be retried only after the exact usage
-- hold for this attempt is proven released. The send helper makes a best-effort
-- release, but a lost release response cannot authorize overwriting that
-- evidence with the next attempt. Re-prove/finalize it here in the same
-- transaction that requeues the delivery.
create or replace function public.record_sms_delivery_provider_rejection(
  p_sms_event_id uuid,
  p_claim_token uuid,
  p_error_code text,
  p_retryable boolean
)
returns table (
  failure_status text,
  task_state text,
  next_attempt_at timestamptz
)
language plpgsql
security definer
set search_path = pg_catalog, pg_temp
set timezone to 'UTC'
as $fn$
declare
  v_now timestamptz := pg_catalog.clock_timestamp();
  v_task public.sms_delivery_tasks%rowtype;
  v_event public.sms_events%rowtype;
  v_reservation public.usage_reservations%rowtype;
  v_overage public.workspace_overage_accrual_events%rowtype;
  v_next timestamptz;
  v_usage_released boolean := false;
  v_release_ok boolean;
  v_released bigint;
begin
  if p_error_code is null or p_error_code !~ '^[a-z][a-z0-9_]{2,99}$'
     or p_retryable is null then
    raise exception 'SMS provider rejection arguments are invalid'
      using errcode = '22023';
  end if;

  select t.* into v_task
    from public.sms_delivery_tasks t
   where t.sms_event_id = p_sms_event_id
   for update;
  select e.* into v_event
    from public.sms_events e
   where e.id = p_sms_event_id
   for update;
  if v_task.sms_event_id is null or v_event.id is null
     or v_task.task_state <> 'leased'
     or v_task.claim_token is distinct from p_claim_token
     or v_task.request_started_at is null
     or v_event.status <> 'sending' then
    raise exception 'SMS provider rejection lease is stale or not request-started'
      using errcode = '55000';
  end if;

  if v_event.text_usage_kind = 'reservation' then
    select r.* into v_reservation
      from public.usage_reservations r
     where r.id = v_event.text_usage_reservation_id
       and r.account_id = v_event.account_id
     for update;
    if found
       and v_reservation.resource_code = 'text_segments'
       and v_reservation.operation_type = 'text_send'
       and v_reservation.idempotency_key || ':commit'
             = v_event.text_usage_finalization_key then
      if v_reservation.state = 'reserved' then
        v_release_ok := public.release_usage_reservation(
          v_event.text_usage_reservation_id,
          v_event.text_usage_finalization_key,
          'provider_rejected');
        v_usage_released := coalesce(v_release_ok, false);
      else
        v_usage_released := v_reservation.state in ('released', 'expired');
      end if;
    end if;
  elsif v_event.text_usage_kind = 'overage' then
    select o.* into v_overage
      from public.workspace_overage_accrual_events o
     where o.account_id = v_event.account_id
       and o.idempotency_key = v_event.text_usage_overage_key
       and o.resource_code = 'text_segments'
     for update;
    if found then
      if v_overage.released_at is null then
        v_released := public.release_usage_overage(
          v_event.account_id, v_event.text_usage_overage_key);
        v_usage_released := v_released > 0;
      else
        v_usage_released := true;
      end if;
    end if;
  elsif v_event.text_usage_kind = 'unmetered' then
    v_usage_released := true;
  elsif v_event.text_usage_kind is null then
    -- Compatibility for an already-request-started row created before usage
    -- evidence existed. Treat it explicitly as unmetered; never manufacture a
    -- reservation or block a safe provider-rejection retry on absent legacy data.
    v_usage_released := true;
  end if;

  update public.sms_events e
     set text_usage_kind = coalesce(e.text_usage_kind, 'unmetered'),
         text_usage_state = case
           when v_usage_released and (e.text_usage_kind is null
             or e.text_usage_kind = 'unmetered') then 'unmetered'
           when v_usage_released then 'released'
           else 'reconciliation_failed'
         end,
         text_usage_last_error = case when v_usage_released then null
           else 'sms_usage_release_unproven' end,
         text_usage_updated_at = v_now
   where e.id = p_sms_event_id;

  -- A retry without proven release can double-charge. Terminalize the provider-
  -- rejected attempt and leave its exact evidence for reconciliation instead.
  if p_retryable and v_usage_released and v_task.attempt_count < 8 then
    v_next := v_now + pg_catalog.make_interval(
      secs => least(900, 15 * (2 ^ least(v_task.attempt_count - 1, 6)))::integer
    );
    update public.sms_events e
       set status = 'queued', send_started_at = null,
           error_reason = p_error_code, updated_at = v_now
     where e.id = p_sms_event_id and e.status = 'sending';
    if not found then
      raise exception 'Retryable SMS rejection has no exact sending event'
        using errcode = '55000';
    end if;
    update public.sms_delivery_tasks t
       set task_state = 'queued', claim_token = null,
           lease_expires_at = null, request_started_at = null,
           available_at = v_next, last_error_code = p_error_code,
           updated_at = v_now
     where t.sms_event_id = p_sms_event_id;
    update public.sms_delivery_attempts a
       set outcome = 'provider_rejected_retryable', error_code = p_error_code,
           finished_at = v_now
     where a.claim_token = p_claim_token and a.outcome is null;
    if not found then
      raise exception 'Retryable SMS rejection has no open attempt'
        using errcode = '55000';
    end if;
    return query select 'retryable'::text, 'queued'::text, v_next;
    return;
  end if;

  update public.sms_events e
     set status = 'failed', error_reason = p_error_code,
         failed_at = v_now, updated_at = v_now
   where e.id = p_sms_event_id and e.status = 'sending';
  if not found then
    raise exception 'Terminal SMS rejection has no exact sending event'
      using errcode = '55000';
  end if;
  update public.sms_delivery_tasks t
     set task_state = 'failed', claim_token = null,
         lease_expires_at = null, last_error_code = case
           when v_usage_released then p_error_code
           else 'sms_usage_release_unproven'
         end,
         failed_at = v_now, updated_at = v_now
   where t.sms_event_id = p_sms_event_id;
  update public.sms_delivery_attempts a
     set outcome = 'provider_rejected_terminal', error_code = p_error_code,
         finished_at = v_now
   where a.claim_token = p_claim_token and a.outcome is null;
  if not found then
    raise exception 'Terminal SMS rejection has no open attempt'
      using errcode = '55000';
  end if;
  return query select 'terminal'::text, 'failed'::text, null::timestamptz;
end
$fn$;

create or replace function public.reconcile_sms_text_usage(
  p_batch_size integer default 50
)
returns table (
  examined integer,
  committed integer,
  released integer,
  unmetered integer,
  failed integer
)
language plpgsql
security definer
set search_path = pg_catalog, pg_temp
set timezone to 'UTC'
as $fn$
declare
  v_row record;
  v_reservation public.usage_reservations%rowtype;
  v_overage public.workspace_overage_accrual_events%rowtype;
  v_should_commit boolean;
  v_ok boolean;
  v_released bigint;
  v_examined integer := 0;
  v_committed integer := 0;
  v_released_count integer := 0;
  v_unmetered integer := 0;
  v_failed integer := 0;
begin
  if p_batch_size is null or p_batch_size < 1 or p_batch_size > 500 then
    raise exception 'SMS text-usage reconciliation batch is invalid'
      using errcode = '22023';
  end if;

  for v_row in
    select e.id, e.account_id, e.provider_id, e.provider_accepted_at,
           e.text_usage_kind,
           e.text_usage_reservation_id, e.text_usage_finalization_key,
           e.text_usage_overage_key, t.task_state
      from public.sms_events e
      join public.sms_delivery_tasks t on t.sms_event_id = e.id
     where e.text_usage_state in ('held', 'accrued', 'reconciliation_failed')
       and t.task_state in ('completed', 'indeterminate', 'failed', 'cancelled')
     order by e.text_usage_updated_at nulls first, e.id
     limit p_batch_size
     for update of e skip locked
  loop
    v_examined := v_examined + 1;
    -- A provider identity/acceptance timestamp is the billing boundary even if
    -- a later delivery callback says failed or undelivered. Only a pre-accept
    -- provider rejection is releasable.
    v_should_commit := v_row.task_state in ('completed', 'indeterminate')
      or v_row.provider_id is not null
      or v_row.provider_accepted_at is not null;
    begin
      if v_row.text_usage_kind = 'reservation' then
        select r.* into v_reservation
          from public.usage_reservations r
         where r.id = v_row.text_usage_reservation_id
           and r.account_id = v_row.account_id
         for update;
        if not found then
          raise exception 'SMS usage reservation is missing' using errcode = 'P0002';
        end if;

        if v_should_commit then
          if v_reservation.state = 'reserved' then
            v_ok := public.commit_usage_reservation(
              v_row.text_usage_reservation_id, v_row.text_usage_finalization_key);
          else
            v_ok := v_reservation.state = 'committed'
              and v_reservation.finalization_key = v_row.text_usage_finalization_key;
          end if;
          if not v_ok then
            raise exception 'SMS usage reservation is not committable'
              using errcode = '55000';
          end if;
          update public.sms_events set text_usage_state = 'committed',
            text_usage_last_error = null, text_usage_updated_at = pg_catalog.clock_timestamp()
           where id = v_row.id;
          v_committed := v_committed + 1;
        else
          if v_reservation.state = 'reserved' then
            v_ok := public.release_usage_reservation(
              v_row.text_usage_reservation_id, v_row.text_usage_finalization_key,
              'provider_rejected');
          else
            v_ok := v_reservation.state in ('released', 'expired');
          end if;
          if not v_ok then
            raise exception 'SMS usage reservation is not releasable'
              using errcode = '55000';
          end if;
          update public.sms_events set text_usage_state = 'released',
            text_usage_last_error = null, text_usage_updated_at = pg_catalog.clock_timestamp()
           where id = v_row.id;
          v_released_count := v_released_count + 1;
        end if;
      elsif v_row.text_usage_kind = 'overage' then
        select o.* into v_overage
          from public.workspace_overage_accrual_events o
         where o.account_id = v_row.account_id
           and o.idempotency_key = v_row.text_usage_overage_key
         for update;
        if not found then
          raise exception 'SMS usage overage is missing' using errcode = 'P0002';
        end if;

        if v_should_commit then
          if v_overage.released_at is not null then
            raise exception 'SMS usage overage was released before commit'
              using errcode = '55000';
          end if;
          update public.sms_events set text_usage_state = 'committed',
            text_usage_last_error = null, text_usage_updated_at = pg_catalog.clock_timestamp()
           where id = v_row.id;
          v_committed := v_committed + 1;
        else
          if v_overage.released_at is null then
            v_released := public.release_usage_overage(
              v_row.account_id, v_row.text_usage_overage_key);
            if v_released <= 0 then
              raise exception 'SMS usage overage release changed nothing'
                using errcode = '55000';
            end if;
          end if;
          update public.sms_events set text_usage_state = 'released',
            text_usage_last_error = null, text_usage_updated_at = pg_catalog.clock_timestamp()
           where id = v_row.id;
          v_released_count := v_released_count + 1;
        end if;
      else
        update public.sms_events set text_usage_state = 'unmetered',
          text_usage_last_error = null, text_usage_updated_at = pg_catalog.clock_timestamp()
         where id = v_row.id;
        v_unmetered := v_unmetered + 1;
      end if;
    exception when others then
      update public.sms_events
         set text_usage_state = 'reconciliation_failed',
             text_usage_last_error = 'sms_usage_reconciliation_failed',
             text_usage_updated_at = pg_catalog.clock_timestamp()
       where id = v_row.id;
      v_failed := v_failed + 1;
    end;
  end loop;

  -- Recover a reservation whose create RPC committed but its response was lost
  -- before the request marker could persist the reservation id. The durable
  -- attempt identity makes the key derivable without trusting process memory.
  for v_row in
    select a.id as attempt_id, e.account_id, r.id as reservation_id,
           r.idempotency_key
      from public.sms_delivery_attempts a
      join public.sms_events e on e.id = a.sms_event_id
      join public.usage_reservations r
        on r.account_id = e.account_id
       and r.resource_code = 'text_segments'
       and r.operation_type = 'text_send'
       and r.idempotency_key = 'text-credit:v1:sms:' || e.id::text
         || ':attempt:' || a.attempt_number::text
     where a.outcome is not null
       and a.request_started_at is null
       and r.state = 'reserved'
     order by a.finished_at nulls last, a.id
     limit p_batch_size
     for update of r skip locked
  loop
    v_examined := v_examined + 1;
    begin
      v_ok := public.release_usage_reservation(
        v_row.reservation_id,
        v_row.idempotency_key || ':commit',
        'provider_request_not_opened');
      if not v_ok then
        raise exception 'Orphan SMS reservation was not released'
          using errcode = '55000';
      end if;
      v_released_count := v_released_count + 1;
    exception when others then
      v_failed := v_failed + 1;
    end;
  end loop;

  -- Same recovery for an overage authorization whose commit response was lost.
  -- This is the charge-without-send case: the attempt is terminal and proves
  -- that the provider request boundary was never crossed.
  for v_row in
    select a.id as attempt_id, e.account_id, o.idempotency_key
      from public.sms_delivery_attempts a
      join public.sms_events e on e.id = a.sms_event_id
      join public.workspace_overage_accrual_events o
        on o.account_id = e.account_id
       and o.resource_code = 'text_segments'
       and o.idempotency_key = 'text-credit:v1:sms:' || e.id::text
         || ':attempt:' || a.attempt_number::text || ':overage'
     where a.outcome is not null
       and a.request_started_at is null
       and o.released_at is null
     order by a.finished_at nulls last, a.id
     limit p_batch_size
     for update of o skip locked
  loop
    v_examined := v_examined + 1;
    begin
      v_released := public.release_usage_overage(
        v_row.account_id, v_row.idempotency_key);
      if v_released <= 0 then
        raise exception 'Orphan SMS overage was not released'
          using errcode = '55000';
      end if;
      v_released_count := v_released_count + 1;
    exception when others then
      v_failed := v_failed + 1;
    end;
  end loop;

  return query select v_examined, v_committed, v_released_count, v_unmetered, v_failed;
end
$fn$;

revoke all on function public.mark_sms_delivery_request_started_with_usage(
  uuid, uuid, text, uuid, text, text)
  from public, anon, authenticated, service_role;
revoke all on function public.rollback_sms_delivery_pre_request_boundary(uuid, uuid)
  from public, anon, authenticated, service_role;
revoke all on function public.reconcile_sms_text_usage(integer)
  from public, anon, authenticated, service_role;
grant execute on function public.mark_sms_delivery_request_started_with_usage(
  uuid, uuid, text, uuid, text, text) to service_role;
grant execute on function public.rollback_sms_delivery_pre_request_boundary(uuid, uuid)
  to service_role;
grant execute on function public.reconcile_sms_text_usage(integer) to service_role;

commit;

-- Source: migrations/20260821191700_sms_status_auto_reconciliation.sql
-- Replay authenticated status receipts that arrived before provider identity
-- was persisted. This migration follows both the webhook inbox and delivery
-- queue foundations so neither lower-level migration depends on the other.

begin;

create or replace function public.reconcile_sms_matched_status_receipts(
  p_batch_size integer default 50
)
returns table (
  examined integer,
  projected integer,
  failed integer
)
language plpgsql
security definer
set search_path = pg_catalog, pg_temp
set timezone to 'UTC'
as $fn$
declare
  v_receipt public.sms_webhook_receipts%rowtype;
  v_disposition text;
  v_event_id uuid;
  v_examined integer := 0;
  v_projected integer := 0;
  v_failed integer := 0;
begin
  if p_batch_size is null or p_batch_size < 1 or p_batch_size > 500 then
    raise exception 'SMS matched-status reconciliation batch is invalid'
      using errcode = '22023';
  end if;

  for v_receipt in
    select r.*
      from public.sms_webhook_receipts r
     where r.webhook_kind = 'status'
       and r.processing_state = 'review'
       and r.disposition = 'unmatched_status'
       and r.sms_event_id is null
       and exists (
         select 1 from public.sms_events e
          where e.provider = r.provider
            and e.provider_id = r.provider_event_id
       )
     order by r.received_at, r.id
     limit p_batch_size
     for update skip locked
  loop
    v_examined := v_examined + 1;
    begin
      select s.status_disposition, s.sms_event_id
        into v_disposition, v_event_id
        from public.apply_sms_delivery_status_webhook(
          v_receipt.provider,
          v_receipt.provider_event_id,
          v_receipt.provider_status,
          v_receipt.provider_error_code,
          v_receipt.receipt_key,
          v_receipt.body_sha256,
          v_receipt.content_type,
          v_receipt.request_url
        ) s;
      if v_event_id is null
         or v_disposition not in ('applied', 'ignored_stale', 'ignored_terminal') then
        raise exception 'Matched SMS status receipt did not project'
          using errcode = '55000';
      end if;
      v_projected := v_projected + 1;
    exception when others then
      v_failed := v_failed + 1;
    end;
  end loop;

  return query select v_examined, v_projected, v_failed;
end
$fn$;

revoke all on function public.reconcile_sms_matched_status_receipts(integer)
  from public, anon, authenticated, service_role;
grant execute on function public.reconcile_sms_matched_status_receipts(integer)
  to service_role;

commit;

-- Source: migrations/20260821192000_sms_inbound_action_outbox.sql
-- Durable, receipt-keyed processing for ordinary inbound SMS replies.
--
-- Authenticated carrier ingest remains the only creator of work. The trigger
-- below runs in the same transaction that stores the inbound transcript, so a
-- routed receipt can never commit without its action task. Domain effects and
-- the exact reply intent commit together; carrier egress remains in the
-- existing durable sms_delivery queue.

begin;

-- An accepted estimate creates one route stop. This source key makes replay
-- harmless even if the caller loses the RPC response after commit.
alter table public.route_stops
  add column if not exists source_sms_webhook_receipt_id uuid
    references public.sms_webhook_receipts(id) on delete restrict;
create unique index if not exists route_stops_sms_webhook_receipt_uidx
  on public.route_stops (source_sms_webhook_receipt_id)
  where source_sms_webhook_receipt_id is not null;

create table if not exists public.sms_inbound_action_tasks (
  id uuid primary key default pg_catalog.gen_random_uuid(),
  webhook_receipt_id uuid not null unique
    references public.sms_webhook_receipts(id) on delete restrict,
  account_id uuid not null references public.accounts(id) on delete restrict,
  sender_number_id uuid not null
    references public.sms_sender_numbers(id) on delete restrict,
  sms_message_id uuid not null unique
    references public.sms_messages(id) on delete restrict,
  task_state text not null default 'pending'
    check (task_state in ('pending', 'processing', 'failed', 'completed')),
  attempt_count integer not null default 0 check (attempt_count >= 0),
  next_attempt_at timestamptz not null default pg_catalog.now(),
  claim_token uuid,
  lease_expires_at timestamptz,
  effect_applied_at timestamptz,
  outcome jsonb,
  customer_reply_event_id uuid references public.sms_events(id) on delete restrict,
  owner_alert_event_id uuid references public.sms_events(id) on delete restrict,
  last_error text,
  created_at timestamptz not null default pg_catalog.now(),
  updated_at timestamptz not null default pg_catalog.now(),
  completed_at timestamptz,
  constraint sms_inbound_action_tasks_claim_shape check (
    (task_state = 'processing' and claim_token is not null and lease_expires_at is not null)
    or (task_state <> 'processing' and claim_token is null and lease_expires_at is null)
  ),
  constraint sms_inbound_action_tasks_effect_shape check (
    (effect_applied_at is null and outcome is null)
    or (effect_applied_at is not null and outcome is not null)
  ),
  constraint sms_inbound_action_tasks_completed_shape check (
    (task_state = 'completed' and completed_at is not null and effect_applied_at is not null)
    or (task_state <> 'completed' and completed_at is null)
  )
);

create index if not exists sms_inbound_action_tasks_due_idx
  on public.sms_inbound_action_tasks (next_attempt_at, created_at, id)
  where task_state in ('pending', 'failed', 'processing');

-- Candidate producers and the reply applier share this per-account/recipient
-- advisory lock. It closes the count-then-mutate race without a global lock on
-- jobs or offers. The trigger is deliberately at the table boundary so every
-- writer (dashboard, cron, public token page, or future code) participates.
create or replace function public.sms_normalize_recipient_phone(p_phone text)
returns text
language sql
immutable
set search_path = pg_catalog, pg_temp
as $$
  with value as (
    select pg_catalog.regexp_replace(coalesce(p_phone, ''), '[^0-9]', '', 'g') as digits
  )
  select case
    when pg_catalog.length(digits) = 10 then '+1' || digits
    when pg_catalog.length(digits) between 8 and 15 and digits ~ '^[1-9][0-9]+$'
      then '+' || digits
    else null::text
  end
  from value
$$;

create or replace function public.sms_inbound_recipient_lock_key(
  p_account_id uuid,
  p_phone text
)
returns bigint
language sql
immutable
set search_path = pg_catalog, pg_temp
as $$
  select pg_catalog.hashtextextended(
    coalesce(p_account_id::text, '') || ':' ||
    coalesce(public.sms_normalize_recipient_phone(p_phone), ''),
    0
  )
$$;

create or replace function public.lock_sms_inbound_candidate_recipient()
returns trigger
language plpgsql
security definer
set search_path = pg_catalog, pg_temp
as $$
declare
  v_old_key bigint;
  v_new_key bigint;
begin
  if tg_op <> 'INSERT' then
    v_old_key := public.sms_inbound_recipient_lock_key(
      old.account_id,
      coalesce(
        pg_catalog.to_jsonb(old)->>'client_phone',
        pg_catalog.to_jsonb(old)->>'phone',
        pg_catalog.to_jsonb(old)->>'phone_number'
      )
    );
  end if;
  if tg_op <> 'DELETE' then
    v_new_key := public.sms_inbound_recipient_lock_key(
      new.account_id,
      coalesce(
        pg_catalog.to_jsonb(new)->>'client_phone',
        pg_catalog.to_jsonb(new)->>'phone',
        pg_catalog.to_jsonb(new)->>'phone_number'
      )
    );
  end if;

  -- Stable ordering prevents two phone/account swaps from deadlocking.
  if v_old_key is not null and v_new_key is not null and v_old_key <> v_new_key then
    perform pg_catalog.pg_advisory_xact_lock(least(v_old_key, v_new_key));
    perform pg_catalog.pg_advisory_xact_lock(greatest(v_old_key, v_new_key));
  else
    perform pg_catalog.pg_advisory_xact_lock(coalesce(v_new_key, v_old_key));
  end if;
  if tg_op = 'DELETE' then return old; end if;
  return new;
end;
$$;

drop trigger if exists estimate_offers_sms_inbound_recipient_lock
  on public.estimate_offers;
create trigger estimate_offers_sms_inbound_recipient_lock
before insert or update or delete on public.estimate_offers
for each row execute function public.lock_sms_inbound_candidate_recipient();

drop trigger if exists reschedule_offers_sms_inbound_recipient_lock
  on public.reschedule_offers;
create trigger reschedule_offers_sms_inbound_recipient_lock
before insert or update or delete on public.reschedule_offers
for each row execute function public.lock_sms_inbound_candidate_recipient();

drop trigger if exists jobs_sms_inbound_recipient_lock on public.jobs;
create trigger jobs_sms_inbound_recipient_lock
before insert or update or delete on public.jobs
for each row execute function public.lock_sms_inbound_candidate_recipient();

drop trigger if exists subcontractor_offers_sms_inbound_recipient_lock
  on public.subcontractor_offers;
create trigger subcontractor_offers_sms_inbound_recipient_lock
before insert or update or delete on public.subcontractor_offers
for each row execute function public.lock_sms_inbound_candidate_recipient();

drop trigger if exists sms_events_sms_inbound_recipient_lock
  on public.sms_events;
create trigger sms_events_sms_inbound_recipient_lock
before insert or update or delete on public.sms_events
for each row execute function public.lock_sms_inbound_candidate_recipient();

-- A sent appointment question is the conjunction of job_feed evidence and a
-- sent/delivered sms_event. Both table boundaries participate in the same
-- recipient lock as jobs so that question cannot appear during exact-one
-- classification.
create or replace function public.lock_sms_inbound_job_feed_recipient()
returns trigger
language plpgsql
security definer
set search_path = pg_catalog, pg_temp
as $$
declare
  v_old_key bigint;
  v_new_key bigint;
begin
  if tg_op <> 'INSERT' and old.kind = 'appointment_reminder' then
    select public.sms_inbound_recipient_lock_key(j.account_id, j.client_phone)
      into v_old_key from public.jobs j where j.id = old.job_id;
  end if;
  if tg_op <> 'DELETE' and new.kind = 'appointment_reminder' then
    select public.sms_inbound_recipient_lock_key(j.account_id, j.client_phone)
      into v_new_key from public.jobs j where j.id = new.job_id;
  end if;
  if v_old_key is not null and v_new_key is not null and v_old_key <> v_new_key then
    perform pg_catalog.pg_advisory_xact_lock(least(v_old_key, v_new_key));
    perform pg_catalog.pg_advisory_xact_lock(greatest(v_old_key, v_new_key));
  elsif coalesce(v_new_key, v_old_key) is not null then
    perform pg_catalog.pg_advisory_xact_lock(coalesce(v_new_key, v_old_key));
  end if;
  if tg_op = 'DELETE' then return old; end if;
  return new;
end;
$$;

drop trigger if exists job_feed_sms_inbound_recipient_lock on public.job_feed;
create trigger job_feed_sms_inbound_recipient_lock
before insert or update or delete on public.job_feed
for each row execute function public.lock_sms_inbound_job_feed_recipient();

-- Request state changes also open/close every linked subcontractor offer. Lock
-- those phone scopes in deterministic order before changing the request.
create or replace function public.lock_sms_inbound_subcontractor_request_recipients()
returns trigger
language plpgsql
security definer
set search_path = pg_catalog, pg_temp
as $$
declare
  v_key bigint;
begin
  for v_key in
    select distinct public.sms_inbound_recipient_lock_key(o.account_id, o.phone)
      from public.subcontractor_offers o
     where o.request_id in (old.id, new.id)
     order by 1
  loop
    perform pg_catalog.pg_advisory_xact_lock(v_key);
  end loop;
  return new;
end;
$$;

drop trigger if exists subcontractor_requests_sms_inbound_recipient_lock
  on public.subcontractor_requests;
create trigger subcontractor_requests_sms_inbound_recipient_lock
before update on public.subcontractor_requests
for each row execute function public.lock_sms_inbound_subcontractor_request_recipients();

create or replace function public.enqueue_sms_inbound_action_task()
returns trigger
language plpgsql
security definer
set search_path = pg_catalog, pg_temp
as $$
begin
  if new.webhook_kind = 'inbound'
     and new.processing_state = 'processed'
     and new.disposition = 'routed'
     and new.account_id is not null
     and new.sender_number_id is not null
     and new.sms_message_id is not null then
    insert into public.sms_inbound_action_tasks (
      webhook_receipt_id, account_id, sender_number_id, sms_message_id
    ) values (
      new.id, new.account_id, new.sender_number_id, new.sms_message_id
    ) on conflict (webhook_receipt_id) do nothing;
  end if;
  return new;
end;
$$;

drop trigger if exists sms_webhook_receipt_enqueue_inbound_action
  on public.sms_webhook_receipts;
create trigger sms_webhook_receipt_enqueue_inbound_action
after insert or update on public.sms_webhook_receipts
for each row execute function public.enqueue_sms_inbound_action_task();

create or replace function public.get_sms_inbound_receipt_disposition(
  p_webhook_receipt_id uuid
)
returns text
language sql
stable
security definer
set search_path = pg_catalog, pg_temp
as $$
  select r.disposition
    from public.sms_webhook_receipts r
   where r.id = p_webhook_receipt_id
     and r.webhook_kind = 'inbound'
$$;

create or replace function public.claim_sms_inbound_action(
  p_webhook_receipt_id uuid
)
returns table (
  claim_status text,
  task_id uuid,
  work_claim_token uuid,
  provider text,
  provider_event_id text,
  account_id uuid,
  sender_number_id uuid,
  sender_purpose text,
  from_number text,
  effect_applied boolean,
  stored_outcome jsonb
)
language plpgsql
security definer
set search_path = pg_catalog, pg_temp
set timezone to 'UTC'
as $$
declare
  v_task public.sms_inbound_action_tasks%rowtype;
  v_now timestamptz := pg_catalog.clock_timestamp();
  v_token uuid;
begin
  if p_webhook_receipt_id is null then
    raise exception 'Inbound action receipt ID is required' using errcode = '22023';
  end if;

  select t.* into v_task
    from public.sms_inbound_action_tasks t
   where t.webhook_receipt_id = p_webhook_receipt_id
   for update;

  if v_task.id is null then
    return query select 'missing'::text, null::uuid, null::uuid, null::text,
      null::text, null::uuid, null::uuid, null::text, null::text,
      false, null::jsonb;
    return;
  end if;
  if v_task.task_state = 'completed' then
    return query
    select 'completed'::text, v_task.id, null::uuid, r.provider,
           r.provider_event_id, v_task.account_id, v_task.sender_number_id,
           s.purpose, r.from_number, true, v_task.outcome
      from public.sms_webhook_receipts r
      join public.sms_sender_numbers s on s.id = v_task.sender_number_id
     where r.id = v_task.webhook_receipt_id;
    return;
  end if;
  if v_task.task_state = 'processing' and v_task.lease_expires_at > v_now then
    return query
    select 'busy'::text, v_task.id, null::uuid, r.provider,
           r.provider_event_id, v_task.account_id, v_task.sender_number_id,
           s.purpose, r.from_number, v_task.effect_applied_at is not null,
           v_task.outcome
      from public.sms_webhook_receipts r
      join public.sms_sender_numbers s on s.id = v_task.sender_number_id
     where r.id = v_task.webhook_receipt_id;
    return;
  end if;
  if v_task.task_state = 'failed' and v_task.next_attempt_at > v_now then
    return query
    select 'deferred'::text, v_task.id, null::uuid, r.provider,
           r.provider_event_id, v_task.account_id, v_task.sender_number_id,
           s.purpose, r.from_number, v_task.effect_applied_at is not null,
           v_task.outcome
      from public.sms_webhook_receipts r
      join public.sms_sender_numbers s on s.id = v_task.sender_number_id
     where r.id = v_task.webhook_receipt_id;
    return;
  end if;

  v_token := pg_catalog.gen_random_uuid();
  update public.sms_inbound_action_tasks
     set task_state = 'processing', claim_token = v_token,
         lease_expires_at = v_now + interval '2 minutes',
         attempt_count = attempt_count + 1, last_error = null,
         updated_at = v_now
   where id = v_task.id;

  return query
  select 'claimed'::text, v_task.id, v_token, r.provider,
         r.provider_event_id, v_task.account_id, v_task.sender_number_id,
         s.purpose, r.from_number, v_task.effect_applied_at is not null,
         v_task.outcome
    from public.sms_webhook_receipts r
    join public.sms_sender_numbers s on s.id = v_task.sender_number_id
   where r.id = v_task.webhook_receipt_id;
end;
$$;

create or replace function public.claim_sms_inbound_action_batch(
  p_batch_size integer default 10
)
returns table (
  claim_status text,
  task_id uuid,
  work_claim_token uuid,
  provider text,
  provider_event_id text,
  account_id uuid,
  sender_number_id uuid,
  sender_purpose text,
  from_number text,
  effect_applied boolean,
  stored_outcome jsonb
)
language plpgsql
security definer
set search_path = pg_catalog, pg_temp
set timezone to 'UTC'
as $$
declare
  v_now timestamptz := pg_catalog.clock_timestamp();
begin
  if p_batch_size not between 1 and 25 then
    raise exception 'Inbound action batch size must be between 1 and 25'
      using errcode = '22023';
  end if;

  return query
  with due as (
    select t.id
      from public.sms_inbound_action_tasks t
     where (
       (t.task_state in ('pending', 'failed') and t.next_attempt_at <= v_now)
       or (t.task_state = 'processing' and t.lease_expires_at <= v_now)
     )
     order by t.next_attempt_at, t.created_at, t.id
     for update skip locked
     limit p_batch_size
  ), claimed as (
    update public.sms_inbound_action_tasks t
       set task_state = 'processing', claim_token = pg_catalog.gen_random_uuid(),
           lease_expires_at = v_now + interval '2 minutes',
           attempt_count = t.attempt_count + 1, last_error = null,
           updated_at = v_now
      from due
     where t.id = due.id
    returning t.*
  )
  select 'claimed'::text, c.id, c.claim_token, r.provider,
         r.provider_event_id, c.account_id, c.sender_number_id,
         s.purpose, r.from_number, c.effect_applied_at is not null, c.outcome
    from claimed c
    join public.sms_webhook_receipts r on r.id = c.webhook_receipt_id
    join public.sms_sender_numbers s on s.id = c.sender_number_id;
end;
$$;

create or replace function public.apply_sms_inbound_action(
  p_task_id uuid,
  p_claim_token uuid
)
returns jsonb
language plpgsql
security definer
set search_path = pg_catalog, pg_temp
set timezone to 'UTC'
as $$
declare
  v_task public.sms_inbound_action_tasks%rowtype;
  v_receipt public.sms_webhook_receipts%rowtype;
  v_message public.sms_messages%rowtype;
  v_now timestamptz := pg_catalog.clock_timestamp();
  v_token text;
  v_decision text;
  v_confirmation_only boolean := false;
  v_candidate_count integer := 0;
  v_kind text;
  v_target_id uuid;
  v_business_name text := 'your contractor';
  v_reply_kind text;
  v_reply_body text;
  v_alert_phone text;
  v_alert_body text;
  v_name text;
  v_when text;
  v_stop_id uuid;
  v_estimate public.estimate_offers%rowtype;
  v_reschedule public.reschedule_offers%rowtype;
  v_job public.jobs%rowtype;
  v_sub_offer public.subcontractor_offers%rowtype;
  v_sub_request public.subcontractor_requests%rowtype;
begin
  select t.* into v_task
    from public.sms_inbound_action_tasks t
   where t.id = p_task_id
   for update;
  if v_task.id is null
     or v_task.task_state <> 'processing'
     or v_task.claim_token is distinct from p_claim_token
     or v_task.lease_expires_at <= v_now then
    raise exception 'Inbound action claim is not active' using errcode = '55000';
  end if;
  if v_task.effect_applied_at is not null then
    return v_task.outcome;
  end if;

  select r.* into strict v_receipt
    from public.sms_webhook_receipts r
   where r.id = v_task.webhook_receipt_id;
  select m.* into strict v_message
    from public.sms_messages m
   where m.id = v_task.sms_message_id;
  if v_receipt.account_id is distinct from v_task.account_id
     or v_message.account_id is distinct from v_task.account_id
     or v_message.phone_number is distinct from v_receipt.from_number
     or v_receipt.disposition <> 'routed' then
    raise exception 'Inbound action task binding is invalid' using errcode = '23514';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    public.sms_inbound_recipient_lock_key(v_task.account_id, v_receipt.from_number)
  );

  v_token := pg_catalog.upper(
    coalesce((pg_catalog.regexp_split_to_array(pg_catalog.btrim(v_message.body), E'\\s+'))[1], '')
  );
  if v_token in ('YES','Y','YEP','YEAH','SURE','OK','ACCEPT','CONFIRM','CONFIRMED','1','C') then
    v_decision := 'accept';
  elsif v_token in ('NO','N','NOPE','DECLINE','2') then
    v_decision := 'decline';
  else
    v_decision := 'unclear';
  end if;
  v_confirmation_only := v_token = 'C';

  select pg_catalog.count(*)::integer,
         (pg_catalog.array_agg(c.kind))[1],
         (pg_catalog.array_agg(c.target_id))[1]
    into v_candidate_count, v_kind, v_target_id
    from (
      select 'estimate'::text as kind, e.id as target_id
        from public.estimate_offers e
       where not v_confirmation_only
         and e.account_id = v_task.account_id
         and e.phone = v_receipt.from_number
         and e.status = 'held'
      union all
      select 'reschedule'::text, o.id
        from public.reschedule_offers o
       where not v_confirmation_only
         and o.account_id = v_task.account_id
         and o.phone = v_receipt.from_number
         and o.status = 'sent'
      union all
      select 'appointment'::text, j.id
        from public.jobs j
       where v_decision = 'accept'
         and j.account_id = v_task.account_id
         and public.sms_normalize_recipient_phone(j.client_phone) = v_receipt.from_number
         and j.scheduled_for >= (v_now at time zone 'UTC')::date
         and j.status in ('new_lead', 'in_progress')
         and j.appointment_confirmed_at is null
         and exists (
           select 1
             from public.job_feed f
             join public.sms_events e on e.id::text = f.meta->>'sms_event_id'
            where f.account_id = j.account_id
              and f.job_id = j.id
              and f.kind = 'appointment_reminder'
              and f.meta->>'channel' = 'sms'
              and f.meta->>'scheduled_for' = j.scheduled_for::text
              and e.status in ('sent', 'delivered')
         )
      union all
      select 'subcontractor'::text, o.id
        from public.subcontractor_offers o
        join public.subcontractor_requests r on r.id = o.request_id
       where not v_confirmation_only
         and v_decision in ('accept', 'decline')
         and o.account_id = v_task.account_id
         and o.phone = v_receipt.from_number
         and o.status in ('queued','sent','delivered','viewed','failed')
         and r.status in ('sent','viewed','partially_responded','reopened')
         and r.expires_at > v_now
    ) c;

  select nullif(pg_catalog.btrim(a.business_name), ''),
         public.sms_normalize_recipient_phone(a.alert_phone)
    into v_business_name, v_alert_phone
    from public.accounts a where a.id = v_task.account_id;
  if v_business_name is null or v_business_name = 'My Business' then
    v_business_name := 'your contractor';
  end if;

  if v_candidate_count = 0 then
    v_reply_kind := null;
    v_reply_body := null;
    v_kind := 'none';
  elsif v_candidate_count > 1 then
    v_kind := 'ambiguous';
    v_reply_kind := 'ambiguity';
    v_reply_body := 'We found more than one open request for this number, so nothing was changed. Please use the link in the message you are answering or contact ' || v_business_name || '.';
  elsif v_kind = 'estimate' then
    select e.* into strict v_estimate
      from public.estimate_offers e where e.id = v_target_id for update;
    select coalesce(nullif(pg_catalog.btrim(l.name), ''), 'there')
      into v_name from public.leads l where l.id = v_estimate.lead_id;
    v_reply_kind := 'offer';
    if v_decision = 'decline' then
      update public.estimate_offers
         set status = 'declined', replied_at = v_now,
             reply_body = pg_catalog.left(v_message.body, 500), updated_at = v_now
       where id = v_estimate.id and status = 'held';
      v_reply_body := 'No problem ' || v_name || ' — that estimate window has been released. ' || v_business_name || ' still has your request.';
      v_alert_body := v_name || ' said NO to an estimate window.';
    elsif v_decision = 'unclear' then
      update public.estimate_offers
         set forwarded_at = coalesce(forwarded_at, v_now), updated_at = v_now
       where id = v_estimate.id and status = 'held';
      v_reply_body := 'Thanks ' || v_name || ' — we passed that to ' || v_business_name || ' and they will follow up shortly.';
    elsif v_estimate.hold_expires_at <= v_now then
      update public.estimate_offers
         set status = 'accepted_late', replied_at = v_now,
             reply_body = pg_catalog.left(v_message.body, 500), updated_at = v_now
       where id = v_estimate.id and status = 'held';
      v_reply_body := 'Thanks ' || v_name || '! That window has just passed, so it was not booked. ' || v_business_name || ' has your reply and will help find a time.';
      v_alert_body := v_name || ' said YES after an estimate hold expired.';
    else
      insert into public.route_stops (
        account_id, crew_id, lead_id, scheduled_for, scheduled_time,
        label, address, lat, lng, minutes, kind, note,
        source_sms_webhook_receipt_id
      )
      select v_estimate.account_id, v_estimate.crew_id, v_estimate.lead_id,
             v_estimate.offer_date, v_estimate.arrival_time,
             'Estimate — ' || v_name, l.address, l.lat, l.lng,
             v_estimate.visit_minutes, 'estimate',
             'Accepted by text from receipt ' || v_receipt.id::text,
             v_receipt.id
        from public.leads l where l.id = v_estimate.lead_id
      on conflict (source_sms_webhook_receipt_id)
        where source_sms_webhook_receipt_id is not null
      do update
        set source_sms_webhook_receipt_id = excluded.source_sms_webhook_receipt_id
      returning id into v_stop_id;
      update public.estimate_offers
         set status = 'accepted', replied_at = v_now,
             reply_body = pg_catalog.left(v_message.body, 500),
             route_stop_id = v_stop_id, updated_at = v_now
       where id = v_estimate.id and status = 'held';
      update public.leads
         set quote_visit = pg_catalog.jsonb_build_object(
               'scheduledFor', v_estimate.offer_date,
               'scheduledTime', v_estimate.arrival_time,
               'durationMinutes', v_estimate.visit_minutes,
               'notes', 'Booked from an estimate offer by text.',
               'confirmationTextSentAt', v_now,
               'scheduledAt', v_now
             ),
             status = case when status = 'new' then 'contacted' else status end,
             updated_at = v_now
       where id = v_estimate.lead_id and account_id = v_task.account_id;
      v_when := pg_catalog.to_char(v_estimate.offer_date, 'FMDay, Mon FMDD') ||
        ' between ' || pg_catalog.to_char(v_estimate.window_start, 'FMHH12:MI AM') ||
        ' and ' || pg_catalog.to_char(v_estimate.window_end, 'FMHH12:MI AM');
      v_reply_body := 'You are booked, ' || v_name || '! ' || v_business_name || ' will arrive ' || v_when || '.';
      v_alert_body := v_name || ' said YES — the estimate was added to the schedule.';
    end if;
  elsif v_kind = 'reschedule' then
    select o.* into strict v_reschedule
      from public.reschedule_offers o where o.id = v_target_id for update;
    select j.* into strict v_job from public.jobs j where j.id = v_reschedule.job_id for update;
    v_name := coalesce(nullif(pg_catalog.btrim(v_job.client_name), ''), 'there');
    v_reply_kind := 'reschedule';
    if v_decision = 'decline' then
      update public.reschedule_offers
         set status = 'declined', replied_at = v_now,
             reply_body = pg_catalog.left(v_message.body, 500), updated_at = v_now
       where id = v_reschedule.id and status = 'sent';
      v_reply_body := 'No problem ' || v_name || ' — you are still booked for the original time. Nothing changed.';
      v_alert_body := v_name || ' said NO to a reschedule offer.';
    elsif v_decision = 'unclear' then
      update public.reschedule_offers
         set forwarded_at = coalesce(forwarded_at, v_now), updated_at = v_now
       where id = v_reschedule.id and status = 'sent';
      v_reply_body := 'Thanks ' || v_name || ' — we passed that to ' || v_business_name || ' and they will follow up shortly.';
    else
      update public.jobs
         set scheduled_for = v_reschedule.to_date,
             scheduled_time = v_reschedule.arrival_time,
             reschedule_discount_percent = v_reschedule.discount_percent,
             reschedule_discount_note = 'Agreed by text to move from ' || v_reschedule.from_date::text || ' to ' || v_reschedule.to_date::text,
             reschedule_discount_agreed_at = v_now
       where id = v_reschedule.job_id and account_id = v_task.account_id;
      update public.reschedule_offers
         set status = 'accepted', replied_at = v_now,
             reply_body = pg_catalog.left(v_message.body, 500), updated_at = v_now
       where id = v_reschedule.id and status = 'sent';
      v_when := pg_catalog.to_char(v_reschedule.to_date, 'FMDay, Mon FMDD') ||
        ', ' || pg_catalog.to_char(v_reschedule.window_start, 'FMHH12:MI AM') ||
        '–' || pg_catalog.to_char(v_reschedule.window_end, 'FMHH12:MI AM');
      v_reply_body := 'You are moved, ' || v_name || ' — ' || v_when || '. The ' ||
        v_reschedule.discount_percent::text || '% comes off your final bill.';
      v_alert_body := v_name || ' said YES — the job was moved and the discount recorded.';
    end if;
  elsif v_kind = 'appointment' then
    select j.* into strict v_job from public.jobs j where j.id = v_target_id for update;
    update public.jobs set appointment_confirmed_at = v_now
     where id = v_job.id and account_id = v_task.account_id
       and appointment_confirmed_at is null;
    v_name := coalesce(nullif(pg_catalog.btrim(v_job.client_name), ''), 'there');
    v_when := pg_catalog.to_char(v_job.scheduled_for, 'FMDay, Mon FMDD') ||
      case when v_job.scheduled_time is null then ''
           else ' at ' || pg_catalog.to_char(v_job.scheduled_time, 'FMHH12:MI AM') end;
    v_reply_kind := 'appointment_confirmation';
    v_reply_body := 'Thanks ' || v_name || ' — your appointment ' || v_when ||
      ' with ' || v_business_name || ' is confirmed. See you then!';
  elsif v_kind = 'subcontractor' then
    select o.* into strict v_sub_offer
      from public.subcontractor_offers o where o.id = v_target_id for update;
    select r.* into strict v_sub_request
      from public.subcontractor_requests r where r.id = v_sub_offer.request_id for update;
    v_reply_kind := 'subcontractor';
    if v_decision = 'decline' then
      update public.subcontractor_offers
         set status = 'declined', responded_at = v_now,
             decline_reason = 'Declined by text', updated_at = v_now
       where id = v_sub_offer.id
         and status in ('queued','sent','delivered','viewed','failed');
      v_reply_body := 'Thanks — we recorded that you are not available for this job.';
      v_alert_body := 'A subcontractor declined ' || v_sub_request.work_description || ' by text.';
    elsif v_sub_request.selection_mode = 'collect_interest' then
      update public.subcontractor_offers
         set status = 'accepted', won = false, responded_at = v_now, updated_at = v_now
       where id = v_sub_offer.id
         and status in ('queued','sent','delivered','viewed','failed');
      update public.subcontractor_requests
         set status = 'partially_responded', updated_at = v_now
       where id = v_sub_request.id
         and status in ('sent','viewed','partially_responded','reopened');
      v_reply_body := 'Thanks — your availability was recorded. ' || v_business_name || ' will let you know if you are selected.';
      v_alert_body := 'A subcontractor is available for ' || v_sub_request.work_description || '.';
    else
      update public.subcontractor_requests
         set status = 'claimed', claimed_offer_id = v_sub_offer.id,
             claimed_crew_id = v_sub_offer.crew_id, claimed_at = v_now,
             updated_at = v_now
       where id = v_sub_request.id
         and claimed_offer_id is null
         and status in ('sent','viewed','partially_responded','reopened')
         and expires_at > v_now;
      if not found then
        raise exception 'Subcontractor request changed during reply processing'
          using errcode = '40001';
      end if;
      insert into public.crew_assignments(account_id, job_id, crew_id)
      values (v_task.account_id, v_sub_request.job_id, v_sub_offer.crew_id)
      on conflict (job_id, crew_id) do nothing;
      update public.subcontractor_offers
         set status = 'accepted', won = true, responded_at = v_now, updated_at = v_now
       where id = v_sub_offer.id;
      update public.subcontractor_offers
         set status = 'covered', updated_at = v_now
       where request_id = v_sub_request.id and id <> v_sub_offer.id
         and status in ('queued','sent','delivered','viewed','failed');
      v_reply_body := 'You got the job. Open the secure link from the offer message for the customer and site details.';
      v_alert_body := 'A subcontractor accepted ' || v_sub_request.work_description || ' and was assigned to the job.';
    end if;
  end if;

  -- Free-text forwarding has no terminal owner alert; the inbox row itself is
  -- the durable owner-visible fact. All other preserved alerts are queued after
  -- this transaction with their own receipt-derived idempotency key.
  if v_decision = 'unclear' or v_kind in ('none', 'ambiguous', 'appointment') then
    v_alert_phone := null;
    v_alert_body := null;
  end if;

  v_task.outcome := pg_catalog.jsonb_strip_nulls(pg_catalog.jsonb_build_object(
    'action_kind', v_kind,
    'target_id', v_target_id,
    'decision', v_decision,
    'reply_kind', v_reply_kind,
    'reply_body', v_reply_body,
    'owner_alert_phone', v_alert_phone,
    'owner_alert_body', v_alert_body
  ));
  update public.sms_inbound_action_tasks
     set effect_applied_at = v_now, outcome = v_task.outcome, updated_at = v_now
   where id = v_task.id and task_state = 'processing'
     and claim_token = p_claim_token;
  return v_task.outcome;
end;
$$;

create or replace function public.complete_sms_inbound_action(
  p_task_id uuid,
  p_claim_token uuid,
  p_customer_reply_event_id uuid default null,
  p_owner_alert_event_id uuid default null
)
returns boolean
language plpgsql
security definer
set search_path = pg_catalog, pg_temp
set timezone to 'UTC'
as $$
declare
  v_now timestamptz := pg_catalog.clock_timestamp();
begin
  update public.sms_inbound_action_tasks
     set task_state = 'completed', claim_token = null, lease_expires_at = null,
         customer_reply_event_id = p_customer_reply_event_id,
         owner_alert_event_id = p_owner_alert_event_id,
         completed_at = v_now, updated_at = v_now, last_error = null
   where id = p_task_id and task_state = 'processing'
     and claim_token = p_claim_token and effect_applied_at is not null;
  if not found then
    raise exception 'Inbound action completion claim is invalid' using errcode = '55000';
  end if;
  return true;
end;
$$;

create or replace function public.fail_sms_inbound_action(
  p_task_id uuid,
  p_claim_token uuid,
  p_error_code text
)
returns boolean
language plpgsql
security definer
set search_path = pg_catalog, pg_temp
set timezone to 'UTC'
as $$
declare
  v_now timestamptz := pg_catalog.clock_timestamp();
begin
  if p_error_code is null or p_error_code !~ '^[a-z][a-z0-9_]{2,99}$' then
    raise exception 'Inbound action error code is invalid' using errcode = '22023';
  end if;
  update public.sms_inbound_action_tasks
     set task_state = 'failed', claim_token = null, lease_expires_at = null,
         next_attempt_at = v_now + least(
           interval '15 minutes',
           pg_catalog.make_interval(secs => (5 * pg_catalog.power(2, least(attempt_count, 8)))::integer)
         ),
         last_error = p_error_code, updated_at = v_now
   where id = p_task_id and task_state = 'processing'
     and claim_token = p_claim_token;
  if not found then
    raise exception 'Inbound action failure claim is invalid' using errcode = '55000';
  end if;
  return true;
end;
$$;

alter table public.sms_inbound_action_tasks enable row level security;
alter table public.sms_inbound_action_tasks force row level security;

revoke all on table public.sms_inbound_action_tasks
