-- Source: migrations/20260821210500_sms_purpose_aware_inbound_routing.sql
-- Purpose-aware tenant routing for ordinary replies to platform SMS numbers.
--
-- The webhook foundation deliberately quarantined every ordinary reply to an
-- LGQ-owned shared number because outbound history is not tenant authority.
-- Consent scopes, introduced by 20260821210000, are the first durable evidence
-- that can safely distinguish an owner/account-holder handset from crew. Keep
-- the old migration fail-closed for partial rollouts and replace the ingest RPC
-- only after that scope table and the inbound-action outbox both exist.

begin;

create or replace function public.ingest_sms_inbound_webhook(
  p_provider text,
  p_provider_event_id text,
  p_receipt_key text,
  p_body_sha256 text,
  p_content_type text,
  p_request_url text,
  p_from_number text,
  p_to_number text,
  p_message_body text,
  p_media_urls text[],
  p_keyword text
)
returns table (
  ingress_disposition text,
  webhook_receipt_id uuid,
  routed_account_id uuid,
  routed_sender_number_id uuid,
  routed_sender_purpose text
)
language plpgsql
security definer
set search_path = pg_catalog, pg_temp
set timezone to 'UTC'
as $$
declare
  v_now timestamptz := pg_catalog.clock_timestamp();
  v_receipt public.sms_webhook_receipts%rowtype;
  v_existing public.sms_webhook_receipts%rowtype;
  v_sender public.sms_sender_numbers%rowtype;
  v_message_id uuid;
  v_reason text;
  v_existing_consent boolean;
  v_routed_account_id uuid;
  v_routed_account_count bigint := 0;
begin
  if p_provider not in ('twilio', 'signalwire')
     or p_provider_event_id is null
     or pg_catalog.length(p_provider_event_id) not between 1 and 255
     or p_receipt_key is null
     or pg_catalog.length(p_receipt_key) not between 1 and 700
     or p_body_sha256 is null
     or p_body_sha256 !~ '^[0-9a-f]{64}$'
     or p_from_number is null
     or p_from_number !~ '^\+[1-9][0-9]{7,14}$'
     or p_to_number is null
     or p_to_number !~ '^\+[1-9][0-9]{7,14}$'
     or p_keyword not in ('stop', 'start', 'help', 'other')
     or pg_catalog.length(coalesce(p_message_body, '')) > 5000
     or coalesce(pg_catalog.array_length(p_media_urls, 1), 0) > 10 then
    raise exception 'SMS inbound webhook arguments are invalid'
      using errcode = '22023';
  end if;

  insert into public.sms_webhook_receipts (
    provider, webhook_kind, receipt_key, provider_event_id, body_sha256,
    content_type, request_url, from_number, to_number
  ) values (
    p_provider, 'inbound', p_receipt_key, p_provider_event_id,
    p_body_sha256, pg_catalog.left(p_content_type, 255),
    pg_catalog.left(p_request_url, 2000), p_from_number, p_to_number
  )
  on conflict (provider, webhook_kind, receipt_key) do nothing
  returning * into v_receipt;

  if v_receipt.id is null then
    select r.* into v_existing
      from public.sms_webhook_receipts r
     where r.provider = p_provider
       and r.webhook_kind = 'inbound'
       and r.receipt_key = p_receipt_key
     for update;
    if v_existing.provider_event_id is distinct from p_provider_event_id
       or v_existing.body_sha256 is distinct from p_body_sha256
       or v_existing.from_number is distinct from p_from_number
       or v_existing.to_number is distinct from p_to_number
       or v_existing.content_type is distinct from pg_catalog.left(p_content_type, 255)
       or v_existing.request_url is distinct from pg_catalog.left(p_request_url, 2000) then
      raise exception 'SMS inbound receipt key was replayed with different immutable evidence'
        using errcode = 'P5120';
    end if;
    -- Dedupe precedes every preference, transcript, review, and outbox write.
    return query
    select 'duplicate'::text, v_existing.id, v_existing.account_id,
           v_existing.sender_number_id, s.purpose
      from public.sms_webhook_receipts r
      left join public.sms_sender_numbers s on s.id = r.sender_number_id
     where r.id = v_existing.id;
    return;
  end if;

  select s.* into v_sender
    from public.sms_sender_numbers s
   where s.provider = p_provider
     and s.e164_number = p_to_number
     and s.provisioning_status = 'active'
     and s.assignment_state = 'assigned'
     and s.inbound_ready
     and s.suspended_at is null
   for share;

  if v_sender.id is null then
    insert into public.sms_operator_review_items (
      webhook_receipt_id, reason, severity, provider, provider_event_id,
      from_number, to_number, message_body, media_urls
    ) values (
      v_receipt.id, 'unknown_destination', 'critical', p_provider,
      p_provider_event_id, p_from_number, p_to_number,
      pg_catalog.left(p_message_body, 5000), p_media_urls
    );
    update public.sms_webhook_receipts
       set processing_state = 'review', disposition = 'unknown_destination',
           processed_at = v_now
     where id = v_receipt.id;
    return query select 'review'::text, v_receipt.id, null::uuid,
                        null::uuid, null::text;
    return;
  end if;

  -- Ordinary replies and STOP/START for the same provider sender/contact must
  -- observe one another in commit order. This is the same lock used by final
  -- delivery staging; a sender-scoped STOP can never race a routing decision.
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'sms-sender-consent:' || v_sender.id::text || ':' || p_from_number,
      20260821
    )
  );

  v_routed_account_id := v_sender.account_id;

  -- Preserve the established keyword behavior. A shared-number STOP/START/HELP
  -- may touch an account ledger only when complete accepted outbound history for
  -- this exact sender/contact identifies one account. Ordinary traffic never
  -- uses this history; it is authorized solely by the audience scope below.
  if p_keyword in ('stop', 'start', 'help')
     and v_sender.purpose = 'lgq_shared'
     and v_routed_account_id is null then
    select pg_catalog.count(*),
           case when pg_catalog.count(*) = 1
             then (pg_catalog.array_agg(candidate.account_id))[1]
             else null::uuid
           end
      into v_routed_account_count, v_routed_account_id
      from (
        select distinct e.account_id
          from public.sms_events e
         where e.sender_number_id = v_sender.id
           and e.phone_number = p_from_number
           and e.account_id is not null
           and e.status in ('sent', 'delivered')
           and e.provider_id is not null
      ) candidate;
  end if;

  -- Dispatch STOP/START must identify a current crew account without requiring
  -- the base consent row to be opted in: START has to remain usable after STOP.
  -- The append-only crew scope establishes the audience, while the live roster
  -- and current phone establish present authority. More than one account fails
  -- closed; duplicate crew rows inside one account do not create ambiguity.
  if p_keyword in ('stop', 'start')
     and v_sender.purpose = 'lgq_dispatch'
     and v_routed_account_id is null then
    select pg_catalog.count(*),
           case when pg_catalog.count(*) = 1
             then (pg_catalog.array_agg(candidate.account_id))[1]
             else null::uuid
           end
      into v_routed_account_count, v_routed_account_id
      from (
        select distinct c.account_id
          from public.sms_consent c
          join public.sms_consent_scopes scope
            on scope.account_id = c.account_id
           and scope.phone_number = c.phone_number
           and scope.consent_scope = 'crew'
         where c.phone_number = p_from_number
           and c.consented_at is not null
           and exists (
             select 1
               from public.crew member
              where member.account_id = c.account_id
                and member.active
                and member.deleted_at is null
                and public.sms_normalize_recipient_phone(member.phone)
                      = p_from_number
           )
      ) candidate;
  end if;

  -- Platform lanes have no account on the number row. Route an ordinary reply
  -- only from current affirmative audience evidence. The aggregate intentionally
  -- has no recency ordering or LIMIT: zero and multiple accounts both fail closed.
  if p_keyword = 'other'
     and v_sender.purpose in ('lgq_shared', 'lgq_dispatch') then
    select pg_catalog.count(*),
           case when pg_catalog.count(*) = 1
             then (pg_catalog.array_agg(candidate.account_id))[1]
             else null::uuid
           end
      into v_routed_account_count, v_routed_account_id
      from (
        select c.account_id
          from public.sms_consent c
          join public.sms_consent_scopes scope
            on scope.account_id = c.account_id
           and scope.phone_number = c.phone_number
            and scope.consent_scope = case v_sender.purpose
              when 'lgq_shared' then 'owner'
              when 'lgq_dispatch' then 'crew'
              else null
            end
         where c.phone_number = p_from_number
           and c.status = 'opted_in'
           and c.consented_at is not null
           and c.opted_out_at is null
           and (
             (
               v_sender.purpose = 'lgq_shared'
               and exists (
                 select 1
                   from public.accounts account
                  where account.id = c.account_id
                    and account.high_value_sms_enabled is true
                    and public.sms_normalize_recipient_phone(account.alert_phone)
                          = p_from_number
               )
             )
             or
             (
               v_sender.purpose = 'lgq_dispatch'
               and exists (
                 select 1
                   from public.crew member
                  where member.account_id = c.account_id
                    and member.active
                    and member.deleted_at is null
                    and public.sms_normalize_recipient_phone(member.phone)
                          = p_from_number
               )
             )
           )
           and not exists (
             select 1
               from public.sms_sender_keyword_preferences preference
              where preference.sender_number_id = v_sender.id
                and preference.phone_number = p_from_number
                and preference.status = 'opted_out'
                and preference.opted_out_at is not null
           )
      ) candidate;
  end if;

  update public.sms_webhook_receipts
     set sender_number_id = v_sender.id,
         account_id = v_routed_account_id
   where id = v_receipt.id;

  -- An unresolved dispatch START must never clear the exact-sender block or
  -- claim re-subscription while no unique account ledger can be restored.
  if p_keyword = 'start'
     and v_sender.purpose = 'lgq_dispatch'
     and v_routed_account_id is null then
    insert into public.sms_sender_keyword_preferences (
      sender_number_id, phone_number, status, source, opted_out_at, updated_at
    ) values (
      v_sender.id, p_from_number, 'opted_out', 'inbound_start', v_now, v_now
    )
    on conflict (sender_number_id, phone_number) do update
      set status = 'opted_out',
          source = 'inbound_start',
          opted_out_at = coalesce(
            public.sms_sender_keyword_preferences.opted_out_at,
            excluded.opted_out_at
          ),
          updated_at = excluded.updated_at;

    v_reason := case
      when v_routed_account_count > 1 then 'ambiguous_destination'
      else 'shared_destination_unroutable'
    end;
    insert into public.sms_operator_review_items (
      webhook_receipt_id, reason, severity, provider, sender_number_id,
      provider_event_id, from_number, to_number, message_body, media_urls
    ) values (
      v_receipt.id, v_reason,
      case when v_reason = 'ambiguous_destination' then 'critical' else 'warning' end,
      p_provider, v_sender.id, p_provider_event_id, p_from_number, p_to_number,
      pg_catalog.left(p_message_body, 5000), p_media_urls
    );
    update public.sms_webhook_receipts
       set account_id = null, processing_state = 'review',
           disposition = v_reason, processed_at = v_now
     where id = v_receipt.id;
    return query select 'review'::text, v_receipt.id, null::uuid,
                        v_sender.id, v_sender.purpose;
    return;
  end if;

  if p_keyword in ('stop', 'start') then
    insert into public.sms_sender_keyword_preferences (
      sender_number_id, phone_number, status, source, opted_out_at, updated_at
    ) values (
      v_sender.id, p_from_number,
      case when p_keyword = 'stop' then 'opted_out' else 'opted_in' end,
      case when p_keyword = 'stop' then 'inbound_stop' else 'inbound_start' end,
      case when p_keyword = 'stop' then v_now else null end,
      v_now
    )
    on conflict (sender_number_id, phone_number) do update
      set status = excluded.status,
          source = excluded.source,
          opted_out_at = excluded.opted_out_at,
          updated_at = excluded.updated_at;

    if v_routed_account_id is not null then
      select pg_catalog.count(*) > 0 into v_existing_consent
        from public.sms_consent c
       where c.account_id = v_routed_account_id
         and c.phone_number = p_from_number;

      insert into public.sms_consent (
        account_id, phone_number, status, source, consented_at,
        opted_out_at, disclosure_version, updated_at
      ) values (
        v_routed_account_id, p_from_number,
        case when p_keyword = 'stop' then 'opted_out' else 'opted_in' end,
        case when p_keyword = 'stop' then 'inbound_stop' else 'inbound_start' end,
        case when p_keyword = 'start' then v_now else null end,
        case when p_keyword = 'stop' then v_now else null end,
        null, v_now
      )
      on conflict (account_id, phone_number) do update
        set status = excluded.status,
            source = excluded.source,
            consented_at = case
              when excluded.status = 'opted_in' then excluded.consented_at
              else public.sms_consent.consented_at
            end,
            opted_out_at = excluded.opted_out_at,
            updated_at = excluded.updated_at;

      if p_keyword = 'start' and not v_existing_consent then
        insert into public.sms_operator_review_items (
          webhook_receipt_id, reason, severity, provider, account_id,
          sender_number_id, provider_event_id, from_number, to_number,
          message_body
        ) values (
          v_receipt.id, 'restart_without_consent', 'info', p_provider,
          v_routed_account_id, v_sender.id, p_provider_event_id,
          p_from_number, p_to_number, pg_catalog.left(p_message_body, 5000)
        );
      end if;
    elsif v_sender.purpose = 'lgq_dispatch' then
      -- STOP remains safe without guessing an account: the exact sender is
      -- blocked above, the account ledger is untouched, and review work records
      -- whether current roster authority was absent or cross-account ambiguous.
      v_reason := case
        when v_routed_account_count > 1 then 'ambiguous_destination'
        else 'shared_destination_unroutable'
      end;
      insert into public.sms_operator_review_items (
        webhook_receipt_id, reason, severity, provider, sender_number_id,
        provider_event_id, from_number, to_number, message_body, media_urls
      ) values (
        v_receipt.id, v_reason,
        case when v_reason = 'ambiguous_destination' then 'critical' else 'warning' end,
        p_provider, v_sender.id, p_provider_event_id, p_from_number, p_to_number,
        pg_catalog.left(p_message_body, 5000), p_media_urls
      );
    end if;

    update public.sms_webhook_receipts
       set processing_state = 'processed',
           disposition = 'keyword_' || p_keyword,
           processed_at = v_now
     where id = v_receipt.id;
    return query select ('keyword_' || p_keyword)::text, v_receipt.id,
                        v_routed_account_id, v_sender.id, v_sender.purpose;
    return;
  end if;

  if p_keyword = 'help' then
    update public.sms_webhook_receipts
       set processing_state = 'processed', disposition = 'keyword_help',
           processed_at = v_now
     where id = v_receipt.id;
    return query select 'keyword_help'::text, v_receipt.id,
                        v_routed_account_id, v_sender.id, v_sender.purpose;
    return;
  end if;

  if v_routed_account_id is null then
    v_reason := case
      when v_routed_account_count > 1 then 'ambiguous_destination'
      when v_sender.purpose in ('lgq_shared', 'lgq_dispatch')
        then 'shared_destination_unroutable'
      else 'unknown_destination'
    end;
    insert into public.sms_operator_review_items (
      webhook_receipt_id, reason, severity, provider, sender_number_id,
      provider_event_id, from_number, to_number, message_body, media_urls
    ) values (
      v_receipt.id, v_reason,
      case when v_reason = 'ambiguous_destination' then 'critical' else 'warning' end,
      p_provider, v_sender.id, p_provider_event_id, p_from_number, p_to_number,
      pg_catalog.left(p_message_body, 5000), p_media_urls
    );
    update public.sms_webhook_receipts
       set account_id = null, processing_state = 'review',
           disposition = v_reason, processed_at = v_now
     where id = v_receipt.id;
    return query select 'review'::text, v_receipt.id, null::uuid,
                        v_sender.id, v_sender.purpose;
    return;
  end if;

  -- The downstream exact-one action classifier and all of its candidate writers
  -- share this account/recipient lock. Bind the transcript and its receipt to
  -- that same authority before the existing receipt trigger creates the outbox.
  perform pg_catalog.pg_advisory_xact_lock(
    public.sms_inbound_recipient_lock_key(v_routed_account_id, p_from_number)
  );

  insert into public.sms_messages (
    account_id, phone_number, direction, body, provider_id, media_urls,
    provider, sender_number_id, read_at, created_at
  ) values (
    v_routed_account_id, p_from_number, 'inbound',
    coalesce(p_message_body, ''), p_provider_event_id,
    p_media_urls, p_provider, v_sender.id, null, v_now
  ) returning id into v_message_id;

  update public.sms_webhook_receipts
     set processing_state = 'processed', disposition = 'routed',
         account_id = v_routed_account_id,
         sms_message_id = v_message_id, processed_at = v_now
   where id = v_receipt.id;
  return query select 'routed'::text, v_receipt.id, v_routed_account_id,
                      v_sender.id, v_sender.purpose;
end;
$$;

-- The receipt's sender purpose is also the authority for which domain intents
-- an ordinary reply may mutate. A handset can legitimately hold more than one
-- audience scope in the same account; matching its phone against every open
-- request would otherwise let a crew YES accept a homeowner estimate, or a
-- customer YES claim a subcontractor offer.
create or replace function public.apply_sms_inbound_action(
  p_task_id uuid,
  p_claim_token uuid
)
returns jsonb
language plpgsql
security definer
set search_path = pg_catalog, pg_temp
set timezone to 'UTC'
as $$
declare
  v_task public.sms_inbound_action_tasks%rowtype;
  v_receipt public.sms_webhook_receipts%rowtype;
  v_message public.sms_messages%rowtype;
  v_sender_purpose text;
  v_now timestamptz := pg_catalog.clock_timestamp();
  v_token text;
  v_decision text;
  v_confirmation_only boolean := false;
  v_candidate_count integer := 0;
  v_kind text;
  v_target_id uuid;
  v_business_name text := 'your contractor';
  v_reply_kind text;
  v_reply_body text;
  v_alert_phone text;
  v_alert_body text;
  v_name text;
  v_when text;
  v_stop_id uuid;
  v_estimate public.estimate_offers%rowtype;
  v_reschedule public.reschedule_offers%rowtype;
  v_job public.jobs%rowtype;
  v_sub_offer public.subcontractor_offers%rowtype;
  v_sub_request public.subcontractor_requests%rowtype;
begin
  select t.* into v_task
    from public.sms_inbound_action_tasks t
   where t.id = p_task_id
   for update;
  if v_task.id is null
     or v_task.task_state <> 'processing'
     or v_task.claim_token is distinct from p_claim_token
     or v_task.lease_expires_at <= v_now then
    raise exception 'Inbound action claim is not active' using errcode = '55000';
  end if;
  if v_task.effect_applied_at is not null then
    return v_task.outcome;
  end if;

  select r.* into strict v_receipt
    from public.sms_webhook_receipts r
   where r.id = v_task.webhook_receipt_id;
  select m.* into strict v_message
    from public.sms_messages m
   where m.id = v_task.sms_message_id;
  if v_receipt.account_id is distinct from v_task.account_id
     or v_message.account_id is distinct from v_task.account_id
     or v_message.phone_number is distinct from v_receipt.from_number
     or v_receipt.sender_number_id is distinct from v_task.sender_number_id
     or v_message.sender_number_id is distinct from v_task.sender_number_id
     or v_receipt.disposition <> 'routed' then
    raise exception 'Inbound action task binding is invalid' using errcode = '23514';
  end if;

  select s.purpose into strict v_sender_purpose
    from public.sms_sender_numbers s
   where s.id = v_task.sender_number_id;
  if v_sender_purpose not in (
    'contractor_dedicated', 'lgq_dispatch', 'lgq_shared'
  ) then
    raise exception 'Inbound action sender purpose is invalid' using errcode = '23514';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    public.sms_inbound_recipient_lock_key(v_task.account_id, v_receipt.from_number)
  );

  v_token := pg_catalog.upper(
    coalesce((pg_catalog.regexp_split_to_array(pg_catalog.btrim(v_message.body), E'\\s+'))[1], '')
  );
  if v_token in ('YES','Y','YEP','YEAH','SURE','OK','ACCEPT','CONFIRM','CONFIRMED','1','C') then
    v_decision := 'accept';
  elsif v_token in ('NO','N','NOPE','DECLINE','2') then
    v_decision := 'decline';
  else
    v_decision := 'unclear';
  end if;
  v_confirmation_only := v_token = 'C';

  -- Domain state may change only in response to the exact outbound question
  -- linked by that domain record. Provider acceptance, sender, audience, tenant,
  -- recipient, and chronology are all part of the binding; queued, failed, and
  -- post-reply events are deliberately invisible to the candidate classifier.
  with accepted_question_events as materialized (
    select e.*
      from public.sms_events e
     where e.account_id = v_task.account_id
       and e.phone_number = v_receipt.from_number
       and e.sender_number_id = v_task.sender_number_id
       and e.sender_purpose = v_sender_purpose
       and e.provider = v_receipt.provider
       and nullif(pg_catalog.btrim(e.provider_id), '') is not null
       and e.provider_id <> 'simulated'
       and e.status in ('sent', 'delivered')
       and e.queued_at is not null
       and e.send_started_at is not null
       and e.provider_accepted_at is not null
       and e.sent_at is not null
       and e.created_at <= e.queued_at
       and e.queued_at <= e.send_started_at
       and e.send_started_at <= e.provider_accepted_at
       and e.provider_accepted_at <= e.sent_at
       and e.created_at <= v_receipt.received_at
       and e.queued_at <= v_receipt.received_at
       and e.send_started_at <= v_receipt.received_at
       and e.provider_accepted_at <= v_receipt.received_at
       and e.sent_at <= v_receipt.received_at
       and (e.status <> 'delivered' or e.delivered_at is not null)
       and e.failed_at is null
       and e.indeterminate_at is null
       and e.cancelled_at is null
  ), candidates as (
    select 'estimate'::text as kind, e.id as target_id
      from public.estimate_offers e
     where v_sender_purpose = 'contractor_dedicated'
       and not v_confirmation_only
          and e.account_id = v_task.account_id
          and e.phone = v_receipt.from_number
          and e.status = 'held'
          and exists (
            select 1
              from public.account_events account_event
              join accepted_question_events question
                on question.id::text = account_event.meta->>'sms_event_id'
             where account_event.account_id = e.account_id
               and account_event.kind = 'automation_toggled'
               and account_event.meta->>'source' = 'estimate_offer'
               and account_event.meta->>'offer_id' = e.id::text
               and account_event.meta->>'lead_id' = e.lead_id::text
               and account_event.created_at <= v_receipt.received_at
               and question.context = 'customer'
               and question.event_type = 'estimate_offer'
               and question.message_kind = 'estimate-offer'
               and question.billing_category = 'customer_message'
               and question.idempotency_key = 'estimate-offer:' || e.id::text
          )
      union all
      select 'reschedule'::text, o.id
        from public.reschedule_offers o
       where v_sender_purpose = 'contractor_dedicated'
         and not v_confirmation_only
          and o.account_id = v_task.account_id
          and o.phone = v_receipt.from_number
          and o.status = 'sent'
          and exists (
            select 1
              from public.account_events account_event
              join accepted_question_events question
                on question.id::text = account_event.meta->>'sms_event_id'
             where account_event.account_id = o.account_id
               and account_event.kind = 'automation_toggled'
               and account_event.meta->>'source' = 'reschedule_offer'
               and account_event.meta->>'offer_id' = o.id::text
               and account_event.meta->>'job_id' = o.job_id::text
               and account_event.created_at <= v_receipt.received_at
               and question.context = 'customer'
               and question.event_type = 'estimate_offer'
               and question.message_kind = 'estimate-offer'
               and question.billing_category = 'customer_message'
               and question.idempotency_key = 'reschedule-offer:' || o.id::text
          )
      union all
      select 'appointment'::text, j.id
        from public.jobs j
       where v_sender_purpose = 'contractor_dedicated'
         and v_decision = 'accept'
         and j.account_id = v_task.account_id
         and public.sms_normalize_recipient_phone(j.client_phone) = v_receipt.from_number
         and j.scheduled_for >= (v_now at time zone 'UTC')::date
         and j.status in ('new_lead', 'in_progress')
         and j.appointment_confirmed_at is null
          and exists (
            select 1
              from public.job_feed f
              join accepted_question_events question
                on question.id::text = f.meta->>'sms_event_id'
             where f.account_id = j.account_id
               and f.job_id = j.id
               and f.kind = 'appointment_reminder'
               and f.meta->>'channel' = 'sms'
               and f.meta->>'scheduled_for' = j.scheduled_for::text
               and (f.meta->>'scheduled_time')
                     is not distinct from j.scheduled_time::text
               and f.created_at <= v_receipt.received_at
               and question.context = 'automation'
               and question.event_type = 'appointment_reminder'
               and question.message_kind = 'appointment-reminder'
               and question.billing_category = 'customer_message'
               and question.idempotency_key =
                     'appointment-reminder:' || j.id::text || ':' ||
                     j.scheduled_for::text || ':' ||
                     coalesce(j.scheduled_time::text, 'none')
          )
      union all
      select 'subcontractor'::text, o.id
        from public.subcontractor_offers o
        join public.subcontractor_requests r on r.id = o.request_id
        join accepted_question_events question on question.id = o.sms_event_id
       where v_sender_purpose = 'lgq_dispatch'
         and not v_confirmation_only
          and v_decision in ('accept', 'decline')
          and o.account_id = v_task.account_id
          and o.phone = v_receipt.from_number
          and o.status in ('sent','delivered','viewed')
          and r.status in ('sent','viewed','partially_responded','reopened')
          and r.expires_at > v_now
          and question.crew_id = o.crew_id
          and question.context = 'subcontractor'
          and question.event_type = 'sub_offer'
          and question.message_kind = 'sub-offer'
          and question.billing_category = 'crew_message'
          and question.idempotency_key =
                'subcontractor:' || o.id::text || ':offer'
  )
  select pg_catalog.count(*)::integer,
         (pg_catalog.array_agg(c.kind))[1],
         (pg_catalog.array_agg(c.target_id))[1]
    into v_candidate_count, v_kind, v_target_id
    from candidates c;

  select nullif(pg_catalog.btrim(a.business_name), ''),
         public.sms_normalize_recipient_phone(a.alert_phone)
    into v_business_name, v_alert_phone
    from public.accounts a where a.id = v_task.account_id;
  if v_business_name is null or v_business_name = 'My Business' then
    v_business_name := 'your contractor';
  end if;

  if v_candidate_count = 0 then
    v_reply_kind := null;
    v_reply_body := null;
    v_kind := 'none';
  elsif v_candidate_count > 1 then
    v_kind := 'ambiguous';
    v_reply_kind := 'ambiguity';
    v_reply_body := 'We found more than one open request for this number, so nothing was changed. Please use the link in the message you are answering or contact ' || v_business_name || '.';
  elsif v_kind = 'estimate' then
    select e.* into strict v_estimate
      from public.estimate_offers e where e.id = v_target_id for update;
    select coalesce(nullif(pg_catalog.btrim(l.name), ''), 'there')
      into v_name from public.leads l where l.id = v_estimate.lead_id;
    v_reply_kind := 'offer';
    if v_decision = 'decline' then
      update public.estimate_offers
         set status = 'declined', replied_at = v_now,
             reply_body = pg_catalog.left(v_message.body, 500), updated_at = v_now
       where id = v_estimate.id and status = 'held';
      v_reply_body := 'No problem ' || v_name || ' — that estimate window has been released. ' || v_business_name || ' still has your request.';
      v_alert_body := v_name || ' said NO to an estimate window.';
    elsif v_decision = 'unclear' then
      update public.estimate_offers
         set forwarded_at = coalesce(forwarded_at, v_now), updated_at = v_now
       where id = v_estimate.id and status = 'held';
      v_reply_body := 'Thanks ' || v_name || ' — we passed that to ' || v_business_name || ' and they will follow up shortly.';
    elsif v_estimate.hold_expires_at <= v_now then
      update public.estimate_offers
         set status = 'accepted_late', replied_at = v_now,
             reply_body = pg_catalog.left(v_message.body, 500), updated_at = v_now
       where id = v_estimate.id and status = 'held';
      v_reply_body := 'Thanks ' || v_name || '! That window has just passed, so it was not booked. ' || v_business_name || ' has your reply and will help find a time.';
      v_alert_body := v_name || ' said YES after an estimate hold expired.';
    else
      insert into public.route_stops (
        account_id, crew_id, lead_id, scheduled_for, scheduled_time,
        label, address, lat, lng, minutes, kind, note,
        source_sms_webhook_receipt_id
      )
      select v_estimate.account_id, v_estimate.crew_id, v_estimate.lead_id,
             v_estimate.offer_date, v_estimate.arrival_time,
             'Estimate — ' || v_name, l.address, l.lat, l.lng,
             v_estimate.visit_minutes, 'estimate',
             'Accepted by text from receipt ' || v_receipt.id::text,
             v_receipt.id
        from public.leads l where l.id = v_estimate.lead_id
      on conflict (source_sms_webhook_receipt_id)
        where source_sms_webhook_receipt_id is not null
      do update
        set source_sms_webhook_receipt_id = excluded.source_sms_webhook_receipt_id
      returning id into v_stop_id;
      update public.estimate_offers
         set status = 'accepted', replied_at = v_now,
             reply_body = pg_catalog.left(v_message.body, 500),
             route_stop_id = v_stop_id, updated_at = v_now
       where id = v_estimate.id and status = 'held';
      update public.leads
         set quote_visit = pg_catalog.jsonb_build_object(
               'scheduledFor', v_estimate.offer_date,
               'scheduledTime', v_estimate.arrival_time,
               'durationMinutes', v_estimate.visit_minutes,
               'notes', 'Booked from an estimate offer by text.',
               'confirmationTextSentAt', v_now,
               'scheduledAt', v_now
             ),
             status = case when status = 'new' then 'contacted' else status end,
             updated_at = v_now
       where id = v_estimate.lead_id and account_id = v_task.account_id;
      v_when := pg_catalog.to_char(v_estimate.offer_date, 'FMDay, Mon FMDD') ||
        ' between ' || pg_catalog.to_char(v_estimate.window_start, 'FMHH12:MI AM') ||
        ' and ' || pg_catalog.to_char(v_estimate.window_end, 'FMHH12:MI AM');
      v_reply_body := 'You are booked, ' || v_name || '! ' || v_business_name || ' will arrive ' || v_when || '.';
      v_alert_body := v_name || ' said YES — the estimate was added to the schedule.';
    end if;
  elsif v_kind = 'reschedule' then
    select o.* into strict v_reschedule
      from public.reschedule_offers o where o.id = v_target_id for update;
    select j.* into strict v_job from public.jobs j where j.id = v_reschedule.job_id for update;
    v_name := coalesce(nullif(pg_catalog.btrim(v_job.client_name), ''), 'there');
    v_reply_kind := 'reschedule';
    if v_decision = 'decline' then
      update public.reschedule_offers
         set status = 'declined', replied_at = v_now,
             reply_body = pg_catalog.left(v_message.body, 500), updated_at = v_now
       where id = v_reschedule.id and status = 'sent';
      v_reply_body := 'No problem ' || v_name || ' — you are still booked for the original time. Nothing changed.';
      v_alert_body := v_name || ' said NO to a reschedule offer.';
    elsif v_decision = 'unclear' then
      update public.reschedule_offers
         set forwarded_at = coalesce(forwarded_at, v_now), updated_at = v_now
       where id = v_reschedule.id and status = 'sent';
      v_reply_body := 'Thanks ' || v_name || ' — we passed that to ' || v_business_name || ' and they will follow up shortly.';
    else
      update public.jobs
         set scheduled_for = v_reschedule.to_date,
             scheduled_time = v_reschedule.arrival_time,
             reschedule_discount_percent = v_reschedule.discount_percent,
             reschedule_discount_note = 'Agreed by text to move from ' || v_reschedule.from_date::text || ' to ' || v_reschedule.to_date::text,
             reschedule_discount_agreed_at = v_now
       where id = v_reschedule.job_id and account_id = v_task.account_id;
      update public.reschedule_offers
         set status = 'accepted', replied_at = v_now,
             reply_body = pg_catalog.left(v_message.body, 500), updated_at = v_now
       where id = v_reschedule.id and status = 'sent';
      v_when := pg_catalog.to_char(v_reschedule.to_date, 'FMDay, Mon FMDD') ||
        ', ' || pg_catalog.to_char(v_reschedule.window_start, 'FMHH12:MI AM') ||
        '–' || pg_catalog.to_char(v_reschedule.window_end, 'FMHH12:MI AM');
      v_reply_body := 'You are moved, ' || v_name || ' — ' || v_when || '. The ' ||
        v_reschedule.discount_percent::text || '% comes off your final bill.';
      v_alert_body := v_name || ' said YES — the job was moved and the discount recorded.';
    end if;
  elsif v_kind = 'appointment' then
    select j.* into strict v_job from public.jobs j where j.id = v_target_id for update;
    update public.jobs set appointment_confirmed_at = v_now
     where id = v_job.id and account_id = v_task.account_id
       and appointment_confirmed_at is null;
    v_name := coalesce(nullif(pg_catalog.btrim(v_job.client_name), ''), 'there');
    v_when := pg_catalog.to_char(v_job.scheduled_for, 'FMDay, Mon FMDD') ||
      case when v_job.scheduled_time is null then ''
           else ' at ' || pg_catalog.to_char(v_job.scheduled_time, 'FMHH12:MI AM') end;
    v_reply_kind := 'appointment_confirmation';
    v_reply_body := 'Thanks ' || v_name || ' — your appointment ' || v_when ||
      ' with ' || v_business_name || ' is confirmed. See you then!';
  elsif v_kind = 'subcontractor' then
    select o.* into strict v_sub_offer
      from public.subcontractor_offers o where o.id = v_target_id for update;
    select r.* into strict v_sub_request
      from public.subcontractor_requests r where r.id = v_sub_offer.request_id for update;
    v_reply_kind := 'subcontractor';
    if v_decision = 'decline' then
      update public.subcontractor_offers
         set status = 'declined', responded_at = v_now,
             decline_reason = 'Declined by text', updated_at = v_now
       where id = v_sub_offer.id
         and status in ('sent','delivered','viewed');
      v_reply_body := 'Thanks — we recorded that you are not available for this job.';
      v_alert_body := 'A subcontractor declined ' || v_sub_request.work_description || ' by text.';
    elsif v_sub_request.selection_mode = 'collect_interest' then
      update public.subcontractor_offers
         set status = 'accepted', won = false, responded_at = v_now, updated_at = v_now
       where id = v_sub_offer.id
         and status in ('sent','delivered','viewed');
      update public.subcontractor_requests
         set status = 'partially_responded', updated_at = v_now
       where id = v_sub_request.id
         and status in ('sent','viewed','partially_responded','reopened');
      v_reply_body := 'Thanks — your availability was recorded. ' || v_business_name || ' will let you know if you are selected.';
      v_alert_body := 'A subcontractor is available for ' || v_sub_request.work_description || '.';
    else
      update public.subcontractor_requests
         set status = 'claimed', claimed_offer_id = v_sub_offer.id,
             claimed_crew_id = v_sub_offer.crew_id, claimed_at = v_now,
             updated_at = v_now
       where id = v_sub_request.id
         and claimed_offer_id is null
         and status in ('sent','viewed','partially_responded','reopened')
         and expires_at > v_now;
      if not found then
        raise exception 'Subcontractor request changed during reply processing'
          using errcode = '40001';
      end if;
      insert into public.crew_assignments(account_id, job_id, crew_id)
      values (v_task.account_id, v_sub_request.job_id, v_sub_offer.crew_id)
      on conflict (job_id, crew_id) do nothing;
      update public.subcontractor_offers
         set status = 'accepted', won = true, responded_at = v_now, updated_at = v_now
       where id = v_sub_offer.id;
      update public.subcontractor_offers
         set status = 'covered', updated_at = v_now
       where request_id = v_sub_request.id and id <> v_sub_offer.id
         and status in ('queued','sent','delivered','viewed','failed');
      v_reply_body := 'You got the job. Open the secure link from the offer message for the customer and site details.';
      v_alert_body := 'A subcontractor accepted ' || v_sub_request.work_description || ' and was assigned to the job.';
    end if;
  end if;

  -- Free-text forwarding has no terminal owner alert; the inbox row itself is
  -- the durable owner-visible fact. All other preserved alerts are queued after
  -- this transaction with their own receipt-derived idempotency key.
  if v_decision = 'unclear' or v_kind in ('none', 'ambiguous', 'appointment') then
    v_alert_phone := null;
    v_alert_body := null;
  end if;

  v_task.outcome := pg_catalog.jsonb_strip_nulls(pg_catalog.jsonb_build_object(
    'action_kind', v_kind,
    'target_id', v_target_id,
    'decision', v_decision,
    'reply_kind', v_reply_kind,
    'reply_body', v_reply_body,
    'owner_alert_phone', v_alert_phone,
    'owner_alert_body', v_alert_body
  ));
  update public.sms_inbound_action_tasks
     set effect_applied_at = v_now, outcome = v_task.outcome, updated_at = v_now
   where id = v_task.id and task_state = 'processing'
     and claim_token = p_claim_token;
  return v_task.outcome;
end;
$$;

revoke all on function public.apply_sms_inbound_action(uuid,uuid)
  from public, anon, authenticated, service_role;
grant execute on function public.apply_sms_inbound_action(uuid,uuid)
  to service_role;

revoke all on function public.ingest_sms_inbound_webhook(
  text,text,text,text,text,text,text,text,text,text[],text
) from public, anon, authenticated, service_role;
grant execute on function public.ingest_sms_inbound_webhook(
  text,text,text,text,text,text,text,text,text,text[],text
) to service_role;

commit;

-- Source: migrations/20260821221223_voice_dedicated_number_invariant.sql
-- AI Voice may answer only a currently assigned SignalWire contractor number.
-- Application reads make the normal path cheap and explainable; this migration
-- repeats the proof under row locks at the admission transaction, where a
-- suspension or number reassignment can no longer race the paid AI answer.

begin;

-- A number can move A -> B -> A. Matching only the E.164 value would revive the
-- first A verification, so every change advances an immutable route epoch.
alter table public.accounts
  add column if not exists ai_voice_route_revision bigint not null default 0;

alter table public.accounts
  drop constraint if exists accounts_ai_voice_route_revision_nonnegative;
alter table public.accounts
  add constraint accounts_ai_voice_route_revision_nonnegative
  check (ai_voice_route_revision >= 0);

create or replace function public.guard_ai_voice_route_revision()
returns trigger
language plpgsql
set search_path = pg_catalog, pg_temp
as $fn$
begin
  if new.call_tracking_number is distinct from old.call_tracking_number then
    new.ai_voice_route_revision := old.ai_voice_route_revision + 1;
    -- Preserve the older missed-call card's safety when a caller updates the
    -- number through SQL/REST rather than the dashboard action.
    new.call_tracking_verified_at := null;
  else
    -- Owners may update accounts through RLS. The epoch is system-owned even if
    -- a crafted REST update tries to name this column directly.
    new.ai_voice_route_revision := old.ai_voice_route_revision;
  end if;
  return new;
end
$fn$;

drop trigger if exists accounts_ai_voice_route_revision_guard on public.accounts;
create trigger accounts_ai_voice_route_revision_guard
before update of call_tracking_number, ai_voice_route_revision on public.accounts
for each row execute function public.guard_ai_voice_route_revision();

revoke all on function public.guard_ai_voice_route_revision()
  from public, anon, authenticated, service_role;

-- Keep the exact number authority on every new admission. Existing historical
-- admissions remain nullable; only the service-only claim RPC can create a new
-- claimed row, and that RPC always binds all three fields.
alter table public.voice_call_admissions
  add column if not exists sender_number_id uuid
    references public.sms_sender_numbers(id) on delete restrict,
  add column if not exists dialed_number text,
  add column if not exists route_revision bigint;

alter table public.voice_call_admissions
  drop constraint if exists voice_call_admissions_number_binding_shape;
alter table public.voice_call_admissions
  add constraint voice_call_admissions_number_binding_shape check (
    (sender_number_id is null and dialed_number is null and route_revision is null)
    or (
      sender_number_id is not null
      and dialed_number ~ '^\+[1-9][0-9]{7,14}$'
      and route_revision >= 0
    )
  );

create index if not exists voice_call_admissions_sender_idx
  on public.voice_call_admissions (sender_number_id, admitted_at desc)
  where sender_number_id is not null;

-- Remove the unbound overload. Dropping it also drops its grants; leaving it
-- executable would make the stronger function optional for a service caller.
drop function if exists public.claim_voice_call_admission(uuid, text, integer);

create or replace function public.claim_voice_call_admission(
  p_account_id uuid,
  p_provider_call_id text,
  p_dialed_number text,
  p_concurrency_limit integer
)
returns table (
  claim_status text,
  admission_id uuid
)
language plpgsql
security definer
set search_path = pg_catalog, pg_temp
set timezone to 'UTC'
as $fn$
declare
  v_existing public.voice_call_admissions%rowtype;
  v_open bigint;
  v_id uuid;
  v_sender_number_id uuid;
  v_route_revision bigint;
begin
  if p_account_id is null
     or p_provider_call_id is null
     or pg_catalog.length(pg_catalog.btrim(p_provider_call_id)) = 0
     or pg_catalog.length(p_provider_call_id) > 255
     or p_dialed_number is null
     or p_dialed_number !~ '^\+[1-9][0-9]{7,14}$'
     or p_concurrency_limit is null
     or p_concurrency_limit < 1
     or p_concurrency_limit > 100 then
    raise exception 'voice admission claim arguments are invalid'
      using errcode = '22023';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(p_account_id::text, 84601211)
  );

  -- FOR SHARE holds both the workspace mapping and sender lifecycle stable
  -- through the insert. A concurrent suspension/transfer wins before this read
  -- (and refuses the call) or waits until the claim is durably bound.
  select s.id, a.ai_voice_route_revision
    into v_sender_number_id, v_route_revision
    from public.accounts a
    join public.sms_sender_numbers s
      on s.account_id = a.id
     and s.e164_number = a.call_tracking_number
   where a.id = p_account_id
     and a.call_tracking_number = p_dialed_number
     and s.provider = 'signalwire'
     and s.purpose = 'contractor_dedicated'
     and s.e164_number = p_dialed_number
     and s.provisioning_status = 'active'
     and s.assignment_state = 'assigned'
     and s.inbound_ready
     and s.activated_at is not null
     and s.suspended_at is null
     and s.provider_number_id ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
   for share of a, s;

  if not found then
    -- One generic answer for unprovisioned, shared, suspended, mismatched and
    -- other-account numbers. The boundary rejects without disclosing ownership.
    return query select 'number_not_ready'::text, null::uuid;
    return;
  end if;

  select a.* into v_existing
    from public.voice_call_admissions a
   where a.provider = 'signalwire'
     and a.provider_call_id = p_provider_call_id;

  if found then
    if v_existing.account_id <> p_account_id then
      raise exception 'voice call id is already bound to another workspace'
        using errcode = '22000';
    end if;
    if v_existing.sender_number_id is distinct from v_sender_number_id
       or v_existing.dialed_number is distinct from p_dialed_number
       or v_existing.route_revision is distinct from v_route_revision then
      return query select 'number_not_ready'::text, null::uuid;
    elsif v_existing.admission_state = 'admitted' then
      return query select 'existing'::text, v_existing.id;
    else
      return query select 'busy'::text, v_existing.id;
    end if;
    return;
  end if;

  select pg_catalog.count(*) into v_open
    from public.voice_call_admissions a
   where a.account_id = p_account_id
     and a.provider = 'signalwire'
     and a.admitted_at >= pg_catalog.clock_timestamp() - interval '60 minutes'
     and not exists (
       select 1
         from public.voice_events e
        where e.provider = a.provider
          and e.provider_call_id = a.provider_call_id
     );

  if v_open >= p_concurrency_limit then
    return query select 'at_capacity'::text, null::uuid;
    return;
  end if;

  insert into public.voice_call_admissions (
    account_id, provider, provider_call_id, reservation_id,
    reserved_minutes, admission_state, sender_number_id,
    dialed_number, route_revision
  ) values (
    p_account_id, 'signalwire', p_provider_call_id, null,
    0, 'claimed', v_sender_number_id, p_dialed_number, v_route_revision
  )
  returning id into v_id;

  return query select 'claimed'::text, v_id;
end
$fn$;

revoke all on function public.claim_voice_call_admission(uuid, text, text, integer)
  from public, anon, authenticated, service_role;
grant execute on function public.claim_voice_call_admission(uuid, text, text, integer)
  to service_role;

-- The receipt is unsigned, so a missing expected scope must never turn exact
-- comparison off. Redefine the original RPC with mandatory provider and
-- deployment project/space values before any admission lookup or insert.
create or replace function public.ingest_voice_event(
  p_provider_call_id text,
  p_event_type text,
  p_provider_project_id text,
  p_provider_space_id text,
  p_expected_project_id text,
  p_expected_space_id text,
  p_payload jsonb
)
returns table (
  voice_event_id uuid,
  inserted boolean,
  workspace_id uuid,
  admitted boolean
)
language plpgsql
security definer
set search_path = pg_catalog, pg_temp
as $fn$
declare
  v_existing public.voice_events%rowtype;
  v_admission public.voice_call_admissions%rowtype;
  v_event_id text;
  v_payload_sha256 text;
  v_inserted_id uuid;
  v_status text;
  v_account uuid;
begin
  if p_provider_call_id is null
     or pg_catalog.length(pg_catalog.btrim(p_provider_call_id)) = 0 then
    raise exception 'voice call id is required' using errcode = '22023';
  end if;

  if p_event_type is distinct from 'post_conversation' then
    raise exception 'unsupported voice event type: %', p_event_type using errcode = '22023';
  end if;

  if p_payload is null or pg_catalog.jsonb_typeof(p_payload) <> 'object' then
    raise exception 'voice event payload must be a JSON object' using errcode = '22023';
  end if;

  if p_expected_project_id is null
     or pg_catalog.length(pg_catalog.btrim(p_expected_project_id)) = 0
     or p_provider_project_id is null
     or pg_catalog.length(pg_catalog.btrim(p_provider_project_id)) = 0 then
    raise exception 'voice event project scope is required' using errcode = '22023';
  end if;
  if p_expected_space_id is null
     or pg_catalog.length(pg_catalog.btrim(p_expected_space_id)) = 0
     or p_provider_space_id is null
     or pg_catalog.length(pg_catalog.btrim(p_provider_space_id)) = 0 then
    raise exception 'voice event space scope is required' using errcode = '22023';
  end if;
  if p_provider_project_id is distinct from p_expected_project_id then
    raise exception 'voice event project does not match this deployment' using errcode = '22023';
  end if;
  if p_provider_space_id is distinct from p_expected_space_id then
    raise exception 'voice event space does not match this deployment' using errcode = '22023';
  end if;

  v_event_id := p_provider_call_id || ':' || p_event_type;
  v_payload_sha256 := pg_catalog.encode(
    extensions.digest(pg_catalog.convert_to(p_payload::text, 'UTF8'), 'sha256'),
    'hex'
  );

  select e.* into v_existing
    from public.voice_events e
   where e.provider = 'signalwire'
     and e.provider_event_id = v_event_id
   for update;

  if found then
    if v_existing.event_type is distinct from p_event_type
       or v_existing.provider_call_id is distinct from p_provider_call_id
       or v_existing.payload is distinct from p_payload
       or v_existing.payload_sha256 is distinct from v_payload_sha256 then
      raise exception 'voice event was already received with different immutable input'
        using errcode = '23505';
    end if;
    return query select v_existing.id, false, v_existing.account_id,
                        v_existing.processing_status <> 'ignored';
    return;
  end if;

  select a.* into v_admission
    from public.voice_call_admissions a
   where a.provider = 'signalwire'
     and a.provider_call_id = p_provider_call_id;

  if found then
    v_account := v_admission.account_id;
    v_status := 'received';
  else
    v_account := null;
    v_status := 'ignored';
  end if;

  insert into public.voice_events (
    provider, provider_event_id, event_type, provider_call_id,
    provider_project_id, provider_space_id, account_id,
    payload, payload_sha256, processing_status, processed_at
  ) values (
    'signalwire', v_event_id, p_event_type, p_provider_call_id,
    p_provider_project_id, p_provider_space_id, v_account,
    p_payload, v_payload_sha256, v_status,
    case when v_status = 'ignored' then pg_catalog.now() else null end
  )
  returning id into v_inserted_id;

  return query select v_inserted_id, true, v_account, v_status <> 'ignored';
end
$fn$;

revoke all on function public.ingest_voice_event(text, text, text, text, text, text, jsonb)
  from public, anon, authenticated, service_role;
grant execute on function public.ingest_voice_event(text, text, text, text, text, text, jsonb)
  to service_role;

commit;

-- Source: migrations/20260821230000_voice_transcript_retention.sql
-- Keep one useful AI Voice transcript, and keep it only for the period the
-- workspace is promised. The billing/admission ledgers are intentionally not
-- touched: voice_events and voice_calls contain caller content; usage_* and
-- voice_call_admissions contain the immutable proof of what was admitted and
-- charged.

begin;

-- Existing dark/staging rows may still contain SignalWire's three copies of a
-- conversation. Move the useful `call_log` into the contractor-facing row
-- before stripping every transcript from the immutable receipt envelope.
update public.voice_calls c
   set transcript = transcript.call_log
  from public.voice_events e
  cross join lateral (
    select coalesce(
      pg_catalog.jsonb_agg(
        pg_catalog.jsonb_strip_nulls(pg_catalog.jsonb_build_object(
          'role', nullif(pg_catalog.btrim(turn.value ->> 'role'), ''),
          'content', nullif(pg_catalog.btrim(turn.value ->> 'content'), ''),
          'timestamp', case
            when pg_catalog.jsonb_typeof(turn.value -> 'timestamp') = 'number'
              then turn.value -> 'timestamp'
            else null
          end
        )) order by turn.ordinal
      ) filter (
        where pg_catalog.jsonb_typeof(turn.value) = 'object'
          and nullif(pg_catalog.btrim(turn.value ->> 'content'), '') is not null
      ),
      '[]'::jsonb
    ) as call_log
      from pg_catalog.jsonb_array_elements(
        case
          when pg_catalog.jsonb_typeof(e.payload -> 'call_log') = 'array'
            then e.payload -> 'call_log'
          else '[]'::jsonb
        end
      ) with ordinality as turn(value, ordinal)
  ) transcript
 where c.transcript is null
   and pg_catalog.jsonb_typeof(e.payload -> 'call_log') = 'array'
   and (
     c.voice_event_id = e.id
     or (
       c.provider = e.provider
       and c.provider_call_id = e.provider_call_id
     )
   );

-- Rewrite events to the same transcript-free envelope the application now
-- sends to ingest_voice_event. The persisted hash follows the persisted JSON
-- so an identical minimized provider retry remains an exact replay.
with minimized as (
  select e.id,
         pg_catalog.jsonb_strip_nulls(pg_catalog.jsonb_build_object(
      'action', e.payload -> 'action',
      'call_id', e.payload -> 'call_id',
      'project_id', e.payload -> 'project_id',
      'space_id', e.payload -> 'space_id',
      'conversation_type', e.payload -> 'conversation_type',
      'call_start_date', e.payload -> 'call_start_date',
      'call_answer_date', e.payload -> 'call_answer_date',
      'call_end_date', e.payload -> 'call_end_date',
      'ai_start_date', e.payload -> 'ai_start_date',
      'ai_end_date', e.payload -> 'ai_end_date',
      'caller_id_number', e.payload -> 'caller_id_number',
      'summary', pg_catalog.to_jsonb(coalesce(
        nullif(pg_catalog.btrim(e.payload #>> '{post_prompt_data,substituted}'), ''),
        nullif(pg_catalog.btrim(e.payload #>> '{post_prompt_data,raw}'), ''),
        (
          select nullif(pg_catalog.btrim(turn.value ->> 'content'), '')
            from pg_catalog.jsonb_array_elements(
              case
                when pg_catalog.jsonb_typeof(e.payload -> 'call_log') = 'array'
                  then e.payload -> 'call_log'
                else '[]'::jsonb
              end
            ) with ordinality as turn(value, ordinal)
           where turn.value ->> 'role' = 'assistant'
           order by turn.ordinal desc
           limit 1
        )
      )),
      'SWMLCall', case
        when nullif(pg_catalog.btrim(e.payload #>> '{SWMLCall,call_id}'), '') is not null
          then pg_catalog.jsonb_build_object(
            'call_id', e.payload #>> '{SWMLCall,call_id}'
          )
        else null
      end,
      'SWMLVars', case
        when nullif(pg_catalog.btrim(
          e.payload #>> '{SWMLVars,userVariables,memberCallId}'
        ), '') is not null then pg_catalog.jsonb_build_object(
          'userVariables', pg_catalog.jsonb_build_object(
            'memberCallId', e.payload #>> '{SWMLVars,userVariables,memberCallId}'
          )
        )
        else null
      end
         )) as payload
    from public.voice_events e
   where e.payload ?| array['call_log', 'raw_call_log', 'call_timeline', 'post_prompt_data']
      or not (e.payload ? 'summary')
)
update public.voice_events e
   set payload = minimized.payload,
       payload_sha256 = pg_catalog.encode(
         extensions.digest(
           pg_catalog.convert_to(minimized.payload::text, 'UTF8'),
           'sha256'
         ),
         'hex'
       )
  from minimized
 where e.id = minimized.id;

alter table public.voice_events
  drop constraint if exists voice_events_minimized_payload_check;
alter table public.voice_events
  add constraint voice_events_minimized_payload_check check (
    not (payload ?| array['call_log', 'raw_call_log', 'call_timeline', 'post_prompt_data'])
    and (
      not (payload ? 'summary')
      or pg_catalog.jsonb_typeof(payload -> 'summary') = 'string'
    )
  );

-- Catalog values are 30 or 90 today. Clamp rather than trusting arbitrary
-- JSON so a malformed or bespoke entitlement cannot retain caller content
-- forever (or erase it immediately). Missing entitlement evidence is the
-- privacy-safe shorter window.
create or replace function public.voice_history_retention_days(
  p_feature_limits jsonb
)
returns integer
language sql
immutable
set search_path = pg_catalog, pg_temp
as $fn$
  select least(90, greatest(30,
    case
      when pg_catalog.length(p_feature_limits ->> 'voice_history_days') between 1 and 3
       and (p_feature_limits ->> 'voice_history_days') ~ '^[0-9]+$'
        then (p_feature_limits ->> 'voice_history_days')::integer
      else 30
    end
  ))
$fn$;

-- RLS is part of retention, not merely tenant isolation. The daily purge may
-- run hours after a row expires (or may be temporarily unhealthy); a direct
-- Supabase REST query must still be unable to read it. This predicate reveals
-- no entitlement data and returns false for every non-owner account.
create or replace function public.voice_call_visible_within_retention(
  p_account_id uuid,
  p_created_at timestamptz
)
returns boolean
language sql
stable
security definer
set search_path = pg_catalog, pg_temp
set timezone to 'UTC'
as $fn$
  select coalesce(public.is_owner(p_account_id), false)
     and p_created_at >= pg_catalog.now() - pg_catalog.make_interval(
       days => coalesce((
         select public.voice_history_retention_days(w.feature_limits)
           from public.workspace_entitlements w
          where w.account_id = p_account_id
       ), 30)
     )
$fn$;

drop policy if exists voice_calls_owner_read on public.voice_calls;
create policy voice_calls_owner_read
  on public.voice_calls
  for select
  to authenticated
  using (public.voice_call_visible_within_retention(account_id, created_at));

-- There is deliberately no feature flag around this function or its cron.
-- Once caller content exists, deletion must not depend on product rollout or
-- provider availability. Only terminal inbox rows are eligible: an actively
-- processing or retryable receipt keeps its evidence until processing reaches
-- a durable outcome.
create or replace function public.purge_expired_voice_history(
  p_batch_size integer default 500
)
returns table (
  voice_calls_deleted integer,
  voice_events_deleted integer,
  more_due boolean
)
language plpgsql
security definer
set search_path = pg_catalog, pg_temp
set timezone to 'UTC'
as $fn$
declare
  v_now timestamptz := pg_catalog.clock_timestamp();
  v_calls integer := 0;
  v_events integer := 0;
  v_more boolean := false;
begin
  if p_batch_size is null or p_batch_size not between 1 and 5000 then
    raise exception 'voice retention batch size must be between 1 and 5000'
      using errcode = '22023';
  end if;

  with candidates as (
    select c.id
      from public.voice_calls c
      left join public.workspace_entitlements w on w.account_id = c.account_id
     where c.created_at < v_now - pg_catalog.make_interval(
       days => public.voice_history_retention_days(w.feature_limits)
     )
       and (
         c.voice_event_id is null
         or exists (
           select 1
             from public.voice_events e
            where e.id = c.voice_event_id
              and (
                e.processing_status in ('processed', 'ignored')
                or (
                  e.processing_status = 'failed'
                  and e.next_attempt_at is null
                  and e.processing_token is null
                  and e.processing_lease_expires_at is null
                )
              )
         )
       )
     order by c.created_at, c.id
     limit p_batch_size
     for update of c skip locked
  ), removed as (
    delete from public.voice_calls c
     using candidates x
     where c.id = x.id
    returning c.id
  )
  select pg_catalog.count(*)::integer into v_calls from removed;

  with candidates as (
    select e.id
      from public.voice_events e
      left join public.workspace_entitlements w on w.account_id = e.account_id
     where e.received_at < v_now - pg_catalog.make_interval(
       days => public.voice_history_retention_days(w.feature_limits)
     )
       and (
         e.processing_status in ('processed', 'ignored')
         or (
           e.processing_status = 'failed'
           and e.next_attempt_at is null
           and e.processing_token is null
           and e.processing_lease_expires_at is null
         )
       )
     order by e.received_at, e.id
     limit p_batch_size
     for update of e skip locked
  ), removed as (
    delete from public.voice_events e
     using candidates x
     where e.id = x.id
    returning e.id
  )
  select pg_catalog.count(*)::integer into v_events from removed;

  select
    exists (
      select 1
        from public.voice_calls c
        left join public.workspace_entitlements w on w.account_id = c.account_id
       where c.created_at < v_now - pg_catalog.make_interval(
         days => public.voice_history_retention_days(w.feature_limits)
       )
         and (
           c.voice_event_id is null
           or exists (
             select 1 from public.voice_events e
              where e.id = c.voice_event_id
                and (
                  e.processing_status in ('processed', 'ignored')
                  or (
                    e.processing_status = 'failed'
                    and e.next_attempt_at is null
                    and e.processing_token is null
                    and e.processing_lease_expires_at is null
                  )
                )
           )
         )
    )
    or exists (
      select 1
        from public.voice_events e
        left join public.workspace_entitlements w on w.account_id = e.account_id
       where e.received_at < v_now - pg_catalog.make_interval(
         days => public.voice_history_retention_days(w.feature_limits)
       )
         and (
           e.processing_status in ('processed', 'ignored')
           or (
             e.processing_status = 'failed'
             and e.next_attempt_at is null
             and e.processing_token is null
             and e.processing_lease_expires_at is null
           )
         )
    )
    into v_more;

  return query select v_calls, v_events, v_more;
end
$fn$;

revoke all on function public.voice_history_retention_days(jsonb)
  from public, anon, authenticated, service_role;
grant execute on function public.voice_history_retention_days(jsonb)
  to service_role;

revoke all on function public.voice_call_visible_within_retention(uuid, timestamptz)
  from public, anon, authenticated, service_role;
grant execute on function public.voice_call_visible_within_retention(uuid, timestamptz)
  to authenticated;

revoke all on function public.purge_expired_voice_history(integer)
  from public, anon, authenticated, service_role;
grant execute on function public.purge_expired_voice_history(integer)
  to service_role;

commit;

-- Source: migrations/20260822120000_messaging_registry_callback_inbox.sql
-- SignalWire 10DLC Campaign Registry status-callback inbox.
--
-- Why this exists: on 2026-08-21 the individual number assignment for the LGQ
-- shared number failed, and the carrier reason was never captured. It was not
-- mislaid -- it was never received. No status_callback_url was ever registered
-- with SignalWire, because assignMessagingNumberCampaign refuses to register one
-- until an authenticated receiving route exists
-- (src/lib/messaging-number-provisioning.ts, "no authenticated 10DLC
-- assignment-callback route"). This migration is the storage half of that route.
--
-- Design constraint that shapes everything below: the payload shape of a
-- Campaign Registry status callback is NOT documented by SignalWire beyond a
-- field list, is not captured anywhere in this repo, and carries no reason field
-- in the published spec. A receiver that stores only parsed fields would lose
-- the next failure exactly as the last one was lost. Therefore raw bytes are the
-- deliverable and the parse is a convenience that is allowed to return nothing.

begin;

-- ---------------------------------------------------------------------------
-- 1. webhook_failures gains its value BEFORE any code writes it.
--    logWebhookFailure catches its own insert error (src/lib/webhook-failures.ts),
--    so a CHECK violation does not raise -- the failure log just silently stops
--    recording, during the exact window someone is watching it. Same ordering
--    and same reason as migrations/20260819100000_webhook_source_ai_voice.sql.
-- ---------------------------------------------------------------------------
alter table public.webhook_failures drop constraint if exists webhook_failures_source_check;
alter table public.webhook_failures add constraint webhook_failures_source_check
  check (source in (
    'stripe', 'resend',
    'twilio_inbound', 'twilio_status',
    'sms_inbound', 'sms_status', 'sms_voice',
    'ai_voice',
    -- the 10DLC Campaign Registry assignment status callback
    'sms_registry'
  ));

-- ---------------------------------------------------------------------------
-- 2. Correlation index. A callback arrives keyed by the provider's order id and
--    there is no index to resolve it back to an application.
--
--    Deliberately NOT unique: production data is unverified from here, and a
--    unique index that discovers a pre-existing duplicate fails the entire
--    migration rather than the one row that is wrong.
-- ---------------------------------------------------------------------------
create index if not exists messaging_registration_applications_assignment_order_idx
  on public.messaging_registration_applications (assignment_order_id)
  where assignment_order_id is not null;

-- ---------------------------------------------------------------------------
-- 3. The inbox. Raw bytes first, meaning second.
--
--    on delete set null, NOT restrict: every FK on this rail is restrict, and a
--    new restrict FK would make an account undeletable the moment this table
--    receives its first row. voice_events took set null for the same reason.
-- ---------------------------------------------------------------------------
create table if not exists public.messaging_registry_callbacks (
  id uuid primary key default pg_catalog.gen_random_uuid(),
  provider text not null default 'signalwire' check (provider = 'signalwire'),

  -- Dedupe identity. Built by the route from whatever identity the body yields
  -- plus the digest of the exact bytes, so a redelivery collides and a genuine
  -- later transition does not.
  receipt_key text not null
    check (pg_catalog.length(receipt_key) between 1 and 700),
  body_sha256 text not null check (body_sha256 ~ '^[0-9a-f]{64}$'),

  -- Bytes exactly as received, before any parse or newline normalization.
  raw_body text not null check (pg_catalog.length(raw_body) <= 65536),
  content_type text check (content_type is null or pg_catalog.length(content_type) <= 255),
  request_method text not null check (request_method in ('POST', 'PUT', 'GET')),
  -- Written with the secret path segment replaced by a placeholder. The token
  -- must never reach this table.
  request_path text not null check (pg_catalog.length(request_path) <= 2048),
  -- Header names verbatim; values only for a safe allowlist, presence-only
  -- booleans for anything that carries reusable authentication material.
  request_headers jsonb not null default '{}'::jsonb
    check (pg_catalog.jsonb_typeof(request_headers) = 'object'),
  -- Recorded, never gated on. Nothing establishes that SignalWire signs this
  -- surface at all; capturing the value is what lets the scheme be verified
  -- offline later. An HMAC value discloses no key.
  signature_header_name text
    check (signature_header_name is null or pg_catalog.length(signature_header_name) <= 128),
  signature_header_value text
    check (signature_header_value is null or pg_catalog.length(signature_header_value) <= 512),

  -- Best-effort interpretation. Null is a legal and expected outcome.
  parsed jsonb check (parsed is null or pg_catalog.jsonb_typeof(parsed) = 'object'),
  provider_order_id text check (provider_order_id is null or pg_catalog.length(provider_order_id) <= 200),
  provider_assignment_id text check (provider_assignment_id is null or pg_catalog.length(provider_assignment_id) <= 200),
  provider_campaign_id text check (provider_campaign_id is null or pg_catalog.length(provider_campaign_id) <= 200),
  provider_phone_number text check (provider_phone_number is null or pg_catalog.length(provider_phone_number) <= 32),
  provider_state text check (provider_state is null or pg_catalog.length(provider_state) <= 200),
  -- Normalized with the same three-way vocabulary as the rest of the rail, plus
  -- 'unknown'. The rail's own case expression maps anything unrecognized to
  -- 'pending'; if the registry spells a terminal state 'FAILED' or 'declined',
  -- that would read as in-progress forever. 'unknown' makes a novel terminal
  -- state visible instead of silently benign.
  normalized_state text
    check (normalized_state is null
           or normalized_state in ('complete', 'failed', 'pending', 'unknown')),
  failure_code text
    check (failure_code is null or failure_code ~ '^[a-z][a-z0-9_]{2,99}$'),
  failure_detail text
    check (failure_detail is null or pg_catalog.length(failure_detail) <= 2000),

  application_id uuid
    references public.messaging_registration_applications(id) on delete set null,
  account_id uuid references public.accounts(id) on delete set null,

  processing_status text not null default 'received'
    check (processing_status in ('received', 'processed', 'unmatched', 'review', 'ignored', 'failed')),
  attempt_count integer not null default 0 check (attempt_count >= 0),
  last_error text check (last_error is null or pg_catalog.length(last_error) <= 2000),
  received_at timestamptz not null default pg_catalog.now(),
  processed_at timestamptz,

  constraint messaging_registry_callbacks_receipt_unique
    unique (provider, receipt_key),
  constraint messaging_registry_callbacks_processing_shape check (
    (processing_status = 'received' and processed_at is null)
    or (processing_status <> 'received' and processed_at is not null)
  )
);

create index if not exists messaging_registry_callbacks_order_idx
  on public.messaging_registry_callbacks (provider_order_id, received_at desc)
  where provider_order_id is not null;
create index if not exists messaging_registry_callbacks_application_idx
  on public.messaging_registry_callbacks (application_id, received_at desc)
  where application_id is not null;
create index if not exists messaging_registry_callbacks_open_idx
  on public.messaging_registry_callbacks (received_at, id)
  where processing_status in ('received', 'failed', 'unmatched');

-- ---------------------------------------------------------------------------
-- 4. Ingest. Every row-count-bearing statement proves its own effect, because
--    on this codebase a zero-row write returns no error and reports success.
-- ---------------------------------------------------------------------------
create or replace function public.ingest_messaging_registry_callback(
  p_receipt_key text,
  p_body_sha256 text,
  p_raw_body text,
  p_content_type text,
  p_request_method text,
  p_request_path text,
  p_request_headers jsonb,
  p_signature_header_name text,
  p_signature_header_value text,
  p_parsed jsonb,
  p_provider_order_id text,
  p_provider_assignment_id text,
  p_provider_campaign_id text,
  p_provider_phone_number text,
  p_provider_state text,
  p_normalized_state text,
  p_failure_code text,
  p_failure_detail text
)
returns table (
  callback_id uuid,
  inserted boolean,
  matched_application_id uuid,
  disposition text
)
language plpgsql
security definer
set search_path = pg_catalog, pg_temp
set timezone to 'UTC'
as $$
declare
  v_now timestamptz := pg_catalog.clock_timestamp();
  v_existing public.messaging_registry_callbacks%rowtype;
  v_application public.messaging_registration_applications%rowtype;
  v_matched boolean := false;
  v_account uuid;
  v_status text;
  v_id uuid;
begin
  if p_receipt_key is null or pg_catalog.length(pg_catalog.btrim(p_receipt_key)) = 0
     or coalesce(p_body_sha256, '') !~ '^[0-9a-f]{64}$'
     or p_raw_body is null then
    raise exception 'registry callback input is invalid' using errcode = '22023';
  end if;

  select c.* into v_existing
    from public.messaging_registry_callbacks c
   where c.provider = 'signalwire' and c.receipt_key = p_receipt_key
   for update;

  if found then
    -- A replay must be byte-identical. Differing bytes under one receipt key
    -- means the key was built from something that does not identify the event.
    if v_existing.body_sha256 is distinct from p_body_sha256 then
      raise exception 'registry callback already received with different bytes'
        using errcode = '23505';
    end if;
    return query select v_existing.id, false, v_existing.application_id,
                        v_existing.processing_status;
    return;
  end if;

  if p_provider_order_id is not null then
    select a.* into v_application
      from public.messaging_registration_applications a
     where a.assignment_order_id = p_provider_order_id
     for update;
    v_matched := found;
  end if;

  if v_matched and v_application.id is not null then
    v_account := v_application.account_id;
    v_status  := 'received';
  else
    -- A callback naming an order LGQ cannot resolve is still stored. Dropping it
    -- would hide a misconfiguration and a forged request equally well.
    v_application.id := null;
    v_account := null;
    v_status  := 'unmatched';
  end if;

  insert into public.messaging_registry_callbacks (
    provider, receipt_key, body_sha256, raw_body, content_type,
    request_method, request_path, request_headers,
    signature_header_name, signature_header_value, parsed,
    provider_order_id, provider_assignment_id, provider_campaign_id,
    provider_phone_number, provider_state, normalized_state,
    failure_code, failure_detail,
    application_id, account_id, processing_status, processed_at
  ) values (
    'signalwire', p_receipt_key, p_body_sha256, p_raw_body, p_content_type,
    p_request_method, p_request_path, coalesce(p_request_headers, '{}'::jsonb),
    p_signature_header_name, p_signature_header_value, p_parsed,
    p_provider_order_id, p_provider_assignment_id, p_provider_campaign_id,
    p_provider_phone_number, p_provider_state, p_normalized_state,
    p_failure_code, p_failure_detail,
    v_application.id, v_account, v_status,
    case when v_status = 'unmatched' then v_now else null end
  )
  returning id into v_id;

  -- Row-count proof: INSERT ... RETURNING INTO leaves v_id null on zero rows,
  -- and "no error" is not evidence that anything was written.
  if v_id is null then
    raise exception 'registry callback was not stored' using errcode = '55000';
  end if;

  -- Advisory mirror onto the application. This records that the provider spoke;
  -- it deliberately does NOT change assignment state. Activation trusts only a
  -- live read of the individual assignment, never an order-level callback.
  if v_application.id is not null
     and p_normalized_state in ('failed', 'pending', 'complete', 'unknown') then
    update public.messaging_registration_applications
       set assignment_checked_at = v_now, updated_at = v_now
     where id = v_application.id;
    if not found then
      raise exception 'registry callback could not touch its application row'
        using errcode = '55000';
    end if;

    insert into public.messaging_registration_events (
      application_id, account_id, event_type, actor_type, actor_reference,
      previous_status, new_status, detail, metadata
    ) values (
      v_application.id, v_account, 'assignment_status_callback_received',
      'provider', 'signalwire:registry-callback',
      v_application.status, v_application.status,
      p_failure_detail,
      pg_catalog.jsonb_build_object(
        'callback_id', v_id,
        'provider_order_id', p_provider_order_id,
        'provider_assignment_id', p_provider_assignment_id,
        'provider_state', p_provider_state,
        'normalized_state', p_normalized_state,
        'failure_code', p_failure_code,
        'body_sha256', p_body_sha256
      )
    );
  end if;

  return query select v_id, true, v_application.id, v_status;
end;
$$;

-- ---------------------------------------------------------------------------
-- 5. Least privilege. The table is unreachable by anon and authenticated, and
--    the route reaches it only through the service role via this one function.
-- ---------------------------------------------------------------------------
alter table public.messaging_registry_callbacks enable row level security;
alter table public.messaging_registry_callbacks force row level security;
-- No policy, deliberately: RLS enabled with no policy means anon and
-- authenticated read nothing at all, and the service-role client bypasses RLS.

revoke all on table public.messaging_registry_callbacks
  from public, anon, authenticated, service_role;
grant select on table public.messaging_registry_callbacks to service_role;

revoke all on function public.ingest_messaging_registry_callback(
  text, text, text, text, text, text, jsonb, text, text, jsonb,
  text, text, text, text, text, text, text, text)
  from public, anon, authenticated, service_role;
grant execute on function public.ingest_messaging_registry_callback(
  text, text, text, text, text, text, jsonb, text, text, jsonb,
  text, text, text, text, text, text, text, text)
  to service_role;

-- ---------------------------------------------------------------------------
-- 6. Post-conditions. Prove the constraint bites and the table is unreachable,
--    rather than trusting that the statements above did what they read like.
-- ---------------------------------------------------------------------------
do $$
declare
  v_bad text;
begin
  if not exists (
    select 1 from pg_catalog.pg_constraint
     where conname = 'webhook_failures_source_check'
       and pg_catalog.pg_get_constraintdef(oid) like '%sms_registry%'
  ) then
    raise exception 'webhook_failures_source_check does not admit sms_registry';
  end if;

  select pg_catalog.string_agg(distinct g.grantee_name, ', ') into v_bad
  from (
    select pg_catalog.pg_get_userbyid(x.grantee) as grantee_name
      from pg_catalog.pg_class c
      join pg_catalog.pg_namespace n on n.oid = c.relnamespace
      cross join lateral pg_catalog.aclexplode(coalesce(c.relacl, '{}'::aclitem[])) x
     where n.nspname = 'public' and c.relname = 'messaging_registry_callbacks'
  ) g
  where g.grantee_name in ('anon', 'authenticated', 'public');
  if v_bad is not null then
    raise exception 'messaging_registry_callbacks is reachable by: %', v_bad;
  end if;

  if not exists (
    select 1 from pg_catalog.pg_class c
      join pg_catalog.pg_namespace n on n.oid = c.relnamespace
     where n.nspname = 'public' and c.relname = 'messaging_registry_callbacks'
       and c.relrowsecurity and c.relforcerowsecurity
  ) then
    raise exception 'row level security is not forced on messaging_registry_callbacks';
  end if;

  if not exists (
    select 1 from pg_catalog.pg_proc p
      join pg_catalog.pg_namespace n on n.oid = p.pronamespace
     where n.nspname = 'public' and p.proname = 'ingest_messaging_registry_callback'
       and p.prosecdef
  ) then
    raise exception 'ingest_messaging_registry_callback is not security definer';
  end if;
end $$;

commit;

-- Source: migrations/20260822210000_shared_number_notice_reply.sql
-- An auto-reply for LGQ's own shared/dispatch numbers, and its audit trail.
--
-- WHY THIS EXISTS. The shared number sends account alerts to the contractor and
-- nothing else. Until now a reply to it produced total silence: a consented
-- owner's message was filed for review, and an unrecognised sender's message
-- went nowhere at all. Somebody texting a business number and receiving nothing
-- is worse than either a monitored inbox or an honest automated answer.
--
-- WHY IT IS NOT PART OF THE COMPLIANCE REPLY. record_sms_compliance_reply_result
-- binds its audit row to the receipt's disposition:
--
--     v_receipt.disposition is distinct from ('keyword_' || p_keyword) -> raise
--
-- A notice reply's disposition is `routed` or `shared_destination_unroutable`,
-- never `keyword_notice`. Widening that function to admit it would weaken the
-- one invariant that ties a compliance acknowledgement to the keyword that
-- earned it. STOP/START/HELP are carrier obligations; this is a courtesy. They
-- get separate machinery on purpose.
--
-- WHAT IS SHARED is the SHAPE, deliberately: a synchronous carrier Message verb
-- is only ever returned by the request that won an atomic insert, so a provider
-- retry cannot text somebody twice.

begin;

-- ---------------------------------------------------------------------------
-- 1. The audit row. One per inbound receipt, immutable, claim-by-insert.
-- ---------------------------------------------------------------------------
create table if not exists public.sms_shared_notice_replies (
  webhook_receipt_id uuid primary key
    references public.sms_webhook_receipts(id) on delete restrict,
  -- `suppressed` records that the reply was WITHHELD by the kill switch, canary
  -- or lane gate. Recording the decision is the point: silence with no row and
  -- silence with a `suppressed` row are different failures.
  egress_result text not null check (egress_result in ('twiml', 'suppressed')),
  response_body_sha256 text not null check (response_body_sha256 ~ '^[0-9a-f]{64}$'),
  created_at timestamptz not null default pg_catalog.now()
);

-- ---------------------------------------------------------------------------
-- 2. The claim.
--
-- Returns true to EXACTLY ONE caller per receipt. Everyone else -- concurrent
-- duplicate, provider retry -- gets false and must answer with empty TwiML.
-- ---------------------------------------------------------------------------
create or replace function public.record_sms_shared_notice_reply(
  p_webhook_receipt_id uuid,
  p_egress_result text,
  p_response_body_sha256 text
)
returns boolean
language plpgsql
security definer
set search_path = pg_catalog, pg_temp
set timezone to 'UTC'
as $$
declare
  v_receipt public.sms_webhook_receipts%rowtype;
  v_purpose text;
  v_result public.sms_shared_notice_replies%rowtype;
begin
  if p_webhook_receipt_id is null
     or p_egress_result not in ('twiml', 'suppressed')
     or p_response_body_sha256 is null
     or p_response_body_sha256 !~ '^[0-9a-f]{64}$' then
    raise exception 'SMS shared notice reply result is invalid' using errcode = '22023';
  end if;

  select r.* into v_receipt
    from public.sms_webhook_receipts r
   where r.id = p_webhook_receipt_id
   for share;

  -- `review` is admitted alongside `processed` on purpose: an unroutable
  -- shared-number message is exactly the case with no other answer, and
  -- refusing it here would leave the original silence in place.
  if v_receipt.id is null
     or v_receipt.webhook_kind <> 'inbound'
     or v_receipt.processing_state not in ('processed', 'review') then
    raise exception 'SMS shared notice reply is not bound to an inbound receipt'
      using errcode = '55000';
  end if;

  -- NEVER shadow a compliance acknowledgement. STOP/START/HELP already answer,
  -- and two Message verbs for one inbound would double-text the sender.
  if v_receipt.disposition is not null
     and v_receipt.disposition like 'keyword\_%' then
    raise exception 'SMS shared notice reply may not answer a compliance keyword'
      using errcode = '55000';
  end if;

  -- Only LGQ's own lanes. A contractor's dedicated number is a real two-way
  -- conversation and must never be auto-answered on their behalf.
  select s.purpose into v_purpose
    from public.sms_sender_numbers s
   where s.id = v_receipt.sender_number_id;
  if v_purpose is null or v_purpose not in ('lgq_shared', 'lgq_dispatch') then
    raise exception 'SMS shared notice reply is only for LGQ platform lanes'
      using errcode = '55000';
  end if;

  insert into public.sms_shared_notice_replies (
    webhook_receipt_id, egress_result, response_body_sha256
  ) values (
    p_webhook_receipt_id, p_egress_result, p_response_body_sha256
  ) on conflict (webhook_receipt_id) do nothing
  returning * into v_result;

  -- The first committed row wins. Anything else answers with empty TwiML.
  return v_result.webhook_receipt_id is not null;
end;
$$;

-- ---------------------------------------------------------------------------
-- 3. Least privilege. Same posture as the compliance audit: unreachable by
--    anon and authenticated, reached by the route only through the function.
-- ---------------------------------------------------------------------------
alter table public.sms_shared_notice_replies enable row level security;
alter table public.sms_shared_notice_replies force row level security;
-- No policy, deliberately: RLS on with no policy means anon and authenticated
-- read nothing, and the service-role client bypasses RLS.

revoke all on table public.sms_shared_notice_replies
  from public, anon, authenticated, service_role;
grant select on table public.sms_shared_notice_replies to service_role;

revoke all on function public.record_sms_shared_notice_reply(uuid, text, text)
  from public, anon, authenticated, service_role;
grant execute on function public.record_sms_shared_notice_reply(uuid, text, text)
  to service_role;

-- ---------------------------------------------------------------------------
-- 4. Post-conditions. Prove it, do not trust that the statements above did what
--    they read like.
-- ---------------------------------------------------------------------------
do $$
declare
  v_bad text;
begin
  if not exists (
    select 1 from pg_catalog.pg_proc p
      join pg_catalog.pg_namespace n on n.oid = p.pronamespace
     where n.nspname = 'public' and p.proname = 'record_sms_shared_notice_reply'
       and p.prosecdef
  ) then
    raise exception 'record_sms_shared_notice_reply is not security definer';
  end if;

  if not exists (
    select 1 from pg_catalog.pg_class c
      join pg_catalog.pg_namespace n on n.oid = c.relnamespace
     where n.nspname = 'public' and c.relname = 'sms_shared_notice_replies'
       and c.relrowsecurity and c.relforcerowsecurity
  ) then
    raise exception 'row level security is not forced on sms_shared_notice_replies';
  end if;

  select pg_catalog.string_agg(distinct g.grantee_name, ', ') into v_bad
  from (
    select pg_catalog.pg_get_userbyid(x.grantee) as grantee_name
      from pg_catalog.pg_class c
      join pg_catalog.pg_namespace n on n.oid = c.relnamespace
      cross join lateral pg_catalog.aclexplode(coalesce(c.relacl, '{}'::aclitem[])) x
     where n.nspname = 'public' and c.relname = 'sms_shared_notice_replies'
  ) g
  where g.grantee_name in ('anon', 'authenticated');
  if v_bad is not null then
    raise exception 'sms_shared_notice_replies is reachable by: %', v_bad;
  end if;
end $$;

commit;

-- Source: migrations/20260822220000_inbound_action_queue_admin_read.sql
-- Let the operations dashboard see the inbound SMS action queue.
--
-- WHAT WAS WRONG. /admin/messaging has been reporting "inbound SMS action queue
-- could not be read" since the queue shipped. loadMessagingOperationsHealth
-- reads three task tables with the service-role client:
--
--     sms_delivery_tasks          service_role: SELECT
--     payment_sms_producer_tasks  service_role: SELECT
--     sms_inbound_action_tasks    service_role: (nothing)   <- 42501
--
-- 20260821192000 revoked ALL on this table from every role and then granted
-- EXECUTE function by function, which is a stricter posture than either sibling
-- and was almost certainly deliberate. The observability code was nonetheless
-- written against direct table reads, so the page has been half-blind ever
-- since — honestly, it names what it could not read, but blind.
--
-- WHAT WAS NOT WRONG, and why this is a dashboard fix rather than an incident:
-- the rail itself never touches the table directly. The worker claims, applies,
-- completes and fails through SECURITY DEFINER functions, each already granted
-- EXECUTE to service_role. enqueue_sms_inbound_action_task has no grant because
-- it is a TRIGGER function, where EXECUTE is checked at CREATE TRIGGER time and
-- not at fire time. Nothing has been failing to process.
--
-- WHAT THIS DOES NOT OPEN. SELECT only, and only for service_role, which already
-- holds BYPASSRLS — so this grants no visibility that role could not obtain
-- through the functions it can already execute. Every WRITE stays RPC-only, and
-- anon and authenticated stay at nothing. The post-conditions below assert all
-- three, because the whole point of this file is that a missing grant is
-- invisible until something reads.

begin;

grant select on table public.sms_inbound_action_tasks to service_role;

-- ---------------------------------------------------------------------------
-- Post-conditions. The bug being fixed was a grant nobody checked, so check.
-- ---------------------------------------------------------------------------
do $$
declare
  v_oid oid := 'public.sms_inbound_action_tasks'::regclass;
begin
  if not pg_catalog.has_table_privilege('service_role', v_oid, 'select') then
    raise exception 'service_role still cannot read sms_inbound_action_tasks';
  end if;

  -- Mutation stays RPC-only. If this ever passes, the outbox has lost the
  -- property that a task can only move through its claim/apply/complete
  -- functions, and the queue's exactly-once guarantee goes with it.
  if pg_catalog.has_table_privilege('service_role', v_oid, 'insert')
     or pg_catalog.has_table_privilege('service_role', v_oid, 'update')
     or pg_catalog.has_table_privilege('service_role', v_oid, 'delete') then
    raise exception 'sms_inbound_action_tasks became writable outside its RPCs';
  end if;

  -- The tenant-facing roles gain nothing. This table carries every account's
  -- inbound traffic, and it has no RLS policy to fall back on.
  if pg_catalog.has_table_privilege('anon', v_oid, 'select')
     or pg_catalog.has_table_privilege('authenticated', v_oid, 'select') then
    raise exception 'sms_inbound_action_tasks is readable by a tenant role';
  end if;

  -- Unchanged, and load-bearing for the above: with RLS forced and no policy,
  -- a role without BYPASSRLS reads nothing even if it were granted SELECT.
  if not exists (
    select 1 from pg_catalog.pg_class c
      join pg_catalog.pg_namespace n on n.oid = c.relnamespace
     where n.nspname = 'public' and c.relname = 'sms_inbound_action_tasks'
       and c.relrowsecurity and c.relforcerowsecurity
  ) then
    raise exception 'row level security is no longer forced on sms_inbound_action_tasks';
  end if;
end $$;

commit;

-- Source: migrations/20260825133000_reconcile_shared_sender_and_registry_matching.sql
-- ===========================================================================
-- Reconcile LGQ shared number (+1 947-941-2323) and improve registry callback
-- matching across applications and platform sender numbers.
-- ===========================================================================

begin;

-- ---------------------------------------------------------------------------
-- 1. Reconcile LGQ shared sender (+1 947-941-2323) as assigned and active.
-- ---------------------------------------------------------------------------
insert into public.sms_sender_numbers (
  provider,
  e164_number,
  purpose,
  account_id,
  assignment_state,
  provisioning_status,
  inbound_ready,
  activated_at,
  updated_at,
  provider_brand_state,
  provider_campaign_state,
  provider_verified_at,
  provider_phone_verified_at,
  provider_sms_capable,
  inbound_request_method,
  inbound_message_handler
) values (
  'signalwire',
  '+19479412323',
  'lgq_shared',
  null,
  'assigned',
  'active',
  true,
  pg_catalog.now(),
  pg_catalog.now(),
  'complete',
  'complete',
  pg_catalog.now(),
  pg_catalog.now(),
  true,
  'POST',
  'laml_webhooks'
) on conflict (provider, e164_number) do update set
  purpose = excluded.purpose,
  assignment_state = excluded.assignment_state,
  provisioning_status = excluded.provisioning_status,
  inbound_ready = excluded.inbound_ready,
  activated_at = coalesce(public.sms_sender_numbers.activated_at, excluded.activated_at),
  suspended_at = null,
  provider_brand_state = coalesce(public.sms_sender_numbers.provider_brand_state, excluded.provider_brand_state),
  provider_campaign_state = coalesce(public.sms_sender_numbers.provider_campaign_state, excluded.provider_campaign_state),
  provider_verified_at = coalesce(public.sms_sender_numbers.provider_verified_at, excluded.provider_verified_at),
  provider_phone_verified_at = coalesce(public.sms_sender_numbers.provider_phone_verified_at, excluded.provider_phone_verified_at),
  provider_sms_capable = coalesce(public.sms_sender_numbers.provider_sms_capable, excluded.provider_sms_capable),
  inbound_request_method = coalesce(public.sms_sender_numbers.inbound_request_method, excluded.inbound_request_method),
  inbound_message_handler = coalesce(public.sms_sender_numbers.inbound_message_handler, excluded.inbound_message_handler),
  updated_at = pg_catalog.now();

-- ---------------------------------------------------------------------------
-- 2. Upgrade ingest_messaging_registry_callback to resolve callbacks against
--    both contractor applications and platform sender inventory.
-- ---------------------------------------------------------------------------
create or replace function public.ingest_messaging_registry_callback(
  p_receipt_key text,
  p_body_sha256 text,
  p_raw_body text,
  p_content_type text,
  p_request_method text,
  p_request_path text,
  p_request_headers jsonb,
  p_signature_header_name text,
  p_signature_header_value text,
  p_parsed jsonb,
  p_provider_order_id text,
  p_provider_assignment_id text,
  p_provider_campaign_id text,
  p_provider_phone_number text,
  p_provider_state text,
  p_normalized_state text,
  p_failure_code text,
  p_failure_detail text
)
returns table (
  callback_id uuid,
  inserted boolean,
  matched_application_id uuid,
  disposition text
)
language plpgsql
security definer
set search_path = pg_catalog, pg_temp
set timezone to 'UTC'
as $$
declare
  v_now timestamptz := pg_catalog.clock_timestamp();
  v_existing public.messaging_registry_callbacks%rowtype;
  v_application public.messaging_registration_applications%rowtype;
  v_sender public.sms_sender_numbers%rowtype;
  v_matched boolean := false;
  v_account uuid;
  v_status text;
  v_id uuid;
begin
  if p_receipt_key is null or pg_catalog.length(pg_catalog.btrim(p_receipt_key)) = 0
     or coalesce(p_body_sha256, '') !~ '^[0-9a-f]{64}$'
     or p_raw_body is null then
    raise exception 'registry callback input is invalid' using errcode = '22023';
  end if;

  select c.* into v_existing
    from public.messaging_registry_callbacks c
   where c.provider = 'signalwire' and c.receipt_key = p_receipt_key
   for update;

  if found then
    -- A replay must be byte-identical. Differing bytes under one receipt key
    -- means the key was built from something that does not identify the event.
    if v_existing.body_sha256 is distinct from p_body_sha256 then
      raise exception 'registry callback already received with different bytes'
        using errcode = '23505';
    end if;
    return query select v_existing.id, false, v_existing.application_id,
                        v_existing.processing_status;
    return;
  end if;

  -- 1. Try matching contractor application by order id
  if p_provider_order_id is not null then
    select a.* into v_application
      from public.messaging_registration_applications a
     where a.assignment_order_id = p_provider_order_id
     for update;
    v_matched := found;
  end if;

  -- 2. Try matching contractor application by phone number, assignment id, or campaign id if not matched by order
  if not v_matched then
    if p_provider_phone_number is not null then
      select a.* into v_application
        from public.messaging_registration_applications a
       where a.purchased_number = p_provider_phone_number
       order by a.created_at desc
       limit 1
       for update;
      v_matched := found;
    end if;

    if not v_matched and p_provider_assignment_id is not null then
      select a.* into v_application
        from public.messaging_registration_applications a
       where a.assignment_id = p_provider_assignment_id
       order by a.created_at desc
       limit 1
       for update;
      v_matched := found;
    end if;
  end if;

  if v_matched and v_application.id is not null then
    v_account := v_application.account_id;
    v_status  := 'received';
  else
    -- 3. Check for platform/shared senders in sms_sender_numbers
    select s.* into v_sender
      from public.sms_sender_numbers s
     where s.provider = 'signalwire'
       and (
         (p_provider_phone_number is not null and s.e164_number = p_provider_phone_number)
         or (p_provider_assignment_id is not null and s.assignment_id = p_provider_assignment_id)
         or (p_provider_campaign_id is not null and s.campaign_id = p_provider_campaign_id and s.purpose in ('lgq_shared', 'lgq_dispatch'))
       )
     order by s.created_at desc
     limit 1
     for update;

    if found then
      v_account := v_sender.account_id;
      v_status  := 'processed';
      v_application.id := v_sender.provisioning_application_id;

      -- Update assignment state on sender number
      if p_normalized_state = 'complete' then
        update public.sms_sender_numbers
           set assignment_state = 'assigned',
               last_verified_at = v_now,
               updated_at = v_now
         where id = v_sender.id;
      elsif p_normalized_state = 'failed' then
        update public.sms_sender_numbers
           set assignment_state = 'failed',
               updated_at = v_now
         where id = v_sender.id;
      end if;
    else
      -- A callback naming an identifier LGQ cannot resolve is still stored.
      v_application.id := null;
      v_account := null;
      v_status  := 'unmatched';
    end if;
  end if;

  insert into public.messaging_registry_callbacks (
    provider, receipt_key, body_sha256, raw_body, content_type,
    request_method, request_path, request_headers,
    signature_header_name, signature_header_value, parsed,
    provider_order_id, provider_assignment_id, provider_campaign_id,
    provider_phone_number, provider_state, normalized_state,
    failure_code, failure_detail,
    application_id, account_id, processing_status, processed_at
  ) values (
    'signalwire', p_receipt_key, p_body_sha256, p_raw_body, p_content_type,
    p_request_method, p_request_path, coalesce(p_request_headers, '{}'::jsonb),
    p_signature_header_name, p_signature_header_value, p_parsed,
    p_provider_order_id, p_provider_assignment_id, p_provider_campaign_id,
    p_provider_phone_number, p_provider_state, p_normalized_state,
    p_failure_code, p_failure_detail,
    v_application.id, v_account, v_status,
    case when v_status <> 'received' then v_now else null end
  )
  returning id into v_id;

  if v_id is null then
    raise exception 'registry callback was not stored' using errcode = '55000';
  end if;

  return query select v_id, true, v_application.id, v_status;
end;
$$;

commit;

-- Source: migrations/20260825140000_voice_calls_workspace_and_workflows.sql
-- Expand voice_calls with granular provider outcomes, provisional admission tracking,
-- recording metadata, and introduce dedicated workflow and note tables for the Voice Calls workspace.

begin;

-- 1. Expand outcome constraints and add operational fields on public.voice_calls
alter table public.voice_calls
  drop constraint if exists voice_calls_outcome_check;

alter table public.voice_calls
  add constraint voice_calls_outcome_check
  check (
    outcome in (
      'in_progress',
      'ai_handled',
      'transfer_attempted',
      'transferred_and_answered',
      'caller_abandoned',
      'no_input',
      'voicemail_fallback',
      'provider_failure',
      'completed',
      'transferred',
      'voicemail',
      'abandoned',
      'failed',
      'unknown'
    )
  );

alter table public.voice_calls
  add column if not exists outcome_source text
    check (outcome_source is null or outcome_source in ('provisional_admission', 'swml_post_prompt', 'reconciliation', 'manual', 'legacy')),
  add column if not exists outcome_observed_at timestamptz,
  add column if not exists is_provisional boolean not null default false,
  add column if not exists recording_status text not null default 'none'
    check (recording_status in ('none', 'pending', 'ready', 'failed', 'expired')),
  add column if not exists recording_storage_path text,
  add column if not exists recording_duration_seconds integer
    check (recording_duration_seconds is null or recording_duration_seconds >= 0),
  add column if not exists recording_size_bytes bigint
    check (recording_size_bytes is null or recording_size_bytes >= 0),
  add column if not exists recording_content_type text,
  add column if not exists recording_captured_at timestamptz;

-- 2. Upgrade voice_calls RLS policy to office_can(account_id, 'leads.read')
create or replace function public.voice_transcript_retention_interval(
  p_account_id uuid
)
returns interval
language plpgsql
stable
security definer
set search_path = pg_catalog, pg_temp
set timezone to 'UTC'
as $$
declare
  v_days integer;
begin
  -- Block anonymous execution oracle
  if auth.role() = 'anon' then
    return pg_catalog.make_interval(days => 30);
  end if;

  -- Ensure authenticated callers only resolve custom retention for accounts they belong to
  if auth.role() = 'authenticated' then
    if not (public.is_owner(p_account_id) or exists (
      select 1 from public.account_memberships
      where account_id = p_account_id and user_id = auth.uid() and active = true
    )) then
      return pg_catalog.make_interval(days => 30);
    end if;
  end if;

  select public.voice_history_retention_days(w.feature_limits)
    into v_days
    from public.workspace_entitlements w
   where w.account_id = p_account_id;

  return pg_catalog.make_interval(days => coalesce(v_days, 30));
end;
$$;

revoke execute on function public.voice_transcript_retention_interval(uuid) from public, anon;
grant execute on function public.voice_transcript_retention_interval(uuid) to authenticated, service_role;

drop policy if exists voice_calls_owner_read on public.voice_calls;
drop policy if exists voice_calls_office_read on public.voice_calls;

create policy voice_calls_office_read
  on public.voice_calls
  for select
  to authenticated
  using (
    public.office_can(account_id, 'leads.read')
    and (
      started_at is null
      or started_at >= now() - public.voice_transcript_retention_interval(account_id)
    )
  );

-- Indexes for fast workspace queue queries
create index if not exists voice_calls_account_outcome_started_idx
  on public.voice_calls (account_id, outcome, started_at desc nulls last);

create index if not exists voice_calls_lead_idx
  on public.voice_calls (lead_id)
  where lead_id is not null;

-- 3. Create public.voice_call_workflows table
create table if not exists public.voice_call_workflows (
  call_id uuid primary key references public.voice_calls(id) on delete cascade,
  account_id uuid not null references public.accounts(id) on delete cascade,
  disposition text not null default 'unreviewed'
    check (disposition in ('unreviewed', 'needs_callback', 'callback_scheduled', 'contacted', 'qualified', 'converted', 'not_a_fit', 'spam', 'resolved')),
  urgency text not null default 'normal'
    check (urgency in ('normal', 'urgent', 'emergency')),
  assigned_user_id uuid references auth.users(id) on delete set null,
  callback_due_at timestamptz,
  callback_completed_at timestamptz,
  reviewed_at timestamptz,
  reviewed_by uuid references auth.users(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists voice_call_workflows_account_disp_idx
  on public.voice_call_workflows (account_id, disposition, callback_due_at);

create index if not exists voice_call_workflows_assigned_user_idx
  on public.voice_call_workflows (account_id, assigned_user_id)
  where assigned_user_id is not null;

alter table public.voice_call_workflows enable row level security;
revoke all on table public.voice_call_workflows from public, anon, authenticated;
grant select, insert, update on table public.voice_call_workflows to authenticated;

create policy voice_call_workflows_read
  on public.voice_call_workflows
  for select
  to authenticated
  using (public.office_can(account_id, 'leads.read'));

create policy voice_call_workflows_insert
  on public.voice_call_workflows
  for insert
  to authenticated
  with check (public.office_can(account_id, 'leads.write'));

create policy voice_call_workflows_update
  on public.voice_call_workflows
  for update
  to authenticated
  using (public.office_can(account_id, 'leads.write'))
  with check (public.office_can(account_id, 'leads.write'));

drop trigger if exists touch_voice_call_workflows_updated_at_trigger on public.voice_call_workflows;
create trigger touch_voice_call_workflows_updated_at_trigger
  before update on public.voice_call_workflows
  for each row execute function public.touch_voice_settings_updated_at();

-- 4. Create public.voice_call_notes table
create table if not exists public.voice_call_notes (
  id uuid primary key default gen_random_uuid(),
  call_id uuid not null references public.voice_calls(id) on delete cascade,
  account_id uuid not null references public.accounts(id) on delete cascade,
  author_user_id uuid references auth.users(id) on delete set null,
  author_name text not null,
  note text not null check (pg_catalog.length(pg_catalog.btrim(note)) > 0 and pg_catalog.length(note) <= 4000),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists voice_call_notes_call_created_idx
  on public.voice_call_notes (call_id, created_at desc);

create index if not exists voice_call_notes_account_idx
  on public.voice_call_notes (account_id, created_at desc);

alter table public.voice_call_notes enable row level security;
revoke all on table public.voice_call_notes from public, anon, authenticated;
grant select, insert, update on table public.voice_call_notes to authenticated;

create policy voice_call_notes_read
  on public.voice_call_notes
  for select
  to authenticated
  using (public.office_can(account_id, 'leads.read'));

create policy voice_call_notes_insert
  on public.voice_call_notes
  for insert
  to authenticated
  with check (public.office_can(account_id, 'leads.write'));

create policy voice_call_notes_update
  on public.voice_call_notes
  for update
  to authenticated
  using (public.office_can(account_id, 'leads.write'))
  with check (public.office_can(account_id, 'leads.write'));

drop trigger if exists touch_voice_call_notes_updated_at_trigger on public.voice_call_notes;
create trigger touch_voice_call_notes_updated_at_trigger
  before update on public.voice_call_notes
  for each row execute function public.touch_voice_settings_updated_at();

-- 5. Safety verification assertion block
do $$
declare
  v_writable text;
begin
  if not exists (
    select 1 from pg_catalog.pg_class c
    join pg_catalog.pg_namespace n on n.oid = c.relnamespace
    where n.nspname = 'public' and c.relname = 'voice_call_workflows' and c.relrowsecurity
  ) then
    raise exception 'row level security is not enabled on voice_call_workflows';
  end if;

  if not exists (
    select 1 from pg_catalog.pg_class c
    join pg_catalog.pg_namespace n on n.oid = c.relnamespace
    where n.nspname = 'public' and c.relname = 'voice_call_notes' and c.relrowsecurity
  ) then
    raise exception 'row level security is not enabled on voice_call_notes';
  end if;

  select string_agg(grantee || ':' || privilege_type, ', ')
    into v_writable
    from information_schema.role_table_grants
   where table_schema = 'public'
     and table_name in ('voice_call_workflows', 'voice_call_notes')
     and privilege_type = 'TRUNCATE'
     and grantee in ('public', 'anon', 'authenticated');

  if v_writable is not null then
    raise exception 'voice tables have dangerous truncate grants: %', v_writable;
  end if;
end $$;

commit;

-- Source: migrations/20260829120000_sms_owner_field_intake_rpc.sql
-- Atomic execution RPC for AI Voice & Text-to-Job Field Intake
--
-- Why this is a single RPC:
-- 1. All domain mutations (notes, costs, tasks, leads), feed audits,
--    and confirmation SMS enqueues happen inside one ACID transaction.
-- 2. Prevents partial failure where a database record is modified but
--    confirmation or auditing fails, avoiding duplicate actions on retry.
-- 3. Field notes are strictly written to job_feed with visibility = 'internal',
--    preserving customer-facing jobs.scope integrity.

create or replace function public.apply_owner_field_action(
  p_task_id uuid,
  p_claim_token uuid,
  p_intent text,
  p_params jsonb,
  p_transcript text,
  p_confirmation_text text
)
returns jsonb
language plpgsql
security definer
set search_path = pg_catalog, pg_temp
set timezone to 'UTC'
as $$
declare
  v_task public.sms_inbound_action_tasks%rowtype;
  v_receipt public.sms_webhook_receipts%rowtype;
  v_now timestamptz := pg_catalog.clock_timestamp();
  v_job public.jobs%rowtype;
  v_job_id uuid;
  v_target_id uuid;
  v_lead_id uuid;
  v_cost_id uuid;
  v_task_id_out uuid;
  v_amount numeric(12,2);
  v_cost_type text;
  v_label text;
  v_note text;
  v_task_title text;
  v_client_name text;
  v_client_phone text;
  v_address text;
  v_feed_kind text;
  v_sms_event_id uuid;
  v_outcome jsonb;
begin
  -- 1. Claim verification and locking
  select t.* into v_task
    from public.sms_inbound_action_tasks t
   where t.id = p_task_id
   for update;

  if v_task.id is null
     or v_task.task_state <> 'processing'
     or v_task.claim_token is distinct from p_claim_token
     or v_task.lease_expires_at <= v_now then
    raise exception 'Inbound action claim is not active' using errcode = '55000';
  end if;

  if v_task.effect_applied_at is not null then
    return v_task.outcome;
  end if;

  -- 2. Receipt and sender validation
  select r.* into strict v_receipt
    from public.sms_webhook_receipts r
   where r.id = v_task.webhook_receipt_id;

  if v_receipt.account_id is distinct from v_task.account_id
     or v_receipt.disposition <> 'routed' then
    raise exception 'Inbound action task binding is invalid' using errcode = '23514';
  end if;

  -- 3. Affirmative owner consent re-validation
  if not exists (
    select 1
      from public.sms_consent c
      join public.sms_consent_scopes scope
        on scope.account_id = c.account_id
       and scope.phone_number = c.phone_number
       and scope.consent_scope = 'owner'
     where c.account_id = v_task.account_id
       and c.phone_number = v_receipt.from_number
       and c.status = 'opted_in'
       and c.opted_out_at is null
  ) then
    raise exception 'Owner consent is missing or revoked' using errcode = '28000';
  end if;

  -- 4. Advisory lock on contractor account
  perform pg_catalog.pg_advisory_xact_lock(
    public.sms_inbound_recipient_lock_key(v_task.account_id, v_receipt.from_number)
  );

  v_feed_kind := case
    when coalesce(pg_catalog.array_length(v_receipt.media_urls, 1), 0) > 0
      then 'field_voice_note'
    else 'field_sms_update'
  end;

  -- 5. Intent Execution
  if p_intent = 'append_internal_note' then
    v_job_id := (p_params->>'job_id')::uuid;
    v_note := pg_catalog.btrim(coalesce(p_params->>'note', ''));

    select j.* into strict v_job
      from public.jobs j
     where j.id = v_job_id
       and j.account_id = v_task.account_id
     for update;

    v_target_id := v_job.id;

    -- Insert internal note into job_feed (strictly keeping jobs.scope clean)
    insert into public.job_feed (
      account_id, job_id, kind, title, body, visibility, author, meta
    ) values (
      v_task.account_id, v_job.id, v_feed_kind, 'Field Note',
      v_note, 'internal', 'Owner (Field Voice/SMS)',
      jsonb_build_object(
        'transcript', p_transcript,
        'receipt_id', v_receipt.id,
        'from_number', v_receipt.from_number
      )
    );

  elsif p_intent = 'log_cost' then
    v_job_id := (p_params->>'job_id')::uuid;
    v_amount := (p_params->>'amount')::numeric;
    v_label := coalesce(nullif(pg_catalog.btrim(p_params->>'label'), ''), 'Material cost');
    v_cost_type := coalesce(nullif(pg_catalog.btrim(p_params->>'cost_type'), ''), 'material');

    select j.* into strict v_job
      from public.jobs j
     where j.id = v_job_id
       and j.account_id = v_task.account_id
     for update;

    v_target_id := v_job.id;

    insert into public.costs (
      account_id, job_id, type, category, description, amount
    ) values (
      v_task.account_id, v_job.id, v_cost_type::cost_type,
      v_cost_type, v_label, v_amount
    ) returning id into v_cost_id;

    insert into public.job_feed (
      account_id, job_id, kind, title, body, amount, visibility, author, meta
    ) values (
      v_task.account_id, v_job.id, 'cost_added',
      'Cost logged: ' || v_label,
      v_label || ' ($' || v_amount::text || ')',
      v_amount, 'internal', 'Owner (Field Voice/SMS)',
      jsonb_build_object(
        'cost_id', v_cost_id,
        'transcript', p_transcript,
        'receipt_id', v_receipt.id
      )
    );

  elsif p_intent = 'add_job_task' then
    v_job_id := (p_params->>'job_id')::uuid;
    v_task_title := coalesce(nullif(pg_catalog.btrim(p_params->>'title'), ''), 'Follow up');

    select j.* into strict v_job
      from public.jobs j
     where j.id = v_job_id
       and j.account_id = v_task.account_id
     for update;

    v_target_id := v_job.id;

    insert into public.job_tasks (
      account_id, job_id, title, done
    ) values (
      v_task.account_id, v_job.id, v_task_title, false
    ) returning id into v_task_id_out;

    insert into public.job_feed (
      account_id, job_id, kind, title, body, visibility, author, meta
    ) values (
      v_task.account_id, v_job.id, v_feed_kind,
      'Task added: ' || v_task_title,
      v_task_title, 'internal', 'Owner (Field Voice/SMS)',
      jsonb_build_object(
        'task_id', v_task_id_out,
        'transcript', p_transcript,
        'receipt_id', v_receipt.id
      )
    );

  elsif p_intent = 'create_lead' then
    v_client_name := coalesce(nullif(pg_catalog.btrim(p_params->>'client_name'), ''), 'New Prospect');
    v_client_phone := nullif(pg_catalog.btrim(p_params->>'client_phone'), '');
    v_address := nullif(pg_catalog.btrim(p_params->>'address'), '');
    v_note := coalesce(nullif(pg_catalog.btrim(p_params->>'notes'), ''), p_transcript);

    insert into public.leads (
      account_id, source, status, name, phone, address, message
    ) values (
      v_task.account_id, 'manual'::lead_source, 'new'::lead_status,
      v_client_name, v_client_phone, v_address, v_note
    ) returning id into v_lead_id;

    v_target_id := v_lead_id;

  elsif p_intent in ('report_ambiguity', 'no_action') then
    -- Ambiguity / no-action creates no domain mutation
    v_target_id := null;
  else
    raise exception 'Unrecognized field intent: %', p_intent using errcode = '22023';
  end if;

  -- 6. Enqueue confirmation SMS if confirmation text is present
  if p_confirmation_text is not null and pg_catalog.length(pg_catalog.btrim(p_confirmation_text)) > 0 then
    select e.sms_event_id into v_sms_event_id
      from public.enqueue_sms_delivery(
        p_account_id => v_task.account_id,
        p_phone_number => v_receipt.from_number,
        p_body => pg_catalog.btrim(p_confirmation_text),
        p_message_kind => 'owner-field-confirm',
        p_billing_category => 'owner_alert'::public.sms_billing_category,
        p_sender_purpose => 'lgq_shared'::public.sms_sender_purpose,
        p_context => 'owner'::public.sms_delivery_context,
        p_event_type => 'owner_field_confirm',
        p_idempotency_key => 'owner-field-confirm:' || v_receipt.id::text,
        p_payment_id => null::uuid,
        p_crew_id => null::uuid,
        p_sender_number_id => v_task.sender_number_id
      ) e;
  end if;

  -- 7. Complete task atomically
  v_outcome := jsonb_build_object(
    'intent', p_intent,
    'target_id', v_target_id,
    'confirmation_text', p_confirmation_text,
    'sms_event_id', v_sms_event_id,
    'applied_at', v_now
  );

  update public.sms_inbound_action_tasks
     set task_state = 'completed',
         effect_applied_at = v_now,
         completed_at = v_now,
         outcome = v_outcome,
         updated_at = v_now
   where id = v_task.id;

  return v_outcome;
end;
$$;

revoke all on function public.apply_owner_field_action(uuid,uuid,text,jsonb,text,text) from public, anon, authenticated;
grant execute on function public.apply_owner_field_action(uuid,uuid,text,jsonb,text,text) to service_role;

-- Source: migrations/20260830120000_crew_field_intake.sql
-- Migration: 20260830120000_crew_field_intake.sql
-- Enables Crew & Subcontractor SMS & Voice Field Intake on the shared company line.
--
-- Key features:
-- 1. Updates `ingest_sms_inbound_webhook` so `lgq_shared` routes inbound texts
--    from active crew phones with `consent_scope = 'crew'` in addition to the owner.
-- 2. Expands `apply_owner_field_action` into a unified caller-aware field intake RPC:
--    - Authenticates whether caller is Owner or an active Crew Member.
--    - Appropriately attributes job_feed timeline entries, costs, and tasks with
--      crew member's full name (e.g. 'Crew: Mike D. (Field SMS)').
--    - Enforces safety boundaries (crew can log notes, costs, and tasks; administrative
--      actions like lead creation and job rescheduling remain owner-only).
--    - Supports `complete_job_task` for marking checklist items done from the field.
--    - Sends deterministic GSM-7 confirmation SMS back to the sender.

begin;

create or replace function public.ingest_sms_inbound_webhook(
  p_provider text,
  p_provider_event_id text,
  p_receipt_key text,
  p_body_sha256 text,
  p_content_type text,
  p_request_url text,
  p_from_number text,
  p_to_number text,
  p_message_body text,
  p_media_urls text[],
  p_keyword text
)
returns table (
  ingress_disposition text,
  webhook_receipt_id uuid,
  routed_account_id uuid,
  routed_sender_number_id uuid,
  routed_sender_purpose text
)
language plpgsql
security definer
set search_path = pg_catalog, pg_temp
set timezone to 'UTC'
as $$
declare
  v_now timestamptz := pg_catalog.clock_timestamp();
  v_receipt public.sms_webhook_receipts%rowtype;
  v_existing public.sms_webhook_receipts%rowtype;
  v_sender public.sms_sender_numbers%rowtype;
  v_message_id uuid;
  v_reason text;
  v_existing_consent boolean;
  v_routed_account_id uuid;
  v_routed_account_count bigint := 0;
begin
  if p_provider not in ('twilio', 'signalwire')
     or p_provider_event_id is null
     or pg_catalog.length(p_provider_event_id) not between 1 and 255
     or p_receipt_key is null
     or pg_catalog.length(p_receipt_key) not between 1 and 700
     or p_body_sha256 is null
     or p_body_sha256 !~ '^[0-9a-f]{64}$'
     or p_from_number is null
     or p_from_number !~ '^\+[1-9][0-9]{7,14}$'
     or p_to_number is null
     or p_to_number !~ '^\+[1-9][0-9]{7,14}$'
     or p_keyword not in ('stop', 'start', 'help', 'other')
     or pg_catalog.length(coalesce(p_message_body, '')) > 5000
     or coalesce(pg_catalog.array_length(p_media_urls, 1), 0) > 10 then
    raise exception 'SMS inbound webhook arguments are invalid'
      using errcode = '22023';
  end if;

  insert into public.sms_webhook_receipts (
    provider, webhook_kind, receipt_key, provider_event_id, body_sha256,
    content_type, request_url, from_number, to_number
  ) values (
    p_provider, 'inbound', p_receipt_key, p_provider_event_id,
    p_body_sha256, pg_catalog.left(p_content_type, 255),
    pg_catalog.left(p_request_url, 2000), p_from_number, p_to_number
  )
  on conflict (provider, webhook_kind, receipt_key) do nothing
  returning * into v_receipt;

  if v_receipt.id is null then
    select r.* into v_existing
      from public.sms_webhook_receipts r
     where r.provider = p_provider
       and r.webhook_kind = 'inbound'
       and r.receipt_key = p_receipt_key
     for update;
    if v_existing.provider_event_id is distinct from p_provider_event_id
       or v_existing.body_sha256 is distinct from p_body_sha256
       or v_existing.from_number is distinct from p_from_number
       or v_existing.to_number is distinct from p_to_number
       or v_existing.content_type is distinct from pg_catalog.left(p_content_type, 255)
       or v_existing.request_url is distinct from pg_catalog.left(p_request_url, 2000) then
      raise exception 'SMS inbound receipt key was replayed with different immutable evidence'
        using errcode = 'P5120';
    end if;
    return query
    select 'duplicate'::text, v_existing.id, v_existing.account_id,
           v_existing.sender_number_id, s.purpose
      from public.sms_webhook_receipts r
      left join public.sms_sender_numbers s on s.id = r.sender_number_id
     where r.id = v_existing.id;
    return;
  end if;

  select s.* into v_sender
    from public.sms_sender_numbers s
   where s.provider = p_provider
     and s.e164_number = p_to_number
     and s.provisioning_status = 'active'
     and s.assignment_state = 'assigned'
     and s.inbound_ready
     and s.suspended_at is null
   for share;

  if v_sender.id is null then
    insert into public.sms_operator_review_items (
      webhook_receipt_id, reason, severity, provider, provider_event_id,
      from_number, to_number, message_body, media_urls
    ) values (
      v_receipt.id, 'unknown_destination', 'critical', p_provider,
      p_provider_event_id, p_from_number, p_to_number,
      pg_catalog.left(p_message_body, 5000), p_media_urls
    );
    update public.sms_webhook_receipts
       set processing_state = 'review', disposition = 'unknown_destination',
           processed_at = v_now
     where id = v_receipt.id;
    return query select 'review'::text, v_receipt.id, null::uuid,
                        null::uuid, null::text;
    return;
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'sms-sender-consent:' || v_sender.id::text || ':' || p_from_number,
      20260821
    )
  );

  v_routed_account_id := v_sender.account_id;

  if p_keyword in ('stop', 'start', 'help')
     and v_sender.purpose = 'lgq_shared'
     and v_routed_account_id is null then
    select pg_catalog.count(*),
           case when pg_catalog.count(*) = 1
             then (pg_catalog.array_agg(candidate.account_id))[1]
             else null::uuid
           end
      into v_routed_account_count, v_routed_account_id
      from (
        select distinct e.account_id
          from public.sms_events e
         where e.sender_number_id = v_sender.id
           and e.phone_number = p_from_number
           and e.account_id is not null
           and e.status in ('sent', 'delivered')
           and e.provider_id is not null
      ) candidate;
  end if;

  if p_keyword in ('stop', 'start')
     and v_sender.purpose = 'lgq_dispatch'
     and v_routed_account_id is null then
    select pg_catalog.count(*),
           case when pg_catalog.count(*) = 1
             then (pg_catalog.array_agg(candidate.account_id))[1]
             else null::uuid
           end
      into v_routed_account_count, v_routed_account_id
      from (
        select distinct c.account_id
          from public.sms_consent c
          join public.sms_consent_scopes scope
            on scope.account_id = c.account_id
           and scope.phone_number = c.phone_number
           and scope.consent_scope = 'crew'
         where c.phone_number = p_from_number
           and c.consented_at is not null
           and exists (
             select 1
               from public.crew member
              where member.account_id = c.account_id
                and member.active
                and member.deleted_at is null
                and public.sms_normalize_recipient_phone(member.phone)
                      = p_from_number
           )
      ) candidate;
  end if;

  -- Platform lanes: route ordinary inbound texts and voice memos.
  -- lgq_shared routes from BOTH owner (account.alert_phone) AND active crew members on public.crew.
  -- lgq_dispatch routes from active crew members.
  if p_keyword = 'other'
     and v_sender.purpose in ('lgq_shared', 'lgq_dispatch') then
    select pg_catalog.count(*),
           case when pg_catalog.count(*) = 1
             then (pg_catalog.array_agg(candidate.account_id))[1]
             else null::uuid
           end
      into v_routed_account_count, v_routed_account_id
      from (
        select distinct c.account_id
          from public.sms_consent c
          join public.sms_consent_scopes scope
            on scope.account_id = c.account_id
           and scope.phone_number = c.phone_number
         where c.phone_number = p_from_number
           and c.status = 'opted_in'
           and c.consented_at is not null
           and c.opted_out_at is null
           and (
             (
               v_sender.purpose = 'lgq_shared'
               and (
                 (
                   scope.consent_scope = 'owner'
                   and exists (
                     select 1
                       from public.accounts account
                      where account.id = c.account_id
                        and account.high_value_sms_enabled is true
                        and public.sms_normalize_recipient_phone(account.alert_phone)
                              = p_from_number
                   )
                 )
                 or
                 (
                   scope.consent_scope = 'crew'
                   and exists (
                     select 1
                       from public.crew member
                      where member.account_id = c.account_id
                        and member.active
                        and member.deleted_at is null
                        and public.sms_normalize_recipient_phone(member.phone)
                              = p_from_number
                   )
                 )
               )
             )
             or
             (
               v_sender.purpose = 'lgq_dispatch'
               and scope.consent_scope = 'crew'
               and exists (
                 select 1
                   from public.crew member
                  where member.account_id = c.account_id
                    and member.active
                    and member.deleted_at is null
                    and public.sms_normalize_recipient_phone(member.phone)
                          = p_from_number
               )
             )
           )
           and not exists (
             select 1
               from public.sms_sender_keyword_preferences preference
              where preference.sender_number_id = v_sender.id
                and preference.phone_number = p_from_number
                and preference.status = 'opted_out'
                and preference.opted_out_at is not null
           )
      ) candidate;
  end if;

  update public.sms_webhook_receipts
     set sender_number_id = v_sender.id,
         account_id = v_routed_account_id
   where id = v_receipt.id;

  if p_keyword = 'start'
     and v_sender.purpose = 'lgq_dispatch'
     and v_routed_account_id is null then
    insert into public.sms_sender_keyword_preferences (
      sender_number_id, phone_number, status, source, opted_out_at, updated_at
    ) values (
      v_sender.id, p_from_number, 'opted_out', 'inbound_start', v_now, v_now
    )
    on conflict (sender_number_id, phone_number) do update
      set status = 'opted_out',
          source = 'inbound_start',
          opted_out_at = coalesce(
            public.sms_sender_keyword_preferences.opted_out_at,
            excluded.opted_out_at
          ),
          updated_at = excluded.updated_at;

    v_reason := case
      when v_routed_account_count > 1 then 'ambiguous_destination'
      else 'shared_destination_unroutable'
    end;
    insert into public.sms_operator_review_items (
      webhook_receipt_id, reason, severity, provider, sender_number_id,
      provider_event_id, from_number, to_number, message_body, media_urls
    ) values (
      v_receipt.id, v_reason,
      case when v_reason = 'ambiguous_destination' then 'critical' else 'warning' end,
      p_provider, v_sender.id, p_provider_event_id, p_from_number, p_to_number,
      pg_catalog.left(p_message_body, 5000), p_media_urls
    );
    update public.sms_webhook_receipts
       set account_id = null, processing_state = 'review',
           disposition = v_reason, processed_at = v_now
     where id = v_receipt.id;
    return query select 'review'::text, v_receipt.id, null::uuid,
                        v_sender.id, v_sender.purpose;
    return;
  end if;

  if p_keyword in ('stop', 'start') then
    insert into public.sms_sender_keyword_preferences (
      sender_number_id, phone_number, status, source, opted_out_at, updated_at
    ) values (
      v_sender.id, p_from_number,
      case when p_keyword = 'stop' then 'opted_out' else 'opted_in' end,
      case when p_keyword = 'stop' then 'inbound_stop' else 'inbound_start' end,
      case when p_keyword = 'stop' then v_now else null end,
      v_now
    )
    on conflict (sender_number_id, phone_number) do update
      set status = excluded.status,
          source = excluded.source,
          opted_out_at = excluded.opted_out_at,
          updated_at = excluded.updated_at;

    if v_routed_account_id is not null then
      select pg_catalog.count(*) > 0 into v_existing_consent
        from public.sms_consent c
       where c.account_id = v_routed_account_id
         and c.phone_number = p_from_number;

      insert into public.sms_consent (
        account_id, phone_number, status, source, consented_at,
        opted_out_at, disclosure_version, updated_at
      ) values (
        v_routed_account_id, p_from_number,
        case when p_keyword = 'stop' then 'opted_out' else 'opted_in' end,
        case when p_keyword = 'stop' then 'inbound_stop' else 'inbound_start' end,
        case when p_keyword = 'start' then v_now else null end,
        case when p_keyword = 'stop' then v_now else null end,
        null, v_now
      )
      on conflict (account_id, phone_number) do update
        set status = excluded.status,
            source = excluded.source,
            consented_at = case
              when excluded.status = 'opted_in' then excluded.consented_at
              else public.sms_consent.consented_at
            end,
            opted_out_at = case
              when excluded.status = 'opted_out' then coalesce(public.sms_consent.opted_out_at, excluded.opted_out_at)
              else null
            end,
            updated_at = excluded.updated_at;

      -- Restored from the live body: a START from a number with no prior
      -- consent row is an opt-in with no recorded prior consent, and an
      -- operator should see it. The account_events row below is an addition,
      -- not a replacement -- an earlier draft swapped one evidence surface for
      -- the other and lost this review item.
      if p_keyword = 'start' and not v_existing_consent then
        insert into public.sms_operator_review_items (
          webhook_receipt_id, reason, severity, provider, account_id,
          sender_number_id, provider_event_id, from_number, to_number,
          message_body
        ) values (
          v_receipt.id, 'restart_without_consent', 'info', p_provider,
          v_routed_account_id, v_sender.id, p_provider_event_id,
          p_from_number, p_to_number, pg_catalog.left(p_message_body, 5000)
        );
      end if;

      insert into public.account_events (
        account_id, kind, summary, meta
      ) values (
        v_routed_account_id, 'compliance_toggled',
        'SMS compliance preference updated via inbound ' || p_keyword,
        jsonb_build_object(
          'source', 'inbound_sms',
          'provider', p_provider,
          'keyword', p_keyword,
          'phone_number', p_from_number,
          'sender_number_id', v_sender.id,
          'webhook_receipt_id', v_receipt.id
        )
      );
    elsif v_sender.purpose = 'lgq_dispatch' then
      -- Restored from the live body. STOP remains safe without guessing an
      -- account: the exact sender is blocked above, the account ledger is
      -- untouched, and review work records whether current roster authority
      -- was absent or cross-account ambiguous.
      v_reason := case
        when v_routed_account_count > 1 then 'ambiguous_destination'
        else 'shared_destination_unroutable'
      end;
      insert into public.sms_operator_review_items (
        webhook_receipt_id, reason, severity, provider, sender_number_id,
        provider_event_id, from_number, to_number, message_body, media_urls
      ) values (
        v_receipt.id, v_reason,
        case when v_reason = 'ambiguous_destination' then 'critical' else 'warning' end,
        p_provider, v_sender.id, p_provider_event_id, p_from_number, p_to_number,
        pg_catalog.left(p_message_body, 5000), p_media_urls
      );
    end if;

    update public.sms_webhook_receipts
       set processing_state = 'processed', disposition = 'keyword_' || p_keyword,
           processed_at = v_now
     where id = v_receipt.id;
    return query select ('keyword_' || p_keyword)::text, v_receipt.id,
                        v_routed_account_id, v_sender.id, v_sender.purpose;
    return;
  end if;

  if p_keyword = 'help' then
    update public.sms_webhook_receipts
       set processing_state = 'processed', disposition = 'keyword_help',
           processed_at = v_now
     where id = v_receipt.id;
    return query select 'keyword_help'::text, v_receipt.id,
                        v_routed_account_id, v_sender.id, v_sender.purpose;
    return;
  end if;

  if v_routed_account_id is null then
    v_reason := case
      when v_routed_account_count > 1 then 'ambiguous_destination'
      else 'shared_destination_unroutable'
    end;
    insert into public.sms_operator_review_items (
      webhook_receipt_id, reason, severity, provider, sender_number_id,
      provider_event_id, from_number, to_number, message_body, media_urls
    ) values (
      v_receipt.id, v_reason,
      case when v_reason = 'ambiguous_destination' then 'critical' else 'warning' end,
      p_provider, v_sender.id, p_provider_event_id, p_from_number, p_to_number,
      pg_catalog.left(p_message_body, 5000), p_media_urls
    );
    update public.sms_webhook_receipts
       set processing_state = 'review', disposition = v_reason,
           processed_at = v_now
     where id = v_receipt.id;
    return query select 'review'::text, v_receipt.id, null::uuid,
                        v_sender.id, v_sender.purpose;
    return;
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    public.sms_inbound_recipient_lock_key(v_routed_account_id, p_from_number)
  );

  -- Column list matches the LIVE table exactly. An earlier draft wrote
  -- sender_purpose and raw_payload here; neither column exists on
  -- public.sms_messages, and plpgsql only syntax-parses bodies at CREATE, so it
  -- applied cleanly and would have thrown 42703 on the first routed inbound
  -- text -- aborting the whole webhook transaction, rolling back the
  -- sms_webhook_receipts dedupe row with it, and putting the provider into an
  -- infinite redelivery loop on the one lane that works today. The payload
  -- provenance those columns wanted already lives on the receipt row.
  insert into public.sms_messages (
    account_id, phone_number, direction, body, provider_id, media_urls,
    provider, sender_number_id, read_at, created_at
  ) values (
    v_routed_account_id, p_from_number, 'inbound',
    coalesce(p_message_body, ''), p_provider_event_id,
    p_media_urls, p_provider, v_sender.id, null, v_now
  ) returning id into v_message_id;

  update public.sms_webhook_receipts
     set processing_state = 'processed', disposition = 'routed',
         account_id = v_routed_account_id, sms_message_id = v_message_id,
         processed_at = v_now
   where id = v_receipt.id;

  return query select 'routed'::text, v_receipt.id, v_routed_account_id,
                      v_sender.id, v_sender.purpose;
end;
$$;

revoke all on function public.ingest_sms_inbound_webhook(text,text,text,text,text,text,text,text,text,text[],text) from public, anon, authenticated;
grant execute on function public.ingest_sms_inbound_webhook(text,text,text,text,text,text,text,text,text,text[],text) to service_role;


-- Unified Caller-Aware Field Intake RPC (Supports Owner and Crew Callers)
create or replace function public.apply_owner_field_action(
  p_task_id uuid,
  p_claim_token uuid,
  p_intent text,
  p_params jsonb,
  p_transcript text,
  p_confirmation_text text
)
returns jsonb
language plpgsql
security definer
set search_path = pg_catalog, pg_temp
set timezone to 'UTC'
as $$
declare
  v_task public.sms_inbound_action_tasks%rowtype;
  v_receipt public.sms_webhook_receipts%rowtype;
  v_now timestamptz := pg_catalog.clock_timestamp();
  v_job public.jobs%rowtype;
  v_job_id uuid;
  v_target_id uuid;
  v_lead_id uuid;
  v_cost_id uuid;
  v_task_id_out uuid;
  v_amount numeric(12,2);
  v_cost_type text;
  v_label text;
  v_note text;
  v_task_title text;
  v_client_name text;
  v_client_phone text;
  v_address text;
  v_feed_kind text;
  v_sms_event_id uuid;
  v_outcome jsonb;
  v_is_owner boolean := false;
  v_crew public.crew%rowtype;
  v_author text;
  v_unsupported boolean := false;
begin
  -- 1. Claim verification and locking
  select t.* into v_task
    from public.sms_inbound_action_tasks t
   where t.id = p_task_id
   for update;

  if v_task.id is null
     or v_task.task_state <> 'processing'
     or v_task.claim_token is distinct from p_claim_token
     or v_task.lease_expires_at <= v_now then
    raise exception 'Inbound action claim is not active' using errcode = '55000';
  end if;

  if v_task.effect_applied_at is not null then
    return v_task.outcome;
  end if;

  -- 2. Receipt and sender validation
  select r.* into strict v_receipt
    from public.sms_webhook_receipts r
   where r.id = v_task.webhook_receipt_id;

  if v_receipt.account_id is distinct from v_task.account_id
     or v_receipt.disposition <> 'routed' then
    raise exception 'Inbound action task binding is invalid' using errcode = '23514';
  end if;

  -- 3. Caller identity & affirmative consent re-validation
  -- Check if caller is Owner
  select true into v_is_owner
    from public.sms_consent c
    join public.sms_consent_scopes scope
      on scope.account_id = c.account_id
     and scope.phone_number = c.phone_number
     and scope.consent_scope = 'owner'
   where c.account_id = v_task.account_id
     and c.phone_number = v_receipt.from_number
     and c.status = 'opted_in'
     and c.opted_out_at is null;

  -- If not owner, check if caller is an active Crew Member
  if not coalesce(v_is_owner, false) then
    select cr.* into v_crew
      from public.crew cr
      join public.sms_consent c
        on c.account_id = cr.account_id
       and c.phone_number = v_receipt.from_number
      join public.sms_consent_scopes scope
        on scope.account_id = c.account_id
       and scope.phone_number = c.phone_number
       and scope.consent_scope = 'crew'
     where cr.account_id = v_task.account_id
       and cr.active
       and cr.deleted_at is null
       and public.sms_normalize_recipient_phone(cr.phone) = v_receipt.from_number
       and c.status = 'opted_in'
       and c.opted_out_at is null
     limit 1;
  end if;

  if not coalesce(v_is_owner, false) and v_crew.id is null then
    raise exception 'Sender consent is missing or revoked' using errcode = '28000';
  end if;

  -- Enforce intent authorization: administrative intents are strictly owner-only.
  -- Only create_lead is listed: it is the sole owner-only intent this rail
  -- actually implements. reschedule_job/assign_crew/update_client fall through
  -- to the graceful unsupported branch below, which answers BOTH roles with an
  -- honest "can't do that by text yet" -- raising 42501 for crew here would
  -- retry the task into the dead-letter queue while the sender hears nothing,
  -- the exact failure mode that branch exists to prevent. Reinstate them in
  -- this guard the day they are implemented.
  if not coalesce(v_is_owner, false) and p_intent = 'create_lead' then
    raise exception 'Intent % is restricted to account owner', p_intent using errcode = '42501';
  end if;

  -- 4. Advisory lock on contractor account
  perform pg_catalog.pg_advisory_xact_lock(
    public.sms_inbound_recipient_lock_key(v_task.account_id, v_receipt.from_number)
  );

  -- Media provenance lives on sms_messages, NOT on the receipt --
  -- sms_webhook_receipts has no media_urls column, and because this runs
  -- unconditionally before intent dispatch, reading v_receipt.media_urls made
  -- EVERY field action throw 42703 at first call.
  select case
    when coalesce(pg_catalog.array_length(m.media_urls, 1), 0) > 0
      then 'field_voice_note'
    else 'field_sms_update'
  end into v_feed_kind
    from public.sms_messages m
   where m.id = v_task.sms_message_id;
  v_feed_kind := coalesce(v_feed_kind, 'field_sms_update');

  v_author := case
    when coalesce(v_is_owner, false)
      then 'Owner (Field ' || case when v_feed_kind = 'field_voice_note' then 'Voice' else 'SMS' end || ')'
    else 'Crew: ' || coalesce(v_crew.name, 'Field Worker') || ' (Field ' || case when v_feed_kind = 'field_voice_note' then 'Voice' else 'SMS' end || ')'
  end;

  -- 5. Intent Execution
  if p_intent = 'append_internal_note' then
    v_job_id := (p_params->>'job_id')::uuid;
    v_note := pg_catalog.btrim(coalesce(p_params->>'note', ''));

    select j.* into strict v_job
      from public.jobs j
     where j.id = v_job_id
       and j.account_id = v_task.account_id
     for update;

    v_target_id := v_job.id;

    -- Insert internal note into job_feed (strictly keeping jobs.scope clean)
    insert into public.job_feed (
      account_id, job_id, kind, title, body, visibility, author, meta
    ) values (
      v_task.account_id, v_job.id, v_feed_kind, 'Field Note',
      v_note, 'internal', v_author,
      jsonb_build_object(
        'transcript', p_transcript,
        'receipt_id', v_receipt.id,
        'from_number', v_receipt.from_number,
        'crew_id', v_crew.id
      )
    );

  elsif p_intent = 'log_cost' then
    v_job_id := (p_params->>'job_id')::uuid;
    v_amount := (p_params->>'amount')::numeric;
    v_label := coalesce(nullif(pg_catalog.btrim(p_params->>'label'), ''), 'Material cost');
    v_cost_type := coalesce(nullif(pg_catalog.btrim(p_params->>'cost_type'), ''), 'material');

    select j.* into strict v_job
      from public.jobs j
     where j.id = v_job_id
       and j.account_id = v_task.account_id
     for update;

    v_target_id := v_job.id;

    insert into public.costs (
      account_id, job_id, type, category, description, amount
    ) values (
      -- schema-qualified: search_path is pinned to pg_catalog, so an
      -- unqualified ::cost_type resolves to nothing and throws 42704 at the
      -- first log_cost action (runtime, not CREATE time)
      v_task.account_id, v_job.id, v_cost_type::public.cost_type,
      v_cost_type, v_label, v_amount
    ) returning id into v_cost_id;

    insert into public.job_feed (
      account_id, job_id, kind, title, body, amount, visibility, author, meta
    ) values (
      v_task.account_id, v_job.id, 'cost_added',
      'Cost logged: ' || v_label,
      v_label || ' ($' || v_amount::text || ')',
      v_amount, 'internal', v_author,
      jsonb_build_object(
        'cost_id', v_cost_id,
        'transcript', p_transcript,
        'receipt_id', v_receipt.id,
        'crew_id', v_crew.id
      )
    );

  elsif p_intent = 'add_job_task' then
    v_job_id := (p_params->>'job_id')::uuid;
    v_task_title := coalesce(nullif(pg_catalog.btrim(p_params->>'title'), ''), 'Follow up');

    select j.* into strict v_job
      from public.jobs j
     where j.id = v_job_id
       and j.account_id = v_task.account_id
     for update;

    v_target_id := v_job.id;

    insert into public.job_tasks (
      account_id, job_id, title, done
    ) values (
      v_task.account_id, v_job.id, v_task_title, false
    ) returning id into v_task_id_out;

    insert into public.job_feed (
      account_id, job_id, kind, title, body, visibility, author, meta
    ) values (
      v_task.account_id, v_job.id, v_feed_kind,
      'Task added: ' || v_task_title,
      v_task_title, 'internal', v_author,
      jsonb_build_object(
        'task_id', v_task_id_out,
        'transcript', p_transcript,
        'receipt_id', v_receipt.id,
        'crew_id', v_crew.id
      )
    );

  elsif p_intent = 'complete_job_task' then
    v_job_id := (p_params->>'job_id')::uuid;
    v_task_title := coalesce(nullif(pg_catalog.btrim(p_params->>'title'), ''), '');

    select j.* into strict v_job
      from public.jobs j
     where j.id = v_job_id
       and j.account_id = v_task.account_id
     for update;

    v_target_id := v_job.id;

    if v_task_title <> '' then
      -- job_tasks has no updated_at column; completion is recorded on
      -- done_at/done_by (both nullable, done_by text).
      update public.job_tasks
         set done = true, done_at = v_now, done_by = v_author
       where account_id = v_task.account_id
         and job_id = v_job.id
         and not done
         and title ilike ('%' || v_task_title || '%');
    end if;

    insert into public.job_feed (
      account_id, job_id, kind, title, body, visibility, author, meta
    ) values (
      v_task.account_id, v_job.id, v_feed_kind,
      'Task completed: ' || coalesce(nullif(v_task_title, ''), 'Checklist item'),
      coalesce(nullif(v_task_title, ''), 'Marked task completed'),
      'internal', v_author,
      jsonb_build_object(
        'transcript', p_transcript,
        'receipt_id', v_receipt.id,
        'crew_id', v_crew.id
      )
    );

  elsif p_intent = 'create_lead' then
    v_client_name := coalesce(nullif(pg_catalog.btrim(p_params->>'client_name'), ''), 'New Prospect');
    v_client_phone := nullif(pg_catalog.btrim(p_params->>'client_phone'), '');
    v_address := nullif(pg_catalog.btrim(p_params->>'address'), '');
    v_note := coalesce(nullif(pg_catalog.btrim(p_params->>'notes'), ''), p_transcript);

    insert into public.leads (
      account_id, source, status, name, phone, address, message
    ) values (
      -- schema-qualified for the same pinned-search_path reason as cost_type
      v_task.account_id, 'manual'::public.lead_source, 'new'::public.lead_status,
      v_client_name, v_client_phone, v_address, v_note
    ) returning id into v_lead_id;

    v_target_id := v_lead_id;

  elsif p_intent in ('report_ambiguity', 'no_action') then
    v_target_id := null;

  elsif p_intent in ('reschedule_job', 'update_client', 'assign_crew',
                     'add_quote_line_item', 'send_client_quote_link') then
    -- Known worker intents this rail does not implement yet. The worker's tool
    -- list offers all five, and the owner-only guard above authorises three of
    -- them, so raising here would be self-contradictory -- and an exception
    -- retries the task 8 times into the dead-letter queue while the sender
    -- hears nothing. Completing with an honest reply is the only ending that
    -- neither lies nor goes silent: no domain write happens, and the
    -- confirmation the worker composed (which claims success) is REPLACED
    -- below with the truth. Implementing these for real is feature work that
    -- belongs to the worker's owner, not a side effect of this migration.
    v_target_id := null;
    v_unsupported := true;

  else
    raise exception 'Unrecognized field intent: %', p_intent using errcode = '22023';
  end if;

  if v_unsupported then
    p_confirmation_text :=
      'Sorry - I can''t make that change by text yet. Please use the dashboard, '
      || 'or reply with a note and I''ll save it to the job.';
  end if;

  -- 6. Enqueue confirmation SMS back to the sender
  if p_confirmation_text is not null and pg_catalog.length(pg_catalog.btrim(p_confirmation_text)) > 0 then
    select e.sms_event_id into v_sms_event_id
      from public.enqueue_sms_delivery(
        p_account_id => v_task.account_id,
        p_phone_number => v_receipt.from_number,
        p_body => pg_catalog.btrim(p_confirmation_text),
        p_message_kind => case when v_crew.id is not null then 'crew-field-confirm' else 'owner-field-confirm' end,
        -- Bare text literals: enqueue_sms_delivery declares these parameters as
        -- plain text, and the enum types an earlier draft cast to
        -- (public.sms_billing_category / sms_sender_purpose / sms_delivery_context)
        -- do not exist in this database -- the casts resolve at first execution,
        -- not at CREATE, so they applied cleanly and threw 42704 on the first
        -- field action.
        p_billing_category => case when v_crew.id is not null then 'crew_message' else 'owner_alert' end,
        p_sender_purpose => 'lgq_shared',
        p_context => case when v_crew.id is not null then 'subcontractor' else 'owner' end,
        p_event_type => case when v_crew.id is not null then 'crew_field_confirm' else 'owner_field_confirm' end,
        p_idempotency_key => 'field-confirm:' || v_receipt.id::text,
        p_payment_id => null::uuid,
        p_crew_id => v_crew.id,
        p_sender_number_id => v_task.sender_number_id
      ) e;
  end if;

  -- 7. Complete task atomically
  v_outcome := jsonb_build_object(
    'intent', p_intent,
    'unsupported_intent', v_unsupported,
    'target_id', v_target_id,
    'confirmation_text', p_confirmation_text,
    'sms_event_id', v_sms_event_id,
    'applied_at', v_now,
    'crew_id', v_crew.id,
    'is_owner', coalesce(v_is_owner, false)
  );

  -- claim_token and lease_expires_at MUST be cleared here:
  -- sms_inbound_action_tasks_claim_shape requires them null for every state
  -- except 'processing', so leaving them set makes every successful action
  -- abort with 23514 at its final statement, rolling back the work it just did.
  update public.sms_inbound_action_tasks
     set task_state = 'completed',
         claim_token = null,
         lease_expires_at = null,
         effect_applied_at = v_now,
         completed_at = v_now,
         outcome = v_outcome,
         updated_at = v_now
   where id = v_task.id;

  return v_outcome;
end;
$$;

revoke all on function public.apply_owner_field_action(uuid,uuid,text,jsonb,text,text) from public, anon, authenticated;
grant execute on function public.apply_owner_field_action(uuid,uuid,text,jsonb,text,text) to service_role;

commit;

-- Source: migrations/20260831190000_atomic_delayed_sms_delivery.sql
-- -------------------------------------------------------------------------
-- Atomic Delayed SMS Delivery Support
-- Allows producers to pass p_available_at timestamptz default null to
-- enqueue_sms_delivery, ensuring delayed messages (e.g. TCPA quiet hours)
-- are inserted directly with their future available_at timestamp in a single
-- atomic database operation.
-- -------------------------------------------------------------------------

create or replace function public.enqueue_sms_delivery(
  p_account_id uuid,
  p_phone_number text,
  p_body text,
  p_message_kind text,
  p_billing_category text,
  p_sender_purpose text,
  p_context text,
  p_event_type text,
  p_idempotency_key text,
  p_payment_id uuid default null,
  p_crew_id uuid default null,
  p_sender_number_id uuid default null,
  p_available_at timestamptz default null
)
returns table (
  sms_event_id uuid,
  task_state text,
  created boolean
)
language plpgsql
security definer
set search_path = pg_catalog, pg_temp
set timezone to 'UTC'
as $$
declare
  v_now timestamptz := pg_catalog.clock_timestamp();
  v_event public.sms_events%rowtype;
  v_inserted boolean := false;
  v_available_at timestamptz := coalesce(p_available_at, v_now);
begin
  if p_account_id is null then
    raise exception 'SMS delivery requires an account'
      using errcode = '22023';
  end if;
  if p_phone_number is null or p_phone_number !~ '^\+[1-9][0-9]{7,14}$' then
    raise exception 'SMS destination must be E.164'
      using errcode = '22023';
  end if;
  if p_body is null or pg_catalog.length(p_body) not between 1 and 5000 then
    raise exception 'SMS body length is invalid'
      using errcode = '22023';
  end if;
  if p_message_kind is null or p_message_kind !~ '^[a-z][a-z0-9_-]{2,99}$' then
    raise exception 'SMS message kind is invalid'
      using errcode = '22023';
  end if;
  if p_billing_category is null or p_billing_category not in (
    'customer_message', 'crew_message', 'owner_alert',
    'payment_message', 'verification'
  ) then
    raise exception 'SMS billing category is invalid'
      using errcode = '22023';
  end if;
  if p_sender_purpose is null or p_sender_purpose not in (
    'lgq_shared', 'lgq_dispatch', 'contractor_dedicated'
  ) then
    raise exception 'SMS sender purpose is invalid'
      using errcode = '22023';
  end if;
  if p_context is null or p_context !~ '^[a-z][a-z0-9_]{2,63}$'
     or p_event_type is null or p_event_type !~ '^[a-z][a-z0-9_]{2,99}$' then
    raise exception 'SMS context or event type is invalid'
      using errcode = '22023';
  end if;
  if p_idempotency_key is null
     or p_idempotency_key !~ '^[A-Za-z0-9][A-Za-z0-9:._/-]{2,199}$' then
    raise exception 'SMS idempotency key is invalid'
      using errcode = '22023';
  end if;
  if p_context = 'payment' and p_payment_id is null
     or p_context in ('crew', 'subcontractor') and p_crew_id is null
     or p_context not in (
       'payment', 'crew', 'subcontractor', 'owner',
       'customer', 'automation', 'platform'
     ) then
    raise exception 'SMS context target is invalid'
      using errcode = '22023';
  end if;

  insert into public.sms_events (
    account_id, payment_id, event_type, phone_number, status, body,
    context, crew_id, provider, sender_number_id, idempotency_key,
    message_kind, billing_category, sender_purpose, queued_at, updated_at
  ) values (
    p_account_id, p_payment_id, p_event_type, p_phone_number, 'queued', p_body,
    p_context, p_crew_id, null, p_sender_number_id, p_idempotency_key,
    p_message_kind, p_billing_category, p_sender_purpose, v_now, v_now
  )
  on conflict (idempotency_key) where idempotency_key is not null do nothing
  returning * into v_event;

  if found then
    v_inserted := true;
    insert into public.sms_delivery_tasks (
      sms_event_id, task_state, available_at, created_at, updated_at
    ) values (
      v_event.id, 'queued', v_available_at, v_now, v_now
    );
  else
    select e.* into v_event
      from public.sms_events e
     where e.idempotency_key = p_idempotency_key
     for update;
    if not found then
      raise exception 'SMS idempotency conflict cannot be resolved'
        using errcode = '40001';
    end if;
    if v_event.account_id is distinct from p_account_id
       or v_event.phone_number is distinct from p_phone_number
       or v_event.body is distinct from p_body
       or v_event.message_kind is distinct from p_message_kind
       or v_event.billing_category is distinct from p_billing_category
       or v_event.sender_purpose is distinct from p_sender_purpose
       or v_event.context is distinct from p_context
       or v_event.event_type is distinct from p_event_type
       or v_event.payment_id is distinct from p_payment_id
       or v_event.crew_id is distinct from p_crew_id
       or v_event.sender_number_id is distinct from p_sender_number_id then
      raise exception 'SMS idempotency key was reused with a different payload'
        using errcode = '42200';
    end if;
  end if;

  return query
  select
    v_event.id as sms_event_id,
    'queued'::text as task_state,
    v_inserted as created;
end;
$$;

revoke all on function public.enqueue_sms_delivery(uuid,text,text,text,text,text,text,text,text,uuid,uuid,uuid,timestamptz) from public, anon;
grant execute on function public.enqueue_sms_delivery(uuid,text,text,text,text,text,text,text,text,uuid,uuid,uuid,timestamptz) to authenticated, service_role;

-- Source: migrations/20260901070000_crew_sms_consent_evidence.sql
-- Migration: 20260901070000_crew_sms_consent_evidence.sql
-- Description: Audited SMS consent evidence ledger for crew members with RLS and explicit grants.

begin;

-- ============================================================================
-- 1. Create sms_consent_evidence table
-- ============================================================================

create table if not exists public.sms_consent_evidence (
  id uuid primary key default gen_random_uuid(),
  account_id uuid not null,
  phone_number text not null
    check (phone_number ~ '^\+[1-9][0-9]{7,14}$'),
  consent_scope text not null default 'crew'
    check (consent_scope in ('customer', 'crew', 'owner')),
  disclosure_version text not null
    check (
      pg_catalog.length(disclosure_version) between 1 and 100
      and disclosure_version !~ '[[:cntrl:]]'
    ),
  disclosure_text text not null,
  disclosure_hash text not null
    check (pg_catalog.length(disclosure_hash) = 64),
  consented_by_user_id uuid,
  consented_at timestamptz not null default pg_catalog.now(),
  source text not null default 'crew_roster'
    check (
      pg_catalog.length(source) between 1 and 100
      and source !~ '[[:cntrl:]]'
    ),
  source_page text not null default '/dashboard/crew'
    check (
      pg_catalog.length(source_page) between 1 and 200
      and source_page !~ '[[:cntrl:]]'
    ),
  crew_id uuid,
  created_at timestamptz not null default pg_catalog.now()
);

create index if not exists idx_sms_consent_evidence_account_phone
  on public.sms_consent_evidence (account_id, phone_number);

create index if not exists idx_sms_consent_evidence_crew_id
  on public.sms_consent_evidence (crew_id)
  where crew_id is not null;

create index if not exists idx_sms_consent_evidence_account_created
  on public.sms_consent_evidence (account_id, created_at desc);

-- ============================================================================
-- 2. Enable and force RLS on sms_consent_evidence
-- ============================================================================

alter table public.sms_consent_evidence enable row level security;
alter table public.sms_consent_evidence force row level security;

drop policy if exists sms_consent_evidence_owner_read on public.sms_consent_evidence;
create policy sms_consent_evidence_owner_read on public.sms_consent_evidence
  for select
  using ( is_owner(account_id) );

-- ============================================================================
-- 3. Explicit table-level privileges (Supabase 2026 posture)
-- ============================================================================

revoke all on table public.sms_consent_evidence from anon, public;
grant select on table public.sms_consent_evidence to authenticated;
grant all on table public.sms_consent_evidence to service_role;

-- ============================================================================
-- 4. Update establish_sms_consent_scope_from_source to handle crew_roster
-- ============================================================================

create or replace function public.establish_sms_consent_scope_from_source()
returns trigger
language plpgsql
security definer
set search_path = pg_catalog, pg_temp
set timezone to 'UTC'
as $$
declare
  v_scope text;
begin
  if new.status <> 'opted_in' or new.consented_at is null then
    return new;
  end if;
  v_scope := case
    when new.source in (
      'payment_request', 'lead_quote_visit', 'lead_quote_visit_options',
      'client_job_dashboard', 'lead_decline', 'job_update',
      'review_request', 'arrival_time_changed', 'reschedule_offer',
      'estimate_offer', 'schedule_request', 'lead_verification_request',
      'portal_link_request', 'missed_call_text_back', 'authenticated_inbound'
    ) then 'customer'
    when new.source in ('crew_added', 'subcontractor_added', 'crew_roster') then 'crew'
    when new.source = 'owner_alerts' then 'owner'
    else null
  end;
  if v_scope is not null then
    insert into public.sms_consent_scopes (
      account_id, phone_number, consent_scope, evidence_source, established_at
    ) values (
      new.account_id, new.phone_number, v_scope, new.source,
      coalesce(new.consented_at, pg_catalog.clock_timestamp())
    ) on conflict (account_id, phone_number, consent_scope) do nothing;
  end if;
  return new;
end;
$$;

commit;

-- Source: migrations/20260903172223_owner_shared_field_command_routing.sql
-- Keep LGQ platform-lane traffic out of the contractor's customer inbox.
--
-- The transcript row remains durable and keeps every receipt/task foreign key
-- intact. Visibility is derived at the sms_messages table boundary instead of
-- being trusted to each producer: inbound webhook rows, delivery mirrors, and
-- future writers all get the same answer from the authenticated sender record.

begin;

alter table public.sms_messages
  add column if not exists inbox_visible boolean default true;

alter table public.sms_messages
  alter column inbox_visible set default true;

-- Existing rows predate the derived column. Reconcile every row so a partially
-- applied deployment is repaired too: LGQ shared/dispatch rows are platform
-- operations, while a dedicated or legacy/null sender remains customer inbox
-- traffic. This changes presentation only; no transcript is deleted or unbound.
update public.sms_messages m
   set inbox_visible = not exists (
     select 1
       from public.sms_sender_numbers s
      where s.id = m.sender_number_id
        and s.purpose in ('lgq_shared', 'lgq_dispatch')
   )
 where m.inbox_visible is distinct from not exists (
     select 1
       from public.sms_sender_numbers s
      where s.id = m.sender_number_id
        and s.purpose in ('lgq_shared', 'lgq_dispatch')
   );

alter table public.sms_messages
  alter column inbox_visible set not null;

create or replace function public.derive_sms_message_inbox_visibility()
returns trigger
language plpgsql
security definer
set search_path = pg_catalog, pg_temp
as $$
declare
  v_sender_purpose text;
begin
  if new.sender_number_id is null then
    new.inbox_visible := true;
    return new;
  end if;

  select s.purpose
    into v_sender_purpose
    from public.sms_sender_numbers s
   where s.id = new.sender_number_id;

  -- A missing sender row will fail the existing FK after BEFORE triggers run.
  -- Keep the derivation fail-open for legacy/null identity; only an exact
  -- platform purpose is allowed to hide a customer-inbox row.
  new.inbox_visible := coalesce(
    v_sender_purpose not in ('lgq_shared', 'lgq_dispatch'),
    true
  );
  return new;
end;
$$;

-- The existing provider-identity trigger is named
-- sms_messages_provider_identity_guard. PostgreSQL runs same-event triggers in
-- name order, so it hydrates sender_number_id from a deterministic sms_event
-- before this visibility guard derives the value. Including inbox_visible in
-- the UPDATE columns also prevents privileged writers from overriding the
-- derived invariant directly; read_at-only inbox updates do not invoke it.
drop trigger if exists sms_messages_visibility_from_sender_guard
  on public.sms_messages;
create trigger sms_messages_visibility_from_sender_guard
before insert or update of sender_number_id, sms_event_id, inbox_visible
on public.sms_messages
for each row execute function public.derive_sms_message_inbox_visibility();

-- PostgreSQL ORs permissive policies. The historic FOR ALL policy therefore
-- bypassed a visibility predicate added only to SELECT, and also let office
-- users update/delete hidden platform-lane transcripts. Replace every legacy
-- policy shape with command-specific policies at the table boundary.
alter table public.sms_messages enable row level security;

drop policy if exists sms_messages_owner on public.sms_messages;
drop policy if exists sms_messages_all on public.sms_messages;
drop policy if exists sms_messages_select on public.sms_messages;
drop policy if exists sms_messages_modify on public.sms_messages;
drop policy if exists sms_messages_insert on public.sms_messages;
drop policy if exists sms_messages_update on public.sms_messages;
drop policy if exists sms_messages_delete on public.sms_messages;

create policy sms_messages_select on public.sms_messages
  for select
  using (
    inbox_visible = true
    and public.office_can(account_id, 'messages.read')
  );

create policy sms_messages_insert on public.sms_messages
  for insert
  with check (public.office_can(account_id, 'messages.send'));

create policy sms_messages_update on public.sms_messages
  for update
  using (
    inbox_visible = true
    and public.office_can(account_id, 'messages.send')
  )
  with check (
    inbox_visible = true
    and public.office_can(account_id, 'messages.send')
  );

create policy sms_messages_delete on public.sms_messages
  for delete
  using (
    inbox_visible = true
    and public.office_can(account_id, 'messages.send')
  );

-- Match the two customer-inbox access paths: recent conversation rows and the
-- unread badge. Existing broad indexes remain available to audit/worker paths.
create index if not exists sms_messages_visible_recent_idx
  on public.sms_messages (account_id, created_at desc)
  where inbox_visible = true;

create index if not exists sms_messages_visible_unread_idx
  on public.sms_messages (account_id)
  where inbox_visible = true
    and direction = 'inbound'
    and read_at is null;

-- Field intake may include authenticated MMS downloads plus one model call.
-- The generic inbound worker leases claims for two minutes, which is suitable
-- for its SQL-only reply parser but too short for bounded multimodal work. Give
-- the exact live claim a six-minute lease before any provider call so the next
-- one-minute cron cannot reclaim it while the first worker is still running.
create or replace function public.extend_sms_inbound_action_field_lease(
  p_task_id uuid,
  p_claim_token uuid
)
returns boolean
language plpgsql
security definer
set search_path = pg_catalog, pg_temp
set timezone to 'UTC'
as $$
declare
  v_now timestamptz := pg_catalog.clock_timestamp();
begin
  update public.sms_inbound_action_tasks
     set lease_expires_at = greatest(
           lease_expires_at,
           v_now + interval '6 minutes'
         ),
         updated_at = v_now
   where id = p_task_id
     and task_state = 'processing'
     and claim_token is not distinct from p_claim_token
     and lease_expires_at > v_now;
  return found;
end;
$$;

-- Final authorization boundary for the fresh shared-number field-intake rail.
-- The model is an untrusted parser: authorization is re-established from the
-- immutable receipt/task bindings and live lifecycle rows immediately before
-- the existing atomic action mutates domain data. Crew callers may only
-- finalize a deterministic no_action response until their model context and
-- every job-targeting action are assignment-scoped end to end.
create or replace function public.apply_authorized_sms_field_action(
  p_task_id uuid,
  p_claim_token uuid,
  p_intent text,
  p_params jsonb,
  p_transcript text,
  p_confirmation_text text
)
returns jsonb
language plpgsql
security definer
set search_path = pg_catalog, pg_temp
set timezone to 'UTC'
as $$
declare
  v_task public.sms_inbound_action_tasks%rowtype;
  v_receipt public.sms_webhook_receipts%rowtype;
  v_message public.sms_messages%rowtype;
  v_sender public.sms_sender_numbers%rowtype;
  v_account public.accounts%rowtype;
  v_crew public.crew%rowtype;
  v_consent public.sms_consent%rowtype;
  v_sender_preference public.sms_sender_keyword_preferences%rowtype;
  v_now timestamptz := pg_catalog.clock_timestamp();
  v_has_caller_scope boolean := false;
  v_is_owner boolean := false;
  v_crew_match_count integer := 0;
  v_required_scope text;
  v_cost_amount numeric;
  v_cost_type text;
begin
  -- Match the legacy applier's first lock so the wrapper and every retry use a
  -- single task-first order. Re-locking this row inside the delegated function
  -- is harmless within the same transaction.
  select t.* into v_task
    from public.sms_inbound_action_tasks t
   where t.id = p_task_id
   for update;

  if v_task.id is null
     or v_task.task_state <> 'processing'
     or v_task.claim_token is distinct from p_claim_token
     or v_task.lease_expires_at <= v_now then
    raise exception 'Inbound action claim is not active' using errcode = '55000';
  end if;

  -- A retry after the mutation but before queue completion is idempotent. It
  -- returns the already-authorized result and can never apply a second effect.
  if v_task.effect_applied_at is not null then
    return v_task.outcome;
  end if;

  select r.* into v_receipt
    from public.sms_webhook_receipts r
   where r.id = v_task.webhook_receipt_id
   for share;

  if v_receipt.id is null
     or v_receipt.webhook_kind <> 'inbound'
     or v_receipt.processing_state <> 'processed'
     or v_receipt.disposition <> 'routed'
     or v_receipt.account_id is distinct from v_task.account_id
     or v_receipt.sender_number_id is distinct from v_task.sender_number_id
     or v_receipt.sms_message_id is distinct from v_task.sms_message_id
     or v_receipt.from_number is null then
    raise exception 'Inbound action task binding is invalid' using errcode = '23514';
  end if;

  select m.* into v_message
    from public.sms_messages m
   where m.id = v_task.sms_message_id
     and m.id = v_receipt.sms_message_id
     and m.account_id = v_task.account_id
     and m.sender_number_id = v_task.sender_number_id
     and m.provider = v_receipt.provider
     and m.provider_id = v_receipt.provider_event_id
     and m.phone_number = v_receipt.from_number
     and m.direction = 'inbound'
   for share;

  if v_message.id is null then
    raise exception 'Inbound action message binding is invalid' using errcode = '23514';
  end if;

  -- STOP/START routing already uses this exact sender/contact key. Take it
  -- before the account/recipient lock everywhere so the two rails cannot form a
  -- lock-order cycle, including when no preference row exists yet.
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'sms-sender-consent:' || v_task.sender_number_id::text || ':' || v_receipt.from_number,
      20260821
    )
  );
  perform pg_catalog.pg_advisory_xact_lock(
    public.sms_inbound_recipient_lock_key(v_task.account_id, v_receipt.from_number)
  );

  -- FOR SHARE is deliberate: concurrent suspension, transfer, alert-phone
  -- change, or consent revocation must serialize before/after this action.
  select s.* into v_sender
    from public.sms_sender_numbers s
   where s.id = v_task.sender_number_id
     and s.id = v_receipt.sender_number_id
     and s.provider = v_receipt.provider
     and s.e164_number = v_receipt.to_number
     and s.purpose = 'lgq_shared'
     and s.account_id is null
     and s.provisioning_status = 'active'
     and s.assignment_state = 'assigned'
     and s.inbound_ready
     and s.activated_at is not null
     and s.suspended_at is null
   for share;

  if v_sender.id is null then
    raise exception 'Shared SMS sender is no longer active' using errcode = '55000';
  end if;

  select a.* into v_account
    from public.accounts a
   where a.id = v_task.account_id
     and a.suspended_at is null
   for share;

  if v_account.id is null then
    raise exception 'Field intake account is no longer active' using errcode = '28000';
  end if;

  v_is_owner := v_account.high_value_sms_enabled is true
    and public.sms_normalize_recipient_phone(v_account.alert_phone) = v_receipt.from_number;

  if v_is_owner then
    v_required_scope := 'owner';
  else
    -- Lock every matching live identity, then require exactly one. This avoids
    -- LIMIT 1 attribution when a reused phone is present on duplicate rows.
    for v_crew in
      select cr.*
        from public.crew cr
       where cr.account_id = v_task.account_id
         and cr.active
         and cr.deleted_at is null
         and cr.access_revoked_at is null
         and public.sms_normalize_recipient_phone(cr.phone) = v_receipt.from_number
       order by cr.id
       for share
    loop
      v_crew_match_count := v_crew_match_count + 1;
    end loop;

    if v_crew_match_count <> 1 then
      raise exception 'Field intake sender identity is missing or ambiguous' using errcode = '28000';
    end if;
    if p_intent <> 'no_action' then
      raise exception 'Crew field commands are not enabled' using errcode = '42501';
    end if;
    v_required_scope := 'crew';
  end if;

  select c.* into v_consent
    from public.sms_consent c
   where c.account_id = v_task.account_id
     and c.phone_number = v_receipt.from_number
   for share;

  if v_consent.id is null
     or v_consent.status <> 'opted_in'
     or v_consent.opted_out_at is not null then
    raise exception 'Sender consent is missing or revoked' using errcode = '28000';
  end if;

  select true into v_has_caller_scope
    from public.sms_consent_scopes scope
   where scope.account_id = v_task.account_id
     and scope.phone_number = v_receipt.from_number
     and scope.consent_scope = v_required_scope
   for share;

  if not coalesce(v_has_caller_scope, false) then
    raise exception 'Sender consent scope is missing' using errcode = '28000';
  end if;

  select pref.* into v_sender_preference
    from public.sms_sender_keyword_preferences pref
   where pref.sender_number_id = v_task.sender_number_id
     and pref.phone_number = v_receipt.from_number
   for share;

  if v_sender_preference.sender_number_id is not null
     and (
       v_sender_preference.status <> 'opted_in'
       or v_sender_preference.opted_out_at is not null
     ) then
    raise exception 'Sender-specific consent is revoked' using errcode = '28000';
  end if;

  -- The legacy completion intent performs an unescaped fuzzy ILIKE update and
  -- can mark zero or many tasks while confirming success. Keep it off this
  -- fresh rail until callers provide one exact task UUID.
  if p_intent = 'complete_job_task' then
    raise exception 'Task completion by SMS requires an exact task ID' using errcode = '42501';
  end if;

  if p_intent = 'log_cost' then
    if pg_catalog.jsonb_typeof(p_params->'amount') is distinct from 'number' then
      raise exception 'Cost amount must be a JSON number' using errcode = '22023';
    end if;
    v_cost_amount := (p_params->>'amount')::numeric;
    v_cost_type := coalesce(
      nullif(pg_catalog.btrim(p_params->>'cost_type'), ''),
      'material'
    );
    if v_cost_amount::text in ('NaN', 'Infinity', '-Infinity')
       or v_cost_amount <= 0
       or v_cost_amount > 1000000 then
      raise exception 'Cost amount is outside the allowed range' using errcode = '22023';
    end if;
    if v_cost_type not in ('material', 'labor', 'sub', 'receipt', 'other') then
      raise exception 'Cost type is invalid' using errcode = '22023';
    end if;
  end if;

  return public.apply_owner_field_action(
    p_task_id,
    p_claim_token,
    p_intent,
    p_params,
    p_transcript,
    p_confirmation_text
  );
end;
$$;

-- Trigger functions are internal implementation details. SECURITY DEFINER is
-- required so authenticated inbox writers cannot influence the lookup through
-- sms_sender_numbers RLS; the hardened path and revoked EXECUTE keep it out of
-- the Data API surface.
revoke all on function public.derive_sms_message_inbox_visibility()
  from public, anon, authenticated, service_role;
revoke all on function public.extend_sms_inbound_action_field_lease(uuid,uuid)
  from public, anon, authenticated, service_role;
grant execute on function public.extend_sms_inbound_action_field_lease(uuid,uuid)
  to service_role;
-- Keep the legacy service-role grant during a migration-first rollout so old
-- application instances do not fail between database and code deployment.
-- A later exact-release migration may revoke this compatibility entry point
-- after every worker version calls the authorized wrapper.
revoke all on function public.apply_owner_field_action(uuid,uuid,text,jsonb,text,text)
  from public, anon, authenticated;
grant execute on function public.apply_owner_field_action(uuid,uuid,text,jsonb,text,text)
  to service_role;
revoke all on function public.apply_authorized_sms_field_action(uuid,uuid,text,jsonb,text,text)
  from public, anon, authenticated, service_role;
grant execute on function public.apply_authorized_sms_field_action(uuid,uuid,text,jsonb,text,text)
  to service_role;

commit;

-- Source: migrations/20260903190000_sms_shared_notice_stop_suppression.sql
-- Make the shared-number courtesy claim the final STOP authority.
--
-- The route performs a fail-closed read before calling this function, but that
-- read and this receipt claim are separate transactions. A concurrent STOP
-- could otherwise commit between them and still allow the old receipt to
-- return a carrier <Message>. The canonical sender/recipient advisory lock is
-- the same one used by inbound STOP/START, so the preference read and immutable
-- notice claim now have a single serialization point.

begin;

create or replace function public.record_sms_shared_notice_reply(
  p_webhook_receipt_id uuid,
  p_egress_result text,
  p_response_body_sha256 text
)
returns boolean
language plpgsql
security definer
set search_path = pg_catalog, pg_temp
set timezone to 'UTC'
as $$
declare
  v_receipt public.sms_webhook_receipts%rowtype;
  v_sender public.sms_sender_numbers%rowtype;
  v_preference public.sms_sender_keyword_preferences%rowtype;
  v_consent public.sms_consent%rowtype;
  v_result public.sms_shared_notice_replies%rowtype;
  v_effective_egress_result text := p_egress_result;
  v_effective_body_sha256 text := p_response_body_sha256;
  v_recipient_opted_out boolean := false;
begin
  if p_webhook_receipt_id is null
     or p_egress_result not in ('twiml', 'suppressed')
     or p_response_body_sha256 is null
     or p_response_body_sha256 !~ '^[0-9a-f]{64}$' then
    raise exception 'SMS shared notice reply result is invalid' using errcode = '22023';
  end if;

  select r.* into v_receipt
    from public.sms_webhook_receipts r
   where r.id = p_webhook_receipt_id
   for share;

  if v_receipt.id is null
     or v_receipt.webhook_kind <> 'inbound'
     or v_receipt.processing_state not in ('processed', 'review')
     or v_receipt.sender_number_id is null
     or v_receipt.from_number is null
     or v_receipt.from_number !~ '^\+[1-9][0-9]{7,14}$'
     or v_receipt.to_number is null then
    raise exception 'SMS shared notice reply is not bound to an exact inbound sender'
      using errcode = '55000';
  end if;

  -- STOP/START/HELP keep their separate compliance acknowledgement and audit.
  if v_receipt.disposition is not null
     and v_receipt.disposition like 'keyword\_%' then
    raise exception 'SMS shared notice reply may not answer a compliance keyword'
      using errcode = '55000';
  end if;

  select s.* into v_sender
    from public.sms_sender_numbers s
   where s.id = v_receipt.sender_number_id
     and s.provider = v_receipt.provider
     and s.e164_number = v_receipt.to_number
     and s.purpose in ('lgq_shared', 'lgq_dispatch')
     and s.account_id is null
     and s.provisioning_status = 'active'
     and s.assignment_state = 'assigned'
     and s.inbound_ready
     and s.activated_at is not null
     and s.suspended_at is null
   for share;

  if v_sender.id is null then
    raise exception 'SMS shared notice reply is not bound to an active LGQ platform sender'
      using errcode = '55000';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'sms-sender-consent:' || v_sender.id::text || ':' || v_receipt.from_number,
      20260821
    )
  );

  -- Global consent writers use this second account/recipient lock. Keep the
  -- canonical sender-then-recipient order used by inbound routing and the field
  -- worker so consent cannot change between the final read and notice claim.
  if v_receipt.account_id is not null then
    perform pg_catalog.pg_advisory_xact_lock(
      public.sms_inbound_recipient_lock_key(
        v_receipt.account_id,
        v_receipt.from_number
      )
    );
  end if;

  select preference.* into v_preference
    from public.sms_sender_keyword_preferences preference
   where preference.sender_number_id = v_sender.id
     and preference.phone_number = v_receipt.from_number
   for share;

  v_recipient_opted_out := v_preference.sender_number_id is not null
    and (
      v_preference.status = 'opted_out'
      or v_preference.opted_out_at is not null
    );

  if v_receipt.account_id is not null then
    select consent.* into v_consent
      from public.sms_consent consent
     where consent.account_id = v_receipt.account_id
       and consent.phone_number = v_receipt.from_number
     for share;

    -- An account-bound courtesy reply requires current affirmative consent;
    -- deletion, an unexpected state, and explicit STOP all fail closed.
    v_recipient_opted_out := v_recipient_opted_out
      or v_consent.id is null
      or v_consent.status <> 'opted_in'
      or v_consent.opted_out_at is not null;
  end if;

  if v_recipient_opted_out then
    v_effective_egress_result := 'suppressed';
    -- SHA-256 of the exact EMPTY_TWIML returned by the route. Persisting the
    -- suppressed claim prevents a retry after a later START from resurrecting
    -- an old courtesy response.
    v_effective_body_sha256 :=
      'f94774d9eace296b75aeb622792d92dd74b7873a3b10ade1f415c0d399cfac07';
  end if;

  insert into public.sms_shared_notice_replies (
    webhook_receipt_id, egress_result, response_body_sha256
  ) values (
    p_webhook_receipt_id, v_effective_egress_result, v_effective_body_sha256
  ) on conflict (webhook_receipt_id) do nothing
  returning * into v_result;

  -- Only the first unsuppressed claim may return a carrier Message verb.
  return v_result.webhook_receipt_id is not null
    and v_effective_egress_result = 'twiml';
end;
$$;

revoke all on function public.record_sms_shared_notice_reply(uuid, text, text)
  from public, anon, authenticated, service_role;
grant execute on function public.record_sms_shared_notice_reply(uuid, text, text)
  to service_role;

do $$
declare
  v_definition text;
begin
  select pg_catalog.pg_get_functiondef(p.oid) into v_definition
    from pg_catalog.pg_proc p
    join pg_catalog.pg_namespace n on n.oid = p.pronamespace
   where n.nspname = 'public'
     and p.proname = 'record_sms_shared_notice_reply'
     and p.proargtypes = '2950 25 25'::pg_catalog.oidvector;

  if v_definition is null
     or v_definition not like '%sms-sender-consent:%'
     or v_definition not like '%sms_inbound_recipient_lock_key%'
     or v_definition not like '%sms_sender_keyword_preferences%'
     or v_definition not like '%sms_consent%' then
    raise exception 'record_sms_shared_notice_reply STOP authority is incomplete';
  end if;
end
$$;

commit;

-- Source: migrations/20260903202831_sms_enqueue_delivery_overload_cleanup.sql
-- Remove the obsolete enqueue_sms_delivery overload left behind when
-- p_available_at was added as an optional thirteenth argument. Keeping both
-- signatures makes named twelve-argument calls ambiguous inside PostgreSQL,
-- which prevents field-intake confirmations from being enqueued.

begin;

do $$
begin
  if not exists (
    select 1
      from pg_catalog.pg_proc p
      join pg_catalog.pg_namespace n on n.oid = p.pronamespace
     where n.nspname = 'public'
       and p.proname = 'enqueue_sms_delivery'
       and p.pronargs = 13
       and p.pronargdefaults = 4
       and p.proargnames[13] = 'p_available_at'
       and p.oid = pg_catalog.to_regprocedure(
         'public.enqueue_sms_delivery(uuid,text,text,text,text,text,text,text,text,uuid,uuid,uuid,timestamptz)'
       )
  ) then
    raise exception 'The delayed SMS enqueue function must exist before overload cleanup';
  end if;
end
$$;

-- Restore the original server-only boundary. The delayed-delivery migration
-- accidentally granted this SECURITY DEFINER function to authenticated users,
-- but every producer calls it from privileged server/database code.
revoke all on function public.enqueue_sms_delivery(
  uuid,
  text,
  text,
  text,
  text,
  text,
  text,
  text,
  text,
  uuid,
  uuid,
  uuid,
  timestamptz
) from public, anon, authenticated, service_role;
grant execute on function public.enqueue_sms_delivery(
  uuid,
  text,
  text,
  text,
  text,
  text,
  text,
  text,
  text,
  uuid,
  uuid,
  uuid,
  timestamptz
) to service_role;

-- No CASCADE: fail closed if a schema object unexpectedly depends on the old
-- function OID. Existing twelve-argument callers resolve to the retained
-- thirteen-argument function because p_available_at defaults to NULL.
drop function if exists public.enqueue_sms_delivery(
  uuid,
  text,
  text,
  text,
  text,
  text,
  text,
  text,
  text,
  uuid,
  uuid,
  uuid
);

do $$
declare
  v_overload_count integer;
begin
  select pg_catalog.count(*)::integer
    into v_overload_count
    from pg_catalog.pg_proc p
    join pg_catalog.pg_namespace n on n.oid = p.pronamespace
   where n.nspname = 'public'
     and p.proname = 'enqueue_sms_delivery';

  if v_overload_count <> 1 then
    raise exception 'enqueue_sms_delivery overload cleanup is incomplete';
  end if;

  if not pg_catalog.has_function_privilege(
    'service_role',
    'public.enqueue_sms_delivery(uuid,text,text,text,text,text,text,text,text,uuid,uuid,uuid,timestamptz)',
    'execute'
  ) then
    raise exception 'service_role lost enqueue_sms_delivery execute access';
  end if;

  if pg_catalog.has_function_privilege(
    'anon',
    'public.enqueue_sms_delivery(uuid,text,text,text,text,text,text,text,text,uuid,uuid,uuid,timestamptz)',
    'execute'
  ) then
    raise exception 'anon unexpectedly gained enqueue_sms_delivery execute access';
  end if;

  if pg_catalog.has_function_privilege(
    'authenticated',
    'public.enqueue_sms_delivery(uuid,text,text,text,text,text,text,text,text,uuid,uuid,uuid,timestamptz)',
    'execute'
  ) then
    raise exception 'authenticated unexpectedly retained enqueue_sms_delivery execute access';
  end if;
end
$$;

notify pgrst, 'reload schema';

commit;

-- Source: migrations/20260903203350_sms_enqueue_delivery_replay_hardening.sql
-- Preserve the legacy enqueue contract after consolidating onto the delayed
-- delivery signature. Idempotent replays must return the real delivery-task
-- state and must fail closed if an event ever exists without its task.

begin;

create or replace function public.enqueue_sms_delivery(
  p_account_id uuid,
  p_phone_number text,
  p_body text,
  p_message_kind text,
  p_billing_category text,
  p_sender_purpose text,
  p_context text,
  p_event_type text,
  p_idempotency_key text,
  p_payment_id uuid default null,
  p_crew_id uuid default null,
  p_sender_number_id uuid default null,
  p_available_at timestamptz default null
)
returns table (
  sms_event_id uuid,
  task_state text,
  created boolean
)
language plpgsql
security definer
set search_path = pg_catalog, pg_temp
set timezone to 'UTC'
as $$
declare
  v_now timestamptz := pg_catalog.clock_timestamp();
  v_event public.sms_events%rowtype;
  v_inserted boolean := false;
  v_available_at timestamptz := coalesce(p_available_at, v_now);
begin
  if p_account_id is null then
    raise exception 'SMS delivery requires an account'
      using errcode = '22023';
  end if;
  if p_phone_number is null or p_phone_number !~ '^\+[1-9][0-9]{7,14}$' then
    raise exception 'SMS destination must be E.164'
      using errcode = '22023';
  end if;
  if p_body is null or pg_catalog.length(p_body) not between 1 and 5000 then
    raise exception 'SMS body length is invalid'
      using errcode = '22023';
  end if;
  if p_message_kind is null or p_message_kind !~ '^[a-z][a-z0-9_-]{2,99}$' then
    raise exception 'SMS message kind is invalid'
      using errcode = '22023';
  end if;
  if p_billing_category is null or p_billing_category not in (
    'customer_message', 'crew_message', 'owner_alert',
    'payment_message', 'verification'
  ) then
    raise exception 'SMS billing category is invalid'
      using errcode = '22023';
  end if;
  if p_sender_purpose is null or p_sender_purpose not in (
    'lgq_shared', 'lgq_dispatch', 'contractor_dedicated'
  ) then
    raise exception 'SMS sender purpose is invalid'
      using errcode = '22023';
  end if;
  if p_context is null or p_context !~ '^[a-z][a-z0-9_]{2,63}$'
     or p_event_type is null or p_event_type !~ '^[a-z][a-z0-9_]{2,99}$' then
    raise exception 'SMS context or event type is invalid'
      using errcode = '22023';
  end if;
  if p_idempotency_key is null
     or p_idempotency_key !~ '^[A-Za-z0-9][A-Za-z0-9:._/-]{2,199}$' then
    raise exception 'SMS idempotency key is invalid'
      using errcode = '22023';
  end if;
  if p_context = 'payment' and p_payment_id is null
     or p_context in ('crew', 'subcontractor') and p_crew_id is null
     or p_context not in (
       'payment', 'crew', 'subcontractor', 'owner',
       'customer', 'automation', 'platform'
     ) then
    raise exception 'SMS context target is invalid'
      using errcode = '22023';
  end if;

  insert into public.sms_events (
    account_id, payment_id, event_type, phone_number, status, body,
    context, crew_id, provider, sender_number_id, idempotency_key,
    message_kind, billing_category, sender_purpose, queued_at, updated_at
  ) values (
    p_account_id, p_payment_id, p_event_type, p_phone_number, 'queued', p_body,
    p_context, p_crew_id, null, p_sender_number_id, p_idempotency_key,
    p_message_kind, p_billing_category, p_sender_purpose, v_now, v_now
  )
  on conflict (idempotency_key) where idempotency_key is not null do nothing
  returning * into v_event;

  if found then
    v_inserted := true;
    insert into public.sms_delivery_tasks (
      sms_event_id, task_state, available_at, created_at, updated_at
    ) values (
      v_event.id, 'queued', v_available_at, v_now, v_now
    );
  else
    select e.* into v_event
      from public.sms_events e
     where e.idempotency_key = p_idempotency_key
     for update;
    if not found then
      raise exception 'SMS idempotency conflict cannot be resolved'
        using errcode = '40001';
    end if;
    if v_event.account_id is distinct from p_account_id
       or v_event.phone_number is distinct from p_phone_number
       or v_event.body is distinct from p_body
       or v_event.message_kind is distinct from p_message_kind
       or v_event.billing_category is distinct from p_billing_category
       or v_event.sender_purpose is distinct from p_sender_purpose
       or v_event.context is distinct from p_context
       or v_event.event_type is distinct from p_event_type
       or v_event.payment_id is distinct from p_payment_id
       or v_event.crew_id is distinct from p_crew_id
       or v_event.sender_number_id is distinct from p_sender_number_id then
      raise exception 'SMS idempotency key was reused with a different payload'
        using errcode = '22000';
    end if;
    if not exists (
      select 1
        from public.sms_delivery_tasks t
       where t.sms_event_id = v_event.id
    ) then
      raise exception 'SMS event exists without its delivery task'
        using errcode = '55000';
    end if;
  end if;

  return query
  select v_event.id, t.task_state, v_inserted
    from public.sms_delivery_tasks t
   where t.sms_event_id = v_event.id;
end;
$$;

revoke all on function public.enqueue_sms_delivery(
  uuid,text,text,text,text,text,text,text,text,uuid,uuid,uuid,timestamptz
) from public, anon, authenticated, service_role;
grant execute on function public.enqueue_sms_delivery(
  uuid,text,text,text,text,text,text,text,text,uuid,uuid,uuid,timestamptz
) to service_role;

do $$
declare
  v_function pg_catalog.pg_proc%rowtype;
  v_overload_count integer;
begin
  select pg_catalog.count(*)::integer into v_overload_count
    from pg_catalog.pg_proc p
    join pg_catalog.pg_namespace n on n.oid = p.pronamespace
   where n.nspname = 'public'
     and p.proname = 'enqueue_sms_delivery';

  if v_overload_count <> 1 then
    raise exception 'enqueue_sms_delivery overload hardening is incomplete';
  end if;

  select p.* into v_function
    from pg_catalog.pg_proc p
    join pg_catalog.pg_namespace n on n.oid = p.pronamespace
   where n.nspname = 'public'
     and p.proname = 'enqueue_sms_delivery';

  if v_function.oid is null
     or v_function.pronargs <> 13
     or v_function.pronargdefaults <> 4
     or v_function.proargnames[13] <> 'p_available_at' then
    raise exception 'enqueue_sms_delivery signature hardening is incomplete';
  end if;

  if not pg_catalog.has_function_privilege('service_role', v_function.oid, 'execute')
     or pg_catalog.has_function_privilege('authenticated', v_function.oid, 'execute')
     or pg_catalog.has_function_privilege('anon', v_function.oid, 'execute') then
    raise exception 'enqueue_sms_delivery privilege hardening is incomplete';
  end if;
end
$$;

notify pgrst, 'reload schema';

commit;

-- Source: migrations/20260903215831_voice_contractor_dispatch_hardening.sql
-- Make AI Voice field dispatch a database-authorized, replay-safe mutation rail.
--
-- SignalWire does not provide a distinct tool-invocation id. The strongest
-- honest retry contract is therefore one identical canonical action per call.
-- An intentional repeat must change a semantic field (work date, amount, note,
-- etc.); a provider retry of the same request replays the stored outcome.

begin;

-- Crew verification was already used by the application, but the roster table
-- did not carry the fields it queried or updated. Add the missing durable facts.
alter table public.crew
  add column if not exists phone_verified boolean not null default false,
  add column if not exists phone_verified_at timestamptz,
  add column if not exists updated_at timestamptz not null default now();

alter table public.crew
  drop constraint if exists crew_phone_verification_shape;
alter table public.crew
  add constraint crew_phone_verification_shape check (
    phone_verified_at is null or phone_verified
  );

-- Bind the signed inbound caller and the identity snapshot to the admission.
-- The receipt is not allowed to invent or replace either value later.
alter table public.voice_call_admissions
  add column if not exists caller_number text,
  add column if not exists caller_kind text;

alter table public.voice_call_admissions
  drop constraint if exists voice_call_admissions_caller_number_shape;
alter table public.voice_call_admissions
  add constraint voice_call_admissions_caller_number_shape check (
    caller_number is null or caller_number ~ '^\+1[2-9][0-9]{9}$'
  );

alter table public.voice_call_admissions
  drop constraint if exists voice_call_admissions_caller_kind_shape;
alter table public.voice_call_admissions
  add constraint voice_call_admissions_caller_kind_shape check (
    caller_kind is null
    or caller_kind in ('customer', 'owner', 'office', 'crew', 'staff_ambiguous', 'unknown')
  );

-- In-call customer booking is a separate mutation from staff dispatch. Bind its
-- lead and pending job to the provider call so a lost webhook response can
-- resume instead of inserting a second customer or a second booking request.
alter table public.leads
  add column if not exists source_voice_provider_call_id text;
alter table public.jobs
  add column if not exists source_voice_provider_call_id text;

alter table public.leads
  drop constraint if exists leads_voice_provider_call_shape;
alter table public.leads
  add constraint leads_voice_provider_call_shape check (
    source_voice_provider_call_id is null
    or pg_catalog.length(pg_catalog.btrim(source_voice_provider_call_id)) between 1 and 255
  );
alter table public.jobs
  drop constraint if exists jobs_voice_provider_call_shape;
alter table public.jobs
  add constraint jobs_voice_provider_call_shape check (
    source_voice_provider_call_id is null
    or pg_catalog.length(pg_catalog.btrim(source_voice_provider_call_id)) between 1 and 255
  );

drop index if exists public.leads_voice_provider_call_uidx;
drop index if exists public.jobs_voice_provider_call_uidx;
do $constraints$
begin
  if not exists (
    select 1
      from pg_catalog.pg_constraint c
     where c.conrelid = 'public.leads'::pg_catalog.regclass
       and c.conname = 'leads_voice_provider_call_unique'
  ) then
    alter table public.leads
      add constraint leads_voice_provider_call_unique
      unique (account_id, source_voice_provider_call_id);
  end if;
end
$constraints$;
do $constraints$
begin
  if not exists (
    select 1
      from pg_catalog.pg_constraint c
     where c.conrelid = 'public.jobs'::pg_catalog.regclass
       and c.conname = 'jobs_voice_provider_call_unique'
  ) then
    alter table public.jobs
      add constraint jobs_voice_provider_call_unique
      unique (account_id, source_voice_provider_call_id);
  end if;
end
$constraints$;

create or replace function public.voice_normalize_us_phone(p_phone text)
returns text
language sql
immutable
strict
set search_path = pg_catalog, pg_temp
as $fn$
  select case
    when pg_catalog.length(pg_catalog.regexp_replace(p_phone, '[^0-9]', '', 'g')) = 10
      then '+1' || pg_catalog.regexp_replace(p_phone, '[^0-9]', '', 'g')
    when pg_catalog.length(pg_catalog.regexp_replace(p_phone, '[^0-9]', '', 'g')) = 11
      and pg_catalog.left(pg_catalog.regexp_replace(p_phone, '[^0-9]', '', 'g'), 1) = '1'
      then '+' || pg_catalog.regexp_replace(p_phone, '[^0-9]', '', 'g')
    else null
  end
$fn$;

revoke all on function public.voice_normalize_us_phone(text)
  from public, anon, authenticated, service_role;

-- Versioned admission entry point. Keeping the previous overload during the
-- migration-first rolling deploy lets old instances drain; new code calls only
-- this caller-bound version.
create or replace function public.claim_voice_call_admission_v2(
  p_account_id uuid,
  p_provider_call_id text,
  p_dialed_number text,
  p_concurrency_limit integer,
  p_caller_number text,
  p_caller_kind text
)
returns table (
  claim_status text,
  admission_id uuid
)
language plpgsql
security definer
set search_path = pg_catalog, pg_temp
set timezone to 'UTC'
as $fn$
declare
  v_existing public.voice_call_admissions%rowtype;
  v_open bigint;
  v_id uuid;
  v_sender_number_id uuid;
  v_route_revision bigint;
begin
  if p_account_id is null
     or p_provider_call_id is null
     or pg_catalog.length(pg_catalog.btrim(p_provider_call_id)) = 0
     or pg_catalog.length(p_provider_call_id) > 255
     or p_dialed_number is null
     or p_dialed_number !~ '^\+[1-9][0-9]{7,14}$'
     or p_concurrency_limit is null
     or p_concurrency_limit < 1
     or p_concurrency_limit > 100
     or (p_caller_number is not null and p_caller_number !~ '^\+1[2-9][0-9]{9}$')
     or p_caller_kind is null
     or p_caller_kind not in ('customer', 'owner', 'office', 'crew', 'staff_ambiguous', 'unknown') then
    raise exception 'voice admission claim arguments are invalid'
      using errcode = '22023';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(p_account_id::text, 84601211)
  );

  select s.id, a.ai_voice_route_revision
    into v_sender_number_id, v_route_revision
    from public.accounts a
    join public.sms_sender_numbers s
      on s.account_id = a.id
     and s.e164_number = a.call_tracking_number
   where a.id = p_account_id
     and a.suspended_at is null
     and a.call_tracking_number = p_dialed_number
     and s.provider = 'signalwire'
     and s.purpose = 'contractor_dedicated'
     and s.e164_number = p_dialed_number
     and s.provisioning_status = 'active'
     and s.assignment_state = 'assigned'
     and s.inbound_ready
     and s.activated_at is not null
     and s.suspended_at is null
     and s.provider_number_id ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
   for share of a, s;

  if not found then
    return query select 'number_not_ready'::text, null::uuid;
    return;
  end if;

  select a.* into v_existing
    from public.voice_call_admissions a
   where a.provider = 'signalwire'
     and a.provider_call_id = p_provider_call_id;

  if found then
    if v_existing.account_id <> p_account_id then
      raise exception 'voice call id is already bound to another workspace'
        using errcode = '22000';
    end if;
    if v_existing.sender_number_id is distinct from v_sender_number_id
       or v_existing.dialed_number is distinct from p_dialed_number
       or v_existing.route_revision is distinct from v_route_revision
       or v_existing.caller_number is distinct from p_caller_number
       or v_existing.caller_kind is distinct from p_caller_kind then
      return query select 'number_not_ready'::text, null::uuid;
    elsif v_existing.admission_state = 'admitted' then
      return query select 'existing'::text, v_existing.id;
    else
      return query select 'busy'::text, v_existing.id;
    end if;
    return;
  end if;

  select pg_catalog.count(*) into v_open
    from public.voice_call_admissions a
   where a.account_id = p_account_id
     and a.provider = 'signalwire'
     and a.admitted_at >= pg_catalog.clock_timestamp() - interval '60 minutes'
     and not exists (
       select 1
         from public.voice_events e
        where e.provider = a.provider
          and e.provider_call_id = a.provider_call_id
     );

  if v_open >= p_concurrency_limit then
    return query select 'at_capacity'::text, null::uuid;
    return;
  end if;

  insert into public.voice_call_admissions (
    account_id, provider, provider_call_id, reservation_id,
    reserved_minutes, admission_state, sender_number_id,
    dialed_number, route_revision, caller_number, caller_kind
  ) values (
    p_account_id, 'signalwire', p_provider_call_id, null,
    0, 'claimed', v_sender_number_id, p_dialed_number, v_route_revision,
    p_caller_number, p_caller_kind
  )
  returning id into v_id;

  return query select 'claimed'::text, v_id;
end
$fn$;

revoke all on function public.claim_voice_call_admission_v2(uuid,text,text,integer,text,text)
  from public, anon, authenticated, service_role;
grant execute on function public.claim_voice_call_admission_v2(uuid,text,text,integer,text,text)
  to service_role;

create table if not exists public.voice_tool_actions (
  id uuid primary key default gen_random_uuid(),
  account_id uuid not null references public.accounts(id) on delete cascade,
  provider text not null default 'signalwire' check (provider = 'signalwire'),
  provider_call_id text not null check (
    pg_catalog.length(pg_catalog.btrim(provider_call_id)) between 1 and 255
  ),
  caller_number text not null check (caller_number ~ '^\+1[2-9][0-9]{9}$'),
  function_name text not null check (function_name in (
    'update_job_details',
    'create_or_update_lead',
    'log_crew_time_and_materials',
    'create_job_change_order',
    'append_job_caution_or_note'
  )),
  request_hash text not null check (request_hash ~ '^[0-9a-f]{64}$'),
  request_payload jsonb not null check (pg_catalog.jsonb_typeof(request_payload) = 'object'),
  target_job_id uuid references public.jobs(id) on delete set null,
  target_lead_id uuid references public.leads(id) on delete set null,
  action_state text not null default 'pending' check (action_state in ('pending', 'applied')),
  outcome jsonb,
  applied_at timestamptz,
  created_at timestamptz not null default now(),
  constraint voice_tool_actions_identity_unique unique (
    account_id, provider, provider_call_id, function_name, request_hash
  ),
  constraint voice_tool_actions_state_shape check (
    (action_state = 'pending' and outcome is null and applied_at is null)
    or (action_state = 'applied' and outcome is not null and applied_at is not null)
  )
);

create index if not exists voice_tool_actions_call_idx
  on public.voice_tool_actions (account_id, provider_call_id, created_at desc);

alter table public.voice_tool_actions enable row level security;
alter table public.voice_tool_actions force row level security;
-- The action table is an internal state machine. Even service-role callers use
-- the single transactional RPC so no other backend path can forge an applied
-- result or skip replay checks.
revoke all on table public.voice_tool_actions from public, anon, authenticated, service_role;

alter table public.leads
  add column if not exists source_voice_action_id uuid
    references public.voice_tool_actions(id) on delete set null;
create unique index if not exists leads_source_voice_action_uidx
  on public.leads (source_voice_action_id)
  where source_voice_action_id is not null;

create or replace function public.apply_voice_contractor_action(
  p_account_id uuid,
  p_provider_call_id text,
  p_caller_number text,
  p_function_name text,
  p_target_job_id uuid,
  p_target_lead_id uuid,
  p_payload jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = pg_catalog, pg_temp
set timezone to 'UTC'
as $fn$
declare
  v_now timestamptz := pg_catalog.clock_timestamp();
  v_admission public.voice_call_admissions%rowtype;
  v_account public.accounts%rowtype;
  v_action public.voice_tool_actions%rowtype;
  v_job public.jobs%rowtype;
  v_lead public.leads%rowtype;
  v_crew public.crew%rowtype;
  v_caller_crew public.crew%rowtype;
  v_function text;
  v_hash text;
  v_action_id uuid;
  v_outcome jsonb;
  v_staff_matches integer := 0;
  v_scope text;
  v_status text;
  v_date text;
  v_time text;
  v_label text;
  v_price numeric;
  v_quote_items jsonb;
  v_hours numeric;
  v_material_amount numeric;
  v_material_description text;
  v_labor_amount numeric;
  v_burden_amount numeric;
  v_note text;
  v_is_caution boolean;
  v_title text;
  v_description text;
  v_operation text;
  v_name text;
  v_phone text;
  v_email text;
  v_address text;
  v_project_type text;
  v_message text;
  v_quote_visit jsonb;
  v_client_notes text;
begin
  v_function := case p_function_name
    when 'update_job_scope' then 'update_job_details'
    when 'add_caution_note' then 'append_job_caution_or_note'
    else p_function_name
  end;

  if p_account_id is null
     or p_provider_call_id is null
     or pg_catalog.length(pg_catalog.btrim(p_provider_call_id)) not between 1 and 255
     or p_caller_number is null
     or p_caller_number !~ '^\+1[2-9][0-9]{9}$'
     or v_function is null
     or v_function not in (
       'update_job_details', 'create_or_update_lead',
       'log_crew_time_and_materials', 'create_job_change_order',
       'append_job_caution_or_note'
     )
     or p_payload is null
     or pg_catalog.jsonb_typeof(p_payload) <> 'object' then
    raise exception 'voice contractor action arguments are invalid' using errcode = '22023';
  end if;

  v_hash := pg_catalog.encode(
    extensions.digest(
      pg_catalog.convert_to(
        v_function || ':' || coalesce(p_target_job_id::text, '') || ':'
        || coalesce(p_target_lead_id::text, '') || ':' || p_payload::text,
        'UTF8'
      ),
      'sha256'
    ),
    'hex'
  );

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      p_account_id::text || ':signalwire:' || p_provider_call_id || ':' || v_function || ':' || v_hash,
      20260903
    )
  );

  select a.* into v_action
    from public.voice_tool_actions a
   where a.account_id = p_account_id
     and a.provider = 'signalwire'
     and a.provider_call_id = p_provider_call_id
     and a.caller_number = p_caller_number
     and a.function_name = v_function
     and a.request_hash = v_hash
   for update;

  if found then
    if v_action.action_state <> 'applied' or v_action.outcome is null then
      raise exception 'voice contractor action is incomplete' using errcode = '55000';
    end if;
    return v_action.outcome || pg_catalog.jsonb_build_object('replayed', true);
  end if;

  select a.* into v_account
    from public.accounts a
   where a.id = p_account_id
     and a.suspended_at is null
   for share;
  if not found then
    raise exception 'voice contractor account is unavailable' using errcode = '28000';
  end if;

  select a.* into v_admission
    from public.voice_call_admissions a
   where a.account_id = p_account_id
     and a.provider = 'signalwire'
     and a.provider_call_id = p_provider_call_id
     and a.admission_state = 'admitted'
     and a.caller_number = p_caller_number
   for share;
  if not found or v_admission.caller_kind not in ('owner', 'office', 'crew') then
    raise exception 'voice contractor caller is not authorized' using errcode = '42501';
  end if;

  -- Re-establish live authorization immediately before the write. Admission is
  -- an immutable snapshot, but suspension/revocation after answer must still win.
  if v_admission.caller_kind = 'owner' then
    select case when (
      public.voice_normalize_us_phone(v_account.alert_phone) = p_caller_number
      or public.voice_normalize_us_phone(v_account.call_forward_number) = p_caller_number
      or exists (
        select 1 from public.voice_settings vs
         where vs.account_id = p_account_id
           and public.voice_normalize_us_phone(vs.transfer_number) = p_caller_number
      )
      or exists (
        select 1 from public.sites s
         where s.account_id = p_account_id
           and public.voice_normalize_us_phone(s.phone) = p_caller_number
      )
      or exists (
        select 1
          from public.memberships m
          join auth.users u on u.id = m.user_id
         where m.account_id = p_account_id
           and m.role = 'owner'
           and m.deactivated_at is null
           and public.voice_normalize_us_phone(u.phone) = p_caller_number
      )
    ) then 1 else 0 end into v_staff_matches;
  elsif v_admission.caller_kind = 'office' then
    select pg_catalog.count(*) into v_staff_matches
      from public.memberships m
      join auth.users u on u.id = m.user_id
     where m.account_id = p_account_id
       and m.role = 'office'
       and m.deactivated_at is null
       and public.voice_normalize_us_phone(u.phone) = p_caller_number;
  else
    select pg_catalog.count(*) into v_staff_matches
      from public.crew c
     where c.account_id = p_account_id
       and c.active
       and c.deleted_at is null
       and c.access_revoked_at is null
       and public.voice_normalize_us_phone(c.phone) = p_caller_number
       and (
         c.phone_verified_at is not null
         or c.phone_verified
         or (c.user_id is not null and c.last_signed_in_at is not null)
       );
    if v_staff_matches = 1 then
      select c.* into v_caller_crew
        from public.crew c
       where c.account_id = p_account_id
         and c.active
         and c.deleted_at is null
         and c.access_revoked_at is null
         and public.voice_normalize_us_phone(c.phone) = p_caller_number
         and (
           c.phone_verified_at is not null
           or c.phone_verified
           or (c.user_id is not null and c.last_signed_in_at is not null)
         )
       for share;
    end if;
  end if;

  if v_staff_matches <> 1 then
    raise exception 'voice contractor caller lifecycle is invalid or ambiguous' using errcode = '42501';
  end if;

  if v_admission.caller_kind = 'crew'
     and v_function in ('update_job_details', 'create_or_update_lead') then
    raise exception 'voice crew caller is not authorized for office records' using errcode = '42501';
  end if;

  if v_function <> 'create_or_update_lead' then
    if p_target_job_id is null then
      raise exception 'voice contractor action requires an exact job' using errcode = '22023';
    end if;
    select j.* into v_job
      from public.jobs j
     where j.id = p_target_job_id
       and j.account_id = p_account_id
       and j.deleted_at is null
     for update;
    if not found then
      raise exception 'voice contractor job is unavailable' using errcode = 'P0002';
    end if;
    if v_admission.caller_kind = 'crew' then
      perform 1
        from public.crew_assignments ca
       where ca.account_id = p_account_id
         and ca.job_id = v_job.id
         and ca.crew_id = v_caller_crew.id;
      if not found then
        raise exception 'voice crew caller is not assigned to this job' using errcode = '42501';
      end if;
    end if;
  elsif p_target_job_id is not null then
    raise exception 'lead action cannot target a job' using errcode = '22023';
  end if;

  insert into public.voice_tool_actions (
    account_id, provider, provider_call_id, caller_number, function_name,
    request_hash, request_payload, target_job_id, target_lead_id
  ) values (
    p_account_id, 'signalwire', p_provider_call_id, p_caller_number, v_function,
    v_hash, p_payload, p_target_job_id, p_target_lead_id
  ) returning id into v_action_id;

  if v_function = 'update_job_details' then
    v_scope := nullif(pg_catalog.btrim(p_payload->>'scope_append'), '');
    v_status := nullif(pg_catalog.btrim(p_payload->>'status'), '');
    v_date := nullif(pg_catalog.btrim(p_payload->>'scheduled_date'), '');
    v_time := nullif(pg_catalog.btrim(p_payload->>'scheduled_time'), '');
    v_label := nullif(pg_catalog.btrim(p_payload->>'line_item_label'), '');

    if p_payload ? 'line_item_price' then
      if pg_catalog.jsonb_typeof(p_payload->'line_item_price') <> 'number' then
        raise exception 'voice quote amount must be numeric' using errcode = '22023';
      end if;
      v_price := (p_payload->>'line_item_price')::numeric;
    end if;
    if v_scope is null and v_status is null and v_date is null and v_time is null and v_label is null then
      raise exception 'voice job update has no effect' using errcode = '22023';
    end if;
    if v_scope is not null and pg_catalog.length(v_scope) > 4000 then
      raise exception 'voice job scope is too long' using errcode = '22023';
    end if;
    if v_status is not null and v_status not in ('new_lead', 'in_progress', 'complete') then
      raise exception 'voice job status is invalid' using errcode = '22023';
    end if;
    if v_date is not null and (
      v_date !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
      or pg_catalog.to_char(v_date::date, 'YYYY-MM-DD') <> v_date
    ) then
      raise exception 'voice job date is invalid' using errcode = '22023';
    end if;
    if v_time is not null and v_time !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$' then
      raise exception 'voice job time is invalid' using errcode = '22023';
    end if;
    if (v_label is null) <> (v_price is null)
       or (v_price is not null and (v_price <= 0 or v_price > 1000000)) then
      raise exception 'voice quote line item is invalid' using errcode = '22023';
    end if;

    if v_label is not null then
      v_quote_items := case
        when pg_catalog.jsonb_typeof(v_job.quote_items) = 'array' then v_job.quote_items
        when v_job.quoted_amount > 0 then pg_catalog.jsonb_build_array(
          pg_catalog.jsonb_build_object(
            'id', 'legacy-' || v_job.id::text,
            'label', 'Existing quote',
            'amount', v_job.quoted_amount,
            'kind', 'base',
            'selected', true,
            'recommended', false
          )
        )
        else '[]'::jsonb
      end;
      v_quote_items := v_quote_items || pg_catalog.jsonb_build_array(
        pg_catalog.jsonb_build_object(
          'id', 'voice-' || v_action_id::text,
          'label', v_label,
          'amount', pg_catalog.round(v_price, 2),
          'kind', 'base',
          'selected', true,
          'recommended', false
        )
      );
    else
      v_quote_items := v_job.quote_items;
    end if;

    update public.jobs j
       set scope = case when v_scope is null then j.scope
                    when j.scope is null or pg_catalog.btrim(j.scope) = '' then v_scope
                    when pg_catalog.strpos(pg_catalog.lower(j.scope), pg_catalog.lower(v_scope)) > 0 then j.scope
                    else j.scope || E'\n\n' || v_scope end,
           status = case when v_status is null then j.status else v_status::public.job_status end,
           scheduled_for = case when v_date is null then j.scheduled_for else v_date::date end,
           scheduled_time = case when v_time is null then j.scheduled_time else v_time::time end,
           quote_items = v_quote_items,
           quoted_amount = case when v_price is null then j.quoted_amount
                                else pg_catalog.round(j.quoted_amount + v_price, 2) end
     where j.id = v_job.id
       and j.account_id = p_account_id;

    v_outcome := pg_catalog.jsonb_build_object(
      'action_id', v_action_id,
      'job_id', v_job.id,
      'job_ref', v_job.ref,
      'target_name', v_job.client_name,
      'replayed', false
    );

  elsif v_function = 'create_or_update_lead' then
    v_operation := pg_catalog.lower(nullif(pg_catalog.btrim(p_payload->>'operation'), ''));
    v_name := nullif(pg_catalog.btrim(p_payload->>'name'), '');
    v_phone := nullif(pg_catalog.btrim(p_payload->>'phone'), '');
    v_email := pg_catalog.lower(nullif(pg_catalog.btrim(p_payload->>'email'), ''));
    v_address := nullif(pg_catalog.btrim(p_payload->>'address'), '');
    v_project_type := nullif(pg_catalog.btrim(p_payload->>'project_type'), '');
    v_message := nullif(pg_catalog.btrim(p_payload->>'message'), '');
    -- The caller supplies only the stable scheduling fields. Stamp the mutable
    -- audit time after the action fingerprint is claimed so an HTTP retry made
    -- seconds later hashes identically and replays instead of creating a
    -- second lead.
    if p_payload ? 'quote_visit' then
      if pg_catalog.jsonb_typeof(p_payload->'quote_visit') <> 'object'
         or (p_payload->'quote_visit') ? 'scheduledAt' then
        raise exception 'voice quote visit payload is invalid' using errcode = '22023';
      end if;
      v_quote_visit := (p_payload->'quote_visit')
        || pg_catalog.jsonb_build_object('scheduledAt', v_now);
    else
      v_quote_visit := null;
    end if;

    if v_operation = 'create' then
      if p_target_lead_id is not null then
        raise exception 'voice lead creation cannot target an existing lead' using errcode = '22023';
      end if;
      if v_name is null or (v_phone is null and v_email is null and v_address is null
                            and v_project_type is null and v_message is null) then
        raise exception 'voice lead creation needs a name and substantive detail' using errcode = '22023';
      end if;
      insert into public.leads (
        account_id, source, status, name, phone, email, address, project_type,
        message, source_page, triage, quote_visit, source_voice_action_id
      ) values (
        p_account_id, 'ai_voice', case when v_quote_visit is null then 'new' else 'contacted' end,
        v_name, v_phone, v_email, v_address, v_project_type, v_message, '/call',
        pg_catalog.jsonb_build_object('score', 'warm', 'flags', '[]'::jsonb, 'contactPreference', 'any'),
        v_quote_visit, v_action_id
      ) returning * into v_lead;
    elsif v_operation = 'update' then
      if p_target_lead_id is null then
        raise exception 'voice lead update requires an exact lead id' using errcode = '22023';
      end if;
      select l.* into v_lead
        from public.leads l
       where l.id = p_target_lead_id
         and l.account_id = p_account_id
         and l.deleted_at is null
       for update;
      if not found then
        raise exception 'voice lead is unavailable' using errcode = 'P0002';
      end if;
      if not (p_payload ? 'name' or p_payload ? 'phone' or p_payload ? 'email'
              or p_payload ? 'address' or p_payload ? 'project_type'
              or p_payload ? 'message' or p_payload ? 'quote_visit') then
        raise exception 'voice lead update has no effect' using errcode = '22023';
      end if;
      update public.leads l
         set name = case when p_payload ? 'name' then v_name else l.name end,
             phone = case when p_payload ? 'phone' then v_phone else l.phone end,
             email = case when p_payload ? 'email' then v_email else l.email end,
             address = case when p_payload ? 'address' then v_address else l.address end,
             project_type = case when p_payload ? 'project_type' then v_project_type else l.project_type end,
             message = case when p_payload ? 'message' then v_message else l.message end,
             quote_visit = case when p_payload ? 'quote_visit' then v_quote_visit else l.quote_visit end,
             status = case when p_payload ? 'quote_visit' and l.status = 'new' then 'contacted' else l.status end,
             updated_at = v_now
       where l.id = v_lead.id
         and l.account_id = p_account_id
       returning * into v_lead;
    else
      raise exception 'voice lead operation must be create or update' using errcode = '22023';
    end if;

    update public.voice_tool_actions
       set target_lead_id = v_lead.id
     where id = v_action_id;
    v_outcome := pg_catalog.jsonb_build_object(
      'action_id', v_action_id,
      'lead_id', v_lead.id,
      'target_name', v_lead.name,
      'operation', v_operation,
      'replayed', false
    );

  elsif v_function = 'log_crew_time_and_materials' then
    if p_payload ? 'hours' then
      if pg_catalog.jsonb_typeof(p_payload->'hours') <> 'number' then
        raise exception 'voice labor hours must be numeric' using errcode = '22023';
      end if;
      v_hours := (p_payload->>'hours')::numeric;
    end if;
    if p_payload ? 'material_cost' then
      if pg_catalog.jsonb_typeof(p_payload->'material_cost') <> 'number' then
        raise exception 'voice material cost must be numeric' using errcode = '22023';
      end if;
      v_material_amount := (p_payload->>'material_cost')::numeric;
    end if;
    v_material_description := nullif(pg_catalog.btrim(p_payload->>'materials'), '');
    if coalesce(v_hours, 0) <= 0 and coalesce(v_material_amount, 0) <= 0 then
      raise exception 'voice cost action has no positive amount' using errcode = '22023';
    end if;
    if v_hours is not null and (v_hours <= 0 or v_hours > 24 or p_payload->>'crew_id' is null) then
      raise exception 'voice labor entry is invalid' using errcode = '22023';
    end if;
    if v_material_amount is not null and (v_material_amount <= 0 or v_material_amount > 1000000
                                          or v_material_description is null) then
      raise exception 'voice material entry is invalid' using errcode = '22023';
    end if;

    if v_hours is not null then
      select c.* into v_crew
        from public.crew c
       where c.id = (p_payload->>'crew_id')::uuid
         and c.account_id = p_account_id
         and c.active
         and c.deleted_at is null
         and c.access_revoked_at is null
       for share;
      if not found or v_crew.hourly_rate <= 0 then
        raise exception 'voice labor crew member is unavailable' using errcode = 'P0002';
      end if;
      if v_admission.caller_kind = 'crew' and v_crew.id is distinct from v_caller_crew.id then
        raise exception 'voice crew caller cannot log labor for a coworker' using errcode = '42501';
      end if;
      v_labor_amount := pg_catalog.round(v_hours * v_crew.hourly_rate, 2);
      v_burden_amount := pg_catalog.round(
        v_labor_amount * coalesce(v_crew.burden_pct, v_account.default_burden_pct, 0) / 100,
        2
      );
      insert into public.costs (
        account_id, job_id, type, category, description, amount,
        crew_id, crew_name, crew_role_label, hours, rate, burden_amount, cost_source
      ) values (
        p_account_id, v_job.id, 'labor', 'Labor', 'Voice logged labor', v_labor_amount,
        v_crew.id, v_crew.name, v_crew.role_label, v_hours, v_crew.hourly_rate,
        v_burden_amount, 'estimated'
      );
    end if;

    if v_material_amount is not null then
      insert into public.costs (
        account_id, job_id, type, category, description, amount, burden_amount, cost_source
      ) values (
        p_account_id, v_job.id, 'material', 'Materials', v_material_description,
        pg_catalog.round(v_material_amount, 2), 0, 'estimated'
      );
    end if;

    v_outcome := pg_catalog.jsonb_build_object(
      'action_id', v_action_id,
      'job_id', v_job.id,
      'job_ref', v_job.ref,
      'target_name', v_job.client_name,
      'hours', coalesce(v_hours, 0),
      'material_cost', coalesce(v_material_amount, 0),
      'replayed', false
    );

  elsif v_function = 'create_job_change_order' then
    v_title := nullif(pg_catalog.btrim(p_payload->>'title'), '');
    v_description := nullif(pg_catalog.btrim(p_payload->>'description'), '');
    if v_title is null or v_description is null
       or pg_catalog.length(v_title) > 200 or pg_catalog.length(v_description) > 8000 then
      raise exception 'voice change order content is invalid' using errcode = '22023';
    end if;
    if v_admission.caller_kind = 'crew'
       and nullif(pg_catalog.btrim(p_payload->>'crew_id'), '') is null then
      raise exception 'voice crew change order must be self-attributed' using errcode = '42501';
    end if;
    if nullif(pg_catalog.btrim(p_payload->>'crew_id'), '') is not null then
      select c.* into v_crew
        from public.crew c
       where c.id = (p_payload->>'crew_id')::uuid
         and c.account_id = p_account_id
         and c.active
         and c.deleted_at is null
         and c.access_revoked_at is null
       for share;
      if not found then
        raise exception 'voice change order crew member is unavailable' using errcode = 'P0002';
      end if;
      if v_admission.caller_kind = 'crew' and v_crew.id is distinct from v_caller_crew.id then
        raise exception 'voice crew caller cannot author a change order for a coworker' using errcode = '42501';
      end if;
    end if;
    insert into public.change_orders (
      id, account_id, job_id, crew_id, crew_name, status, title, field_note, scope
    ) values (
      v_action_id, p_account_id, v_job.id, v_crew.id, v_crew.name,
      'draft', v_title, v_description, v_description
    );
    v_outcome := pg_catalog.jsonb_build_object(
      'action_id', v_action_id,
      'change_order_id', v_action_id,
      'job_id', v_job.id,
      'job_ref', v_job.ref,
      'target_name', v_job.client_name,
      'title', v_title,
      'replayed', false
    );

  elsif v_function = 'append_job_caution_or_note' then
    v_note := nullif(pg_catalog.btrim(p_payload->>'note'), '');
    v_is_caution := coalesce((p_payload->>'is_caution')::boolean, false);
    if v_note is null or pg_catalog.length(v_note) > 4000 then
      raise exception 'voice job note is invalid' using errcode = '22023';
    end if;
    if v_job.client_id is not null then
      select c.notes into v_client_notes
        from public.clients c
       where c.id = v_job.client_id
         and c.account_id = p_account_id
       for update;
      if found and pg_catalog.strpos(pg_catalog.lower(coalesce(v_client_notes, '')), pg_catalog.lower(v_note)) = 0 then
        update public.clients c
           set notes = case when coalesce(pg_catalog.btrim(c.notes), '') = '' then '• ' || v_note
                            else c.notes || E'\n• ' || v_note end,
               updated_at = v_now
         where c.id = v_job.client_id
           and c.account_id = p_account_id;
      end if;
    end if;
    v_outcome := pg_catalog.jsonb_build_object(
      'action_id', v_action_id,
      'job_id', v_job.id,
      'job_ref', v_job.ref,
      'target_name', v_job.client_name,
      'is_caution', v_is_caution,
      'replayed', false
    );
  end if;

  if v_function <> 'create_or_update_lead' then
    insert into public.job_feed (
      account_id, job_id, kind, title, body, author, meta,
      visibility, source_table, source_id
    ) values (
      p_account_id,
      v_job.id,
      case when v_function = 'append_job_caution_or_note' and v_is_caution
           then 'field_caution'
           when v_function = 'append_job_caution_or_note' then 'field_note'
           else 'job_update' end,
      case v_function
        when 'update_job_details' then 'Updated by AI Voice Dispatch'
        when 'log_crew_time_and_materials' then 'Logged Time & Materials'
        when 'create_job_change_order' then 'Draft Change Order Created'
        when 'append_job_caution_or_note' then case when v_is_caution then 'Site Caution' else 'Internal Note' end
      end,
      case v_function
        when 'update_job_details' then coalesce(v_scope, 'Schedule, status, or quote details updated by phone.')
        when 'log_crew_time_and_materials' then
          pg_catalog.concat_ws(' ',
            case when v_hours is not null then v_hours::text || ' labor hours logged.' end,
            case when v_material_amount is not null then '$' || v_material_amount::text || ' materials: ' || v_material_description || '.' end
          )
        when 'create_job_change_order' then v_title || ': ' || v_description
        when 'append_job_caution_or_note' then v_note
      end,
      'Contractor (AI Voice Dispatch)',
      pg_catalog.jsonb_build_object(
        'voiceLogged', true,
        'providerCallId', p_provider_call_id,
        'actionId', v_action_id
      ),
      'internal', 'voice_tool_actions', v_action_id
    );
  end if;

  update public.voice_tool_actions
     set action_state = 'applied',
         outcome = v_outcome,
         applied_at = v_now
   where id = v_action_id;

  return v_outcome;
end
$fn$;

revoke all on function public.apply_voice_contractor_action(uuid,text,text,text,uuid,uuid,jsonb)
  from public, anon, authenticated, service_role;
grant execute on function public.apply_voice_contractor_action(uuid,text,text,text,uuid,uuid,jsonb)
  to service_role;

-- The action ledger is internal evidence, never a browser mutation surface.
do $assert$
declare
  v_bad text;
begin
  select pg_catalog.string_agg(grantee || ':' || privilege_type, ', ' order by grantee, privilege_type)
    into v_bad
    from information_schema.role_table_grants
   where table_schema = 'public'
     and table_name = 'voice_tool_actions'
     and grantee in ('PUBLIC', 'anon', 'authenticated');
  if v_bad is not null then
    raise exception 'voice_tool_actions browser grants remain: %', v_bad;
  end if;
end
$assert$;

commit;

-- Source: migrations/20260903231235_ai_voice_number_provisioning.sql
-- Dedicated AI Voice number inventory and provider-operation state machine.
--
-- DARK BY CONSTRUCTION. This migration creates no spend policy, purchase
-- authorization, scheduled worker, provider request, number, or entitlement.
-- A purchase is possible only after a service-side caller records a fresh,
-- exact-price authorization and then claims the matching leased operation.

begin;

-- -------------------------------------------------------------------------
-- 1. Voice-only inventory and exact recurring-charge authorization.
-- -------------------------------------------------------------------------

create table if not exists public.voice_number_spend_policies (
  provider text primary key check (provider = 'signalwire'),
  currency text not null default 'USD' check (currency = 'USD'),
  monthly_unit_price_cents bigint not null
    check (monthly_unit_price_cents between 1 and 999999999),
  aggregate_monthly_ceiling_cents bigint not null
    check (
      aggregate_monthly_ceiling_cents between 1 and 999999999
      and aggregate_monthly_ceiling_cents >= monthly_unit_price_cents
    ),
  purchase_enabled boolean not null default false,
  revision bigint not null default 1 check (revision between 1 and 2147483647),
  updated_by text not null check (pg_catalog.length(updated_by) between 3 and 320),
  created_at timestamptz not null default pg_catalog.now(),
  updated_at timestamptz not null default pg_catalog.now()
);

comment on table public.voice_number_spend_policies is
  'Operations-controlled AI Voice number price/aggregate ceiling. No row is seeded by migrations.';

create table if not exists public.voice_number_inventory (
  id uuid primary key default pg_catalog.gen_random_uuid(),
  account_id uuid not null references public.accounts(id) on delete restrict,
  provider text not null default 'signalwire' check (provider = 'signalwire'),
  provider_number_id text not null check (
    provider_number_id ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
  ),
  e164_number text not null check (e164_number ~ '^\+[1-9][0-9]{7,14}$'),
  purpose text not null default 'ai_voice' check (purpose = 'ai_voice'),
  lifecycle_state text not null default 'purchased' check (lifecycle_state in (
    'purchased', 'configuring', 'active', 'suspended',
    'release_pending', 'release_indeterminate', 'released'
  )),
  voice_capable boolean not null default false,
  call_handler text,
  call_request_url text,
  call_request_method text,
  call_status_callback_url text,
  call_status_callback_method text,
  provider_verified_at timestamptz,
  last_provider_sync_at timestamptz,
  last_provider_check_attempt_at timestamptz,
  last_provider_check_error_code text check (
    last_provider_check_error_code is null
    or last_provider_check_error_code ~ '^[a-z][a-z0-9_]{2,99}$'
  ),
  provider_readiness_state text not null default 'unverified' check (
    provider_readiness_state in ('unverified', 'ready', 'drifted', 'missing')
  ),
  provider_readiness_reason text check (
    provider_readiness_reason is null
    or provider_readiness_reason ~ '^[a-z][a-z0-9_]{2,99}$'
  ),
  provider_readiness_changed_at timestamptz,
  last_provider_observation jsonb check (
    last_provider_observation is null
    or (
      pg_catalog.jsonb_typeof(last_provider_observation) = 'object'
      and pg_catalog.octet_length(last_provider_observation::text) <= 65536
    )
  ),
  activated_at timestamptz,
  suspended_at timestamptz,
  released_at timestamptz,
  created_at timestamptz not null default pg_catalog.now(),
  updated_at timestamptz not null default pg_catalog.now(),
  constraint voice_number_inventory_active_shape check (
    lifecycle_state <> 'active'
    or (
      voice_capable
      and provider_readiness_state = 'ready'
      and pg_catalog.lower(coalesce(call_handler, '')) = 'laml_webhooks'
      and call_request_method = 'POST'
      and call_request_url ~ '^https://[^[:space:]]+/api/voice/ai$'
      and call_status_callback_url ~ '^https://[^[:space:]]+/api/voice/provider-status$'
      and call_status_callback_method = 'POST'
      and provider_verified_at is not null
      and last_provider_sync_at is not null
      and activated_at is not null
      and suspended_at is null
      and released_at is null
    )
  ),
  constraint voice_number_inventory_lifecycle_shape check (
    (lifecycle_state = 'released' and released_at is not null and suspended_at is not null)
    or (lifecycle_state in ('suspended', 'release_indeterminate')
        and suspended_at is not null and released_at is null)
    or (lifecycle_state not in ('released', 'suspended', 'release_indeterminate')
        and released_at is null)
  )
);

create unique index if not exists voice_number_inventory_live_account_uidx
  on public.voice_number_inventory (account_id)
  where lifecycle_state <> 'released';
create index if not exists voice_number_inventory_account_idx
  on public.voice_number_inventory (account_id);
create unique index if not exists voice_number_inventory_live_e164_uidx
  on public.voice_number_inventory (provider, e164_number)
  where lifecycle_state <> 'released';
create unique index if not exists voice_number_inventory_live_provider_id_uidx
  on public.voice_number_inventory (provider, provider_number_id)
  where lifecycle_state <> 'released';
create index if not exists voice_number_inventory_ready_lookup_idx
  on public.voice_number_inventory (provider, account_id, e164_number)
  where lifecycle_state = 'active';

create table if not exists public.voice_number_candidate_observations (
  id uuid primary key default pg_catalog.gen_random_uuid(),
  provider text not null default 'signalwire' check (provider = 'signalwire'),
  candidate_number text not null check (candidate_number ~ '^\+[1-9][0-9]{7,14}$'),
  voice_capable boolean not null check (voice_capable),
  search_fingerprint text not null unique check (search_fingerprint ~ '^[a-f0-9]{64}$'),
  provider_result jsonb not null check (
    pg_catalog.jsonb_typeof(provider_result) = 'object'
    and pg_catalog.octet_length(provider_result::text) <= 8192
    and provider_result->>'provider' = provider
    and provider_result->>'number' = candidate_number
    and provider_result->'voice_capable' = 'true'::jsonb
  ),
  currency text not null default 'USD' check (currency = 'USD'),
  monthly_unit_price_cents bigint not null
    check (monthly_unit_price_cents between 1 and 999999999),
  aggregate_monthly_ceiling_cents bigint not null
    check (aggregate_monthly_ceiling_cents between monthly_unit_price_cents and 999999999),
  spend_policy_revision bigint not null check (spend_policy_revision between 1 and 2147483647),
  price_evidence_source text not null check (price_evidence_source = 'signalwire_dashboard'),
  observed_by text not null check (pg_catalog.length(observed_by) between 3 and 320),
  observed_at timestamptz not null,
  expires_at timestamptz not null,
  created_at timestamptz not null default pg_catalog.now(),
  constraint voice_number_candidate_observation_window check (
    expires_at > observed_at and expires_at <= observed_at + interval '15 minutes'
  )
);
create index if not exists voice_number_candidate_observations_number_idx
  on public.voice_number_candidate_observations (provider, candidate_number, expires_at desc);

create table if not exists public.voice_number_purchase_authorizations (
  id uuid primary key default pg_catalog.gen_random_uuid(),
  account_id uuid not null references public.accounts(id) on delete restrict,
  provider text not null default 'signalwire' check (provider = 'signalwire'),
  candidate_observation_id uuid not null unique
    references public.voice_number_candidate_observations(id) on delete restrict,
  candidate_number text not null check (candidate_number ~ '^\+[1-9][0-9]{7,14}$'),
  currency text not null default 'USD' check (currency = 'USD'),
  monthly_unit_price_cents bigint not null
    check (monthly_unit_price_cents between 1 and 999999999),
  aggregate_monthly_ceiling_cents bigint not null
    check (aggregate_monthly_ceiling_cents between monthly_unit_price_cents and 999999999),
  spend_policy_revision bigint not null check (spend_policy_revision between 1 and 2147483647),
  confirmation_key text not null unique
    check (confirmation_key ~ '^[A-Za-z0-9][A-Za-z0-9:._/+\-]{15,249}$'),
  authorized_by text not null check (pg_catalog.length(authorized_by) between 3 and 320),
  price_evidence_source text not null check (price_evidence_source = 'signalwire_dashboard'),
  price_observed_at timestamptz not null,
  authorized_at timestamptz not null,
  expires_at timestamptz not null,
  state text not null default 'authorized' check (state in ('authorized', 'consumed', 'revoked')),
  consumed_operation_id uuid,
  consumed_at timestamptz,
  revoked_at timestamptz,
  created_at timestamptz not null default pg_catalog.now(),
  constraint voice_number_purchase_authorization_window check (
    expires_at > authorized_at
    and expires_at <= authorized_at + interval '15 minutes'
    and expires_at <= price_observed_at + interval '15 minutes'
  ),
  constraint voice_number_purchase_authorization_state_shape check (
    (state = 'authorized' and consumed_operation_id is null and consumed_at is null and revoked_at is null)
    or (state = 'consumed' and consumed_operation_id is not null and consumed_at is not null and revoked_at is null)
    or (state = 'revoked' and consumed_operation_id is null and consumed_at is null and revoked_at is not null)
  )
);

create index if not exists voice_number_purchase_authorizations_account_idx
  on public.voice_number_purchase_authorizations (account_id, authorized_at desc);

-- -------------------------------------------------------------------------
-- 2. Idempotent, leased provider mutations and immutable attempts.
-- -------------------------------------------------------------------------

create table if not exists public.voice_number_provisioning_operations (
  id uuid primary key default pg_catalog.gen_random_uuid(),
  account_id uuid not null references public.accounts(id) on delete restrict,
  provider text not null default 'signalwire' check (provider = 'signalwire'),
  operation_type text not null check (operation_type in (
    'purchase_number', 'configure_voice', 'release_number'
  )),
  inventory_id uuid references public.voice_number_inventory(id) on delete restrict,
  purchase_authorization_id uuid
    references public.voice_number_purchase_authorizations(id) on delete restrict,
  idempotency_key text not null unique
    check (idempotency_key ~ '^[A-Za-z0-9][A-Za-z0-9:._/+\-]{7,249}$'),
  request_fingerprint text not null check (request_fingerprint ~ '^[a-f0-9]{64}$'),
  request_payload jsonb not null check (
    pg_catalog.jsonb_typeof(request_payload) = 'object'
    and pg_catalog.octet_length(request_payload::text) <= 32768
  ),
  state text not null default 'pending' check (state in (
    'pending', 'claimed', 'request_started', 'succeeded', 'failed',
    'indeterminate', 'cancelled'
  )),
  attempt_count integer not null default 0 check (attempt_count between 0 and 5),
  claim_token uuid,
  lease_expires_at timestamptz,
  request_started_at timestamptz,
  monthly_unit_price_cents bigint,
  aggregate_monthly_ceiling_cents bigint,
  spend_policy_revision bigint,
  provider_object_id text,
  provider_result jsonb check (
    provider_result is null
    or (
      pg_catalog.jsonb_typeof(provider_result) = 'object'
      and pg_catalog.octet_length(provider_result::text) <= 65536
    )
  ),
  observed_provider_object_id text check (
    observed_provider_object_id is null
    or observed_provider_object_id ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
  ),
  observed_provider_result jsonb check (
    observed_provider_result is null
    or (
      pg_catalog.jsonb_typeof(observed_provider_result) = 'object'
      and pg_catalog.octet_length(observed_provider_result::text) <= 65536
    )
  ),
  observed_provider_recorded_at timestamptz,
  observed_provider_recorded_by text check (
    observed_provider_recorded_by is null
    or pg_catalog.length(observed_provider_recorded_by) between 3 and 320
  ),
  expected_identity_disposition text check (
    expected_identity_disposition is null
    or expected_identity_disposition in ('retained', 'released', 'confirmed_absent')
  ),
  observed_identity_disposition text check (
    observed_identity_disposition is null
    or observed_identity_disposition in (
      'not_observed', 'same_as_expected', 'released', 'confirmed_absent'
    )
  ),
  reconciliation_evidence jsonb check (
    reconciliation_evidence is null
    or (
      pg_catalog.jsonb_typeof(reconciliation_evidence) = 'object'
      and pg_catalog.octet_length(reconciliation_evidence::text) <= 8192
    )
  ),
  error_code text check (error_code is null or error_code ~ '^[a-z][a-z0-9_]{2,99}$'),
  error_detail text check (error_detail is null or pg_catalog.length(error_detail) <= 2000),
  completed_at timestamptz,
  failed_at timestamptz,
  indeterminate_at timestamptz,
  resolved_at timestamptz,
  resolved_by text check (resolved_by is null or pg_catalog.length(resolved_by) between 3 and 320),
  created_at timestamptz not null default pg_catalog.now(),
  updated_at timestamptz not null default pg_catalog.now(),
  constraint voice_number_operation_spend_shape check (
    operation_type <> 'purchase_number'
    or (state = 'succeeded' and inventory_id is not null)
    or (state <> 'succeeded' and inventory_id is null)
  ),
  constraint voice_number_operation_price_shape check (
    (
      operation_type = 'purchase_number'
      and purchase_authorization_id is not null
      and monthly_unit_price_cents between 1 and 999999999
      and aggregate_monthly_ceiling_cents between monthly_unit_price_cents and 999999999
      and spend_policy_revision between 1 and 2147483647
    )
    or (
      operation_type <> 'purchase_number'
      and purchase_authorization_id is null
      and monthly_unit_price_cents is null
      and aggregate_monthly_ceiling_cents is null
      and spend_policy_revision is null
    )
  ),
  constraint voice_number_operation_inventory_shape check (
    (operation_type = 'purchase_number')
    or (operation_type in ('configure_voice', 'release_number') and inventory_id is not null)
  ),
  constraint voice_number_operation_state_shape check (
    (state = 'pending' and claim_token is null and lease_expires_at is null
      and request_started_at is null and completed_at is null and failed_at is null
      and indeterminate_at is null and resolved_at is null)
    or (state = 'claimed' and claim_token is not null and lease_expires_at is not null
      and request_started_at is null and completed_at is null and failed_at is null
      and indeterminate_at is null and resolved_at is null)
    or (state = 'request_started' and claim_token is not null and lease_expires_at is not null
      and request_started_at is not null and completed_at is null and failed_at is null
      and indeterminate_at is null and resolved_at is null)
    or (state = 'succeeded' and claim_token is null and lease_expires_at is null
      and completed_at is not null and failed_at is null)
    or (state = 'failed' and claim_token is null and lease_expires_at is null
      and failed_at is not null and completed_at is null)
    or (state = 'indeterminate' and claim_token is null and lease_expires_at is null
      and indeterminate_at is not null and completed_at is null and failed_at is null
      and resolved_at is null)
    or (state = 'cancelled' and claim_token is null and lease_expires_at is null)
  ),
  constraint voice_number_operation_resolution_shape check (
    (resolved_at is null and resolved_by is null
      and expected_identity_disposition is null
      and observed_identity_disposition is null
      and reconciliation_evidence is null)
    or (resolved_at is not null and resolved_by is not null
        and indeterminate_at is not null and state in ('succeeded', 'failed')
        and expected_identity_disposition is not null
        and observed_identity_disposition is not null
        and reconciliation_evidence is not null)
  )
);

