revoke all on function public.mark_voice_staff_step_up_provider_accepted(uuid,text,text,uuid,text,text,integer,text)
  from public, anon, authenticated, service_role;
revoke all on function public.invalidate_voice_staff_step_up_challenge(uuid,text,text,text)
  from public, anon, authenticated, service_role;
revoke all on function public.get_voice_staff_step_up_status(uuid,text,text)
  from public, anon, authenticated, service_role;
revoke all on function public.close_voice_staff_step_up_from_provider_status(text,text)
  from public, anon, authenticated, service_role;
revoke all on function public.invalidate_voice_staff_step_up_on_call_end()
  from public, anon, authenticated, service_role;
revoke all on function public.prevent_voice_staff_step_up_send_event_mutation()
  from public, anon, authenticated, service_role;
revoke all on function public.apply_voice_contractor_action(uuid,text,text,text,uuid,uuid,jsonb)
  from public, anon, authenticated, service_role;

grant execute on function public.issue_voice_staff_step_up_challenge(uuid,text,text,text,text)
  to service_role;
grant execute on function public.verify_voice_staff_step_up_challenge(uuid,text,text,text,text)
  to service_role;
grant execute on function public.mark_voice_staff_step_up_provider_accepted(uuid,text,text,uuid,text,text,integer,text)
  to service_role;
grant execute on function public.invalidate_voice_staff_step_up_challenge(uuid,text,text,text)
  to service_role;
grant execute on function public.get_voice_staff_step_up_status(uuid,text,text)
  to service_role;
grant execute on function public.close_voice_staff_step_up_from_provider_status(text,text)
  to service_role;
grant execute on function public.apply_voice_contractor_action(uuid,text,text,text,uuid,uuid,jsonb)
  to service_role;

do $assert$
declare
  v_bad text;
begin
  select pg_catalog.string_agg(
           grantee || ':' || privilege_type,
           ', ' order by grantee, privilege_type
         )
    into v_bad
    from information_schema.role_table_grants
   where table_schema = 'public'
     and table_name in ('voice_staff_step_up_challenges', 'voice_staff_step_up_send_events')
     and grantee in ('PUBLIC', 'anon', 'authenticated', 'service_role');
  if v_bad is not null then
    raise exception 'Voice staff step-up direct table grants remain: %', v_bad;
  end if;

  if pg_catalog.has_function_privilege(
       'service_role',
       'public.apply_voice_contractor_action_after_step_up(uuid,text,text,text,uuid,uuid,jsonb)',
       'EXECUTE'
     ) then
    raise exception 'Unchecked voice contractor action remains executable by service_role';
  end if;
end
$assert$;

commit;

-- Source: migrations/20260904133000_unify_delivery_request_started_sender.sql
-- migrations/20260904133000_unify_delivery_request_started_sender.sql
-- Allow contractor_dedicated sender numbers during the provider pre-request boundary
-- in mark_sms_delivery_request_started_with_usage when stage_sms_delivery routed
-- outbound traffic through the account's dedicated line.

create or replace function public.mark_sms_delivery_request_started_with_usage(
  p_sms_event_id uuid,
  p_claim_token uuid,
  p_usage_kind text,
  p_reservation_id uuid,
  p_finalization_key text,
  p_overage_key text
)
returns boolean
language plpgsql
security definer
set search_path = pg_catalog, pg_temp
set "TimeZone" to 'UTC'
as $function$
declare
  v_event public.sms_events%rowtype;
  v_task public.sms_delivery_tasks%rowtype;
  v_sender public.sms_sender_numbers%rowtype;
  v_consent public.sms_consent%rowtype;
  v_preference public.sms_sender_keyword_preferences%rowtype;
  v_reservation public.usage_reservations%rowtype;
  v_overage public.workspace_overage_accrual_events%rowtype;
  v_now timestamptz := pg_catalog.clock_timestamp();
begin
  if p_usage_kind not in ('reservation', 'overage', 'unmetered')
     or (p_usage_kind = 'reservation' and (
       p_reservation_id is null or p_finalization_key is null or p_overage_key is not null))
     or (p_usage_kind = 'overage' and (
       p_reservation_id is not null or p_finalization_key is not null or p_overage_key is null))
     or (p_usage_kind = 'unmetered' and (
       p_reservation_id is not null or p_finalization_key is not null or p_overage_key is not null)) then
    raise exception 'SMS text-usage evidence is malformed' using errcode = '22023';
  end if;

  select e.* into v_event
    from public.sms_events e
   where e.id = p_sms_event_id
   for update;
  select t.* into v_task
    from public.sms_delivery_tasks t
   where t.sms_event_id = p_sms_event_id
   for update;
  if v_event.id is null or v_task.sms_event_id is null
     or v_event.status <> 'queued'
     or v_task.task_state <> 'leased'
     or v_task.claim_token is distinct from p_claim_token
     or v_task.lease_expires_at <= v_now
     or v_task.request_started_at is not null then
    raise exception 'SMS delivery usage boundary is stale or invalid'
      using errcode = '55000';
  end if;

  -- Verify sender availability at compare-and-set boundary. Allow dedicated line for account.
  select s.* into v_sender
    from public.sms_sender_numbers s
   where s.id = v_event.sender_number_id
     and s.provider = v_event.provider
     and (
       s.purpose = v_event.sender_purpose
       or (s.purpose = 'contractor_dedicated' and s.account_id = v_event.account_id)
     )
     and (s.account_id is null or s.account_id = v_event.account_id)
     and s.provisioning_status = 'active'
     and s.assignment_state = 'assigned'
     and s.inbound_ready
     and s.suspended_at is null
   for share;
  if not found then
    raise exception 'SMS sender became unavailable before provider request'
      using errcode = 'P5102';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'sms-sender-consent:' || v_sender.id::text || ':' || v_event.phone_number,
      20260821
    )
  );

  select c.* into v_consent
    from public.sms_consent c
   where c.account_id = v_event.account_id
     and c.phone_number = v_event.phone_number
   for share;
  if not found
     or v_consent.status <> 'opted_in'
     or v_consent.consented_at is null
     or v_consent.opted_out_at is not null then
    raise exception 'SMS consent became unavailable before provider request'
      using errcode = 'P5101';
  end if;

  select p.* into v_preference
    from public.sms_sender_keyword_preferences p
   where p.sender_number_id = v_sender.id
     and p.phone_number = v_event.phone_number
   for share;
  if found and v_preference.status = 'opted_out'
     and v_preference.opted_out_at is not null then
    raise exception 'SMS sender preference became opted out before provider request'
      using errcode = 'P5103';
  end if;

  if p_usage_kind = 'reservation' then
    select r.* into v_reservation
      from public.usage_reservations r
     where r.id = p_reservation_id;
    if not found
       or v_reservation.account_id <> v_event.account_id
       or v_reservation.resource_code <> 'text_segments'
       or v_reservation.operation_type <> 'text_send'
       or v_reservation.state <> 'reserved'
       or p_finalization_key <> v_reservation.idempotency_key || ':commit' then
      raise exception 'SMS text reservation does not match this delivery'
        using errcode = '22000';
    end if;
  elsif p_usage_kind = 'overage' then
    select o.* into v_overage
      from public.workspace_overage_accrual_events o
     where o.account_id = v_event.account_id
       and o.idempotency_key = p_overage_key;
    if not found
       or v_overage.resource_code <> 'text_segments'
       or v_overage.released_at is not null then
      raise exception 'SMS text overage does not match this delivery'
        using errcode = '22000';
    end if;
  end if;

  update public.sms_events e
     set text_usage_kind = p_usage_kind,
         text_usage_reservation_id = p_reservation_id,
         text_usage_finalization_key = p_finalization_key,
         text_usage_overage_key = p_overage_key,
         text_usage_state = case p_usage_kind
           when 'reservation' then 'held'
           when 'overage' then 'accrued'
           else 'unmetered'
         end,
         text_usage_last_error = null,
         text_usage_updated_at = v_now
   where e.id = p_sms_event_id;

  perform public.mark_sms_delivery_request_started(p_sms_event_id, p_claim_token);
  return true;
end
$function$;
-- END GENERATED SIGNALWIRE MESSAGING AND VOICE RUNTIME


-- -------------------------------------------------------------------------
-- Canonical Crew Seat Entitlement RPCs
-- -------------------------------------------------------------------------

create or replace function public.create_crew_member_with_seat_entitlement(
  p_account_id uuid,
  p_name text,
  p_phone text,
  p_email text,
  p_role_label text,
  p_photo_path text,
  p_hourly_rate numeric,
  p_pay_type text,
  p_annual_salary numeric,
  p_day_rate numeric,
  p_payroll_id text
)
returns jsonb
language plpgsql
security definer
set search_path = pg_catalog, pg_temp
as $$
declare
  v_actor_id uuid := auth.uid();
  v_limits jsonb;
  v_limit_json jsonb;
  v_limit_text text;
  v_limit_numeric numeric;
  v_limit bigint;
  v_active_count bigint;
  v_entitlement_state text;
  v_created jsonb;
begin
  if v_actor_id is null or not (
    public.is_owner(p_account_id)
    or public.office_can(p_account_id, 'crew.write')
  ) then
    raise exception 'crew_seat_forbidden' using errcode = 'P0001';
  end if;

  select e.feature_limits, e.entitlement_state
    into v_limits, v_entitlement_state
  from public.workspace_entitlements e
  where e.account_id = p_account_id
  for update;

  if not found or v_entitlement_state = 'archived' then
    raise exception 'crew_seat_entitlement_unavailable'
      using errcode = 'P0001';
  end if;

  v_limit_json := v_limits -> 'crew_users';
  v_limit_text := v_limit_json #>> '{}';
  if pg_catalog.jsonb_typeof(v_limit_json) <> 'number'
     or v_limit_text is null then
    raise exception 'crew_seat_entitlement_unavailable'
      using errcode = 'P0001';
  end if;

  begin
    v_limit_numeric := v_limit_text::numeric;
  exception when numeric_value_out_of_range then
    raise exception 'crew_seat_entitlement_unavailable'
      using errcode = 'P0001';
  end;

  if v_limit_numeric < 0
     or pg_catalog.trunc(v_limit_numeric) <> v_limit_numeric
     or v_limit_numeric > 9223372036854775807::numeric then
    raise exception 'crew_seat_entitlement_unavailable'
      using errcode = 'P0001';
  end if;
  v_limit := v_limit_numeric::bigint
    + public.workspace_purchased_capacity_units(p_account_id, 'crew_users');

  select pg_catalog.count(*)
    into v_active_count
  from public.crew c
  where c.account_id = p_account_id
    and c.active = true
    and c.deleted_at is null
    and c.worker_type = 'employee';

  if v_active_count > v_limit then
    raise exception 'crew_seat_remediation_required'
      using errcode = 'P0001',
            detail = pg_catalog.jsonb_build_object(
              'code', 'crew_seat_remediation_required',
              'active_count', v_active_count,
              'crew_limit', v_limit
            )::text;
  end if;

  if v_active_count = v_limit then
    raise exception 'crew_seat_limit_reached'
      using errcode = 'P0001',
            detail = pg_catalog.jsonb_build_object(
              'code', 'crew_seat_limit_reached',
              'active_count', v_active_count,
              'crew_limit', v_limit
            )::text;
  end if;

  insert into public.crew as c (
    account_id,
    name,
    phone,
    email,
    role_label,
    photo_path,
    hourly_rate,
    pay_type,
    annual_salary,
    day_rate,
    payroll_id,
    worker_type,
    active
  ) values (
    p_account_id,
    p_name,
    p_phone,
    p_email,
    p_role_label,
    p_photo_path,
    p_hourly_rate,
    p_pay_type,
    p_annual_salary,
    p_day_rate,
    p_payroll_id,
    'employee',
    true
  )
  returning pg_catalog.to_jsonb(c) into v_created;

  return v_created;
end;
$$;

revoke all on function public.create_crew_member_with_seat_entitlement(
  uuid, text, text, text, text, text, numeric, text, numeric, numeric, text
) from public, anon, service_role;
grant execute on function public.create_crew_member_with_seat_entitlement(
  uuid, text, text, text, text, text, numeric, text, numeric, numeric, text
) to authenticated;

create or replace function public.reactivate_crew_member_with_seat_entitlement(
  p_account_id uuid,
  p_crew_id uuid
)
returns boolean
language plpgsql
security definer
set search_path = pg_catalog, pg_temp
as $$
declare
  v_actor_id uuid := auth.uid();
  v_member public.crew%rowtype;
  v_worker_type text;
  v_limits jsonb;
  v_limit_json jsonb;
  v_limit_text text;
  v_limit_numeric numeric;
  v_limit bigint;
  v_active_count bigint;
  v_entitlement_state text;
begin
  if v_actor_id is null or not (
    public.is_owner(p_account_id)
    or public.office_can(p_account_id, 'crew.write')
  ) then
    raise exception 'crew_seat_forbidden' using errcode = 'P0001';
  end if;

  select c.*
    into v_member
  from public.crew c
  where c.account_id = p_account_id
    and c.id = p_crew_id
    and c.deleted_at is null;

  if not found then
    raise exception 'crew_member_not_found' using errcode = 'P0001';
  end if;

  if v_member.active then
    return true;
  end if;

  v_worker_type := coalesce(v_member.worker_type, 'employee');
  if v_worker_type <> 'employee' then
    update public.crew as c
    set active = true
    where c.account_id = p_account_id
      and c.id = p_crew_id
      and c.deleted_at is null
    returning c.* into v_member;
    if not found then
      raise exception 'crew_member_not_found' using errcode = 'P0001';
    end if;
    return true;
  end if;

  select e.feature_limits, e.entitlement_state
    into v_limits, v_entitlement_state
  from public.workspace_entitlements e
  where e.account_id = p_account_id
  for update;

  if not found or v_entitlement_state = 'archived' then
    raise exception 'crew_seat_entitlement_unavailable'
      using errcode = 'P0001';
  end if;

  v_limit_json := v_limits -> 'crew_users';
  v_limit_text := v_limit_json #>> '{}';
  if pg_catalog.jsonb_typeof(v_limit_json) <> 'number'
     or v_limit_text is null then
    raise exception 'crew_seat_entitlement_unavailable'
      using errcode = 'P0001';
  end if;

  begin
    v_limit_numeric := v_limit_text::numeric;
  exception when numeric_value_out_of_range then
    raise exception 'crew_seat_entitlement_unavailable'
      using errcode = 'P0001';
  end;

  if v_limit_numeric < 0
     or pg_catalog.trunc(v_limit_numeric) <> v_limit_numeric
     or v_limit_numeric > 9223372036854775807::numeric then
    raise exception 'crew_seat_entitlement_unavailable'
      using errcode = 'P0001';
  end if;
  v_limit := v_limit_numeric::bigint
    + public.workspace_purchased_capacity_units(p_account_id, 'crew_users');

  select c.*
    into v_member
  from public.crew c
  where c.account_id = p_account_id
    and c.id = p_crew_id
    and c.deleted_at is null
  for update;

  if not found then
    raise exception 'crew_member_not_found' using errcode = 'P0001';
  end if;
  if v_member.active then
    return true;
  end if;
  if coalesce(v_member.worker_type, 'employee') <> 'employee' then
    update public.crew
    set active = true
    where account_id = p_account_id
      and id = p_crew_id
      and active = false;
    return true;
  end if;

  select pg_catalog.count(*)
    into v_active_count
  from public.crew c
  where c.account_id = p_account_id
    and c.active = true
    and c.deleted_at is null
    and c.worker_type = 'employee';

  if v_active_count > v_limit then
    raise exception 'crew_seat_remediation_required'
      using errcode = 'P0001',
            detail = pg_catalog.jsonb_build_object(
              'code', 'crew_seat_remediation_required',
              'active_count', v_active_count,
              'crew_limit', v_limit
            )::text;
  end if;

  if v_active_count = v_limit then
    raise exception 'crew_seat_limit_reached'
      using errcode = 'P0001',
            detail = pg_catalog.jsonb_build_object(
              'code', 'crew_seat_limit_reached',
              'active_count', v_active_count,
              'crew_limit', v_limit
            )::text;
  end if;

  update public.crew
    set active = true,
        updated_at = pg_catalog.now()
  where id = p_crew_id
    and account_id = p_account_id;

  return true;
end;
$$;

